                            <div>
                                <label class="block text-xs font-bold text-slate-500 mb-1">Sampai Tanggal:</label>
                                <input type="date" id="report-end-date" class="px-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-xl">
