                        <div>
                            <p class="font-bold text-amber-900 text-xs">Informasi Pengiriman / Kurir</p>
                            <p id="detail-modal-delivery-desc" class="text-[11px] text-amber-800">Driver: - | Kendaraan: -</p>
                        </div>
                    </div>
                    <div class="text-right">
                        <span id="detail-modal-delivery-fee" class="text-xs font-bold text-amber-900">Rp 0</span>
                        <p id="detail-modal-delivery-dist" class="text-[10px] text-amber-700">0 km</p>
                    </div>
                </div>

                <!-- Items Table -->
                <div class="border border-slate-200 rounded-2xl overflow-hidden">
                    <div class="bg-slate-100 px-3 py-2 font-bold text-slate-700 flex justify-between items-center text-xs">
                        <span>Rincian Produk Belanja</span>
                        <span id="detail-modal-items-count" class="text-[11px] font-normal text-slate-500">0 Item</span>
                    </div>
                    <div class="overflow-x-auto">
                        <table class="w-full text-left text-xs">
                            <thead class="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200 text-[11px]">
                                <tr>
                                    <th class="py-2 px-3">Produk & Varian</th>
                                    <th class="py-2 px-2 text-center">Qty</th>
                                    <th class="py-2 px-2 text-right">Harga Satuan</th>
                                    <th class="py-2 px-2 text-right">Pajak</th>
                                    <th class="py-2 px-3 text-right">Subtotal</th>
                                </tr>
                            </thead>
                            <tbody id="detail-modal-items-body" class="divide-y divide-slate-100"></tbody>
                        </table>
                    </div>
                </div>

                <!-- Bahan Baku Terpakai (BOM Ingredients) -->
                <div id="detail-modal-bom-card" class="hidden border border-amber-200 bg-amber-50/40 rounded-2xl p-3.5 space-y-2">
                    <div class="flex items-center justify-between">
                        <span class="font-bold text-amber-900 text-xs flex items-center gap-1.5">
                            <i data-lucide="boxes" class="w-4 h-4 text-amber-600"></i>
                            Bahan Baku Terpotong Otomatis (BOM):
                        </span>
                        <span id="detail-modal-bom-count" class="text-[11px] font-semibold text-amber-800">0 Bahan</span>
