                                <tr>
                                    <th class="py-1.5 px-3">Bahan Baku</th>
                                    <th class="py-1.5 px-2 text-center">Tipe / Sumber</th>
                                    <th class="py-1.5 px-2 text-right">Pemakaian</th>
                                    <th class="py-1.5 px-3 text-right">Biaya HPP</th>
                                </tr>
                            </thead>
                            <tbody id="detail-modal-bom-body" class="divide-y divide-amber-100"></tbody>
                        </table>
                    </div>
                </div>

                <!-- Summary Breakdown -->
                <div class="bg-slate-50 p-3.5 rounded-2xl border border-slate-200 space-y-1.5 text-xs">
                    <div class="flex justify-between text-slate-600">
                        <span>Subtotal Produk:</span>
                        <span id="detail-modal-subtotal" class="font-bold">Rp 0</span>
                    </div>
                    <div class="flex justify-between text-rose-600">
                        <span>Diskon Promo:</span>
                        <span id="detail-modal-discount" class="font-bold">- Rp 0</span>
                    </div>
                    <div class="flex justify-between text-slate-600">
                        <span>Pajak Transaksi:</span>
                        <span id="detail-modal-tax" class="font-bold">Rp 0</span>
                    </div>
                    <div id="detail-modal-delivery-row" class="flex justify-between text-amber-700">
                        <span>Biaya Ongkos Kirim:</span>
                        <span id="detail-modal-delivery-subtotal" class="font-bold">Rp 0</span>
                    </div>
                    <div class="flex justify-between text-sm font-black text-slate-900 border-t border-slate-200 pt-2">
                        <span>GRAND TOTAL:</span>
                        <span id="detail-modal-grand-total" class="text-indigo-700 font-black">Rp 0</span>
                    </div>
                    <div class="flex justify-between text-[11px] text-slate-500 pt-1 border-t border-dashed border-slate-200">
                        <span>Pembayaran Diterima / Kembalian:</span>
                        <span id="detail-modal-cash-info">-</span>
                    </div>
                </div>
            </div>

            <!-- Modal Footer -->
            <div class="pt-3 border-t border-slate-100 flex flex-wrap items-center justify-between gap-2">
                <button onclick="closeSaleDetailModal()" class="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-xl text-xs font-bold text-slate-700">
                    Tutup
                </button>
                <div class="flex items-center gap-2">
                    <button id="detail-modal-export-btn" onclick="exportDetailCurrentInvoice()" class="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 rounded-xl text-xs font-bold text-white flex items-center space-x-1.5 shadow">
                        <i data-lucide="download" class="w-3.5 h-3.5"></i>
                        <span>Export Excel Transaksi Ini</span>
                    </button>
                    <button id="detail-modal-print-btn" onclick="printFromDetailModal()" class="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 rounded-xl text-xs font-bold text-white flex items-center space-x-1.5 shadow">
                        <i data-lucide="printer" class="w-3.5 h-3.5"></i>
                        <span>Cetak Struk Thermal</span>
                    </button>
                </div>
            </div>
        </div>
