        function calculateOpeningShiftVariance() {
            const addedInputs = document.querySelectorAll('.shift-added-item-input');
            const box = document.getElementById('opening-variance-box');
            if (!box) return;

            let addedItems = [];
            let sameCount = 0;

            addedInputs.forEach(input => {
                const pId = input.getAttribute('data-product-id');
                const pName = input.getAttribute('data-product-name') || 'Produk';
                const unit = input.getAttribute('data-unit') || 'pcs';
                const nightVal = parseInt(input.getAttribute('data-night-stock')) || 0;
                const addedVal = Math.max(0, parseInt(input.value) || 0);
                const totalOpeningVal = nightVal + addedVal;

                const badge = document.getElementById(`item-calc-badge-${pId}`);
                const nightTotal = document.getElementById(`item-night-total-${pId}`);
                if (nightTotal) {
                    nightTotal.innerText = `${totalOpeningVal} ${unit}`;
                }

                if (badge) {
                    if (addedVal > 0) {
                        badge.className = 'text-[11px] pt-1.5 border-t border-emerald-100 flex items-center justify-between text-emerald-800 transition-all';
                        badge.innerHTML = `
                            <span>Stok Awal: <b class="font-mono text-emerald-950 font-black">${totalOpeningVal}</b> ${unit} <span class="text-[10px] text-emerald-700 font-bold">(${nightVal} malam + ${addedVal} baru)</span></span>
                            <span class="text-[9px] font-black px-1.5 py-0.5 rounded bg-emerald-100 text-emerald-800">📥 +${addedVal} Masuk</span>
                        `;
                    } else {
                        badge.className = 'text-[11px] pt-1.5 border-t border-slate-100 flex items-center justify-between text-slate-600 transition-all';
                        badge.innerHTML = `
                            <span>Stok Awal: <b class="font-mono text-slate-900">${nightVal}</b> ${unit}</span>
                            <span class="text-[9px] font-semibold px-1.5 py-0.5 rounded bg-slate-100 text-slate-600">✓ Stok Tetap</span>
                        `;
                    }
                }

                if (addedVal > 0) {
                    addedItems.push({ name: pName, added: addedVal, night: nightVal, total: totalOpeningVal, unit: unit });
                } else {
                    sameCount++;
                }
            });

            if (addedItems.length > 0) {
                box.className = 'p-3.5 rounded-2xl text-xs font-medium transition-all bg-emerald-50 border border-emerald-300 text-emerald-900 space-y-1.5 shadow-sm';
                let addedRows = addedItems.map(it => `• <b>${it.name}</b>: Sisa malam ${it.night} + <b class="text-emerald-700 font-black">+${it.added} ${it.unit} Tambahan Baru</b> = <b>Total Stok Awal ${it.total} ${it.unit}</b>`).join('<br>');
                box.innerHTML = `
                    <div class="flex items-center space-x-2 font-black text-emerald-950 text-sm">
                        <span>📥</span>
                        <span>Penambahan Stok Baru Pagi Terverifikasi:</span>
                    </div>
                    <div class="pl-6 text-[11px] leading-relaxed">
                        ${addedRows}
                    </div>
                    <p class="text-[10px] text-emerald-700 pl-6 italic">Perhitungan: Stok Awal = Stok Input Awal Shift (+ Tambahan) + Stok Malam.</p>
                `;
            } else {
                box.className = 'p-3.5 rounded-2xl text-xs font-bold transition-all bg-slate-50 border border-slate-200 text-slate-700 flex items-center space-x-2.5';
                box.innerHTML = `
                    <span class="p-1 bg-emerald-100 text-emerald-700 rounded-lg text-sm">✓</span>
                    <div>
                        <span class="font-black text-slate-900">Stok Awal Pagi = Stok Malam Hari Kemarin</span>
                        <span class="block text-[10px] font-normal text-slate-500">Tidak ada penambahan stok baru masuk pagi ini (Stok Awal = 0 + Stok Malam). Seluruh ${sameCount} item siap dijual.</span>
                    </div>
                `;
            }
        }

        function switchDisbursementTab(tabName) {
            document.querySelectorAll('.disb-tab-pane').forEach(el => el.classList.add('hidden'));
            document.querySelectorAll('.disb-tab-btn').forEach(btn => {
                btn.classList.remove('bg-rose-600', 'text-white', 'shadow-xs');
                btn.classList.add('bg-slate-100', 'text-slate-600');
            });
            const pane = document.getElementById(`disb-pane-${tabName}`);
            if (pane) pane.classList.remove('hidden');
            const activeBtn = document.getElementById(`disb-btn-${tabName}`);
            if (activeBtn) {
                activeBtn.classList.remove('bg-slate-100', 'text-slate-600');
                activeBtn.classList.add('bg-rose-600', 'text-white', 'shadow-xs');
            }
        }

        function updateClosingCashSummary() {
            const initCash = window.closingShiftState?.initialCash || 0;
            const cashSales = window.closingShiftState?.cashSales || 0;

            let totExp = 0;
            document.querySelectorAll('.closing-expense-row .expense-amount-input').forEach(el => {
                totExp += parseFloat(el.value) || 0;
            });

            let totLoan = 0;
            document.querySelectorAll('.closing-loan-row .loan-amount-input').forEach(el => {
                totLoan += parseFloat(el.value) || 0;
            });

            let totMeal = 0;
            document.querySelectorAll('.closing-meal-row .meal-amount-input').forEach(el => {
                totMeal += parseFloat(el.value) || 0;
            });

            const totalDisb = totExp + totLoan + totMeal;
            const expectedCash = Math.max(0, (initCash + cashSales) - totalDisb);

            if (window.closingShiftState) {
                window.closingShiftState.expectedCash = expectedCash;
            }

            // Update DOM badges and KPI
            const badgeDisb = document.getElementById('closing-total-disbursements-badge');
            if (badgeDisb) badgeDisb.innerText = '- ' + formatRupiah(totalDisb);

            const kpiDisb = document.getElementById('closing-kpi-disbursements');
            if (kpiDisb) kpiDisb.innerText = '- ' + formatRupiah(totalDisb);

            const kpiExp = document.getElementById('closing-kpi-expected');
            if (kpiExp) kpiExp.innerText = '= ' + formatRupiah(expectedCash);

            const subExp = document.getElementById('closing-sub-expense');
            if (subExp) subExp.innerText = formatRupiah(totExp);

            const subLoan = document.getElementById('closing-sub-loan');
            if (subLoan) subLoan.innerText = formatRupiah(totLoan);

            const subMeal = document.getElementById('closing-sub-meal');
            if (subMeal) subMeal.innerText = formatRupiah(totMeal);

            calculateClosingCashDifference(expectedCash);
        }

        function addShiftExpenseRow() {
            const list = document.getElementById('closing-expenses-list');
            if (!list) return;
            const emptyNote = list.querySelector('.empty-expense-note');
            if (emptyNote) emptyNote.remove();

            const categories = window.closingShiftState?.categories || [];
            const catOptions = categories.map(c => `<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>`).join('') || '<option value="Biaya Operasional Toko">Biaya Operasional Toko</option>';

            const div = document.createElement('div');
            div.className = 'closing-expense-row bg-slate-50/90 p-2 sm:p-2.5 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-12 gap-2 items-center';
            div.innerHTML = `
                <div class="sm:col-span-4">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Kategori Beban</label>
                    <select class="expense-category-input w-full p-1.5 bg-white border border-slate-300 rounded-lg text-xs font-semibold text-slate-800 focus:ring-1 focus:ring-rose-500">
                        ${catOptions}
                    </select>
                </div>
                <div class="sm:col-span-3">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Nominal (Rp)</label>
                    <input type="number" min="0" placeholder="0" oninput="updateClosingCashSummary()" class="expense-amount-input w-full p-1.5 bg-white border border-rose-200 rounded-lg text-xs font-black text-rose-900 text-right focus:ring-1 focus:ring-rose-500">
                </div>
                <div class="sm:col-span-4">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Keterangan / Keperluan</label>
                    <input type="text" placeholder="Contoh: Lakban, sapu, token..." class="expense-notes-input w-full p-1.5 bg-white border border-slate-300 rounded-lg text-xs text-slate-800 focus:ring-1 focus:ring-rose-500">
                </div>
                <div class="sm:col-span-1 text-center pt-1 sm:pt-4">
                    <button type="button" onclick="this.closest('.closing-expense-row').remove(); updateClosingCashSummary();" class="p-1 text-rose-500 hover:text-rose-700 hover:bg-rose-100 rounded text-xs transition-colors" title="Hapus">✕</button>
                </div>
            `;
            list.appendChild(div);
            updateClosingCashSummary();
        }

        function addShiftLoanRow() {
            const list = document.getElementById('closing-loans-list');
            if (!list) return;
            const emptyNote = list.querySelector('.empty-loan-note');
            if (emptyNote) emptyNote.remove();

            const employees = window.closingShiftState?.employees || [];
            const empOptions = employees.map(e => `<option value="${e.id}">${escapeHtml(e.name)} (${escapeHtml(e.role || 'Karyawan')})</option>`).join('') || '<option value="0">Tidak ada karyawan</option>';

            const div = document.createElement('div');
            div.className = 'closing-loan-row bg-slate-50/90 p-2 sm:p-2.5 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-12 gap-2 items-center';
            div.innerHTML = `
                <div class="sm:col-span-4">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Karyawan Penerima</label>
                    <select class="loan-user-input w-full p-1.5 bg-white border border-slate-300 rounded-lg text-xs font-semibold text-slate-800 focus:ring-1 focus:ring-amber-500">
                        ${empOptions}
                    </select>
                </div>
                <div class="sm:col-span-3">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Nominal Kasbon (Rp)</label>
                    <input type="number" min="0" placeholder="0" oninput="updateClosingCashSummary()" class="loan-amount-input w-full p-1.5 bg-white border border-amber-200 rounded-lg text-xs font-black text-amber-900 text-right focus:ring-1 focus:ring-amber-500">
                </div>
                <div class="sm:col-span-4">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Alasan Kasbon</label>
                    <input type="text" placeholder="Contoh: Kasbon darurat harian..." class="loan-notes-input w-full p-1.5 bg-white border border-slate-300 rounded-lg text-xs text-slate-800 focus:ring-1 focus:ring-amber-500">
                </div>
                <div class="sm:col-span-1 text-center pt-1 sm:pt-4">
                    <button type="button" onclick="this.closest('.closing-loan-row').remove(); updateClosingCashSummary();" class="p-1 text-rose-500 hover:text-rose-700 hover:bg-rose-100 rounded text-xs transition-colors" title="Hapus">✕</button>
                </div>
            `;
            list.appendChild(div);
            updateClosingCashSummary();
        }

        function addShiftMealRow() {
            const list = document.getElementById('closing-meals-list');
            if (!list) return;
            const emptyNote = list.querySelector('.empty-meal-note');
            if (emptyNote) emptyNote.remove();

            const employees = window.closingShiftState?.employees || [];
            const empOptions = employees.map(e => `<option value="${e.id}">${escapeHtml(e.name)} (${escapeHtml(e.role || 'Karyawan')})</option>`).join('') || '<option value="0">Tidak ada karyawan</option>';

            const div = document.createElement('div');
            div.className = 'closing-meal-row bg-slate-50/90 p-2 sm:p-2.5 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-12 gap-2 items-center';
            div.innerHTML = `
                <div class="sm:col-span-4">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Karyawan</label>
                    <select class="meal-user-input w-full p-1.5 bg-white border border-slate-300 rounded-lg text-xs font-semibold text-slate-800 focus:ring-1 focus:ring-emerald-500">
                        ${empOptions}
                    </select>
                </div>
                <div class="sm:col-span-3">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Uang Makan (Rp)</label>
                    <input type="number" min="0" placeholder="25000" oninput="updateClosingCashSummary()" class="meal-amount-input w-full p-1.5 bg-white border border-emerald-200 rounded-lg text-xs font-black text-emerald-900 text-right focus:ring-1 focus:ring-emerald-500">
                </div>
                <div class="sm:col-span-4">
                    <label class="block text-[9px] font-bold text-slate-500 uppercase">Keterangan Shift</label>
                    <input type="text" placeholder="Contoh: Uang makan shift 1, lembur..." class="meal-notes-input w-full p-1.5 bg-white border border-slate-300 rounded-lg text-xs text-slate-800 focus:ring-1 focus:ring-emerald-500">
                </div>
                <div class="sm:col-span-1 text-center pt-1 sm:pt-4">
                    <button type="button" onclick="this.closest('.closing-meal-row').remove(); updateClosingCashSummary();" class="p-1 text-rose-500 hover:text-rose-700 hover:bg-rose-100 rounded text-xs transition-colors" title="Hapus">✕</button>
                </div>
            `;
            list.appendChild(div);
            updateClosingCashSummary();
        }

        function calculateClosingCashDifference(expectedCash) {
            const actual = parseFloat(document.getElementById('shift-input-actual-cash')?.value) || 0;
            const statusBox = document.getElementById('closing-cash-status-box');
            if (!statusBox) return;

            const targetExpected = (expectedCash !== undefined) ? expectedCash : (window.closingShiftState ? window.closingShiftState.expectedCash : 0);
            const diff = actual - targetExpected;

            if (actual === 0 && !document.getElementById('shift-input-actual-cash')?.value) {
                statusBox.className = 'p-2.5 rounded-xl text-xs font-bold transition-all bg-slate-100 text-slate-600 flex items-center space-x-2';
                statusBox.innerHTML = `<span>💡</span><span>Masukkan total uang fisik di laci kasir untuk menghitung selisih kas secara otomatis.</span>`;
            } else if (diff === 0) {
                statusBox.className = 'p-2.5 rounded-xl text-xs font-bold transition-all bg-emerald-50 border border-emerald-200 text-emerald-800 flex items-center space-x-2';
                statusBox.innerHTML = `<span>✓</span><span>Uang Fisik Kasir Cocok Sempurna dengan Ekspektasi Sistem (Selisih: Rp 0).</span>`;
            } else if (diff < 0) {
                statusBox.className = 'p-2.5 rounded-xl text-xs font-bold transition-all bg-rose-50 border border-rose-200 text-rose-800 flex items-center space-x-2';
                statusBox.innerHTML = `<span>⚠️</span><span>Uang Fisik Kasir Kurang (Minus) sebesar: <b>${formatRupiah(Math.abs(diff))}</b> dari ekspektasi sistem.</span>`;
            } else {
                statusBox.className = 'p-2.5 rounded-xl text-xs font-bold transition-all bg-amber-50 border border-amber-200 text-amber-800 flex items-center space-x-2';
                statusBox.innerHTML = `<span>ℹ️</span><span>Uang Fisik Kasir Lebih (Surplus) sebesar: <b>+${formatRupiah(diff)}</b> dari ekspektasi sistem.</span>`;
            }
        }

        function calculateClosingItemDiff(input) {
            const pId = input.getAttribute('data-product-id');
            const unit = input.getAttribute('data-unit') || 'pcs';
            const openQty = parseInt(input.getAttribute('data-opening-qty')) || 0;
            const closeQty = parseInt(input.value) || 0;
            const used = openQty - closeQty;

            const badge = document.getElementById(`closing-diff-badge-${pId}`);
            if (badge) {
                if (used >= 0) {
                    badge.innerHTML = `Terpakai / Terjual: <b class="text-indigo-700">${used} ${unit}</b>`;
                } else {
                    badge.innerHTML = `Fisik Lebih: <b class="text-emerald-700">+${Math.abs(used)} ${unit}</b>`;
                }
            }
        }

        // ==========================================
        // WATER METER COUNTER & ADJUSTMENT HELPERS
        // ==========================================
        function calculateWaterMeterOutput() {
            const yesterday = parseFloat(document.getElementById('closing-meter-yesterday')?.value) || 0;
            const todayInput = document.getElementById('closing-meter-today');
            const todayVal = todayInput ? todayInput.value.trim() : '';
            const previewEl = document.getElementById('closing-meter-dispensed-preview');
            const diffPulsaEl = document.getElementById('closing-meter-diff-pulsa');
            const adjustedPreviewEl = document.getElementById('closing-meter-final-adjusted-galon');
            
            if (todayVal === '') {
                if (previewEl) previewEl.innerText = '0.00 Galon';
                if (diffPulsaEl) diffPulsaEl.innerText = 'Selisih: 0 pulsa';
                if (adjustedPreviewEl) adjustedPreviewEl.innerText = '0.00 Galon';
                return;
            }

            const today = parseFloat(todayVal) || 0;
            const diff = today - yesterday;
            const adjType = document.getElementById('closing-meter-adj-type')?.value || 'PULSE';
            const adjVal = parseFloat(document.getElementById('closing-meter-adj-val')?.value) || 0;

            let galon = 0;
            if (adjType === 'GALON') {
                galon = (diff / 782) + adjVal;
            } else {
                galon = (diff + adjVal) / 782;
            }

            const rawGalon = diff / 782;

            if (previewEl) {
                previewEl.innerText = (galon < 0 ? '0.00' : galon.toFixed(2)) + ' Galon';
            }
            if (diffPulsaEl) {
                diffPulsaEl.innerText = `Selisih: ${diff.toLocaleString('id-ID')} pulsa (${rawGalon.toFixed(2)} gal)`;
            }
            if (adjustedPreviewEl) {
                adjustedPreviewEl.innerText = (galon < 0 ? '0.00' : galon.toFixed(2)) + ' Galon';
            }
        }

        function unlockYesterdayMeter() {
            const input = document.getElementById('closing-meter-yesterday');
            const btn = document.getElementById('btn-unlock-yesterday');
            if (!input) return;
            if (input.hasAttribute('readonly')) {
                input.removeAttribute('readonly');
                input.classList.remove('bg-slate-100');
                input.classList.add('bg-white', 'border-amber-400');
                input.focus();
                if (btn) btn.innerText = 'Kunci';
            } else {
                input.setAttribute('readonly', 'true');
                input.classList.remove('bg-white', 'border-amber-400');
                input.classList.add('bg-slate-100');
                if (btn) btn.innerText = 'Ubah';
            }
            calculateWaterMeterOutput();
        }

        function toggleWaterMeterAdjustmentForm() {
            const container = document.getElementById('closing-meter-adj-container');
            const icon = document.getElementById('closing-meter-adj-icon');
            const text = document.getElementById('closing-meter-adj-toggle-text');
            if (!container) return;
            if (container.classList.contains('hidden')) {
                container.classList.remove('hidden');
                if (icon) icon.innerText = '➖';
                if (text) text.innerText = 'Sembunyikan Form Koreksi / Adjustment';
            } else {
                container.classList.add('hidden');
                if (icon) icon.innerText = '➕';
                if (text) text.innerText = 'Tambah Koreksi / Adjustment Nilai Meteran (Opsional)';
            }
        }

        async function openWaterMeterModal() {
            const modal = document.getElementById('water-meter-adjust-modal');
            if (!modal) return;
            modal.classList.remove('hidden');

            const dateInput = document.getElementById('wma-date');
            if (dateInput) {
                const today = new Date().toISOString().split('T')[0];
                dateInput.value = today;
            }

            const branchLabel = document.getElementById('wma-branch-name-badge');
            if (branchLabel) {
                branchLabel.innerText = state.currentBranch ? state.currentBranch.name : 'Cabang';
            }

            await loadWaterMeterLogs();
        }

        function closeWaterMeterModal() {
            const modal = document.getElementById('water-meter-adjust-modal');
            if (modal) modal.classList.add('hidden');
        }

        function calculateModalMeterOutput() {
            const yesterday = parseFloat(document.getElementById('wma-yesterday')?.value) || 0;
            const today = parseFloat(document.getElementById('wma-today')?.value) || 0;
            const adjType = document.getElementById('wma-adj-type')?.value || 'PULSE';
            const adjVal = parseFloat(document.getElementById('wma-adj-val')?.value) || 0;
            const previewEl = document.getElementById('wma-calc-preview');

            const diff = today - yesterday;
            let galon = 0;
            if (adjType === 'GALON') {
                galon = (diff / 782) + adjVal;
            } else {
                galon = (diff + adjVal) / 782;
            }

            if (previewEl) {
                previewEl.innerText = `${galon.toFixed(2)} Galon (Δ ${diff.toLocaleString('id-ID')} pulsa)`;
            }
        }

        async function loadWaterMeterLogs() {
            const branchId = state.currentBranch ? state.currentBranch.id : 1;
            const container = document.getElementById('wma-logs-table-container');
            const yesterdayInput = document.getElementById('wma-yesterday');

            try {
                const res = await fetch(`api.php?action=get_water_meter_logs&branch_id=${branchId}&limit=30`);
                const data = await res.json();
                if (!data.success) {
                    if (container) container.innerHTML = `<div class="p-4 text-center text-rose-500">${escapeHtml(data.message || 'Gagal memuat log meteran')}</div>`;
                    return;
                }

                if (yesterdayInput && (!yesterdayInput.value || yesterdayInput.value === '0')) {
                    yesterdayInput.value = data.latest_meter || 0;
                }

                const logs = data.logs || [];
                if (logs.length === 0) {
                    if (container) container.innerHTML = `<div class="p-6 text-center text-slate-400">Belum ada riwayat pencatatan meteran air untuk cabang ini.</div>`;
                    return;
                }

                let rows = logs.map(l => {
                    const galon = parseFloat(l.water_dispensed_galon) || 0;
                    const diff = parseFloat(l.meter_difference) || 0;
                    const adj = parseFloat(l.meter_adjustment) || 0;
                    let adjText = '-';
                    if (adj !== 0) {
                        adjText = `<span class="text-amber-700 font-bold">${adj > 0 ? '+' : ''}${adj} ${escapeHtml(l.adjustment_type || 'PULSE')}</span>`;
                        if (l.adjustment_reason) {
                            adjText += `<br><span class="text-[9px] text-slate-400 italic">${escapeHtml(l.adjustment_reason)}</span>`;
                        }
                    }

                    return `
                        <tr class="hover:bg-slate-50 border-b border-slate-100 last:border-0">
                            <td class="p-2.5 font-bold text-slate-800">
                                <div>${l.log_date}</div>
                                <div class="text-[10px] text-slate-400 font-normal">${escapeHtml(l.shift_name || 'Penyesuaian')} • ${escapeHtml(l.recorder_name || '-')}</div>
                            </td>
                            <td class="p-2.5 text-center font-mono text-slate-600">${parseFloat(l.meter_yesterday).toLocaleString('id-ID')}</td>
                            <td class="p-2.5 text-center font-mono font-bold text-sky-900 bg-sky-50/50">${parseFloat(l.meter_today).toLocaleString('id-ID')}</td>
                            <td class="p-2.5 text-center font-mono text-slate-700">${diff.toLocaleString('id-ID')}</td>
                            <td class="p-2.5 text-center text-[11px]">${adjText}</td>
                            <td class="p-2.5 text-right font-mono font-black text-emerald-700">${galon.toFixed(2)} Galon</td>
                        </tr>
                    `;
                }).join('');

                if (container) {
                    container.innerHTML = `
                        <div class="overflow-x-auto max-h-60">
                            <table class="w-full text-left">
                                <thead class="bg-slate-100 text-slate-600 font-black text-[10px] uppercase sticky top-0">
                                    <tr>
                                        <th class="p-2.5">Tanggal / Petugas</th>
                                        <th class="p-2.5 text-center">Awal</th>
                                        <th class="p-2.5 text-center">Akhir</th>
                                        <th class="p-2.5 text-center">Selisih</th>
                                        <th class="p-2.5 text-center">Koreksi</th>
                                        <th class="p-2.5 text-right">Galon</th>
                                    </tr>
                                </thead>
                                <tbody class="divide-y divide-slate-100">
                                    ${rows}
                                </tbody>
                            </table>
                        </div>
                    `;
                }
            } catch (e) {
                if (container) container.innerHTML = `<div class="p-4 text-center text-rose-500">Error: ${escapeHtml(e.message)}</div>`;
            }
        }

        async function saveWaterMeterAdjustmentForm(e) {
            if (e) e.preventDefault();
            const branchId = state.currentBranch ? state.currentBranch.id : 1;
            const userId = state.currentUser ? state.currentUser.id : 1;
            const date = document.getElementById('wma-date')?.value;
            const yesterday = parseFloat(document.getElementById('wma-yesterday')?.value) || 0;
            const today = parseFloat(document.getElementById('wma-today')?.value) || 0;
            const adjVal = parseFloat(document.getElementById('wma-adj-val')?.value) || 0;
            const adjType = document.getElementById('wma-adj-type')?.value || 'PULSE';
            const reason = document.getElementById('wma-reason')?.value?.trim() || '';

            if (!date) {
                alert('Silakan pilih tanggal pencatatan.');
                return;
            }

            try {
                const res = await fetch('api.php?action=save_water_meter_adjustment', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        branch_id: branchId,
                        user_id: userId,
                        log_date: date,
                        meter_yesterday: yesterday,
                        meter_today: today,
                        meter_adjustment: adjVal,
                        adjustment_type: adjType,
                        adjustment_reason: reason
                    })
                });
                const data = await res.json();
                if (data.success) {
                    alert('Penyesuaian meteran air berhasil disimpan!');
                    const todayInput = document.getElementById('wma-today');
                    if (todayInput) todayInput.value = '';
                    const reasonInput = document.getElementById('wma-reason');
                    if (reasonInput) reasonInput.value = '';
                    const adjValInput = document.getElementById('wma-adj-val');
                    if (adjValInput) adjValInput.value = '0';
                    await loadWaterMeterLogs();
                    if (state.reportActiveSubtab === 'shifts') {
                        loadShiftReports();
                    }
                } else {
                    alert(data.message || 'Gagal menyimpan penyesuaian meteran air.');
                }
            } catch (err) {
                alert('Terjadi kesalahan koneksi: ' + err.message);
            }
        }

        function closeShiftModal() {
            document.getElementById('shift-modal').classList.add('hidden');
        }

        async function executeShiftAction() {
            const isShiftOpen = state.activeShift && state.activeShift.status === 'OPEN';
            if (isShiftOpen) {
                const actual = parseFloat(document.getElementById('shift-input-actual-cash').value) || 0;
                const closeMin = document.getElementById('closing-raw-mineral') ? parseInt(document.getElementById('closing-raw-mineral').value) : null;
                const closeRo = document.getElementById('closing-raw-ro') ? parseInt(document.getElementById('closing-raw-ro').value) : null;
                const closePl = document.getElementById('closing-raw-plastik') ? parseInt(document.getElementById('closing-raw-plastik').value) : null;
                const notes = document.getElementById('shift-input-notes')?.value || '';
                const isFinal = document.getElementById('check-is-final-shift')?.checked ? 1 : 0;

                // Collect dynamic closing items
                const dynamicClosingItems = [];
                document.querySelectorAll('.shift-closing-item-input').forEach(input => {
                    const pId = parseInt(input.getAttribute('data-product-id')) || 0;
                    if (pId > 0) {
                        dynamicClosingItems.push({
                            product_id: pId,
                            closing_qty: parseInt(input.value) || 0
                        });
                    }
                });

                // Collect 3 Jenis Pengeluaran Kasir
                const expenses = [];
                document.querySelectorAll('.closing-expense-row').forEach(row => {
                    const cat = row.querySelector('.expense-category-input')?.value || 'Biaya Operasional Toko';
                    const amt = parseFloat(row.querySelector('.expense-amount-input')?.value) || 0;
                    const nts = row.querySelector('.expense-notes-input')?.value || '';
                    if (amt > 0) {
                        expenses.push({ category: cat, amount: amt, notes: nts });
                    }
                });

                const loans = [];
                document.querySelectorAll('.closing-loan-row').forEach(row => {
                    const uId = parseInt(row.querySelector('.loan-user-input')?.value) || 0;
                    const amt = parseFloat(row.querySelector('.loan-amount-input')?.value) || 0;
                    const nts = row.querySelector('.loan-notes-input')?.value || '';
                    if (amt > 0 && uId > 0) {
                        loans.push({ user_id: uId, amount: amt, notes: nts });
                    }
                });

                const meals = [];
                document.querySelectorAll('.closing-meal-row').forEach(row => {
                    const uId = parseInt(row.querySelector('.meal-user-input')?.value) || 0;
                    const amt = parseFloat(row.querySelector('.meal-amount-input')?.value) || 0;
                    const nts = row.querySelector('.meal-notes-input')?.value || '';
                    if (amt > 0 && uId > 0) {
                        meals.push({ user_id: uId, amount: amt, notes: nts });
                    }
                });

                // Collect Water Meter Display Counter Input
                const meterTodayVal = document.getElementById('closing-meter-today') ? document.getElementById('closing-meter-today').value.trim() : '';
                const meterToday = meterTodayVal !== '' ? parseFloat(meterTodayVal) : null;
                const meterYesterdayVal = document.getElementById('closing-meter-yesterday') ? document.getElementById('closing-meter-yesterday').value.trim() : '';
                const meterYesterday = meterYesterdayVal !== '' ? parseFloat(meterYesterdayVal) : null;
                const meterAdj = document.getElementById('closing-meter-adj-val') ? (parseFloat(document.getElementById('closing-meter-adj-val').value) || 0) : 0;
                const meterAdjType = document.getElementById('closing-meter-adj-type')?.value || 'PULSE';
                const meterAdjReason = document.getElementById('closing-meter-adj-reason')?.value || '';

                const res = await fetch('api.php?action=close_shift', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        shift_id: state.activeShift.id,
                        actual_cash: actual,
                        items: dynamicClosingItems,
                        closing_raw_mineral: closeMin,
                        closing_raw_ro: closeRo,
                        closing_raw_plastik: closePl,
                        shift_notes: notes,
                        is_final_shift: isFinal,
                        expenses: expenses,
                        loans: loans,
                        meals: meals,
                        meter_today: meterToday,
                        meter_yesterday: meterYesterday,
                        meter_adjustment: meterAdj,
                        adjustment_type: meterAdjType,
                        adjustment_reason: meterAdjReason
                    })
                });
                const data = await res.json();
                if (data.success) {
                    let disbInfo = '';
                    if (data.summary && data.summary.total_disbursements > 0) {
                        disbInfo = `\n\n💸 Rincian Pengeluaran Kas Laci:\n- Biaya Beban Toko: ${formatRupiah(data.summary.total_expenses)}\n- Kasbon Karyawan: ${formatRupiah(data.summary.total_kasbon)}\n- Uang Makan Karyawan: ${formatRupiah(data.summary.total_meal_allowance)}\nTotal Kas Keluar: ${formatRupiah(data.summary.total_disbursements)}`;
                    }

                    let meterInfo = '';
                    if (data.summary && data.summary.water_meter_dispensed_galon !== null && data.summary.water_meter_dispensed_galon !== undefined) {
                        meterInfo = `\n💧 Pengeluaran Air Mesin: ${parseFloat(data.summary.water_meter_dispensed_galon).toFixed(2)} Galon (Display: ${data.summary.water_meter_today})`;
                    }

                    if (data.is_final_shift) {
                        alert(`Penutupan Toko Malam Selesai (Closing Akhir Terkunci)!\n\nShift: ${data.summary?.shift_name || 'Shift Akhir'}\nUang Fisik Aktual: ${formatRupiah(data.summary.actual_cash)}\nEkspektasi Sistem: ${formatRupiah(data.summary.expected_cash)}\nSelisih Kas: ${formatRupiah(data.summary.cash_difference)}${disbInfo}${meterInfo}\n\nLaporan pengeluaran telah otomatis tersinkronisasi ke Beban Operasional, Kasbon, dan Slip Gaji!`);
                    } else {
                        alert(`Shift Berhasil Ditutup (Serah Terima Kasir Selesai)!\n\nShift: ${data.summary?.shift_name || 'Shift 1'}\nUang Fisik Aktual: ${formatRupiah(data.summary.actual_cash)}\nEkspektasi Sistem: ${formatRupiah(data.summary.expected_cash)}\nSelisih Kas: ${formatRupiah(data.summary.cash_difference)}${disbInfo}${meterInfo}\n\nSisa stok fisik & saldo kas otomatis siap diserahterimakan ke Shift berikutnya.`);
                    }
                    state.activeShift = null;
                    renderShiftBanner();
                    closeShiftModal();
                    if (state.reportActiveSubtab === 'shifts') {
                        loadShiftReports();
                    }
                } else alert(data.message || data.error);
            } else {
                const actionBtn = document.getElementById('shift-modal-action-btn');
                const nextNum = parseInt(actionBtn?.getAttribute('data-next-shift-number')) || 1;
                const nextName = actionBtn?.getAttribute('data-next-shift-name') || ('Shift ' + nextNum);

                const initCash = parseFloat(document.getElementById('shift-input-initial-cash')?.value) || 0;

                // Collect dynamic opening items
                const dynamicOpeningItems = [];
                let openMin = null, openRo = null, openPl = null;
                let nightMin = null, nightRo = null, nightPl = null;

                if (nextNum === 1) {
                    // Kasir Pertama (Shift 1):
                    // Rumus: Stok Awal = Input Tambahan Baru + Stok Malam Kemarin
                    const nightInputsMap = {};
                    document.querySelectorAll('.shift-night-item-input').forEach(input => {
                        const pId = parseInt(input.getAttribute('data-product-id')) || 0;
                        if (pId > 0) {
                            nightInputsMap[pId] = parseInt(input.value) || 0;
                        }
                    });

                    document.querySelectorAll('.shift-added-item-input').forEach(input => {
                        const pId = parseInt(input.getAttribute('data-product-id')) || 0;
                        const sku = input.getAttribute('data-sku') || '';
                        const nightStockAttr = input.getAttribute('data-night-stock');
                        const nightStock = (nightStockAttr !== null && !isNaN(parseInt(nightStockAttr)))
                            ? parseInt(nightStockAttr)
                            : (nightInputsMap[pId] !== undefined ? nightInputsMap[pId] : 0);
                        const addedQty = parseInt(input.value) || 0;
                        const openingQty = nightStock + addedQty;

                        if (pId > 0) {
                            dynamicOpeningItems.push({
                                product_id: pId,
                                sku: sku,
                                added_qty: addedQty,
                                night_qty: nightStock,
                                opening_qty: openingQty
                            });

                            if (sku === 'RAW-089' || pId === 89) {
                                openMin = openingQty;
                                nightMin = nightStock;
                            } else if (sku === 'RAW-020' || pId === 88) {
                                openRo = openingQty;
                                nightRo = nightStock;
                            } else if (sku === 'RAW-00092' || pId === 105) {
                                openPl = openingQty;
                                nightPl = nightStock;
                            }
                        }
                    });
                } else {
                    // Kasir Berikutnya (Shift 2+):
                    // Kasir hanya input uang modal awal! Stok otomatis diteruskan dari shift sebelumnya
                    document.querySelectorAll('.shift-carried-item').forEach(el => {
                        const pId = parseInt(el.getAttribute('data-product-id')) || 0;
                        const stock = parseInt(el.getAttribute('data-stock')) || 0;
                        if (pId > 0) {
                            dynamicOpeningItems.push({
                                product_id: pId,
                                added_qty: 0,
                                night_qty: stock,
                                opening_qty: stock
                            });

                            if (pId === 89) { openMin = stock; nightMin = stock; }
                            else if (pId === 88) { openRo = stock; nightRo = stock; }
                            else if (pId === 105) { openPl = stock; nightPl = stock; }
                        }
                    });
                }

                const res = await fetch('api.php?action=open_shift', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        branch_id: state.currentBranch?.id || 1,
                        user_id: state.currentUser?.id || 1,
                        shift_number: nextNum,
                        shift_name: nextName,
                        initial_cash: initCash,
                        items: dynamicOpeningItems,
                        opening_raw_mineral: openMin,
                        opening_raw_ro: openRo,
                        opening_raw_plastik: openPl,
                        closing_night_mineral: nightMin,
                        closing_night_ro: nightRo,
                        closing_night_plastik: nightPl
                    })
                });
                const data = await res.json();
                if (data.success) {
                    alert(data.message);
                    state.activeShift = data.shift;
                    renderShiftBanner();
                    closeShiftModal();
                    if (state.reportActiveSubtab === 'shifts') {
                        loadShiftReports();
                    }
                } else alert(data.message || data.error);
            }
        }

        // ==========================================
        // 2. LAPORAN PENJUALAN
        // ==========================================
        async function loadSalesReports() {
            const start = document.getElementById('report-start-date').value;
            const end = document.getElementById('report-end-date').value;
            const method = document.getElementById('report-payment-filter').value;
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            const res = await fetch(`api.php?action=sales_reports&branch_id=${branchId}&start_date=${start}&end_date=${end}&payment_method=${method}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('kpi-net-sales').innerText = formatRupiah(data.kpi.net_sales);
            document.getElementById('kpi-cogs').innerText = formatRupiah(data.kpi.total_cogs);
            document.getElementById('kpi-gross-profit').innerText = formatRupiah(data.kpi.gross_profit);
            document.getElementById('kpi-gross-margin').innerText = `Margin: ${data.kpi.gross_margin_percent}%`;
            document.getElementById('kpi-discount').innerText = formatRupiah(data.kpi.total_discount);
            document.getElementById('kpi-tx-count').innerText = data.kpi.total_transactions;
            document.getElementById('kpi-aov').innerText = formatRupiah(data.kpi.aov);

            // Populate Quick BOM Consumption Summary Banner
            if (data.bom_summary && Array.isArray(data.bom_summary)) {
                let totalWater = 0;
                let totalCaps = 0;
                let totalTissues = 0;
                data.bom_summary.forEach(m => {
                    const name = (m.name || '').toLowerCase();
                    const qty = Number(m.total_qty) || 0;
                    if (name.includes('air')) totalWater += qty;
                    else if (name.includes('tutup')) totalCaps += qty;
                    else if (name.includes('tisu')) totalTissues += qty;
                });
                const elWater = document.getElementById('quick-bom-water');
                if (elWater) elWater.innerText = `${totalWater.toLocaleString('id-ID')} Liter`;

                const elCaps = document.getElementById('quick-bom-caps');
                if (elCaps) elCaps.innerText = `${totalCaps.toLocaleString('id-ID')} Pcs`;

                const elTissues = document.getElementById('quick-bom-tissues');
                if (elTissues) elTissues.innerText = `${totalTissues.toLocaleString('id-ID')} Pcs`;
            }

            document.getElementById('report-top-products-body').innerHTML = data.top_products.map(tp => `
                <tr>
                    <td class="py-2.5 px-3 font-semibold text-slate-800">${tp.product_name}</td>
                    <td class="py-2.5 px-3 text-right font-bold text-slate-700">${tp.total_qty} pcs</td>
                    <td class="py-2.5 px-3 text-right font-medium text-slate-600">${formatRupiah(tp.total_sales)}</td>
                    <td class="py-2.5 px-3 text-right font-bold text-emerald-700">${formatRupiah(tp.profit)}</td>
                </tr>
            `).join('') || `<tr><td colspan="4" class="text-center py-4 text-slate-400">Belum ada transaksi</td></tr>`;

            document.getElementById('payment-breakdown-list').innerHTML = data.payment_breakdown.map(pb => `
                <div class="p-3 bg-slate-50 rounded-xl flex items-center justify-between text-xs">
                    <span class="font-bold text-slate-700">${pb.payment_method}</span>
                    <div class="text-right">
                        <span class="font-extrabold text-indigo-900">${formatRupiah(pb.total)}</span>
                        <span class="text-[10px] text-slate-400 ml-1">(${pb.count} tx)</span>
                    </div>
                </div>
            `).join('') || `<p class="text-xs text-slate-400">Belum ada transaksi</p>`;

            document.getElementById('report-transactions-body').innerHTML = data.recent_sales.map(s => `
                <tr class="hover:bg-slate-50 transition-colors">
                    <td class="py-2.5 px-3 font-mono font-bold">
                        <button onclick="openSaleDetailModal('${s.invoice_number}')" class="text-indigo-600 hover:text-indigo-800 hover:underline flex items-center space-x-1 font-bold text-left" title="Klik untuk lihat detail transaksi">
                            <span>${s.invoice_number}</span>
                            <i data-lucide="external-link" class="w-3 h-3 text-indigo-400"></i>
                        </button>
                    </td>
                    <td class="py-2.5 px-3 text-slate-500">${s.created_at}</td>
                    <td class="py-2.5 px-3 text-slate-700 font-medium">${s.branch_name}</td>
                    <td class="py-2.5 px-3 text-slate-600">${s.cashier_name}</td>
                    <td class="py-2.5 px-3"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 text-slate-700">${s.payment_method}</span></td>
                    <td class="py-2.5 px-3 text-right font-bold text-slate-800">${formatRupiah(s.grand_total)}</td>
                    <td class="py-2.5 px-3 text-right font-bold text-emerald-700">${formatRupiah(s.gross_profit)}</td>
                    <td class="py-2.5 px-3 text-center">
                        <div class="flex items-center justify-center space-x-1.5">
                            <button onclick="openSaleDetailModal('${s.invoice_number}')" class="p-1 px-2 text-[11px] bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-lg font-bold flex items-center space-x-1" title="Lihat Detail">
                                <i data-lucide="eye" class="w-3 h-3"></i>
                                <span>Detail</span>
                            </button>
                            <button onclick="exportSingleSaleExcel('${s.invoice_number}')" class="p-1 px-2 text-[11px] bg-emerald-50 hover:bg-emerald-100 text-emerald-700 rounded-lg font-bold flex items-center space-x-1" title="Export Excel Transaksi Ini">
                                <i data-lucide="file-spreadsheet" class="w-3 h-3"></i>
                                <span>Excel</span>
                            </button>
                        </div>
                    </td>
                </tr>
            `).join('') || `<tr><td colspan="8" class="text-center py-6 text-slate-400">Belum ada riwayat transaksi</td></tr>`;
            lucide.createIcons();
        }

        // --- Sales Detail Modal & Excel Export Functions ---
        let currentDetailSaleData = null;

        async function openSaleDetailModal(invoiceNumber) {
            try {
                const res = await fetch(`api.php?action=get_sale_detail&invoice_number=${encodeURIComponent(invoiceNumber)}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.error || 'Gagal memuat detail transaksi');
                    return;
                }

                currentDetailSaleData = data;
                const s = data.sale;
                const items = data.items || [];

                document.getElementById('detail-modal-invoice-badge').innerText = s.invoice_number;
                document.getElementById('detail-modal-time').innerText = `${s.created_at} • Shift ID: #${s.shift_id || '-'}`;
                document.getElementById('detail-modal-branch').innerText = s.branch_name || 'Cabang';
                document.getElementById('detail-modal-cashier').innerText = `${s.cashier_name || '-'} (${s.cashier_nik || 'NIK -'})`;
                document.getElementById('detail-modal-customer').innerText = s.customer_name || 'Pelanggan Umum';
                document.getElementById('detail-modal-customer-cat').innerText = `Kategori: ${s.customer_category || 'REGULER'}`;
                document.getElementById('detail-modal-payment').innerText = s.payment_method;
                document.getElementById('detail-modal-sales-type').innerText = `Jenis: ${s.sales_type || 'RETAIL'}`;

                // Delivery Card
                const delivCard = document.getElementById('detail-modal-delivery-card');
                const delivRow = document.getElementById('detail-modal-delivery-row');
                const hasDelivery = (s.delivery_fee && Number(s.delivery_fee) > 0) || (s.delivery_status && s.delivery_status !== 'NONE') || s.driver_name || s.effective_driver_name;
                if (hasDelivery) {
                    delivCard.classList.remove('hidden');
                    delivRow.classList.remove('hidden');
                    const driverName = s.effective_driver_name || s.driver_name || '-';
                    const plate = s.plate_number ? `(${s.plate_number})` : '';
                    const isInc = (Number(s.is_delivery_included) === 1 || Number(s.delivery_fee) === 0);
                    const delivTitle = isInc ? 'Termasuk Biaya Kirim (Rp 0)' : formatRupiah(s.delivery_fee);
                    document.getElementById('detail-modal-delivery-desc').innerText = `Driver: ${driverName} ${plate} • Status: ${s.delivery_status || 'DELIVERED'}${isInc ? ' (Free Included)' : ''}`;
                    document.getElementById('detail-modal-delivery-fee').innerText = delivTitle;
                    document.getElementById('detail-modal-delivery-dist').innerText = `Jarak: ${s.delivery_distance_km || 0} km`;
                    document.getElementById('detail-modal-delivery-subtotal').innerText = formatRupiah(s.delivery_fee || 0);
                } else {
                    delivCard.classList.add('hidden');
                    delivRow.classList.add('hidden');
                }

                // Items list
                document.getElementById('detail-modal-items-count').innerText = `${items.length} Item Produk`;
                document.getElementById('detail-modal-items-body').innerHTML = items.map(it => {
                    const varBadge = it.variant_name ? `<span class="px-1.5 py-0.5 rounded text-[10px] bg-slate-100 text-slate-700 font-medium ml-1">${it.variant_name}</span>` : '';
                    const taxBadge = (it.is_taxable && it.is_taxable == 1) ? `<span class="px-1.5 py-0.2 rounded text-[9px] bg-amber-50 text-amber-700 border border-amber-200">PPN ${it.tax_percent || 11}%</span>` : `<span class="text-[10px] text-slate-400">Non-PPN</span>`;
                    return `
                        <tr class="hover:bg-slate-50">
                            <td class="py-2 px-3">
                                <div class="font-bold text-slate-800">${it.product_name}</div>
                                <div class="flex items-center space-x-1 mt-0.5">
                                    <span class="text-[10px] text-slate-400 font-mono">${it.sku || '-'}</span>
                                    ${varBadge}
                                </div>
                            </td>
                            <td class="py-2 px-2 text-center font-bold text-slate-700">${it.qty} ${it.unit || 'pcs'}</td>
                            <td class="py-2 px-2 text-right font-medium text-slate-600">${formatRupiah(it.unit_price)}</td>
                            <td class="py-2 px-2 text-right">${taxBadge}</td>
                            <td class="py-2 px-3 text-right font-bold text-slate-800">${formatRupiah(it.subtotal_price)}</td>
                        </tr>
                    `;
                }).join('');

                // Financial Summary
                document.getElementById('detail-modal-subtotal').innerText = formatRupiah(s.subtotal);
                document.getElementById('detail-modal-discount').innerText = s.discount > 0 ? `- ${formatRupiah(s.discount)}` : 'Rp 0';
                document.getElementById('detail-modal-tax').innerText = formatRupiah(s.tax || 0);
                document.getElementById('detail-modal-grand-total').innerText = formatRupiah(s.grand_total);
                document.getElementById('detail-modal-cash-info').innerText = `Diterima: ${formatRupiah(s.cash_received || s.grand_total)} • Kembalian: ${formatRupiah(s.cash_change || 0)}`;

                // Render BOM Ingredients Terpakai
                const bomCard = document.getElementById('detail-modal-bom-card');
                const bomBody = document.getElementById('detail-modal-bom-body');
                const bomCount = document.getElementById('detail-modal-bom-count');
                const materials = data.bom_materials || [];
                if (materials.length > 0) {
                    if (bomCard) bomCard.classList.remove('hidden');
                    if (bomCount) bomCount.innerText = `${materials.length} Bahan Baku Terpotong`;
                    if (bomBody) {
                        bomBody.innerHTML = materials.map(m => {
                            const isVar = (m.notes || '').includes('Varian');
                            const typeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-semibold ${isVar ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-700'}">${isVar ? 'VARIANT' : 'BASE BOM'}</span>`;
                            const qty = Math.abs(Number(m.qty_change)) || 0;
                            return `
                                <tr class="hover:bg-amber-50/50">
                                    <td class="py-1.5 px-3">
                                        <div class="font-bold text-slate-800">${m.ingredient_name || '-'}</div>
                                        <div class="text-[10px] text-slate-400 font-mono">${m.ingredient_sku || '-'}</div>
                                    </td>
                                    <td class="py-1.5 px-2 text-center">${typeBadge}</td>
                                    <td class="py-1.5 px-2 text-right font-black text-amber-900">${qty.toLocaleString('id-ID')} ${m.unit || 'pcs'}</td>
                                    <td class="py-1.5 px-3 text-right font-semibold text-slate-700">${formatRupiah(m.total_cogs || 0)}</td>
                                </tr>
                            `;
                        }).join('');
                    }
                } else {
                    if (bomCard) bomCard.classList.add('hidden');
                }

                document.getElementById('sale-detail-modal').classList.remove('hidden');
                lucide.createIcons();
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan saat memuat data transaksi');
            }
        }

        function closeSaleDetailModal() {
            document.getElementById('sale-detail-modal').classList.add('hidden');
        }

        // ==========================================
        // MODUL LAPORAN PEMAKAIAN BAHAN BAKU (BOM)
        // ==========================================
        let currentBomUsageData = null;

        async function loadBomUsageReport() {
            let start = document.getElementById('bom-report-start-date').value;
            let end = document.getElementById('bom-report-end-date').value;
            if (!start || !end) {
                const today = new Date().toISOString().split('T')[0];
                start = today;
                end = today;
                document.getElementById('bom-report-start-date').value = start;
                document.getElementById('bom-report-end-date').value = end;
            }
            const matFilter = document.getElementById('bom-report-material-filter').value || 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            try {
                const res = await fetch(`api.php?action=bom_usage_report&branch_id=${branchId}&start_date=${start}&end_date=${end}&ingredient_id=${encodeURIComponent(matFilter === 'ALL' ? '' : matFilter)}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.error || 'Gagal memuat laporan pemakaian bahan baku');
                    return;
                }

                currentBomUsageData = data;

                // Populate KPI Cards
                const kpi = data.kpi || {};
                const waterLiters = Number(kpi.total_water_liters) || 0;
                document.getElementById('bom-kpi-water-liters').innerText = `${waterLiters.toLocaleString('id-ID')} L`;
                document.getElementById('bom-kpi-water-sub').innerText = `Air Baku: ${waterLiters.toLocaleString('id-ID')} L`;
                document.getElementById('bom-kpi-caps-mineral').innerText = `${(Number(kpi.total_caps_mineral) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-caps-ro').innerText = `${(Number(kpi.total_caps_ro) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-tissues').innerText = `${(Number(kpi.total_tissues) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-plastics').innerText = `${(Number(kpi.total_plastics) || 0).toLocaleString('id-ID')} Pcs`;
                document.getElementById('bom-kpi-total-cost').innerText = formatRupiah(kpi.total_bom_cogs || 0);

                // Populate Material Filter Dropdown if options not built yet
                const matSelect = document.getElementById('bom-report-material-filter');
                if (matSelect && matSelect.options.length <= 1 && data.materials) {
                    data.materials.forEach(m => {
                        const opt = document.createElement('option');
                        opt.value = m.product_id;
                        opt.textContent = m.name;
                        matSelect.appendChild(opt);
                    });
                }

                // Populate Table 1: Rekapitulasi Akumulasi Per Bahan Baku (data.materials)
                const summaryBody = document.getElementById('bom-summary-tbody');
                const summaryCountBadge = document.getElementById('bom-summary-count-badge');
                if (summaryCountBadge) summaryCountBadge.innerText = `${(data.materials || []).length} Bahan Baku Terdata`;

                if (!data.materials || data.materials.length === 0) {
                    summaryBody.innerHTML = `<tr><td colspan="7" class="text-center py-6 text-slate-400">Tidak ada pemakaian bahan baku pada periode tanggal ini.</td></tr>`;
                } else {
                    summaryBody.innerHTML = data.materials.map(m => {
                        let statusBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800">AMAN</span>';
                        if (m.stock_status === 'HABIS') {
                            statusBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-800">HABIS (0)</span>';
                        } else if (m.stock_status === 'MENIPIS') {
                            statusBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800">MENIPIS</span>';
                        }

                        return `
                            <tr class="hover:bg-slate-50 transition-colors">
                                <td class="py-2.5 px-3">
                                    <div class="font-bold text-slate-800">${m.name}</div>
                                    <div class="text-[10px] text-slate-400 font-mono">${m.sku || '-'}</div>
                                </td>
                                <td class="py-2.5 px-3 text-slate-600 font-medium">Bahan Baku / Raw</td>
                                <td class="py-2.5 px-3 text-right font-black text-amber-900 text-sm">${Number(m.total_qty_used).toLocaleString('id-ID')} <span class="text-xs font-normal text-slate-500">${m.unit}</span></td>
                                <td class="py-2.5 px-3 text-right font-medium text-slate-600">${formatRupiah(m.cogs)}</td>
                                <td class="py-2.5 px-3 text-right font-bold text-slate-800">${formatRupiah(m.total_cogs_used)}</td>
                                <td class="py-2.5 px-3 text-right font-bold ${Number(m.current_stock) <= 0 ? 'text-rose-600' : 'text-slate-800'}">${Number(m.current_stock).toLocaleString('id-ID')} ${m.unit}</td>
                                <td class="py-2.5 px-3 text-center">${statusBadge}</td>
                            </tr>
                        `;
                    }).join('');
                }

                // Populate Table 2: Rincian Log Transaksi Penjualan yang Memotong Bahan Baku (data.raw_logs)
                const logsBody = document.getElementById('bom-logs-tbody');
                const logsCountBadge = document.getElementById('bom-logs-count-badge');
                if (logsCountBadge) logsCountBadge.innerText = `${(data.raw_logs || []).length} Log Transaksi`;

                if (!data.raw_logs || data.raw_logs.length === 0) {
                    logsBody.innerHTML = `<tr><td colspan="8" class="text-center py-6 text-slate-400">Tidak ada transaksi penjualan produk ber-BOM pada periode ini.</td></tr>`;
                } else {
                    logsBody.innerHTML = data.raw_logs.map(log => {
                        const isVar = (log.notes || '').includes('Varian');
                        const typeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-semibold ${isVar ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-700'}">${isVar ? 'VARIANT' : 'BASE BOM'}</span>`;
                        const qty = Math.abs(Number(log.qty_change)) || 0;
                        return `
                            <tr class="hover:bg-slate-50 transition-colors">
                                <td class="py-2.5 px-3 font-mono text-slate-500 text-[11px]">${log.created_at}</td>
                                <td class="py-2.5 px-3">
                                    <span class="font-mono font-bold text-indigo-600 hover:underline cursor-pointer" onclick="openSaleDetailModal('${log.reference_no}')">${log.reference_no}</span>
                                </td>
                                <td class="py-2.5 px-3">
                                    <span class="font-bold text-slate-800">${log.notes}</span>
                                </td>
                                <td class="py-2.5 px-3 text-center font-bold text-slate-700">-</td>
                                <td class="py-2.5 px-3">
                                    <div class="flex items-center space-x-1.5">
                                        <span class="font-bold text-slate-800">${log.ingredient_name}</span>
                                        ${typeBadge}
                                    </div>
                                    <div class="text-[10px] text-slate-400 font-mono">${log.ingredient_sku || '-'}</div>
                                </td>
                                <td class="py-2.5 px-3 text-right font-black text-amber-900">${qty.toLocaleString('id-ID')} <span class="text-xs font-normal text-slate-500">${log.unit}</span></td>
                                <td class="py-2.5 px-3 text-right font-medium text-slate-700">${formatRupiah(log.total_ingredient_cost)}</td>
                                <td class="py-2.5 px-3 text-center">
                                    <button onclick="openSaleDetailModal('${log.reference_no}')" class="px-2.5 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-600 rounded-lg text-xs font-bold transition-all">
                                        Lihat Nota
                                    </button>
                                </td>
                            </tr>
                        `;
                    }).join('');
                }

                lucide.createIcons();
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat memuat laporan pemakaian bahan baku');
            }
        }

        function exportBomUsageExcel() {
            let start = document.getElementById('bom-report-start-date').value;
            let end = document.getElementById('bom-report-end-date').value;
            if (!start || !end) {
                const today = new Date().toISOString().split('T')[0];
                start = today;
                end = today;
            }
            const matFilter = document.getElementById('bom-report-material-filter').value || 'ALL';
            const branchId = state.currentBranch ? state.currentBranch.id : '';
            window.location.href = `api.php?action=export_bom_usage_excel&branch_id=${branchId}&start_date=${start}&end_date=${end}&material_id=${encodeURIComponent(matFilter)}`;
        }

        function exportSalesDetailExcel() {
            const start = document.getElementById('report-start-date').value;
            const end = document.getElementById('report-end-date').value;
            const method = document.getElementById('report-payment-filter').value;
            const branchId = state.currentBranch ? state.currentBranch.id : '';

            const url = `api.php?action=export_sales_excel&branch_id=${branchId}&start_date=${start}&end_date=${end}&payment_method=${method}`;
            window.open(url, '_blank');
        }

        function exportSingleSaleExcel(invoiceNumber) {
            if (!invoiceNumber) return;
            const url = `api.php?action=export_sales_excel&invoice_number=${encodeURIComponent(invoiceNumber)}`;
            window.open(url, '_blank');
        }

        function exportDetailCurrentInvoice() {
            if (!currentDetailSaleData || !currentDetailSaleData.sale) return;
            exportSingleSaleExcel(currentDetailSaleData.sale.invoice_number);
        }

        function printFromDetailModal() {
            if (!currentDetailSaleData || !currentDetailSaleData.sale) return;
            const s = currentDetailSaleData.sale;
            const items = currentDetailSaleData.items || [];
            
            // Siapkan format untuk showReceiptModal
            const modalData = {
                ...s,
                items: items
            };
            showReceiptModal(modalData);
        }

        // ==========================================
        // 2b. MODUL LAPORAN & PELUNASAN PIUTANG USAHA (ACCOUNTS RECEIVABLE)
        // ==========================================
        // ==========================================
        // 2b. MODUL LAPORAN MULTI-SHIFT, PENJUALAN & PIUTANG USAHA
        // ==========================================
        let currentDailyShiftReportData = null;

        function setReportSubtab(subtab) {
            state.reportActiveSubtab = subtab;
            const btnSales = document.getElementById('report-subtab-btn-sales');
            const btnAR = document.getElementById('report-subtab-btn-receivables');
            const btnShifts = document.getElementById('report-subtab-btn-shifts');
            const btnBom = document.getElementById('report-subtab-btn-bom');

            const viewSales = document.getElementById('subtab-reports-sales');
            const viewAR = document.getElementById('subtab-reports-ar');
            const viewShifts = document.getElementById('subtab-reports-shifts');
            const viewBOM = document.getElementById('subtab-reports-bom');

            // Reset buttons style
            const inactiveClass = 'px-4 py-2 rounded-xl text-xs font-bold transition-all text-slate-600 hover:text-indigo-600 hover:bg-slate-50 flex items-center space-x-1.5';
            const activeClass = 'px-4 py-2 rounded-xl text-xs font-bold transition-all bg-indigo-600 text-white shadow-sm flex items-center space-x-1.5';

            if (btnSales) btnSales.className = inactiveClass;
            if (btnAR) btnAR.className = inactiveClass;
            if (btnShifts) btnShifts.className = inactiveClass;
            if (btnBom) btnBom.className = inactiveClass;

            if (viewSales) viewSales.classList.add('hidden');
            if (viewAR) viewAR.classList.add('hidden');
            if (viewShifts) viewShifts.classList.add('hidden');
            if (viewBOM) viewBOM.classList.add('hidden');

            if (subtab === 'receivables') {
                if (viewAR) viewAR.classList.remove('hidden');
                if (btnAR) btnAR.className = activeClass;
                loadReceivablesReport();
            } else if (subtab === 'shifts') {
                if (viewShifts) viewShifts.classList.remove('hidden');
                if (btnShifts) btnShifts.className = activeClass;
                loadShiftReports();
            } else if (subtab === 'bom') {
                if (viewBOM) viewBOM.classList.remove('hidden');
                if (btnBom) btnBom.className = activeClass;
                loadBomUsageReport();
            } else {
                if (viewSales) viewSales.classList.remove('hidden');
                if (btnSales) btnSales.className = activeClass;
                loadSalesReports();
            }
            lucide.createIcons();
        }

        async function loadShiftReports() {
            const dateInput = document.getElementById('shift-report-date');
            if (dateInput && !dateInput.value) {
                const today = new Date().toISOString().split('T')[0];
                dateInput.value = today;
            }
            const date = dateInput ? dateInput.value : new Date().toISOString().split('T')[0];
            const branchId = state.currentBranch ? state.currentBranch.id : 1;

            const branchLabel = document.getElementById('shift-report-branch-label');
            if (branchLabel) {
                branchLabel.innerText = state.currentBranch?.name || 'Cabang Aktif';
            }

            const container = document.getElementById('shift-cards-container');
            if (container) {
                container.innerHTML = `
                    <div class="col-span-full py-12 text-center text-slate-400 bg-white rounded-3xl border border-slate-200">
                        <div class="w-6 h-6 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                        <span class="text-xs font-bold">Memuat rincian laporan shift kasir (${date})...</span>
                    </div>
                `;
            }

            try {
                const res = await fetch(`api.php?action=get_shift_reports&branch_id=${branchId}&date=${date}`);
                const data = await res.json();
                if (!data.success) {
                    if (container) container.innerHTML = `<div class="col-span-full p-6 text-center text-rose-600 bg-rose-50 rounded-2xl border border-rose-200 text-xs font-bold">${escapeHtml(data.message || 'Gagal memuat data shift')}</div>`;
                    return;
                }

                currentDailyShiftReportData = data;
                renderDailyClosingSummary(data.daily_summary, data.report_date);
                renderShiftCards(data.shifts);
                renderFinalNightStocksTable(data.daily_summary.final_stocks, data.daily_summary.is_store_closed, data.daily_summary.final_cashier_name, data.daily_summary.final_closing_time);
            } catch (err) {
                console.error("Gagal load shift reports:", err);
                if (container) {
                    container.innerHTML = `<div class="col-span-full p-6 text-center text-rose-600 bg-rose-50 rounded-2xl border border-rose-200 text-xs font-bold">Terjadi kesalahan memuat data: ${escapeHtml(err.message)}</div>`;
                }
            }
        }

        function renderDailyClosingSummary(summary, reportDate) {
            if (!summary) return;
            const badge = document.getElementById('daily-store-status-badge');
            const desc = document.getElementById('daily-store-desc');
            const countEl = document.getElementById('daily-total-shifts-count');

            if (badge) {
                if (summary.is_store_closed) {
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black bg-rose-500/20 text-rose-300 border border-rose-500/30';
                    badge.innerText = 'TUTUP TOKO MALAM SELESAI 🔒';
                } else if (summary.total_shifts > 0) {
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-500/20 text-emerald-300 border border-emerald-500/30';
                    badge.innerText = 'TOKO AKTIF BEROPERASI 🟢';
                } else {
                    badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black bg-slate-500/20 text-slate-300 border border-slate-500/30';
                    badge.innerText = 'BELUM ADA SHIFT ⚪';
                }
            }

            if (desc) {
                if (summary.is_store_closed) {
                    desc.innerText = `Toko telah ditutup resmi pada ${summary.final_closing_time || '-'} oleh ${summary.final_cashier_name || 'Kasir Akhir'}. Sisa stok fisik malam terkunci.`;
                } else {
                    desc.innerText = `Konsolidasi seluruh transaksi shift & rekonsiliasi kas laci toko tanggal ${reportDate}.`;
                }
            }

            if (countEl) countEl.innerText = `${summary.total_shifts} Shift`;

            const revEl = document.getElementById('daily-kpi-total-revenue');
            if (revEl) revEl.innerText = formatRupiah(summary.total_revenue || 0);

            const cashEl = document.getElementById('daily-kpi-cash-sales');
            if (cashEl) cashEl.innerText = formatRupiah(summary.total_cash_sales || 0);

            const nonCashEl = document.getElementById('daily-kpi-noncash-sales');
            if (nonCashEl) nonCashEl.innerText = formatRupiah(summary.total_non_cash_sales || 0);

            const initEl = document.getElementById('daily-kpi-initial-cash');
            if (initEl) initEl.innerText = formatRupiah(summary.total_initial_cash || 0);

            const actEl = document.getElementById('daily-kpi-actual-cash');
            if (actEl) actEl.innerText = formatRupiah(summary.total_actual_cash || 0);

            const diffEl = document.getElementById('daily-kpi-cash-difference');
            if (diffEl) {
                const diff = summary.total_cash_difference || 0;
                diffEl.innerText = (diff >= 0 ? '+' : '') + formatRupiah(diff);
                if (diff < 0) diffEl.className = 'text-sm sm:text-base font-black text-rose-300 mt-1 block';
                else if (diff > 0) diffEl.className = 'text-sm sm:text-base font-black text-amber-300 mt-1 block';
                else diffEl.className = 'text-sm sm:text-base font-black text-emerald-300 mt-1 block';
            }
        }

        function renderShiftCards(shifts) {
            const container = document.getElementById('shift-cards-container');
            if (!container) return;

            if (!shifts || shifts.length === 0) {
                container.innerHTML = `
                    <div class="col-span-full py-12 text-center text-slate-400 bg-white rounded-3xl border border-slate-200 space-y-2">
                        <span class="text-3xl block">🏪</span>
                        <div class="text-sm font-bold text-slate-700">Belum Ada Shift Kasir Buka/Tutup</div>
                        <p class="text-xs text-slate-400 max-w-md mx-auto">Tidak ada rekaman transaksi atau pembukaan laci kasir pada tanggal yang dipilih di cabang ini.</p>
                    </div>
                `;
                return;
            }

            container.innerHTML = shifts.map(s => {
                const isOpen = s.status === 'OPEN';
                const isFinal = s.is_final_shift === 1 || s.shift_number >= 2;
                const statusBadge = isOpen
                    ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-200">SEDANG BERJALAN 🟢</span>'
                    : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-slate-100 text-slate-700 border border-slate-200">SELESAI DITUTUP 🔒</span>';

                const shiftTypeBadge = s.shift_number === 1
                    ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-indigo-50 text-indigo-700 border border-indigo-200">Shift 1 (Pagi) 🌅</span>'
                    : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-amber-50 text-amber-800 border border-amber-200">Shift 2 (Siang/Malam) 🌤️</span>';

                const finalBadge = isFinal && !isOpen
                    ? '<span class="px-2 py-0.5 rounded-full text-[9px] font-black bg-rose-50 text-rose-700 border border-rose-200">Tutup Toko Malam 🌙</span>'
                    : '';

                const diff = s.cash_difference || 0;
                let diffText = formatRupiah(diff);
                let diffBadgeClass = 'text-emerald-700 bg-emerald-50 border-emerald-200';
                if (diff < 0) {
                    diffBadgeClass = 'text-rose-700 bg-rose-50 border-rose-200';
                    diffText = `Defisit ${formatRupiah(Math.abs(diff))}`;
                } else if (diff > 0) {
                    diffBadgeClass = 'text-amber-700 bg-amber-50 border-amber-200';
                    diffText = `Surplus +${formatRupiah(diff)}`;
                } else {
                    diffText = 'Seimbang Rp 0 ✅';
                }

                // Table Mini Rekonsiliasi Stok Produk Shift
                const itemsRows = (s.reconciled_items || []).map(item => `
                    <tr class="hover:bg-slate-50/50">
                        <td class="py-2 px-2.5 font-bold text-slate-800 flex items-center gap-1.5">
                            <span>${item.image_emoji || '📦'}</span>
                            <span class="truncate">${escapeHtml(item.name)}</span>
                        </td>
                        <td class="py-2 px-2 text-center font-mono text-slate-600">${item.opening_qty}</td>
                        <td class="py-2 px-2 text-center font-bold text-indigo-700">${item.usage_qty}</td>
                        <td class="py-2 px-2 text-center font-black text-slate-900 bg-slate-50">${item.closing_qty}</td>
                    </tr>
                `).join('');

                return `
                    <div class="bg-white rounded-3xl border border-slate-200/90 shadow-sm p-4 sm:p-5 space-y-4 hover:border-indigo-300 transition-all">
                        <!-- Header Kartu Shift -->
                        <div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 pb-3">
                            <div class="flex items-center space-x-2 flex-wrap gap-1">
                                <h3 class="font-black text-sm sm:text-base text-slate-900">${escapeHtml(s.shift_name)}</h3>
                                ${shiftTypeBadge}
                                ${finalBadge}
                            </div>
                            <div>
                                ${statusBadge}
                            </div>
                        </div>

                        <!-- Info Petugas Kasir & Waktu -->
                        <div class="bg-slate-50/80 p-3 rounded-2xl border border-slate-100 flex flex-wrap items-center justify-between gap-3 text-xs">
                            <div>
                                <span class="text-[10px] text-slate-400 font-bold uppercase block">Kasir Bertugas</span>
                                <span class="font-black text-slate-800 text-sm flex items-center gap-1">
                                    👤 ${escapeHtml(s.cashier_name)} <span class="text-[10px] font-normal text-slate-400">(${escapeHtml(s.cashier_nik || 'KASIR')})</span>
                                </span>
                            </div>
                            <div class="text-right text-[11px] text-slate-500 font-medium">
                                <div>Mulai: <b>${s.start_time || '-'}</b></div>
                                <div>Selesai: <b>${s.end_time || (isOpen ? 'Shift Berjalan' : '-')}</b></div>
                            </div>
                        </div>

                        <!-- Rincian Finansial Shift (Isolasi Kasir) -->
                        <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
                            <div class="bg-indigo-50/50 p-2.5 rounded-xl border border-indigo-100/80">
                                <span class="text-[9px] text-indigo-500 font-bold uppercase block">Modal Awal</span>
                                <span class="font-black text-indigo-950 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.initial_cash)}</span>
                            </div>
                            <div class="bg-slate-50 p-2.5 rounded-xl border border-slate-100">
                                <span class="text-[9px] text-slate-500 font-bold uppercase block">Penjualan Tunai</span>
                                <span class="font-black text-slate-900 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.cash_sales)}</span>
                            </div>
                            <div class="bg-slate-50 p-2.5 rounded-xl border border-slate-100">
                                <span class="text-[9px] text-slate-500 font-bold uppercase block">Non-Tunai (QRIS/Trf)</span>
                                <span class="font-black text-slate-900 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.non_cash_sales)}</span>
                            </div>
                            <div class="bg-emerald-50/60 p-2.5 rounded-xl border border-emerald-100">
                                <span class="text-[9px] text-emerald-700 font-bold uppercase block">Total Omzet Shift</span>
                                <span class="font-black text-emerald-900 text-xs sm:text-sm mt-0.5 block">${formatRupiah(s.total_sales)}</span>
                            </div>
                        </div>

                        <!-- Rekonsiliasi Kas Laci Kasir -->
                        <div class="p-3 bg-slate-50 rounded-2xl border border-slate-200/70 space-y-2 text-xs">
                            <div class="flex items-center justify-between text-slate-600 font-medium">
                                <span>Kas Terhitung Sistem (Modal + Tunai - Pengeluaran):</span>
                                <span class="font-bold text-slate-900">${formatRupiah(s.expected_cash)}</span>
                            </div>
                            ${(s.total_disbursements > 0) ? `
                                <div class="p-2 bg-rose-50/70 rounded-xl border border-rose-200/80 space-y-1">
                                    <div class="flex items-center justify-between font-bold text-rose-900 text-[11px]">
                                        <span>💸 Pengeluaran Kasir (Petty Cash):</span>
                                        <span class="font-mono text-rose-800">- ${formatRupiah(s.total_disbursements)}</span>
                                    </div>
                                    <div class="grid grid-cols-3 gap-1 text-[10px] text-slate-600 pt-1 border-t border-rose-100">
                                        <div>Beban Toko: <b class="text-rose-700">${formatRupiah(s.total_expenses || 0)}</b></div>
                                        <div>Kasbon: <b class="text-amber-700">${formatRupiah(s.total_kasbon || 0)}</b></div>
                                        <div>Uang Makan: <b class="text-emerald-700">${formatRupiah(s.total_meal_allowance || 0)}</b></div>
                                    </div>
                                </div>
                            ` : ''}
                            <div class="flex items-center justify-between text-slate-600 font-medium">
                                <span>Kas Fisik Aktual Diserahkan:</span>
                                <span class="font-black text-slate-900 text-sm">${isOpen ? 'Menunggu Closing' : formatRupiah(s.actual_cash)}</span>
                            </div>
                            ${!isOpen ? `
                                <div class="flex items-center justify-between pt-1 border-t border-slate-200">
                                    <span class="font-bold text-slate-700">Hasil Audit Kas Laci:</span>
                                    <span class="px-2.5 py-1 rounded-lg text-xs font-black border ${diffBadgeClass}">${diffText}</span>
                                </div>
                            ` : ''}
                        </div>

                        <!-- Rincian Pemakaian Stok Bahan/Produk Shift Ini -->
                        <div class="space-y-1.5">
                            <div class="flex items-center justify-between text-[11px] font-bold text-slate-700">
                                <span>Pemakaian Stok Selama Shift Ini:</span>
                                <span class="text-slate-400 font-normal">Awal - Terpakai = Sisa</span>
                            </div>
                            <div class="overflow-x-auto rounded-xl border border-slate-100">
                                <table class="w-full text-left text-[11px]">
                                    <thead class="bg-slate-50 text-slate-500 font-bold">
                                        <tr>
                                            <th class="py-1.5 px-2.5">Produk</th>
                                            <th class="py-1.5 px-2 text-center">Awal</th>
                                            <th class="py-1.5 px-2 text-center">Terjual</th>
                                            <th class="py-1.5 px-2 text-center">Sisa</th>
                                        </tr>
                                    </thead>
                                    <tbody class="divide-y divide-slate-100">
                                        ${itemsRows}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        ${s.water_meter_today !== null ? `
                            <!-- Rincian Meteran Air Display Counter -->
                            <div class="p-3 bg-sky-50/70 rounded-2xl border border-sky-200 text-xs space-y-2">
                                <div class="flex items-center justify-between">
                                    <span class="font-black text-sky-950 flex items-center gap-1.5">
                                        <span>💧</span> Meteran Air Mesin (Display Counter)
                                    </span>
                                    <span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-sky-600 text-white shadow-2xs font-mono">
                                        ${s.water_meter_dispensed_galon !== null ? s.water_meter_dispensed_galon.toLocaleString('id-ID', {minimumFractionDigits: 1, maximumFractionDigits: 2}) : '0'} Galon
                                    </span>
                                </div>
                                <div class="grid grid-cols-3 gap-2 text-center pt-1 border-t border-sky-100">
                                    <div class="bg-white/80 p-1.5 rounded-xl border border-sky-100">
                                        <span class="text-[9px] text-slate-400 font-bold block uppercase">Kemarin</span>
                                        <span class="font-mono font-bold text-slate-700 text-xs">${(s.water_meter_yesterday || 0).toLocaleString('id-ID')}</span>
                                    </div>
                                    <div class="bg-white/80 p-1.5 rounded-xl border border-sky-100">
                                        <span class="text-[9px] text-slate-400 font-bold block uppercase">Hari Ini</span>
                                        <span class="font-mono font-black text-sky-900 text-xs">${(s.water_meter_today || 0).toLocaleString('id-ID')}</span>
                                    </div>
                                    <div class="bg-sky-100/70 p-1.5 rounded-xl border border-sky-200">
                                        <span class="text-[9px] text-sky-800 font-bold block uppercase">Selisih Pulsa</span>
                                        <span class="font-mono font-black text-sky-950 text-xs">${(s.water_meter_difference || 0).toLocaleString('id-ID')}</span>
                                    </div>
                                </div>
                                ${s.water_meter_adjustment ? `
                                    <div class="text-[10px] text-sky-900 bg-white/70 p-2 rounded-xl border border-sky-100 flex items-center justify-between">
                                        <span>Adjustment (${escapeHtml(s.water_meter_adjustment_type || 'PULSE')}): <b>${s.water_meter_adjustment > 0 ? '+' : ''}${s.water_meter_adjustment}</b></span>
                                        <span class="italic text-slate-500">${escapeHtml(s.water_meter_adjustment_reason || '-')}</span>
                                    </div>
                                ` : ''}
                            </div>
                        ` : ''}

                        <!-- Catatan Shift & Tombol Cetak -->
                        <div class="pt-2 border-t border-slate-100 flex flex-wrap items-center justify-between gap-2">
                            <div class="text-[11px] text-slate-500 italic truncate max-w-xs">
                                ${s.shift_notes ? `Catatan: "${escapeHtml(s.shift_notes)}"` : '<span class="text-slate-400">Tidak ada catatan shift</span>'}
                            </div>
                            <button onclick="printSingleShiftReceipt(${s.id})" class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold rounded-xl border border-slate-200 transition-colors flex items-center space-x-1">
                                <i data-lucide="printer" class="w-3.5 h-3.5"></i>
                                <span>Cetak Struk Shift</span>
                            </button>
                        </div>
                    </div>
                `;
            }).join('');

            lucide.createIcons();
        }

        function renderFinalNightStocksTable(finalStocks, isClosed, cashierName, closingTime) {
            const tbody = document.getElementById('daily-final-stocks-tbody');
            const metaBadge = document.getElementById('final-stocks-meta-badge');
            if (!tbody) return;

            if (metaBadge) {
                if (isClosed) {
                    metaBadge.innerHTML = `Terkunci Tutup Toko • <b>${cashierName || 'Kasir'}</b> (${closingTime || '-'})`;
                    metaBadge.className = 'text-xs font-mono font-bold text-emerald-900 bg-emerald-50 px-3 py-1 rounded-xl border border-emerald-200';
                } else {
                    metaBadge.innerHTML = `Estimasi Realtime • Shift Masih Aktif`;
                    metaBadge.className = 'text-xs font-mono font-bold text-amber-900 bg-amber-50 px-3 py-1 rounded-xl border border-amber-200';
                }
            }

            if (!finalStocks || finalStocks.length === 0) {
                tbody.innerHTML = `
                    <tr>
                        <td colspan="7" class="py-8 text-center text-slate-400 text-xs">Belum ada data stok closing malam untuk tanggal ini.</td>
                    </tr>
                `;
                return;
            }

            tbody.innerHTML = finalStocks.map(item => {
                const totalUsed = item.usage_qty || 0;
                return `
                    <tr class="hover:bg-slate-50/50">
                        <td class="py-3 px-4 font-bold text-slate-800 flex items-center gap-2">
                            <span class="text-base">${item.image_emoji || '📦'}</span>
                            <span>${escapeHtml(item.name)}</span>
                        </td>
                        <td class="py-3 px-4 font-mono text-slate-500 text-[11px]">${escapeHtml(item.sku)}</td>
                        <td class="py-3 px-4 text-center font-bold text-slate-600">${escapeHtml(item.unit || 'pcs')}</td>
                        <td class="py-3 px-4 text-center font-semibold text-slate-700">${item.opening_qty}</td>
                        <td class="py-3 px-4 text-center font-bold text-indigo-700">${totalUsed}</td>
                        <td class="py-3 px-4 text-center font-black text-indigo-950 bg-indigo-50/40 text-sm">
                            ${item.closing_qty} <span class="text-[10px] text-slate-400 font-normal">${escapeHtml(item.unit || 'pcs')}</span>
                        </td>
                        <td class="py-3 px-4 text-center">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${isClosed ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}">
                                ${isClosed ? 'Terkunci 🔒' : 'Berjalan 🟢'}
                            </span>
                        </td>
                    </tr>
                `;
            }).join('');
        }

        function printSingleShiftReceipt(shiftId) {
            if (!currentDailyShiftReportData || !currentDailyShiftReportData.shifts) return;
            const s = currentDailyShiftReportData.shifts.find(x => x.id === shiftId);
            if (!s) {
                alert('Data shift tidak ditemukan.');
                return;
            }

            const branchName = s.branch_name || (state.currentBranch?.name || 'OUTLET');
            const diff = s.cash_difference || 0;
            const diffStr = (diff >= 0 ? '+' : '') + formatRupiah(diff);

            const itemsStr = (s.reconciled_items || []).map(it => 
                `  - ${it.name} (${it.sku}): Awal ${it.opening_qty} | Pakai ${it.usage_qty} | Sisa ${it.closing_qty} ${it.unit}`
            ).join('\n');

            const content = 
`========================================
       STRUK LAPORAN SHIFT KASIR        
========================================
Cabang     : ${branchName}
Shift      : ${s.shift_name} (${s.shift_type || 'SHIFT'})
Kasir      : ${s.cashier_name} (${s.cashier_nik || 'KASIR'})
Status     : ${s.status === 'CLOSED' ? 'SELESAI DITUTUP' : 'AKTIF'}
Mulai      : ${s.start_time}
Selesai    : ${s.end_time || '-'}
----------------------------------------
RINCIAN KEUANGAN KASIR:
- Modal Awal Kasir    : ${formatRupiah(s.initial_cash)}
- Penjualan Tunai     : ${formatRupiah(s.cash_sales)}
- Penjualan Non-Tunai : ${formatRupiah(s.non_cash_sales)}
  * QRIS              : ${formatRupiah(s.qris_sales)}
  * Transfer Bank     : ${formatRupiah(s.transfer_sales)}
  * Piutang Pelanggan : ${formatRupiah(s.piutang_sales)}
- Total Omzet Shift   : ${formatRupiah(s.total_sales)}
- Total Transaksi     : ${s.tx_count} Struk
----------------------------------------
AUDIT KAS LACI KASIR:
- Kas Terhitung Sistem: ${formatRupiah(s.expected_cash)}
- Kas Fisik Diserahkan: ${formatRupiah(s.actual_cash)}
- Selisih Kas         : ${diffStr}
----------------------------------------
REKONSILIASI STOK SHIFT:
${itemsStr || '  (Tidak ada item terlacak)'}
----------------------------------------
Catatan: ${s.shift_notes || '-'}
========================================
Dicetak: ${new Date().toLocaleString('id-ID')}
TTD Kasir: __________________
`;

            const win = window.open('', '_blank', 'width=450,height=600');
            win.document.write('<pre style="font-family:monospace;font-size:12px;padding:20px;">' + content + '</pre>');
            win.document.close();
            win.focus();
            setTimeout(() => { win.print(); }, 250);
        }

        function printDailyClosingSummaryReceipt() {
            if (!currentDailyShiftReportData || !currentDailyShiftReportData.daily_summary) {
                alert('Silakan muat laporan terlebih dahulu.');
                return;
            }
            const data = currentDailyShiftReportData;
            const ds = data.daily_summary;
            const branchName = state.currentBranch?.name || 'SEMUA CABANG';

            const shiftsStr = (data.shifts || []).map(s => 
                `[${s.shift_name}] ${s.cashier_name} | Omzet: ${formatRupiah(s.total_sales)} | Tunai: ${formatRupiah(s.cash_sales)} | Fisik: ${formatRupiah(s.actual_cash)}`
            ).join('\n');

            const stocksStr = (ds.final_stocks || []).map(st => 
                `  - ${st.name} (${st.sku}): Sisa Malam ${st.closing_qty} ${st.unit}`
            ).join('\n');

            const content = 
`========================================
    REKAP TUTUP TOKO HARIAN (SUMMARY)   
========================================
Cabang     : ${branchName}
Tanggal    : ${data.report_date}
Status     : ${ds.is_store_closed ? 'TUTUP TOKO SELESAI (MALAM)' : 'TOKO BERJALAN'}
Shift Final: Ditutup oleh ${ds.final_cashier_name || '-'} (${ds.final_closing_time || '-'})
----------------------------------------
KONSOLIDASI FINANSIAL (${ds.total_shifts} Shift):
- Total Omzet Gabungan: ${formatRupiah(ds.total_revenue)}
- Total Tunai Toko    : ${formatRupiah(ds.total_cash_sales)}
- Total Non-Tunai     : ${formatRupiah(ds.total_non_cash_sales)}
  * QRIS              : ${formatRupiah(ds.total_qris_sales)}
  * Transfer Bank     : ${formatRupiah(ds.total_transfer_sales)}
  * Piutang Pelanggan : ${formatRupiah(ds.total_piutang_sales)}
- Total Modal Awal    : ${formatRupiah(ds.total_initial_cash)}
- Total Kas Keluar    : - ${formatRupiah(ds.total_disbursements || 0)}
  * Beban Toko        : ${formatRupiah(ds.total_expenses || 0)}
  * Kasbon Karyawan   : ${formatRupiah(ds.total_kasbon || 0)}
  * Uang Makan        : ${formatRupiah(ds.total_meal_allowance || 0)}
- Total Kas Diserahkan: ${formatRupiah(ds.total_actual_cash)}
- Total Selisih Kas   : ${(ds.total_cash_difference >= 0 ? '+' : '') + formatRupiah(ds.total_cash_difference)}
- Total Transaksi     : ${ds.total_transactions} Struk
----------------------------------------
RINCIAN PER SHIFT:
${shiftsStr || '  (Tidak ada shift)'}
----------------------------------------
STOK AKHIR MALAM (TERKUNCI):
${stocksStr || '  (Tidak ada item terlacak)'}
========================================
Dicetak: ${new Date().toLocaleString('id-ID')}
Manager / Supervisor: __________________
`;

            const win = window.open('', '_blank', 'width=480,height=650');
            win.document.write('<pre style="font-family:monospace;font-size:12px;padding:20px;">' + content + '</pre>');
            win.document.close();
            win.focus();
            setTimeout(() => { win.print(); }, 250);
        }

        async function loadReceivablesReport() {
            try {
                const statusEl = document.getElementById('ar-filter-status');
                const startEl = document.getElementById('ar-start-date');
                const endEl = document.getElementById('ar-end-date');
                const kwEl = document.getElementById('ar-search-keyword');

                const status = statusEl ? statusEl.value : 'ALL';
                const start = startEl ? startEl.value : '';
                const end = endEl ? endEl.value : '';
                const keyword = kwEl ? encodeURIComponent(kwEl.value.trim()) : '';
                const branchId = state.currentBranch ? state.currentBranch.id : '';

                const res = await fetch(`api.php?action=get_receivables&branch_id=${branchId}&status=${status}&start_date=${start}&end_date=${end}&keyword=${keyword}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                // 1. Update KPI Cards
                const kpi = data.kpi || {};
                const totalReceivables = Number(kpi.total_receivables || 0);
                const totalPaid = Number(kpi.total_paid || 0);
                const totalOut = Number(kpi.total_outstanding || 0);
                const paidRate = totalReceivables > 0 ? Math.round((totalPaid / totalReceivables) * 100) : 0;

                const elKpiTotal = document.getElementById('ar-kpi-total');
                if (elKpiTotal) elKpiTotal.innerText = formatRupiah(totalReceivables);
                const elKpiCount = document.getElementById('ar-kpi-invoices-count');
                if (elKpiCount) elKpiCount.innerText = `${kpi.total_invoices || 0} Total Faktur`;

                const elKpiPaid = document.getElementById('ar-kpi-paid');
                if (elKpiPaid) elKpiPaid.innerText = formatRupiah(totalPaid);
                const elKpiPaidRate = document.getElementById('ar-kpi-paid-rate');
                if (elKpiPaidRate) elKpiPaidRate.innerText = `Tertagih: ${paidRate}%`;

                const elKpiOut = document.getElementById('ar-kpi-outstanding');
                if (elKpiOut) elKpiOut.innerText = formatRupiah(totalOut);

                const elKpiUnpaid = document.getElementById('ar-kpi-unpaid-count');
                if (elKpiUnpaid) elKpiUnpaid.innerText = `${kpi.count_unpaid || 0} Faktur`;

                const elKpiOverdue = document.getElementById('ar-kpi-overdue-count');
                if (elKpiOverdue) elKpiOverdue.innerText = `${kpi.count_overdue || 0} Faktur`;

                const countLabel = document.getElementById('ar-table-count-label');
                if (countLabel) countLabel.innerText = `Menampilkan ${(data.receivables || []).length} faktur`;

                // 2. Render Tabel Piutang Usaha
                const tbody = document.getElementById('receivables-table-body');
                if (!tbody) return;

                if (!data.receivables || data.receivables.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="9" class="py-8 text-center text-slate-400">Tidak ada faktur piutang yang cocok dengan filter.</td></tr>`;
                    return;
                }

                tbody.innerHTML = data.receivables.map(r => {
                    const total = Number(r.total_amount || 0);
                    const paid = Number(r.paid_amount || 0);
                    const remaining = Number(r.remaining_amount || 0);
                    const isOverdue = r.is_overdue == 1;
                    const aging = Number(r.aging_days || 0);

                    // Badge Kategori Pelanggan
                    const catBadge = (r.customer_category === 'MITRA')
                        ? '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-purple-100 text-purple-700">🤝 MITRA</span>'
                        : (r.customer_category === 'RESELLER'
                            ? '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-blue-100 text-blue-700">📦 RESELLER</span>'
                            : (r.customer_category === 'MEMBER'
                                ? '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800">⭐ MEMBER</span>'
                                : '<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-600">RITEL</span>'));

                    // Badge Status Piutang
                    let statusBadge = '<span class="px-2.5 py-1 rounded-lg text-[10px] font-black bg-rose-100 text-rose-800 border border-rose-200">BELUM LUNAS</span>';
                    if (r.status === 'SEBAGIAN') {
                        statusBadge = '<span class="px-2.5 py-1 rounded-lg text-[10px] font-black bg-amber-100 text-amber-900 border border-amber-300">SEBAGIAN (CICILAN)</span>';
                    } else if (r.status === 'LUNAS') {
                        statusBadge = '<span class="px-2.5 py-1 rounded-lg text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300">LUNAS PENUH</span>';
                    }

                    // Aging & Due Date Indicator
                    let agingHtml = `<span class="text-slate-600 font-medium">${r.due_date || '-'}</span>`;
                    if (r.status !== 'LUNAS') {
                        if (isOverdue) {
                            agingHtml += `<br><span class="inline-block mt-0.5 px-1.5 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-700 border border-rose-200">⚠️ LEWAT JATUH TEMPO (${aging} hr)</span>`;
                        } else {
                            agingHtml += `<br><span class="inline-block mt-0.5 px-1.5 py-0.5 rounded text-[10px] font-semibold bg-slate-100 text-slate-600">Umur Piutang: ${aging} hr</span>`;
                        }
                    } else {
                        agingHtml += `<br><span class="inline-block mt-0.5 px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-50 text-emerald-700">Selesai Dibayar</span>`;
                    }

                    // Tombol Aksi
                    const payBtnDisabled = (r.status === 'LUNAS' || remaining <= 0);
                    const payBtnCls = payBtnDisabled
                        ? 'p-1 px-2.5 text-[11px] bg-slate-100 text-slate-400 rounded-lg font-bold cursor-not-allowed flex items-center space-x-1'
                        : 'p-1 px-2.5 text-[11px] bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg font-bold shadow-sm transition-colors flex items-center space-x-1';

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-3 font-mono font-bold">
                                <button onclick="openReceivableDetailModal(${r.id})" class="text-indigo-600 hover:text-indigo-900 hover:underline flex items-center space-x-1 text-left" title="Lihat detail faktur piutang">
                                    <span>${r.invoice_number}</span>
                                    <i data-lucide="external-link" class="w-3 h-3 text-indigo-400"></i>
                                </button>
                                <span class="text-[10px] text-slate-400 font-sans block">${r.branch_name}</span>
                            </td>
                            <td class="py-3 px-3">
                                <div class="font-bold text-slate-800">${r.customer_name}</div>
                                <div class="mt-0.5 flex items-center gap-1.5">${catBadge} <span class="text-[10px] text-slate-400 font-mono">${r.customer_phone || '-'}</span></div>
                            </td>
                            <td class="py-3 px-3 text-slate-500 font-mono text-[11px]">${r.created_at ? r.created_at.substring(0, 10) : '-'}</td>
                            <td class="py-3 px-3 font-mono text-[11px]">${agingHtml}</td>
                            <td class="py-3 px-3 text-right font-bold text-slate-800 font-mono">${formatRupiah(total)}</td>
                            <td class="py-3 px-3 text-right font-bold text-emerald-700 font-mono">${formatRupiah(paid)}</td>
                            <td class="py-3 px-3 text-right font-black ${remaining > 0 ? 'text-amber-700' : 'text-slate-400'} font-mono">${formatRupiah(remaining)}</td>
                            <td class="py-3 px-3 text-center">${statusBadge}</td>
                            <td class="py-3 px-3 text-center">
                                <div class="flex items-center justify-center space-x-1.5">
                                    <button onclick="openReceivableDetailModal(${r.id})" class="p-1 px-2 text-[11px] bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-lg font-bold flex items-center space-x-1" title="Lihat Detail Transaksi">
                                        <i data-lucide="eye" class="w-3.5 h-3.5"></i>
                                        <span>Detail</span>
                                    </button>
                                    <button onclick="openPayReceivableModal(${r.id}, ${remaining}, '${r.invoice_number}')" ${payBtnDisabled ? 'disabled' : ''} class="${payBtnCls}" title="${payBtnDisabled ? 'Faktur sudah lunas' : 'Catat cicilan/pelunasan'}">
                                        <i data-lucide="wallet" class="w-3.5 h-3.5"></i>
                                        <span>Bayar</span>
                                    </button>
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('');
                lucide.createIcons();
            } catch (err) {
                console.error("loadReceivablesReport error:", err);
            }
        }

        function resetReceivablesFilter() {
            const statusEl = document.getElementById('ar-filter-status');
            const startEl = document.getElementById('ar-start-date');
            const endEl = document.getElementById('ar-end-date');
            const kwEl = document.getElementById('ar-search-keyword');
            if (statusEl) statusEl.value = 'ALL';
            if (startEl) startEl.value = '';
            if (endEl) endEl.value = '';
            if (kwEl) kwEl.value = '';
            loadReceivablesReport();
        }

        let currentActiveReceivable = null;

        async function openReceivableDetailModal(receivableId) {
            try {
                const res = await fetch(`api.php?action=get_receivable_detail&id=${receivableId}`);
                const data = await res.json();
                if (!data.success) {
                    alert(data.message || 'Gagal memuat detail piutang');
                    return;
                }

                currentActiveReceivable = data;
                const rec = data.receivable;
                const items = data.items || [];
                const payments = data.payments || [];

                document.getElementById('rd-invoice-no').innerText = rec.invoice_number;
                document.getElementById('rd-customer-name').innerText = rec.customer_name;
                document.getElementById('rd-customer-cat').innerText = `KATEGORI: ${rec.customer_category} • TELP: ${rec.customer_phone || '-'}`;
                document.getElementById('rd-branch-name').innerText = `${rec.branch_name} (${rec.cashier_name || 'Kasir'})`;
                document.getElementById('rd-sale-date').innerText = `Tgl Transaksi: ${rec.created_at || '-'}`;
                document.getElementById('rd-due-date').innerText = rec.due_date || '-';

                const agingEl = document.getElementById('rd-aging-badge');
                if (rec.status === 'LUNAS') {
                    agingEl.innerText = 'LUNAS';
                    agingEl.className = 'inline-block mt-0.5 px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800';
                } else if (rec.is_overdue == 1) {
                    agingEl.innerText = `⚠️ LEWAT TEMPO (${rec.aging_days} hari)`;
                    agingEl.className = 'inline-block mt-0.5 px-2 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-800';
                } else {
                    agingEl.innerText = `Umur Piutang: ${rec.aging_days || 0} hari`;
                    agingEl.className = 'inline-block mt-0.5 px-2 py-0.5 rounded text-[10px] font-bold bg-slate-200 text-slate-700';
                }

                const statusEl = document.getElementById('rd-status-badge');
                if (rec.status === 'LUNAS') {
                    statusEl.innerText = 'LUNAS PENUH';
                    statusEl.className = 'inline-block mt-0.5 px-2.5 py-1 rounded-lg text-xs font-black bg-emerald-100 text-emerald-800';
                } else if (rec.status === 'SEBAGIAN') {
                    statusEl.innerText = 'SEBAGIAN (CICILAN)';
                    statusEl.className = 'inline-block mt-0.5 px-2.5 py-1 rounded-lg text-xs font-black bg-amber-100 text-amber-900';
                } else {
                    statusEl.innerText = 'BELUM LUNAS';
                    statusEl.className = 'inline-block mt-0.5 px-2.5 py-1 rounded-lg text-xs font-black bg-rose-100 text-rose-800';
                }

                document.getElementById('rd-total-amount').innerText = formatRupiah(rec.total_amount);
                document.getElementById('rd-paid-amount').innerText = formatRupiah(rec.paid_amount);
                document.getElementById('rd-remaining-amount').innerText = formatRupiah(rec.remaining_amount);

                // Items list
                document.getElementById('rd-items-body').innerHTML = items.map(it => `
                    <tr>
                        <td class="py-2 px-3 font-semibold text-slate-800">${it.product_name}</td>
                        <td class="py-2 px-3 text-center font-bold text-slate-700">${it.qty}</td>
                        <td class="py-2 px-3 text-right font-mono text-slate-600">${formatRupiah(it.unit_price)}</td>
                        <td class="py-2 px-3 text-right font-mono font-bold text-slate-800">${formatRupiah(it.subtotal_price)}</td>
                    </tr>
                `).join('') || `<tr><td colspan="4" class="text-center py-3 text-slate-400">Tidak ada item tercatat</td></tr>`;

                // Payments list
                document.getElementById('rd-payments-count').innerText = `${payments.length} Kali Pembayaran`;
                document.getElementById('rd-payments-body').innerHTML = payments.map(p => `
                    <tr>
                        <td class="py-2 px-3 font-mono text-slate-700">${p.payment_date}</td>
                        <td class="py-2 px-3"><span class="px-2 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-700">${p.payment_method}</span></td>
                        <td class="py-2 px-3 text-slate-600 font-mono text-[11px]">${p.reference_no || '-'} <span class="text-slate-400">(${p.cashier_name || 'Kasir'})</span></td>
                        <td class="py-2 px-3 text-slate-500 italic text-[11px]">${p.notes || '-'}</td>
                        <td class="py-2 px-3 text-right font-mono font-bold text-emerald-700">${formatRupiah(p.amount)}</td>
                    </tr>
                `).join('') || `<tr><td colspan="5" class="text-center py-4 text-slate-400">Belum ada catatan pembayaran cicilan</td></tr>`;

                const notesEl = document.getElementById('rd-notes-text');
                if (notesEl) notesEl.innerText = rec.notes ? `Catatan Faktur: ${rec.notes}` : '';

                const actionPayBtn = document.getElementById('rd-btn-action-pay');
                if (actionPayBtn) {
                    if (rec.status === 'LUNAS' || Number(rec.remaining_amount) <= 0) {
                        actionPayBtn.classList.add('hidden');
                    } else {
                        actionPayBtn.classList.remove('hidden');
                        actionPayBtn.onclick = () => {
                            closeReceivableDetailModal();
                            openPayReceivableModal(rec.id, rec.remaining_amount, rec.invoice_number);
                        };
                    }
                }

                document.getElementById('receivable-detail-modal').classList.remove('hidden');
                lucide.createIcons();
            } catch (err) {
                console.error("openReceivableDetailModal error:", err);
            }
        }

        function closeReceivableDetailModal() {
            const modal = document.getElementById('receivable-detail-modal');
            if (modal) modal.classList.add('hidden');
        }

        let currentPayMaxRemaining = 0;

        function openPayReceivableModal(receivableId, remainingAmount, invoiceNumber) {
            currentPayMaxRemaining = Number(remainingAmount || 0);
            document.getElementById('pay-modal-receivable-id').value = receivableId;
            document.getElementById('pay-modal-invoice-no').innerText = invoiceNumber;
            document.getElementById('pay-modal-remaining-display').innerText = formatRupiah(currentPayMaxRemaining);
            document.getElementById('pay-modal-date').value = new Date().toISOString().split('T')[0];
            document.getElementById('pay-modal-amount').value = currentPayMaxRemaining;
            document.getElementById('pay-modal-method').value = 'CASH';
            document.getElementById('pay-modal-ref').value = '';
            document.getElementById('pay-modal-notes').value = '';

            document.getElementById('receivable-pay-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closePayReceivableModal() {
            const modal = document.getElementById('receivable-pay-modal');
            if (modal) modal.classList.add('hidden');
        }

        function setPayAmountFull() {
            document.getElementById('pay-modal-amount').value = currentPayMaxRemaining;
        }

        async function submitPayReceivableForm(e) {
            e.preventDefault();
            const receivableId = parseInt(document.getElementById('pay-modal-receivable-id').value);
            const amount = parseFloat(document.getElementById('pay-modal-amount').value) || 0;
            const paymentDate = document.getElementById('pay-modal-date').value;
            const paymentMethod = document.getElementById('pay-modal-method').value;
            const ref = document.getElementById('pay-modal-ref').value.trim();
            const notes = document.getElementById('pay-modal-notes').value.trim();
            const cashierId = state.currentUser ? state.currentUser.id : 3;

            if (amount <= 0) {
                alert('Nominal pembayaran wajib lebih dari Rp 0');
                return;
            }
            if (amount > currentPayMaxRemaining) {
                alert(`Nominal pembayaran (${formatRupiah(amount)}) tidak boleh melebihi sisa tagihan (${formatRupiah(currentPayMaxRemaining)})`);
                return;
            }

            const submitBtn = document.getElementById('pay-modal-submit-btn');
            submitBtn.disabled = true;
            submitBtn.innerText = 'Memproses...';

            try {
                const res = await fetch('api.php?action=pay_receivable', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        receivable_id: receivableId,
                        amount: amount,
                        payment_date: paymentDate,
                        payment_method: paymentMethod,
                        reference_no: ref,
                        notes: notes,
                        cashier_user_id: cashierId
                    })
                });
                const data = await res.json();
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="check-circle" class="w-4 h-4"></i><span>Konfirmasi Bayar</span>`;

                if (data.success) {
                    alert(data.message);
                    closePayReceivableModal();
                    await loadReceivablesReport();
                    if (state.currentTab === 'pnl') await loadProfitLoss();
                } else {
                    alert('Gagal: ' + (data.message || data.error));
                }
            } catch (err) {
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="check-circle" class="w-4 h-4"></i><span>Konfirmasi Bayar</span>`;
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // 3. EMPLOYEE SELF SERVICE (ESS)
        // ==========================================
        function isManagerOrSuperAdminUser(user) {
            const u = user || state.currentUser || state.loggedInUser;
            if (!u || !u.role) return false;
            const r = String(u.role).toUpperCase().trim();
            return ['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(r);
        }

        async function loadEssData() {
            const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
            const uId = curUser.id || 3;
            const bId = state.currentBranch ? state.currentBranch.id : 1;
            const isManager = isManagerOrSuperAdminUser(curUser);

            const res = await fetch(`api.php?action=ess_get_data&user_id=${uId}&branch_id=${bId}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('ess-emp-name').innerText = data.user.name;
            document.getElementById('ess-emp-role').innerText = `${data.user.role} • NIK: ${data.user.nik} • ${state.currentBranch.name}`;
            document.getElementById('ess-commission-amount').innerText = formatRupiah(data.commission.commission_earned);
            document.getElementById('ess-commission-details').innerText = `Rate: ${data.commission.rate_percent}% • Total Omzet: ${formatRupiah(data.commission.total_omzet)}`;

            const todayStatusEl = document.getElementById('ess-today-status');
            const todayTimeEl = document.getElementById('ess-today-time');
            if (data.today_attendance) {
                todayStatusEl.innerText = data.today_attendance.clock_out ? 'SELESAI (CLOCK-OUT)' : 'SUDAH CLOCK-IN';
                todayStatusEl.className = 'px-2 py-0.5 bg-emerald-200 text-emerald-900 rounded-md font-bold';
                todayTimeEl.innerText = `Masuk: ${data.today_attendance.clock_in} ${data.today_attendance.clock_out ? '• Pulang: ' + data.today_attendance.clock_out : ''}`;
            } else {
                todayStatusEl.innerText = 'BELUM CLOCK-IN';
                todayStatusEl.className = 'px-2 py-0.5 bg-rose-200 text-rose-900 rounded-md font-bold';
                todayTimeEl.innerText = 'Silakan tekan tombol Clock-In di atas.';
            }

            document.getElementById('ess-attendance-history').innerHTML = data.attendance_history.map(ah => `
                <div class="flex justify-between items-center p-2.5 bg-slate-50 rounded-xl border border-slate-100">
                    <div>
                        <span class="font-bold text-slate-700">${ah.clock_in}</span>
                        <span class="text-[10px] text-slate-400 block">${ah.branch_name} (${ah.distance_meters}m)</span>
                    </div>
                    <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${ah.status === 'ON_TIME' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}">${ah.status}</span>
                </div>
            `).join('') || `<p class="text-slate-400">Belum ada riwayat</p>`;

            const titleEl = document.getElementById('ess-reimburse-table-title');
            if (titleEl) {
                titleEl.innerText = isManager ? 'Daftar Klaim Toko & Aksi Pencairan (Manager / Finance):' : 'Riwayat Pengajuan Klaim Reimbursement Saya:';
            }

            document.getElementById('ess-reimburse-table-body').innerHTML = data.branch_reimbursements.map(r => `
                <tr class="hover:bg-slate-50">
                    <td class="py-2.5 px-2.5 font-semibold text-slate-800">${r.employee_name}</td>
                    <td class="py-2.5 px-2.5 text-slate-600">${r.category}<br><span class="text-[10px] text-slate-400">${r.description}</span></td>
                    <td class="py-2.5 px-2.5 text-right font-bold text-slate-800">${formatRupiah(r.amount)}</td>
                    <td class="py-2.5 px-2.5"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${r.status === 'DISBURSED' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}">${r.status}</span></td>
                    <td class="py-2.5 px-2.5 text-center">
                        ${r.status !== 'DISBURSED' ? (
                            isManager ? `
                                <button onclick="disburseReimbursement(${r.id})" class="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold shadow-sm">Cairkan & Catat</button>
                            ` : `<span class="px-2 py-0.5 bg-amber-100 text-amber-800 rounded-full text-[10px] font-semibold">⏳ Menunggu</span>`
                        ) : `<span class="text-emerald-700 font-bold text-[10px]">✓ Dicairkan</span>`}
                    </td>
                </tr>
            `).join('') || `<tr><td colspan="5" class="text-center py-3 text-slate-400">Belum ada klaim</td></tr>`;
            lucide.createIcons();
        }

        function setSimulatedGps(isInside) {
            state.simulatedInsideShop = isInside;
            const distEl = document.getElementById('ess-geo-distance');
            if (isInside) {
                distEl.innerText = '12.5 Meter (Valid di Toko)';
                distEl.className = 'font-bold text-emerald-600 font-mono text-sm';
            } else {
                distEl.innerText = '250.0 Meter (Di Luar Radius!)';
                distEl.className = 'font-bold text-rose-600 font-mono text-sm';
            }
        }

        async function submitClockIn() {
            const b = state.currentBranch;
            const u = state.currentUser;
            const lat = state.simulatedInsideShop ? b.latitude + 0.00008 : b.latitude + 0.003;
            const lng = state.simulatedInsideShop ? b.longitude + 0.00008 : b.longitude + 0.003;
            const res = await fetch('api.php?action=ess_clock_in', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ user_id: u.id, branch_id: b.id, latitude: lat, longitude: lng })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadEssData();
        }

        async function submitClockOut() {
            const u = state.currentUser;
            const res = await fetch('api.php?action=ess_clock_out', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ user_id: u.id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadEssData();
        }

        async function submitReimbursement() {
            const cat = document.getElementById('reimburse-category').value;
            const amount = parseFloat(document.getElementById('reimburse-amount').value) || 0;
            const desc = document.getElementById('reimburse-notes').value;
            if (amount <= 0) { alert('Nominal tidak valid'); return; }

            const res = await fetch('api.php?action=ess_submit_reimbursement', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ user_id: state.currentUser.id, branch_id: state.currentBranch.id, category: cat, amount, description: desc })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                document.getElementById('reimburse-amount').value = '';
                document.getElementById('reimburse-notes').value = '';
                loadEssData();
            }
        }

        async function disburseReimbursement(id) {
            if (!confirm('Cairkan reimbursement? Nominal akan OTOMATIS tercatat ke Beban Laba Rugi!')) return;
            const res = await fetch('api.php?action=ess_approve_reimbursement', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ reimbursement_id: id, approval_action: 'DISBURSE' })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadEssData();
        }

        // ==========================================
        // 3b. ESS SUBTABS CONTROLLER & LOGIC
        // ==========================================
        let essActiveSubtab = 'presensi';
        let essWorkShiftsList = [];
        let essCurrentPayslipData = null;

        function setEssSubtab(subtab) {
            essActiveSubtab = subtab;
            const subtabs = ['presensi', 'schedules', 'swaps', 'leaves', 'attendance', 'payslip', 'loans'];
            subtabs.forEach(st => {
                const container = document.getElementById(`ess-subtab-${st}`);
                const btn = document.getElementById(`ess-subtab-btn-${st}`);
                if (container) container.classList.toggle('hidden', st !== subtab);
                if (btn) {
                    if (st === subtab) {
                        btn.className = 'px-4 py-2.5 rounded-xl bg-indigo-600 text-white shadow-sm flex items-center space-x-2 transition-all';
                    } else {
                        btn.className = 'px-4 py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center space-x-2 transition-all';
                    }
                }
            });

            if (subtab === 'presensi') loadEssData();
            if (subtab === 'schedules') {
                loadWorkShifts();
                initRosterControls();
                loadMonthlySchedules();
            }
            if (subtab === 'swaps') {
                populateSwapPeerDropdown();
                loadShiftSwaps();
            }
            if (subtab === 'leaves') loadLeaveRequests();
            if (subtab === 'attendance') {
                initAttendanceControls();
                loadAttendanceReport();
            }
            if (subtab === 'payslip') {
                initPayslipControls();
                loadEmployeePayslip();
            }
            if (subtab === 'loans') loadSalaryLoans();

            lucide.createIcons();
        }

        // --- 1. Master Jam Kerja (Work Shifts CRUD) ---
        async function loadWorkShifts() {
            try {
                const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
                const isManager = isManagerOrSuperAdminUser(curUser);
                const addBtn = document.getElementById('btn-add-work-shift');
                if (addBtn) addBtn.style.display = isManager ? '' : 'none';

                const res = await fetch('api.php?action=get_work_shifts');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
                essWorkShiftsList = data.shifts || [];

                const container = document.getElementById('ess-work-shifts-grid');
                if (!container) return;

                container.innerHTML = essWorkShiftsList.map(ws => `
                    <div class="p-3.5 rounded-2xl border ${ws.is_day_off ? 'bg-slate-50 border-slate-200' : 'bg-white border-slate-200'} shadow-2xs space-y-2 relative">
                        <div class="flex items-center justify-between">
                            <span class="px-2 py-0.5 rounded-lg text-[10px] font-black font-mono text-white" style="background-color: ${ws.color_tag || '#3b82f6'}">${ws.code}</span>
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${ws.is_active ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-500'}">
                                ${ws.is_active ? 'Aktif' : 'Nonaktif'}
                            </span>
                        </div>
                        <div>
                            <h4 class="font-bold text-slate-800 text-xs">${ws.name}</h4>
                            <p class="font-mono text-xs text-slate-600 font-bold mt-0.5">
                                ${ws.is_day_off ? '🏖️ HARI LIBUR / OFF' : `🕒 ${ws.start_time} - ${ws.end_time}`}
                            </p>
                            ${!ws.is_day_off ? `<p class="text-[10px] text-slate-400 mt-0.5">Toleransi: ${ws.late_tolerance_mins} menit</p>` : ''}
                        </div>
                        ${isManager ? `
                        <div class="flex items-center justify-end space-x-1 pt-2 border-t border-slate-100">
                            <button onclick='openWorkShiftModal(${JSON.stringify(ws)})' class="p-1 text-slate-500 hover:text-indigo-600 rounded-lg text-xs font-semibold flex items-center space-x-1">
                                <i data-lucide="edit" class="w-3.5 h-3.5"></i>
                                <span>Edit</span>
                            </button>
                            <button onclick="deleteWorkShift(${ws.id})" class="p-1 text-slate-400 hover:text-rose-600 rounded-lg text-xs font-semibold">
                                <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                            </button>
                        </div>
                        ` : ''}
                    </div>
                `).join('') || `<p class="text-xs text-slate-400 col-span-4">Belum ada shift kerja terdaftar</p>`;

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function openWorkShiftModal(shift = null) {
            const modal = document.getElementById('work-shift-modal');
            const title = document.getElementById('ws-modal-title');
            if (!modal) return;

            if (shift) {
                title.innerText = 'Edit Shift Jam Kerja';
                document.getElementById('ws-id').value = shift.id || '';
                document.getElementById('ws-code').value = shift.code || '';
                document.getElementById('ws-color').value = shift.color_tag || '#3b82f6';
                document.getElementById('ws-name').value = shift.name || '';
                document.getElementById('ws-start-time').value = shift.start_time || '07:00';
                document.getElementById('ws-end-time').value = shift.end_time || '15:00';
                document.getElementById('ws-tolerance').value = shift.late_tolerance_mins ?? 15;
                document.getElementById('ws-is-active').value = shift.is_active ?? 1;
                document.getElementById('ws-is-day-off').checked = shift.is_day_off == 1;
            } else {
                title.innerText = 'Tambah Shift Jam Kerja Baru';
                document.getElementById('ws-id').value = '';
                document.getElementById('ws-code').value = '';
                document.getElementById('ws-color').value = '#3b82f6';
                document.getElementById('ws-name').value = '';
                document.getElementById('ws-start-time').value = '07:00';
                document.getElementById('ws-end-time').value = '15:00';
                document.getElementById('ws-tolerance').value = 15;
                document.getElementById('ws-is-active').value = '1';
                document.getElementById('ws-is-day-off').checked = false;
            }
            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeWorkShiftModal() {
            const modal = document.getElementById('work-shift-modal');
            if (modal) modal.classList.add('hidden');
        }

        async function saveWorkShiftForm(e) {
            e.preventDefault();
            const payload = {
                id: document.getElementById('ws-id').value || null,
                code: document.getElementById('ws-code').value,
                color_tag: document.getElementById('ws-color').value,
                name: document.getElementById('ws-name').value,
                start_time: document.getElementById('ws-start-time').value,
                end_time: document.getElementById('ws-end-time').value,
                late_tolerance_mins: parseInt(document.getElementById('ws-tolerance').value) || 15,
                is_active: parseInt(document.getElementById('ws-is-active').value) || 1,
                is_day_off: document.getElementById('ws-is-day-off').checked ? 1 : 0
            };

            const res = await fetch('api.php?action=save_work_shift', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeWorkShiftModal();
                loadWorkShifts();
                loadMonthlySchedules();
            }
        }

        async function deleteWorkShift(id) {
            if (!confirm('Hapus atau nonaktifkan shift kerja ini?')) return;
            const res = await fetch('api.php?action=delete_work_shift', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadWorkShifts();
                loadMonthlySchedules();
            }
        }

        // --- 2. Roster Jadwal Kerja Bulanan ---
        function initRosterControls() {
            const bSelect = document.getElementById('ess-roster-branch-select');
            const mInput = document.getElementById('ess-roster-month-input');
            if (bSelect && state.branches.length > 0 && bSelect.children.length === 0) {
                bSelect.innerHTML = state.branches.map(b => `<option value="${b.id}" ${b.id === state.currentBranch.id ? 'selected' : ''}>${b.name}</option>`).join('');
            }
            if (mInput && !mInput.value) {
                const now = new Date();
                const mStr = now.toISOString().slice(0, 7);
                mInput.value = mStr;
            }
        }

        async function loadMonthlySchedules() {
            const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
            const isManager = isManagerOrSuperAdminUser(curUser);
            const bId = document.getElementById('ess-roster-branch-select')?.value || state.currentBranch.id;
            const mVal = document.getElementById('ess-roster-month-input')?.value || new Date().toISOString().slice(0, 7);

            const impBtn = document.getElementById('btn-import-schedule');
            if (impBtn) impBtn.style.display = isManager ? '' : 'none';
            const holBtn = document.getElementById('btn-holiday-setter');
            if (holBtn) holBtn.style.display = isManager ? '' : 'none';

            try {
                const res = await fetch(`api.php?action=get_monthly_schedules&branch_id=${bId}&month=${mVal}&user_id=${curUser.id}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const thead = document.getElementById('ess-roster-table-head');
                const tbody = document.getElementById('ess-roster-table-body');
                if (!thead || !tbody) return;

                const daysCount = data.days_in_month || 31;
                const employees = data.employees || [];
                const schedules = data.schedules || [];

                // Map schedules: user_id -> date -> sched
                const schedMap = {};
                schedules.forEach(s => {
                    if (!schedMap[s.user_id]) schedMap[s.user_id] = {};
                    schedMap[s.user_id][s.shift_date] = s;
                });

                // Render Header
                let thHtml = `<tr>
                    <th class="py-2.5 px-3 sticky left-0 bg-slate-100 z-10 w-44 min-w-[170px] border-r border-slate-200">Karyawan / Tanggal</th>`;
                for (let d = 1; d <= daysCount; d++) {
                    const dStr = String(d).padStart(2, '0');
                    const fullDate = `${mVal}-${dStr}`;
                    const dayName = new Date(fullDate).toLocaleDateString('id-ID', { weekday: 'narrow' });
                    const isSun = new Date(fullDate).getDay() === 0;
                    thHtml += `<th class="py-2 px-1.5 text-center min-w-[38px] border-r border-slate-200 ${isSun ? 'bg-rose-50 text-rose-700' : ''}">
                        <span class="block text-[10px] text-slate-400 font-semibold">${dayName}</span>
                        <span>${d}</span>
                    </th>`;
                }
                thHtml += `</tr>`;
                thead.innerHTML = thHtml;

                // Render Body
                if (employees.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="${daysCount + 1}" class="text-center py-6 text-slate-400">Belum ada jadwal untuk Anda di periode ini</td></tr>`;
                    return;
                }

                let tbHtml = '';
                employees.forEach(emp => {
                    tbHtml += `<tr class="hover:bg-slate-50/80 transition-colors">
                        <td class="py-2 px-3 sticky left-0 bg-white z-10 border-r border-slate-200 shadow-xs">
                            <span class="font-bold text-slate-800 block truncate max-w-[150px]">${emp.name}</span>
                            <span class="text-[10px] text-slate-400 font-mono">${emp.nik} &bull; ${emp.role}</span>
                        </td>`;
                    for (let d = 1; d <= daysCount; d++) {
                        const dStr = String(d).padStart(2, '0');
                        const fullDate = `${mVal}-${dStr}`;
                        const isSun = new Date(fullDate).getDay() === 0;
                        const cellSched = schedMap[emp.id] ? schedMap[emp.id][fullDate] : null;

                        let badgeCode = cellSched ? (cellSched.shift_code || 'S1') : (isSun ? 'OFF' : '-');
                        let badgeColor = cellSched ? (cellSched.color_tag || '#3b82f6') : (isSun ? '#94a3b8' : '#e2e8f0');
                        let isOff = cellSched ? (cellSched.is_holiday == 1 || cellSched.shift_is_day_off == 1) : isSun;
                        let textColor = isOff ? 'text-slate-600' : 'text-white';
                        let bgColor = isOff ? 'bg-slate-200' : '';

                        tbHtml += `<td class="p-1 text-center border-r border-slate-200 ${isSun ? 'bg-rose-50/30' : ''}">
                            <button ${isManager ? `onclick="openSingleScheduleModal(${emp.id}, '${fullDate}', '${emp.name}', ${cellSched ? cellSched.work_shift_id : null})"` : `onclick="void(0)"`}
                                    class="w-full py-1 rounded text-[10px] font-black font-mono shadow-2xs ${isManager ? 'hover:scale-105 cursor-pointer' : 'cursor-default'} transition-transform ${textColor} ${bgColor}"
                                    style="${!isOff ? `background-color: ${badgeColor};` : ''}"
                                    title="${cellSched ? `${cellSched.shift_name} (${cellSched.start_time}-${cellSched.end_time})` : (isManager ? 'Klik untuk atur shift' : 'Libur / Tidak Terjadwal')}">
                                ${badgeCode}
                            </button>
                        </td>`;
                    }
                    tbHtml += `</tr>`;
                });
                tbody.innerHTML = tbHtml;
                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function openSingleScheduleModal(userId, date, empName, currentShiftId) {
            const modal = document.getElementById('single-schedule-edit-modal');
            if (!modal) return;
            document.getElementById('sched-cell-user-id').value = userId;
            document.getElementById('sched-cell-date').value = date;
            document.getElementById('sched-cell-modal-sub').innerText = `Karyawan: ${empName} (${date})`;

            const select = document.getElementById('sched-cell-shift-select');
            select.innerHTML = essWorkShiftsList.map(ws => `
                <option value="${ws.id}" ${ws.id == currentShiftId ? 'selected' : ''}>
                    ${ws.code} - ${ws.name} (${ws.start_time} - ${ws.end_time})
                </option>
            `).join('');

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeSingleScheduleModal() {
            document.getElementById('single-schedule-edit-modal')?.classList.add('hidden');
        }

        async function saveSingleScheduleForm(e) {
            e.preventDefault();
            const bId = document.getElementById('ess-roster-branch-select')?.value || state.currentBranch.id;
            const uId = document.getElementById('sched-cell-user-id').value;
            const date = document.getElementById('sched-cell-date').value;
            const shiftId = document.getElementById('sched-cell-shift-select').value;
            const notes = document.getElementById('sched-cell-notes').value;

            const res = await fetch('api.php?action=save_single_schedule', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ branch_id: bId, user_id: uId, shift_date: date, work_shift_id: shiftId, notes })
            });
            const data = await res.json();
            if (data.success) {
                closeSingleScheduleModal();
                loadMonthlySchedules();
            } else {
                alert(data.message || data.error);
            }
        }

        function exportMonthlySchedules() {
            const bId = document.getElementById('ess-roster-branch-select')?.value || state.currentBranch.id;
            const mVal = document.getElementById('ess-roster-month-input')?.value || new Date().toISOString().slice(0, 7);
            window.location.href = `api.php?action=export_monthly_schedules&branch_id=${bId}&month=${mVal}&download=1`;
        }

        function openImportScheduleModal() {
            document.getElementById('import-schedule-modal')?.classList.remove('hidden');
        }

        function closeImportScheduleModal() {
            document.getElementById('import-schedule-modal')?.classList.add('hidden');
        }

        function handleScheduleFileSelect(event) {
            const file = event.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = function(e) {
                document.getElementById('import-sched-text').value = e.target.result;
            };
            reader.readAsText(file);
        }

        async function submitImportSchedule(e) {
            e.preventDefault();
            const bId = document.getElementById('ess-roster-branch-select')?.value || state.currentBranch.id;
            const csvText = document.getElementById('import-sched-text').value;

            if (!csvText.trim()) {
                alert('Silakan pilih file CSV atau tempel teks data CSV terlebih dahulu.');
                return;
            }

            const res = await fetch('api.php?action=import_monthly_schedules', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ branch_id: bId, csv_data: csvText })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeImportScheduleModal();
                loadMonthlySchedules();
            }
        }

        function openHolidaySetterModal() {
            document.getElementById('holiday-setter-modal')?.classList.remove('hidden');
        }

        function closeHolidaySetterModal() {
            document.getElementById('holiday-setter-modal')?.classList.add('hidden');
        }

        async function submitHolidaySetter(e) {
            e.preventDefault();
            const bId = document.getElementById('ess-roster-branch-select')?.value || state.currentBranch.id;
            const date = document.getElementById('holiday-date-input').value;
            const notes = document.getElementById('holiday-notes-input').value;

            const res = await fetch('api.php?action=set_monthly_holidays', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ branch_id: bId, dates: [date], notes })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeHolidaySetterModal();
                loadMonthlySchedules();
            }
        }

        // --- 3. Tukar Jadwal (Shift Swap) ---
        function populateSwapPeerDropdown() {
            const select = document.getElementById('swap-target-user');
            if (!select) return;
            const curUserId = state.currentUser ? state.currentUser.id : 3;
            const peers = (state.users || []).filter(u => u.id != curUserId && u.is_active == 1 && !['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(u.role));
            select.innerHTML = peers.map(u => `
                <option value="${u.id}">${u.name} (${u.nik} - ${u.role})</option>
            `).join('') || `<option value="">Belum ada rekan kerja terdaftar</option>`;

            // Default dates
            const today = new Date().toISOString().slice(0, 10);
            if (!document.getElementById('swap-req-date').value) document.getElementById('swap-req-date').value = today;
            if (!document.getElementById('swap-target-date').value) document.getElementById('swap-target-date').value = today;
        }

        async function loadShiftSwaps() {
            try {
                const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
                const isManager = isManagerOrSuperAdminUser(curUser);
                const bId = state.currentBranch ? state.currentBranch.id : 1;
                const res = await fetch(`api.php?action=get_shift_swaps&branch_id=${bId}&user_id=${curUser.id}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const tbody = document.getElementById('ess-swaps-table-body');
                if (!tbody) return;

                tbody.innerHTML = (data.swaps || []).map(s => `
                    <tr class="hover:bg-slate-50">
                        <td class="py-2.5 px-3">
                            <span class="font-bold text-slate-800">${s.requester_name}</span>
                            <span class="text-slate-400 block text-[10px]">🔄 Tukar dengan: <strong>${s.target_name}</strong></span>
                        </td>
                        <td class="py-2.5 px-3 font-mono">
                            <span class="font-bold text-indigo-700">${s.shift_date}</span> (${s.requester_shift_name || '-'})<br>
                            <span class="text-purple-700">${s.target_date || s.shift_date}</span> (${s.target_shift_name || '-'})
                        </td>
                        <td class="py-2.5 px-3 text-slate-600">${s.reason || '-'}</td>
                        <td class="py-2.5 px-3">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${
                                s.status === 'APPROVED' ? 'bg-emerald-100 text-emerald-800' :
                                (s.status === 'REJECTED' ? 'bg-rose-100 text-rose-800' : 'bg-amber-100 text-amber-800')
                            }">
                                ${s.status === 'APPROVED' ? '✓ DISETUJUI' : (s.status === 'REJECTED' ? '✕ DITOLAK' : '⏳ PENDING')}
                            </span>
                        </td>
                        <td class="py-2.5 px-3 text-center">
                            ${s.status === 'PENDING' ? (
                                isManager ? `
                                    <div class="flex items-center justify-center space-x-1">
                                        <button onclick="approveShiftSwap(${s.id}, 'APPROVE')" class="px-2 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-[10px] font-bold shadow-xs">Setujui</button>
                                        <button onclick="approveShiftSwap(${s.id}, 'REJECT')" class="px-2 py-1 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-[10px] font-bold shadow-xs">Tolak</button>
                                    </div>
                                ` : `<span class="text-[10px] text-amber-700 font-semibold">⏳ Menunggu Manajer</span>`
                            ) : `<span class="text-[10px] text-slate-400">Selesai</span>`}
                        </td>
                    </tr>
                `).join('') || `<tr><td colspan="5" class="text-center py-4 text-slate-400">Belum ada pengajuan tukar jadwal</td></tr>`;

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        async function submitShiftSwapForm(e) {
            e.preventDefault();
            const curUserId = state.currentUser ? state.currentUser.id : 3;
            const bId = state.currentBranch ? state.currentBranch.id : 1;
            const targetId = document.getElementById('swap-target-user').value;
            const shiftDate = document.getElementById('swap-req-date').value;
            const targetDate = document.getElementById('swap-target-date').value;
            const reason = document.getElementById('swap-reason').value;

            const res = await fetch('api.php?action=request_shift_swap', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    requester_id: curUserId,
                    target_id: targetId,
                    branch_id: bId,
                    shift_date: shiftDate,
                    target_date: targetDate,
                    reason
                })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                document.getElementById('swap-reason').value = '';
                loadShiftSwaps();
            }
        }

        async function approveShiftSwap(swapId, action) {
            const reason = action === 'REJECT' ? prompt('Alasan penolakan (opsional):') : '';
            const approverId = state.currentUser ? state.currentUser.id : 1;

            const res = await fetch('api.php?action=approve_shift_swap', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ swap_id: swapId, action, user_id: approverId, rejection_reason: reason })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadShiftSwaps();
                loadMonthlySchedules();
            }
        }

