        async function loadAttendanceReport() {
            const curUser = state.currentUser || state.loggedInUser || { id: 3, role: 'CASHIER' };
            const isManager = isManagerOrSuperAdminUser(curUser);
            const bId = document.getElementById('ess-att-branch-select')?.value || '';
            const mVal = document.getElementById('ess-att-month-input')?.value || new Date().toISOString().slice(0, 7);

            try {
                const res = await fetch(`api.php?action=get_attendance_report&branch_id=${bId}&month=${mVal}&user_id=${curUser.id}&actor_id=${curUser.id}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const summary = data.summary || [];
                const logs = data.logs || [];

                // Calculate KPIs
                const totalEmp = summary.length;
                const avgAtt = totalEmp > 0 ? (summary.reduce((acc, s) => acc + s.attendance_rate, 0) / totalEmp).toFixed(1) : 0;
                const totalLate = summary.reduce((acc, s) => acc + s.late_days, 0);
                const totalLeave = summary.reduce((acc, s) => acc + s.leave_days + s.sick_days, 0);

                document.getElementById('ess-kpi-total-emp').innerText = isManager ? `${totalEmp} Orang` : '1 Karyawan (Data Pribadi)';
                document.getElementById('ess-kpi-att-rate').innerText = `${avgAtt}%`;
                document.getElementById('ess-kpi-late-count').innerText = `${totalLate} Kali`;
                document.getElementById('ess-kpi-leave-count').innerText = `${totalLeave} Hari`;

                // Render Summary Table
                document.getElementById('ess-att-summary-table-body').innerHTML = summary.map(s => `
                    <tr class="hover:bg-slate-50">
                        <td class="py-2.5 px-3 font-mono font-bold text-indigo-700">${s.nik}</td>
                        <td class="py-2.5 px-3 font-semibold text-slate-800">${s.name}<br><span class="text-[10px] text-slate-400 font-normal">${s.branch_name}</span></td>
                        <td class="py-2.5 px-3 text-slate-600">${s.role}</td>
                        <td class="py-2.5 px-3 text-center font-bold">${s.scheduled_days}</td>
                        <td class="py-2.5 px-3 text-center font-bold text-emerald-700">${s.present_days}</td>
                        <td class="py-2.5 px-3 text-center font-bold text-emerald-600">${s.ontime_days}</td>
                        <td class="py-2.5 px-3 text-center font-bold text-amber-600">${s.late_days}</td>
                        <td class="py-2.5 px-3 text-center font-bold text-blue-600">${s.leave_days}</td>
                        <td class="py-2.5 px-3 text-center font-bold text-rose-600">${s.sick_days}</td>
                        <td class="py-2.5 px-3 text-center">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-black ${s.attendance_rate >= 90 ? 'bg-emerald-100 text-emerald-800' : (s.attendance_rate >= 75 ? 'bg-amber-100 text-amber-800' : 'bg-rose-100 text-rose-800')}">
                                ${s.attendance_rate}%
                            </span>
                        </td>
                    </tr>
                `).join('') || `<tr><td colspan="10" class="text-center py-4 text-slate-400">Belum ada data kehadiran</td></tr>`;

                // Render Daily Logs Table
                document.getElementById('ess-att-logs-table-body').innerHTML = logs.map(l => `
                    <tr class="hover:bg-slate-50">
                        <td class="py-2 px-3 font-mono text-emerald-700 font-bold">${l.clock_in}</td>
                        <td class="py-2 px-3 font-mono text-slate-600">${l.clock_out || '-'}</td>
                        <td class="py-2 px-3 font-semibold text-slate-800">${l.employee_name} <span class="text-[10px] text-slate-400 font-mono">(${l.employee_nik})</span></td>
                        <td class="py-2 px-3 text-slate-600">${l.branch_name}</td>
                        <td class="py-2 px-3 font-mono text-slate-500">${l.distance_meters ? l.distance_meters + 'm' : '-'}</td>
                        <td class="py-2 px-3"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${l.status === 'ON_TIME' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}">${l.status}</span></td>
                    </tr>
                `).join('') || `<tr><td colspan="6" class="text-center py-4 text-slate-400">Belum ada riwayat log presensi</td></tr>`;

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

