        async function approveSalaryLoan(loanId, action) {
            const reason = action === 'REJECT' ? prompt('Alasan penolakan (opsional):') : '';
            const approverId = state.currentUser ? state.currentUser.id : 1;

            const res = await fetch('api.php?action=approve_salary_loan', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ loan_id: loanId, action, user_id: approverId, rejection_reason: reason })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadSalaryLoans();
            }
        }

        function openLoanRepayModal(loanId, remaining) {
            const modal = document.getElementById('loan-repay-modal');
            if (!modal) return;
            document.getElementById('loan-repay-id').value = loanId;
            document.getElementById('loan-repay-sub').innerText = `Sisa Utang: ${formatRupiah(remaining)}`;
            document.getElementById('loan-repay-amount').value = remaining;
            modal.classList.remove('hidden');
        }

        function closeLoanRepayModal() {
            document.getElementById('loan-repay-modal')?.classList.add('hidden');
        }

        async function submitLoanRepayForm(e) {
            e.preventDefault();
            const loanId = document.getElementById('loan-repay-id').value;
            const amount = parseFloat(document.getElementById('loan-repay-amount').value) || 0;
            const notes = document.getElementById('loan-repay-notes').value;

            const res = await fetch('api.php?action=pay_salary_loan', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ loan_id: loanId, amount_paid: amount, notes })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeLoanRepayModal();
                loadSalaryLoans();
            }
        }

        // ==========================================
        // 4. KARYAWAN CRUD (EMPLOYEES) & SHIFT MAPPING
        // ==========================================
        let currentEditingEmployee = null;
        let currentScheduleEmployee = null;
        let currentEmployeeScheduleData = null;

        async function ensureWorkShiftsLoaded() {
            if (!essWorkShiftsList || essWorkShiftsList.length === 0) {
                try {
                    const res = await fetch('api.php?action=get_work_shifts');
                    const data = await res.json();
                    if (data.success) {
                        essWorkShiftsList = data.shifts || [];
                    }
                } catch (e) {
                    console.error('Failed to load work shifts:', e);
                }
            }
            return essWorkShiftsList;
        }

        async function loadEmployees() {
            await ensureWorkShiftsLoaded();
            const res = await fetch('api.php?action=get_employees');
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('employee-table-body').innerHTML = data.employees.map(e => {
                const isExempt = ['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(e.role);
                let shiftBadge = '';
                if (isExempt) {
                    shiftBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-600 border border-slate-200">Fleksibel (Manajerial)</span>`;
                } else if (e.default_shift_name) {
                    shiftBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-50 text-indigo-700 border border-indigo-200">${e.default_shift_code ? '[' + e.default_shift_code + '] ' : ''}${e.default_shift_name}</span>`;
                } else {
                    shiftBadge = `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-50 text-amber-700 border border-amber-200">Belum Diset</span>`;
                }

                return `
                <tr class="hover:bg-slate-50">
                    <td class="py-2.5 px-4 font-mono font-bold text-indigo-700">${e.nik}</td>
                    <td class="py-2.5 px-4 font-semibold text-slate-800">${e.name}</td>
                    <td class="py-2.5 px-4"><span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold ${e.role === 'SUPER_ADMIN' ? 'bg-purple-100 text-purple-800' : (e.role === 'BRANCH_MANAGER' ? 'bg-blue-100 text-blue-800' : 'bg-slate-200 text-slate-700')}">${e.role}</span></td>
                    <td class="py-2.5 px-4 text-slate-600">${e.branch_name || 'Semua Cabang'}</td>
                    <td class="py-2.5 px-4 text-slate-500">${e.email || '-'} / ${e.phone || '-'}</td>
                    <td class="py-2.5 px-4">${shiftBadge}</td>
                    <td class="py-2.5 px-4 font-bold text-amber-700">${(e.commission_rate * 100).toFixed(1)}%</td>
                    <td class="py-2.5 px-4">
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${e.is_active ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}">
                            ${e.is_active ? 'Aktif' : 'Nonaktif'}
                        </span>
                    </td>
                    <td class="py-2.5 px-4 text-center space-x-1 whitespace-nowrap">
                        <button onclick='editEmployee(${JSON.stringify(e)})' class="px-2.5 py-1 bg-indigo-50 text-indigo-600 hover:bg-indigo-100 rounded-lg text-[11px] font-bold">Edit</button>
                        <button onclick='openEmployeeScheduleModal(${JSON.stringify(e)})' class="px-2.5 py-1 bg-purple-50 text-purple-700 hover:bg-purple-100 rounded-lg text-[11px] font-bold" title="Detail & Petakan Jadwal Shift">🗓️ Jadwal Shift</button>
                        ${e.id !== 1 ? `<button onclick="deleteEmployee(${e.id})" class="px-2.5 py-1 bg-rose-50 text-rose-600 hover:bg-rose-100 rounded-lg text-[11px] font-bold">Nonaktifkan</button>` : ''}
                    </td>
                </tr>
            `}).join('');
            lucide.createIcons();
        }

        async function openEmployeeModal() {
            currentEditingEmployee = null;
            await ensureWorkShiftsLoaded();

            document.getElementById('emp-id').value = '';
            document.getElementById('emp-nik').value = '';
            document.getElementById('emp-name').value = '';
            document.getElementById('emp-email').value = '';
            document.getElementById('emp-phone').value = '';
            document.getElementById('emp-password').value = '';
            document.getElementById('emp-pin').value = '123456';
            document.getElementById('emp-commission').value = '1.5';
            document.getElementById('emp-modal-title').innerText = 'Tambah Karyawan Baru';

                        const curUser = state.currentUser || state.loggedInUser;
            const canSwitchBranch = curUser && (Number(curUser.can_access_all_branches) === 1 || ['SUPER_ADMIN', 'SUPERADMIN'].includes((curUser.role || '').toUpperCase().replace(/_/g, '')));
            const branchSelect = document.getElementById('emp-branch');
            if (!canSwitchBranch) {
                const uBId = curUser ? curUser.branch_id : (state.currentBranch ? state.currentBranch.id : 1);
                const uBranch = (state.branches || []).find(b => b.id == uBId) || state.currentBranch;
                branchSelect.innerHTML = `<option value="${uBranch.id}" selected>${uBranch.name}</option>`;
                branchSelect.disabled = true;
                branchSelect.title = "Karyawan cabang hanya dapat menambahkan/mengedit staf pada cabang penempatan yang sama.";
            } else {
                branchSelect.disabled = false;
                branchSelect.innerHTML = state.branches.map(b => 
                    `<option value="${b.id}" ${b.id === (state.currentBranch ? state.currentBranch.id : 1) ? 'selected' : ''}>${b.name}</option>`
                ).join('');
            }
            // Populate default shifts & courier vehicles
            renderEmployeeModalShiftOptions();
            renderEmployeeModalVehicleOptions(state.currentBranch ? state.currentBranch.id : 1);
            document.getElementById('emp-branch').onchange = () => {
                renderEmployeeModalVehicleOptions(document.getElementById('emp-branch').value);
            };

            // Set role change listener
            const roleSelect = document.getElementById('emp-role');
            roleSelect.onchange = handleEmployeeRoleChange;
            handleEmployeeRoleChange();

            document.getElementById('emp-shift-detail-action')?.classList.add('hidden');
            document.getElementById('employee-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function renderEmployeeModalShiftOptions(selectedId = null) {
            const shiftSelect = document.getElementById('emp-default-shift');
            if (!shiftSelect) return;
            const options = ['<option value="">-- Pilih Shift Kerja Bawaan --</option>'];
            (essWorkShiftsList || []).forEach(ws => {
                const timeInfo = ws.is_day_off ? 'Hari Libur / Off' : `${ws.start_time} - ${ws.end_time}`;
                options.push(`<option value="${ws.id}" ${ws.id == selectedId ? 'selected' : ''}>${ws.code} - ${ws.name} (${timeInfo})</option>`);
            });
            shiftSelect.innerHTML = options.join('');
        }

        function renderEmployeeModalVehicleOptions(branchId, selectedVehId = null) {
            const vehSelect = document.getElementById('emp-assigned-vehicle');
            if (!vehSelect) return;
            const bId = branchId ? parseInt(branchId) : 1;
            const branchVehs = (state.vehicles || []).filter(v => (!v.branch_id || v.branch_id === bId) && v.status === 'ACTIVE');
            let opts = ['<option value="">-- Tidak Terhubung ke Armada (Bukan Kurir) --</option>'];
            branchVehs.forEach(v => {
                opts.push(`<option value="${v.id}" ${v.id == selectedVehId ? 'selected' : ''}>${v.plate_number} - ${v.vehicle_name} (${v.driver_name || 'Tanpa Driver'})</option>`);
            });
            vehSelect.innerHTML = opts.join('');
        }

        function handleEmployeeRoleChange() {
            const role = document.getElementById('emp-role').value;
            const isExempt = ['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(role);
            const pickerGroup = document.getElementById('emp-shift-picker-group');
            const exemptNotice = document.getElementById('emp-shift-exempt-notice');
            const detailAction = document.getElementById('emp-shift-detail-action');

            if (isExempt) {
                if (pickerGroup) pickerGroup.classList.add('hidden');
                if (exemptNotice) exemptNotice.classList.remove('hidden');
                if (detailAction) detailAction.classList.add('hidden');
                document.getElementById('emp-default-shift').value = '';
            } else {
                if (pickerGroup) pickerGroup.classList.remove('hidden');
                if (exemptNotice) exemptNotice.classList.add('hidden');
                if (currentEditingEmployee && currentEditingEmployee.id) {
                    if (detailAction) detailAction.classList.remove('hidden');
                } else {
                    if (detailAction) detailAction.classList.add('hidden');
                }
            }
            lucide.createIcons();
        }

        async function editEmployee(emp) {
            currentEditingEmployee = emp;
            await openEmployeeModal();
            document.getElementById('emp-id').value = emp.id;
            document.getElementById('emp-nik').value = emp.nik;
            document.getElementById('emp-name').value = emp.name;
            document.getElementById('emp-role').value = emp.role;
                        document.getElementById('emp-branch').value = emp.branch_id || 1;
            if (!canSwitchBranch) {
                document.getElementById('emp-branch').disabled = true;
            } else {
                document.getElementById('emp-branch').disabled = false;
            }
            document.getElementById('emp-email').value = emp.email || '';
            document.getElementById('emp-phone').value = emp.phone || '';
            document.getElementById('emp-pin').value = emp.pin || '123456';
            document.getElementById('emp-commission').value = (emp.commission_rate * 100).toFixed(1);
            document.getElementById('emp-modal-title').innerText = 'Edit Karyawan: ' + emp.name;

            renderEmployeeModalShiftOptions(emp.default_work_shift_id);
            renderEmployeeModalVehicleOptions(emp.branch_id || 1, emp.assigned_vehicle_id);
            handleEmployeeRoleChange();
        }

        function closeEmployeeModal() {
            document.getElementById('employee-modal').classList.add('hidden');
        }

        function openScheduleFromEmployeeModal() {
            if (currentEditingEmployee) {
                closeEmployeeModal();
                openEmployeeScheduleModal(currentEditingEmployee);
            }
        }

        async function saveEmployeeForm(e) {
            e.preventDefault();
            const id = document.getElementById('emp-id').value;
            const role = document.getElementById('emp-role').value;
            const isExempt = ['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(role);
            const defaultShiftId = (!isExempt && document.getElementById('emp-default-shift').value) ? parseInt(document.getElementById('emp-default-shift').value) : null;
            const assignedVehicleId = document.getElementById('emp-assigned-vehicle')?.value ? parseInt(document.getElementById('emp-assigned-vehicle').value) : null;

            const payload = {
                id: id ? parseInt(id) : null,
                nik: document.getElementById('emp-nik').value,
                name: document.getElementById('emp-name').value,
                role: role,
                branch_id: parseInt(document.getElementById('emp-branch').value),
                email: document.getElementById('emp-email').value,
                phone: document.getElementById('emp-phone').value,
                pin: document.getElementById('emp-pin').value,
                password: document.getElementById('emp-password').value,
                commission_rate: parseFloat(document.getElementById('emp-commission').value) / 100,
                default_work_shift_id: defaultShiftId,
                assigned_vehicle_id: assignedVehicleId
            };

            const res = await fetch('api.php?action=save_employee', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeEmployeeModal();
                loadEmployees();
                if (typeof loadLogisticsData === 'function') loadLogisticsData();
                renderPosCourierSelect();
            }
        }

        async function deleteEmployee(id) {
            if (!confirm('Nonaktifkan karyawan ini?')) return;
            const res = await fetch('api.php?action=delete_employee', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadEmployees();
        }

        // ==========================================
        // 4b. DETAIL & PEMETAAN JADWAL SHIFT KARYAWAN
        // ==========================================
        async function openEmployeeScheduleModal(emp) {
            currentScheduleEmployee = emp;
            await ensureWorkShiftsLoaded();

            document.getElementById('emp-sched-user-name').innerText = emp.name;
            document.getElementById('emp-sched-user-nik').innerText = emp.nik;
            document.getElementById('emp-sched-user-role').innerText = emp.role;
            document.getElementById('emp-sched-user-branch').innerText = emp.branch_name || 'Semua Cabang';

            const mInput = document.getElementById('emp-sched-month-input');
            if (!mInput.value) {
                mInput.value = new Date().toISOString().slice(0, 7);
            }

            const isExempt = ['SUPER_ADMIN', 'SUPERADMIN', 'BRANCH_MANAGER', 'MANAGER'].includes(emp.role);
            const exemptContainer = document.getElementById('emp-sched-exempt-container');
            const mainContent = document.getElementById('emp-sched-main-content');

            if (isExempt) {
                exemptContainer.classList.remove('hidden');
                mainContent.classList.add('hidden');
                document.getElementById('emp-sched-exempt-role').innerText = emp.role;
            } else {
                exemptContainer.classList.add('hidden');
                mainContent.classList.remove('hidden');

                // Render default shift dropdown options in modal
                const defSelect = document.getElementById('emp-sched-default-shift-select');
                defSelect.innerHTML = ['<option value="">-- Pilih Shift Bawaan --</option>']
                    .concat((essWorkShiftsList || []).map(ws => {
                        const timeInfo = ws.is_day_off ? 'Libur / Off' : `${ws.start_time} - ${ws.end_time}`;
                        return `<option value="${ws.id}" ${ws.id == emp.default_work_shift_id ? 'selected' : ''}>${ws.code} - ${ws.name} (${timeInfo})</option>`;
                    })).join('');

                await loadEmployeeScheduleData();
            }

            document.getElementById('employee-schedule-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeEmployeeScheduleModal() {
            document.getElementById('employee-schedule-modal').classList.add('hidden');
        }

        async function loadEmployeeScheduleData() {
            if (!currentScheduleEmployee) return;
            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            const tbody = document.getElementById('emp-sched-table-body');
            tbody.innerHTML = '<tr><td colspan="5" class="py-6 text-center text-slate-400">Memuat jadwal shift...</td></tr>';

            try {
                const res = await fetch(`api.php?action=get_employee_schedule&user_id=${currentScheduleEmployee.id}&month=${month}`);
                const data = await res.json();
                if (!data.success) {
                    tbody.innerHTML = `<tr><td colspan="5" class="py-6 text-center text-rose-500 font-medium">${data.message || 'Gagal memuat jadwal.'}</td></tr>`;
                    return;
                }

                currentEmployeeScheduleData = data;
                if (data.work_shifts) essWorkShiftsList = data.work_shifts;

                // Sync default shift dropdown if updated
                if (data.employee && data.employee.default_work_shift_id) {
                    currentScheduleEmployee.default_work_shift_id = data.employee.default_work_shift_id;
                    const defSelect = document.getElementById('emp-sched-default-shift-select');
                    if (defSelect) defSelect.value = data.employee.default_work_shift_id;
                }

                const daysInMonth = data.days_in_month;
                const schedules = data.schedules || {};
                const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

                let totalWork = 0;
                let totalOff = 0;
                let rowsHtml = '';

                for (let d = 1; d <= daysInMonth; d++) {
                    const dateStr = `${month}-${String(d).padStart(2, '0')}`;
                    const dateObj = new Date(`${dateStr}T00:00:00`);
                    const dayName = dayNames[dateObj.getDay()];
                    const isSunday = (dateObj.getDay() === 0);

                    const sched = schedules[dateStr] || null;
                    const assignedShiftId = sched ? sched.work_shift_id : null;
                    const isHoliday = sched ? sched.is_holiday : (isSunday ? 1 : 0);

                    let assignedShift = null;
                    if (assignedShiftId) {
                        assignedShift = essWorkShiftsList.find(ws => ws.id == assignedShiftId);
                    }

                    if (assignedShift && !assignedShift.is_day_off && !isHoliday) {
                        totalWork++;
                    } else {
                        totalOff++;
                    }

                    const shiftOptions = ['<option value="">-- Belum Diset / Libur --</option>']
                        .concat((essWorkShiftsList || []).map(ws => {
                            return `<option value="${ws.id}" ${ws.id == assignedShiftId ? 'selected' : ''}>${ws.code} - ${ws.name}</option>`;
                        })).join('');

                    const timeDisplay = (assignedShift && !assignedShift.is_day_off) 
                        ? `<span class="font-mono text-slate-700 font-bold">${assignedShift.start_time} - ${assignedShift.end_time}</span>` 
                        : `<span class="text-slate-400 font-medium italic">Libur / Fleksibel</span>`;

                    rowsHtml += `
                        <tr class="hover:bg-slate-50 transition-colors ${isSunday ? 'bg-rose-50/30' : ''}" data-date="${dateStr}">
                            <td class="py-2.5 px-3 font-mono font-bold text-slate-800">${dateStr}</td>
                            <td class="py-2.5 px-3 font-medium ${isSunday ? 'text-rose-600 font-bold' : 'text-slate-600'}">${dayName}</td>
                            <td class="py-2.5 px-3">
                                <select class="emp-row-shift-select p-1.5 bg-white border border-slate-300 rounded-lg text-xs font-medium w-full max-w-[220px]" onchange="handleEmployeeRowShiftChange(this, '${dateStr}')">
                                    ${shiftOptions}
                                </select>
                            </td>
                            <td class="py-2.5 px-3 emp-row-time-col">
                                ${timeDisplay}
                            </td>
                            <td class="py-2.5 px-3">
                                <input type="text" class="emp-row-notes p-1.5 bg-white border border-slate-200 rounded-lg text-xs w-full" placeholder="Catatan shift..." value="${sched ? (sched.notes || '') : ''}">
                            </td>
                        </tr>
                    `;
                }

                tbody.innerHTML = rowsHtml;
                document.getElementById('emp-sched-stats').innerHTML = `
                    <span class="inline-flex items-center gap-1.5">
                        <span class="w-2.5 h-2.5 rounded-full bg-emerald-500"></span>
                        <span>Hari Kerja: <strong>${totalWork} hari</strong></span>
                    </span>
                    <span class="mx-2 text-slate-300">|</span>
                    <span class="inline-flex items-center gap-1.5">
                        <span class="w-2.5 h-2.5 rounded-full bg-slate-400"></span>
                        <span>Hari Libur/Off: <strong>${totalOff} hari</strong></span>
                    </span>
                `;
            } catch (err) {
                tbody.innerHTML = `<tr><td colspan="5" class="py-6 text-center text-rose-500 font-medium">Terjadi kesalahan: ${err.message}</td></tr>`;
            }
        }

        function handleEmployeeRowShiftChange(selectEl, dateStr) {
            const shiftId = selectEl.value;
            const row = selectEl.closest('tr');
            const timeCol = row.querySelector('.emp-row-time-col');
            if (!shiftId) {
                timeCol.innerHTML = `<span class="text-slate-400 font-medium italic">Libur / Fleksibel</span>`;
                return;
            }
            const ws = (essWorkShiftsList || []).find(w => w.id == shiftId);
            if (ws && !ws.is_day_off) {
                timeCol.innerHTML = `<span class="font-mono text-slate-700 font-bold">${ws.start_time} - ${ws.end_time}</span>`;
            } else {
                timeCol.innerHTML = `<span class="text-slate-400 font-medium italic">Libur / Fleksibel</span>`;
            }
        }

        async function applyDefaultShiftToMonth(overrideAll) {
            if (!currentScheduleEmployee) return;
            const defSelect = document.getElementById('emp-sched-default-shift-select');
            const defaultShiftId = defSelect.value ? parseInt(defSelect.value) : null;
            if (!defaultShiftId) {
                alert('Silakan pilih Shift Bawaan terlebih dahulu pada dropdown di atas.');
                return;
            }

            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            const confirmMsg = overrideAll 
                ? `Terapkan shift ini ke SELURUH hari pada bulan ${month} (semua jadwal lama akan ditimpa)?` 
                : `Terapkan shift ini ke tanggal-tanggal yang belum memiliki jadwal pada bulan ${month}?`;
            if (!confirm(confirmMsg)) return;

            try {
                const res = await fetch('api.php?action=apply_employee_default_shift_month', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        user_id: currentScheduleEmployee.id,
                        month: month,
                        default_work_shift_id: defaultShiftId,
                        override_all: overrideAll ? 1 : 0
                    })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    currentScheduleEmployee.default_work_shift_id = defaultShiftId;
                    await loadEmployeeScheduleData();
                    loadEmployees();
                }
            } catch (e) {
                alert('Terjadi kesalahan saat menerapkan shift: ' + e.message);
            }
        }

        async function saveEmployeeScheduleData() {
            if (!currentScheduleEmployee) return;
            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            const rows = document.querySelectorAll('#emp-sched-table-body tr[data-date]');
            const entries = [];

            rows.forEach(r => {
                const dateStr = r.getAttribute('data-date');
                const shiftId = r.querySelector('.emp-row-shift-select').value;
                const notes = r.querySelector('.emp-row-notes').value;
                const ws = shiftId ? (essWorkShiftsList || []).find(w => w.id == shiftId) : null;
                const isHoliday = (!ws || ws.is_day_off) ? 1 : 0;

                entries.push({
                    shift_date: dateStr,
                    work_shift_id: shiftId ? parseInt(shiftId) : null,
                    is_holiday: isHoliday,
                    notes: notes
                });
            });

            try {
                const res = await fetch('api.php?action=save_employee_schedule_batch', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        user_id: currentScheduleEmployee.id,
                        month: month,
                        branch_id: currentScheduleEmployee.branch_id || 1,
                        entries: entries
                    })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadEmployeeScheduleData();
                    loadEmployees();
                }
            } catch (e) {
                alert('Gagal menyimpan jadwal shift: ' + e.message);
            }
        }

        function goToBranchRosterTab() {
            closeEmployeeScheduleModal();
            const month = document.getElementById('emp-sched-month-input').value || new Date().toISOString().slice(0, 7);
            if (typeof switchTab === 'function') switchTab('ess');
            if (typeof setEssSubtab === 'function') setEssSubtab('schedules');
            const rMonth = document.getElementById('ess-roster-month-input');
            if (rMonth) rMonth.value = month;
            if (typeof loadMonthlySchedules === 'function') loadMonthlySchedules();
        }

        async function deleteEmployee(id) {
            if (!confirm('Nonaktifkan karyawan ini?')) return;
            const res = await fetch('api.php?action=delete_employee', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadEmployees();
        }

        // ==========================================
        // 5. MASTER PRODUK, KATEGORI & VARIAN
        // ==========================================
        async function loadAllProducts() {
            const res = await fetch('api.php?action=get_all_products');
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
            state.allProducts = data.products;

            document.getElementById('master-products-table-body').innerHTML = data.products.map(p => {
                const typeBadge = p.product_type === 'FINISHED_GOODS' 
                    ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">Barang Jadi</span>'
                    : (p.product_type === 'RAW_MATERIAL'
                        ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800">Bahan Baku</span>'
                        : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-blue-100 text-blue-800">Jasa</span>');

                const variantsText = p.variants && p.variants.length > 0 
                    ? p.variants.map(v => {
                        const addPrice = Number(v.additional_price || 0);
                        const isFree = addPrice === 0;
                        return `
                            <span class="inline-flex items-center gap-1 ${isFree ? 'bg-slate-100 text-slate-700 border-slate-200' : 'bg-emerald-50 text-emerald-800 border-emerald-300'} border px-2 py-0.5 rounded-lg text-[10px] mr-1 mb-1 font-semibold">
                                <span>${v.variant_name}</span>
                                <span class="font-bold ${isFree ? 'text-slate-500' : 'text-emerald-700'}">${isFree ? '(+Rp 0 / Bebas Biaya)' : '(+' + formatRupiah(addPrice) + ')'}</span>
                                <button type="button" onclick="deleteProductVariant(${v.id}, '${v.variant_name.replace(/'/g, "\\'")}')" class="text-rose-400 hover:text-rose-600 ml-1 font-bold">×</button>
                            </span>
                        `;
                    }).join('')
                    : '<span class="text-slate-400 text-[10px]">Standar (Tanpa Varian)</span>';

                const isTaxable = p.is_taxable !== undefined ? Number(p.is_taxable) : 1;
                const taxName = p.tax_name || (isTaxable ? 'PPN 11%' : 'Bebas Pajak');
                const taxBadge = isTaxable === 1 
                    ? `<span class="inline-flex items-center gap-1 bg-emerald-50 text-emerald-800 border border-emerald-300 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>${taxName}</span>`
                    : `<span class="inline-flex items-center gap-1 bg-slate-100 text-slate-500 border border-slate-200 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-slate-400"></span>Non-Pajak</span>`;

                const isDelivInc = Number(p.is_delivery_included || 0) === 1 || Number(p.is_delivery_required || 0) === 2;
                const isDelivReq = Number(p.is_delivery_required || 0) === 1;
                const deliveryBadge = isDelivInc
                    ? `<span class="inline-flex items-center gap-1 bg-emerald-50 text-emerald-800 border border-emerald-300 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>🎁 Termasuk Kirim</span>`
                    : (isDelivReq
                        ? `<span class="inline-flex items-center gap-1 bg-amber-50 text-amber-800 border border-amber-300 px-2 py-0.5 rounded-full text-[10px] font-bold"><span class="w-1.5 h-1.5 rounded-full bg-amber-500"></span>🚚 Wajib Ongkir</span>`
                        : `<span class="inline-flex items-center gap-1 bg-slate-100 text-slate-400 border border-slate-200 px-2 py-0.5 rounded-full text-[10px] font-medium">Standar</span>`);

                return `
                    <tr class="hover:bg-slate-50">
                        <td class="py-2.5 px-3 font-mono font-bold text-indigo-700">${p.sku}<br><span class="text-[10px] text-slate-400">${p.barcode}</span></td>
                        <td class="py-2.5 px-3 font-semibold text-slate-800">
                            <span class="mr-1.5">${p.image_emoji || '📦'}</span>${p.name}${(p.effective_is_stockable === 0 || p.requires_stock === 0) ? ' <span class="inline-block text-[9px] px-1.5 py-0.2 bg-violet-100 text-violet-800 border border-violet-200 rounded font-bold">⚡ Tanpa Stok</span>' : ''}
                        </td>
                        <td class="py-2.5 px-3">${typeBadge}</td>
                        <td class="py-2.5 px-3 text-slate-600">${p.category}</td>
                        <td class="py-2.5 px-3 text-slate-500 font-medium">${p.unit}</td>
                        <td class="py-2.5 px-3 text-right font-medium text-slate-700 font-mono">${formatRupiah(p.cogs)}</td>
                        <td class="py-2.5 px-3 text-right font-bold text-indigo-900 font-mono">${p.product_type === 'RAW_MATERIAL' ? '-' : formatRupiah(p.selling_price)}</td>
                        <td class="py-2.5 px-3 text-center">
                            <div class="flex flex-col items-center gap-1">
                                ${taxBadge}
                                ${deliveryBadge}
                            </div>
                        </td>
                        <td class="py-2.5 px-3">
                            <div class="flex flex-wrap items-center">
                                ${variantsText}
                            </div>
                            <div class="mt-1 flex items-center space-x-2">
                                <button onclick="openProductVariantModal(${p.id}, '${p.name.replace(/'/g, "\\'")}', '${p.sku}')" class="text-[10px] text-indigo-600 hover:text-indigo-800 font-bold flex items-center space-x-0.5">
                                    <span>➕ Tambah Varian</span>
                                </button>
                                ${p.has_bom ? '<span class="text-[9px] text-emerald-600 font-bold">🧪 Ada BOM</span>' : ''}
                            </div>
                        </td>
                        <td class="py-2.5 px-3 text-center whitespace-nowrap">
                            <div class="inline-flex items-center space-x-1">
                                <button onclick='editProduct(${JSON.stringify(p)})' class="px-2.5 py-1 bg-indigo-50 text-indigo-600 hover:bg-indigo-100 rounded-lg text-[11px] font-bold transition-colors">Edit</button>
                                <button onclick="deleteProduct(${p.id}, '${p.name.replace(/'/g, "\\'")}')" class="px-2 py-1 bg-rose-50 text-rose-600 hover:bg-rose-100 rounded-lg text-[11px] font-bold transition-colors flex items-center space-x-0.5" title="Hapus Produk">
                                    <i data-lucide="trash-2" class="w-3 h-3"></i>
                                    <span>Hapus</span>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');
            lucide.createIcons();
        }

        function renderTaxOptionsForProductModal(selectedTaxId = 1) {
            const select = document.getElementById('prod-tax-id');
            if (!select) return;
            const taxes = state.taxes || [];
            select.innerHTML = taxes.map(t => 
                `<option value="${t.id}" ${t.id == selectedTaxId ? 'selected' : ''}>${t.name} (${t.rate_percent}%)</option>`
            ).join('');
        }

        function toggleProductTaxSelect() {
            const isChecked = document.getElementById('prod-is-taxable').checked;
            const cont = document.getElementById('prod-tax-select-container');
            const badge = document.getElementById('prod-tax-status-badge');
            if (isChecked) {
                if (cont) cont.classList.remove('hidden');
                if (badge) {
                    badge.innerText = 'Kena Pajak';
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800';
                }
            } else {
                if (cont) cont.classList.add('hidden');
                if (badge) {
                    badge.innerText = 'Bebas Pajak (Tax Exempt)';
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-200 text-slate-700';
                }
            }
        }

        function toggleProductDeliveryBadge() {
            const selectEl = document.getElementById('prod-delivery-mode');
            const hiddenEl = document.getElementById('prod-is-delivery-required');
            const badge = document.getElementById('prod-delivery-status-badge');
            const desc = document.getElementById('prod-delivery-desc-text');
            if (!badge) return;

            const mode = selectEl ? selectEl.value : (hiddenEl && (hiddenEl.checked || hiddenEl.value === '1') ? '1' : '0');
            if (hiddenEl) {
                hiddenEl.value = (mode === '2') ? '2' : ((mode === '1') ? '1' : '0');
                hiddenEl.checked = (mode === '1' || mode === '2');
            }

            if (mode === '2') {
                badge.innerText = 'Termasuk Ongkir';
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300';
                if (desc) desc.innerText = '🎁 Produk sudah termasuk ongkir: Biaya kirim Rp 0 di POS, kurir pengirim & armada tetap dicatat.';
            } else if (mode === '1') {
                badge.innerText = 'Wajib Ongkir (+Tarif)';
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-800 border border-amber-300';
                if (desc) desc.innerText = '🚚 Wajib ongkir tambahan: Kasir otomatis dikenakan tarif dasar pengiriman cabang / per KM.';
            } else {
                badge.innerText = 'Standar';
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-100 text-slate-600';
                if (desc) desc.innerText = '⚪ Standar: Pelanggan belanja biasa di toko tanpa mewajibkan layanan pengantaran.';
            }
        }

        function onProductTypeChange() {
            const type = document.getElementById('prod-type').value;
            const id = document.getElementById('prod-id').value;
            const btnBom = document.getElementById('btn-fetch-bom-cogs');
            if (type === 'FINISHED_GOODS' && id) {
                if (btnBom) btnBom.classList.remove('hidden');
            } else if (!id && type === 'FINISHED_GOODS') {
                if (btnBom) btnBom.classList.add('hidden');
            } else {
                if (btnBom) btnBom.classList.add('hidden');
            }
            // Auto generate SKU baru jika menambah produk baru
            if (!id) {
                autoGenerateSkuBarcode();
            }
        }

        async function autoGenerateSkuBarcode() {
            try {
                const pType = document.getElementById('prod-type').value || 'FINISHED_GOODS';
                const cId = document.getElementById('prod-category').value || 1;
                const res = await fetch(`api.php?action=generate_sku_barcode&product_type=${pType}&category_id=${cId}`);
                const data = await res.json();
                if (data.success) {
                    document.getElementById('prod-sku').value = data.sku;
                    document.getElementById('prod-barcode').value = data.barcode;
                }
            } catch (err) {
                console.error('Gagal generate SKU/Barcode:', err);
            }
        }

        function renderProductModalOptions(selectedType = 'FINISHED_GOODS', selectedCatId = 1, selectedUnit = 'pcs') {
            // Render Jenis Produk
            const typeSelect = document.getElementById('prod-type');
            if (typeSelect && state.productTypes && state.productTypes.length > 0) {
                typeSelect.innerHTML = state.productTypes.map(pt => 
                    `<option value="${pt.code}" ${pt.code === selectedType ? 'selected' : ''}>${pt.name} (${pt.prefix})</option>`
                ).join('');
            } else if (typeSelect) {
                typeSelect.innerHTML = `
                    <option value="FINISHED_GOODS" ${selectedType === 'FINISHED_GOODS' ? 'selected' : ''}>Barang Jadi (PRD)</option>
                    <option value="RAW_MATERIAL" ${selectedType === 'RAW_MATERIAL' ? 'selected' : ''}>Bahan Baku (RAW)</option>
                    <option value="SERVICE" ${selectedType === 'SERVICE' ? 'selected' : ''}>Jasa / Servis (SRV)</option>
                `;
            }

            // Render Kategori
            const catSelect = document.getElementById('prod-category');
            if (catSelect && state.categories) {
                catSelect.innerHTML = state.categories.map(c => 
                    `<option value="${c.id}" ${c.id == selectedCatId ? 'selected' : ''}>${c.name}</option>`
                ).join('');
            }

            // Render Satuan
            const unitSelect = document.getElementById('prod-unit');
            if (unitSelect && state.productUnits && state.productUnits.length > 0) {
                unitSelect.innerHTML = state.productUnits.map(u => 
                    `<option value="${u.code}" ${u.code.toLowerCase() === (selectedUnit || '').toLowerCase() ? 'selected' : ''}>${u.code} - ${u.name}</option>`
                ).join('');
            } else if (unitSelect) {
                const defaultUnits = ['pcs', 'cup', 'botol', 'porsi', 'gram', 'kg', 'ml', 'liter', 'pack', 'box'];
                unitSelect.innerHTML = defaultUnits.map(u => 
                    `<option value="${u}" ${u.toLowerCase() === (selectedUnit || '').toLowerCase() ? 'selected' : ''}>${u}</option>`
                ).join('');
            }
        }

        async function autoFillCogsFromBOM() {
            const id = document.getElementById('prod-id').value;
            if (!id) {
                alert('Simpan produk terlebih dahulu atau tambahkan formula resep di Menu BOM untuk menghitung HPP otomatis.');
                return;
            }
            try {
                const res = await fetch(`api.php?action=get_product_bom_cogs&product_id=${id}`);
                const data = await res.json();
                if (data.success && data.count > 0) {
                    document.getElementById('prod-cogs').value = data.calculated_cogs;
                    const hint = document.getElementById('prod-cogs-hint');
                    if (hint) {
                        hint.innerText = `✓ Dihitung dari ${data.count} bahan baku BOM: Rp ${formatRupiah(data.calculated_cogs)}`;
                        hint.classList.remove('hidden');
                    }
                    alert(`HPP Berhasil Diperbarui dari Formula BOM!\n\nTotal modal dari ${data.count} bahan baku: Rp ${formatRupiah(data.calculated_cogs)}`);
                } else {
                    alert('Produk ini belum memiliki bahan baku terdaftar di formula resep (BOM). Silakan atur formula di Tab BOM.');
                }
            } catch (err) {
                alert('Gagal mengambil kalkulasi HPP dari BOM.');
            }
        }

        async function openProductModal() {
            document.getElementById('prod-id').value = '';
            document.getElementById('prod-sku').value = '';
            document.getElementById('prod-barcode').value = '';
            document.getElementById('prod-name').value = '';
            document.getElementById('prod-cogs').value = '10000';
            document.getElementById('prod-price').value = '25000';
            document.getElementById('prod-emoji').value = '📦';
            document.getElementById('prod-has-bom').checked = false;
            document.getElementById('prod-reorder').value = '10';
            document.getElementById('prod-modal-title').innerText = 'Tambah Produk Baru';

            renderProductModalOptions('FINISHED_GOODS', 1, 'pcs');

            const btnBom = document.getElementById('btn-fetch-bom-cogs');
            if (btnBom) btnBom.classList.add('hidden');
            const hint = document.getElementById('prod-cogs-hint');
            if (hint) hint.classList.add('hidden');

            // Reset status pajak default aktif
            document.getElementById('prod-is-taxable').checked = true;
            renderTaxOptionsForProductModal(1);
            toggleProductTaxSelect();

            // Reset status pengiriman default Standar (0)
            if (document.getElementById('prod-delivery-mode')) {
                document.getElementById('prod-delivery-mode').value = '0';
            }
            document.getElementById('prod-is-delivery-required').value = '0';
            document.getElementById('prod-is-delivery-required').checked = false;
            toggleProductDeliveryBadge();
            if (document.getElementById('prod-is-stockable')) {
                document.getElementById('prod-is-stockable').value = '1';
            }
            toggleProductStockableBadge();

            // Generate otomatis SKU dan Barcode unik untuk produk baru (5 digit)
            await autoGenerateSkuBarcode();

            document.getElementById('product-modal').classList.remove('hidden');
            if (typeof lucide !== 'undefined') lucide.createIcons();
        }

        async function editProduct(p) {
            document.getElementById('prod-id').value = p.id;
            document.getElementById('prod-sku').value = p.sku;
            document.getElementById('prod-barcode').value = p.barcode;
            document.getElementById('prod-name').value = p.name;
            document.getElementById('prod-cogs').value = p.cogs;
            document.getElementById('prod-price').value = p.selling_price;
            document.getElementById('prod-emoji').value = p.image_emoji || '📦';
            document.getElementById('prod-has-bom').checked = !!p.has_bom;
            document.getElementById('prod-reorder').value = p.reorder_point || 10;
            
            renderProductModalOptions(p.product_type || 'FINISHED_GOODS', p.category_id || 1, p.unit || 'pcs');

            // Tampilkan tombol kalkulasi BOM jika barang jadi
            const btnBom = document.getElementById('btn-fetch-bom-cogs');
            const hint = document.getElementById('prod-cogs-hint');
            if (p.product_type === 'FINISHED_GOODS') {
                if (btnBom) btnBom.classList.remove('hidden');
                if (p.has_bom && hint) {
                    hint.innerText = `💡 Produk memiliki formula BOM. Klik 'Dari BOM' untuk sinkronisasi modal.`;
                    hint.classList.remove('hidden');
                } else if (hint) {
                    hint.classList.add('hidden');
                }
            } else {
                if (btnBom) btnBom.classList.add('hidden');
                if (hint) hint.classList.add('hidden');
            }

            // Atur status pajak produk
            const isTaxable = p.is_taxable !== undefined ? (Number(p.is_taxable) === 1) : true;
            document.getElementById('prod-is-taxable').checked = isTaxable;
            renderTaxOptionsForProductModal(p.tax_id || 1);
            toggleProductTaxSelect();

            // Atur status ongkos kirim / delivery produk (0 = Standar, 1 = Wajib Ongkir Ekstra, 2 = Termasuk Ongkir)
            let delivVal = '0';
            if (p.is_delivery_included == 1 || p.is_delivery_required == 2) {
                delivVal = '2';
            } else if (p.is_delivery_required == 1) {
                delivVal = '1';
            }
            if (document.getElementById('prod-delivery-mode')) {
                document.getElementById('prod-delivery-mode').value = delivVal;
            }
            document.getElementById('prod-is-delivery-required').value = delivVal;
            document.getElementById('prod-is-delivery-required').checked = (delivVal === '1' || delivVal === '2');
            toggleProductDeliveryBadge();
            if (document.getElementById('prod-is-stockable')) {
                document.getElementById('prod-is-stockable').value = (p.is_stockable !== undefined && Number(p.is_stockable) === 0) ? '0' : '1';
            }
            toggleProductStockableBadge();

            document.getElementById('prod-modal-title').innerText = 'Edit Produk: ' + p.name;
            document.getElementById('product-modal').classList.remove('hidden');
            if (typeof lucide !== 'undefined') lucide.createIcons();
        }

        function toggleProductStockableBadge() {
            const el = document.getElementById('prod-is-stockable');
            const badge = document.getElementById('prod-stockable-status-badge');
            if (!el || !badge) return;
            if (el.value === '0') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-violet-100 text-violet-800';
                badge.innerText = '⚡ Tanpa Stok (BOM)';
            } else {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800';
                badge.innerText = '📦 Wajib Stok';
            }
        }

        function closeProductModal() {
            document.getElementById('product-modal').classList.add('hidden');
        }

        async function saveProductForm(e) {
            e.preventDefault();
            const id = document.getElementById('prod-id').value;
            const isTaxable = document.getElementById('prod-is-taxable').checked ? 1 : 0;
            const taxId = parseInt(document.getElementById('prod-tax-id').value) || 1;
            
            const delivMode = document.getElementById('prod-delivery-mode') 
                ? document.getElementById('prod-delivery-mode').value 
                : (document.getElementById('prod-is-delivery-required').checked ? '1' : '0');
            const isDelivReq = (delivMode === '2') ? 2 : ((delivMode === '1') ? 1 : 0);
            const isDelivInc = (delivMode === '2') ? 1 : 0;

            const payload = {
                id: id ? parseInt(id) : null,
                branch_id: state.currentBranch ? state.currentBranch.id : 1,
                sku: document.getElementById('prod-sku').value,
                barcode: document.getElementById('prod-barcode').value,
                name: document.getElementById('prod-name').value,
                product_type: document.getElementById('prod-type').value,
                category_id: parseInt(document.getElementById('prod-category').value),
                unit: document.getElementById('prod-unit').value,
                cogs: parseFloat(document.getElementById('prod-cogs').value) || 0,
                selling_price: parseFloat(document.getElementById('prod-price').value) || 0,
                image_emoji: document.getElementById('prod-emoji').value,
                has_bom: document.getElementById('prod-has-bom').checked ? 1 : 0,
                reorder_point: parseInt(document.getElementById('prod-reorder').value) || 10,
                is_taxable: isTaxable,
                tax_id: taxId,
                is_delivery_required: isDelivReq,
                is_delivery_included: isDelivInc,
                is_stockable: document.getElementById('prod-is-stockable') ? (parseInt(document.getElementById('prod-is-stockable').value) === 0 ? 0 : 1) : 1
            };

            const res = await fetch('api.php?action=save_product', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeProductModal();
                loadAllProducts();
                await initApp();
                recalculateCartPrices();
            }
        }

        async function deleteProduct(id, name) {
            if (!confirm(`Apakah Anda yakin ingin MENGHAPUS produk '${name}'?\n\nJika produk memiliki riwayat transaksi, produk akan dinonaktifkan (Soft Delete) agar laporan akuntansi tetap terjaga.`)) {
                return;
            }
            try {
                const res = await fetch('api.php?action=delete_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadAllProducts();
                    await initApp();
                    recalculateCartPrices();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan saat menghapus produk.');
            }
        }

        function exportMasterProducts() {
            window.open('api.php?action=export_products', '_blank');
        }

        function openImportProductModal() {
            const fileInput = document.getElementById('product-import-file-input');
            const textInput = document.getElementById('product-import-text-input');
            if (fileInput) fileInput.value = '';
            if (textInput) textInput.value = '';
            document.getElementById('product-import-modal').classList.remove('hidden');
            if (window.lucide) lucide.createIcons();
        }

        function closeImportProductModal() {
            document.getElementById('product-import-modal').classList.add('hidden');
        }

        function downloadProductTemplateCsv() {
            window.open('api.php?action=export_products&format=template', '_blank');
        }

        async function submitImportProducts(e) {
            e.preventDefault();
            const fileInput = document.getElementById('product-import-file-input');
            const textInput = document.getElementById('product-import-text-input');
            const btnSubmit = document.getElementById('btn-submit-import-products');

            const hasFile = fileInput && fileInput.files && fileInput.files.length > 0;
            const hasText = textInput && textInput.value.trim().length > 0;

            if (!hasFile && !hasText) {
                alert('Silakan pilih file CSV atau tempel teks data CSV terlebih dahulu.');
                return;
            }

            btnSubmit.disabled = true;
            btnSubmit.innerHTML = `<span>Memproses Import...</span>`;

            try {
                let res;
                if (hasFile) {
                    const formData = new FormData();
                    formData.append('file', fileInput.files[0]);
                    res = await fetch('api.php?action=import_products', {
                        method: 'POST',
                        body: formData
                    });
                } else {
                    res = await fetch('api.php?action=import_products', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ csv_content: textInput.value.trim() })
                    });
                }

                const data = await res.json();
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = `<i data-lucide="upload" class="w-4 h-4"></i><span>Proses Import Produk</span>`;

                alert(data.message || (data.success ? 'Import produk selesai!' : 'Gagal import produk'));
                if (data.success) {
                    closeImportProductModal();
                    await loadAllProducts();
                    await initApp();
                }
            } catch (err) {
                btnSubmit.disabled = false;
                btnSubmit.innerHTML = `<i data-lucide="upload" class="w-4 h-4"></i><span>Proses Import Produk</span>`;
                alert('Terjadi kesalahan jaringan saat import data produk: ' + err.message);
            }
        }

        // ==========================================
        // MANAJEMEN VARIAN PRODUK (DENGAN / TANPA BIAYA)
        // CRUD VARIAN PRODUK & SUB-TAB RESEP PILIHAN VARIAN
