            document.getElementById('pvam-variant-name').value = '';
            document.getElementById('pvam-sku-variant').value = `${productSku}-VAR${Math.floor(Math.random()*900 + 100)}`;
            document.getElementById('pvam-add-price').value = '0';
            document.getElementById('pvam-add-cogs').value = '0';
            document.getElementById('pvam-submit-btn').innerText = 'Simpan Varian';
            document.getElementById('product-variant-add-modal').classList.remove('hidden');
