        async function loadOpeningShiftProductsTable() {
            try {
                const res = await fetch('api.php?action=get_opening_shift_products');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
                state.openingShiftProducts = data.products || [];

                const tbody = document.getElementById('opening-shift-products-table-body');
                if (!tbody) return;

                if (state.openingShiftProducts.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="7" class="py-4 text-center text-slate-400">Belum ada produk pelacakan opening shift. Klik '+ Tambah Produk' untuk menambahkan.</td></tr>`;
                    return;
                }

                tbody.innerHTML = state.openingShiftProducts.map((p, idx) => {
                    const statusBadge = p.is_active != 0
                        ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800">Aktif Dilacak</span>'
                        : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 text-slate-600">Nonaktif</span>';

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-4 text-center font-mono font-bold text-slate-500">${p.sort_order || (idx + 1)}</td>
                            <td class="py-3 px-4 font-mono font-bold text-indigo-700">${p.sku}</td>
                            <td class="py-3 px-4 font-black text-slate-800">
                                <span class="mr-1.5">${p.image_emoji || '📦'}</span>${p.name}${(p.effective_is_stockable === 0 || p.requires_stock === 0) ? ' <span class="inline-block text-[9px] px-1.5 py-0.2 bg-violet-100 text-violet-800 border border-violet-200 rounded font-bold">⚡ Tanpa Stok</span>' : ''}
                            </td>
                            <td class="py-3 px-4">
                                <span class="px-2 py-0.5 rounded-md text-[10px] font-bold ${p.product_type === 'RAW_MATERIAL' ? 'bg-amber-100 text-amber-900' : 'bg-indigo-100 text-indigo-900'}">${p.product_type}</span>
                                <span class="text-[11px] text-slate-500 ml-1">• ${p.category}</span>
                            </td>
                            <td class="py-3 px-4 font-semibold text-slate-600">${p.unit}</td>
                            <td class="py-3 px-4 text-center">${statusBadge}</td>
                            <td class="py-3 px-4 text-center space-x-1 whitespace-nowrap">
                                <button onclick="toggleOpeningShiftProductStatus(${p.product_id}, ${p.is_active != 0 ? 0 : 1})" class="px-2.5 py-1 ${p.is_active != 0 ? 'bg-amber-50 text-amber-700 hover:bg-amber-100' : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'} rounded-lg text-[11px] font-bold transition-colors">
                                    ${p.is_active != 0 ? 'Nonaktifkan' : 'Aktifkan'}
                                </button>
                                <button onclick="deleteOpeningShiftProduct(${p.product_id}, '${p.name.replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-rose-50 text-rose-600 hover:bg-rose-100 rounded-lg text-[11px] font-bold transition-colors">
                                    Hapus
                                </button>
                            </td>
                        </tr>
                    `;
                }).join('');
                lucide.createIcons();
            } catch (err) {
                console.error('Gagal memuat produk opening shift:', err);
            }
        }

        async function openOpeningShiftProductModal() {
            // Load dropdown seluruh produk aktif
            const selectEl = document.getElementById('osp-modal-product-select');
            if (selectEl) {
                const prods = state.allProducts && state.allProducts.length > 0 ? state.allProducts : state.products;
                // Exclude yang sudah terdaftar
                const existingIds = (state.openingShiftProducts || []).map(o => Number(o.product_id));
                selectEl.innerHTML = prods.map(p => {
                    const isAlready = existingIds.includes(Number(p.id));
                    return `<option value="${p.id}" ${isAlready ? 'disabled class="text-slate-300"' : ''}>${p.sku} - ${p.name} (${p.unit}) ${isAlready ? '[Sudah Terdaftar]' : ''}</option>`;
                }).join('');
            }
            document.getElementById('osp-modal-sort-order').value = (state.openingShiftProducts ? state.openingShiftProducts.length + 1 : 1);
            document.getElementById('osp-modal-is-active').value = '1';
            document.getElementById('opening-shift-product-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeOpeningShiftProductModal() {
            document.getElementById('opening-shift-product-modal').classList.add('hidden');
        }

        async function saveOpeningShiftProductForm(e) {
            e.preventDefault();
            const prodId = parseInt(document.getElementById('osp-modal-product-select').value);
            const sortOrder = parseInt(document.getElementById('osp-modal-sort-order').value) || 0;
            const isActive = parseInt(document.getElementById('osp-modal-is-active').value);

            if (!prodId) {
                alert('Pilih produk yang valid.');
                return;
            }

            try {
                const res = await fetch('api.php?action=save_opening_shift_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ product_id: prodId, sort_order: sortOrder, is_active: isActive })
                });
                const data = await res.json();
                alert(data.message || (data.success ? 'Berhasil disimpan!' : 'Gagal menyimpan'));
                if (data.success) {
                    closeOpeningShiftProductModal();
                    loadOpeningShiftProductsTable();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function toggleOpeningShiftProductStatus(productId, newStatus) {
            try {
                const res = await fetch('api.php?action=save_opening_shift_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ product_id: productId, is_active: newStatus })
                });
                const data = await res.json();
                if (data.success) {
                    loadOpeningShiftProductsTable();
                } else alert(data.message || data.error);
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function deleteOpeningShiftProduct(productId, name) {
            if (!confirm(`Hapus produk '${name}' dari daftar pelacakan Opening Shift?`)) return;
            try {
                const res = await fetch('api.php?action=delete_opening_shift_product', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ product_id: productId })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadOpeningShiftProductsTable();
                }
            } catch (err) {
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // 6. RECIPE / BOM (BILL OF MATERIALS)
        // ==========================================
        async function loadBOMRecipes() {
            const res = await fetch('api.php?action=get_recipes');
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }
            state.recipesData = data;

            document.getElementById('bom-cards-grid').innerHTML = data.finished_goods.map(fg => `
                <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-3">
                    <div class="flex items-center justify-between border-b pb-2.5">
                        <div>
                            <h4 class="font-bold text-slate-800 text-sm flex items-center space-x-1.5">
                                <span class="text-xl">☕</span>
                                <span>${fg.name}</span>
                            </h4>
                            <p class="text-[10px] text-slate-400 font-medium">${fg.sku} • Jual: ${formatRupiah(fg.selling_price)}</p>
                        </div>
                        <button onclick="openAddRecipeModal(${fg.id}, '${fg.name}')" class="px-3 py-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-xl text-xs font-bold border border-indigo-200 flex items-center space-x-1 transition-colors">
                            <i data-lucide="plus" class="w-3.5 h-3.5"></i>
                            <span>Bahan Baku</span>
                        </button>
                    </div>

                    <!-- Ingredients List -->
                    <div class="space-y-1.5 text-xs">
                        ${fg.ingredients && fg.ingredients.length > 0 ? fg.ingredients.map(ing => `
                            <div class="flex items-center justify-between p-2.5 bg-slate-50 rounded-xl border border-slate-100">
                                <div>
                                    <span class="font-bold text-slate-700">${ing.ingredient_name}</span>
                                    <span class="text-[10px] text-slate-400 block">${ing.qty_needed} ${ing.unit} @ ${formatRupiah(ing.ingredient_cogs)}/${ing.unit}</span>
                                </div>
                                <div class="flex items-center space-x-2">
                                    <span class="font-mono text-slate-700 font-bold">${formatRupiah(ing.subtotal_ingredient_cost)}</span>
                                    <button onclick="deleteRecipeItem(${ing.id})" class="text-rose-500 hover:text-rose-700 p-1">
                                        <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                    </button>
                                </div>
                            </div>
                        `).join('') : '<p class="text-slate-400 text-center py-2.5 font-medium">Belum ada formula resep bahan</p>'}
                    </div>

                    <!-- Total BOM Cost Calculation -->
                    <div class="p-3 bg-emerald-50 rounded-xl border border-emerald-200 flex justify-between items-center text-xs">
                        <span class="font-bold text-emerald-900">Total HPP Berbasis Resep:</span>
                        <span class="font-black text-emerald-800 text-sm font-mono">${formatRupiah(fg.calculated_cogs)}</span>
                    </div>
                </div>
            `).join('');
            lucide.createIcons();
        }

        function renderUnitSelectOptions(selectId, selectedUnit) {
            const select = document.getElementById(selectId);
            if (!select) return;
            let units = (state.productUnits && state.productUnits.length > 0)
                ? state.productUnits.map(u => ({ code: u.code, label: `${u.code} - ${u.name}` }))
                : ['pcs', 'cup', 'botol', 'porsi', 'gram', 'kg', 'ml', 'liter', 'pack', 'box'].map(u => ({ code: u, label: u }));
            
            const currentCode = (selectedUnit || '').toLowerCase().trim();
            if (currentCode) {
                const exists = units.some(u => u.code.toLowerCase() === currentCode);
                if (!exists) {
                    units.unshift({ code: selectedUnit, label: selectedUnit });
                }
            }
            select.innerHTML = units.map(u => `<option value="${u.code}" ${u.code.toLowerCase() === currentCode ? 'selected' : ''}>${u.label}</option>`).join('');
            if (currentCode) {
                select.value = selectedUnit;
            }
        }

        function onRecipeIngredientChange() {
            const ingId = parseInt(document.getElementById('recipe-ingredient-select').value);
            const rawList = state.recipesData?.raw_materials || [];
            const raw = rawList.find(r => r.id === ingId);
            const unit = raw ? raw.unit : 'gram';
            renderUnitSelectOptions('recipe-unit-name', unit);
        }

        function openAddRecipeModal(fgId, fgName) {
            document.getElementById('recipe-finished-id').value = fgId;
            document.getElementById('recipe-modal-product-name').innerText = 'Produk: ' + fgName;

            const rawList = state.recipesData?.raw_materials || [];
            document.getElementById('recipe-ingredient-select').innerHTML = rawList.map(rm => 
                `<option value="${rm.id}">${rm.name} (${rm.sku} - Satuan: ${rm.unit})</option>`
            ).join('');

            document.getElementById('recipe-qty-needed').value = '20';
            onRecipeIngredientChange();
            document.getElementById('recipe-add-modal').classList.remove('hidden');
        }

        function closeRecipeModal() {
            document.getElementById('recipe-add-modal').classList.add('hidden');
        }

        async function saveRecipeItemForm(e) {
            e.preventDefault();
            const payload = {
                finished_product_id: parseInt(document.getElementById('recipe-finished-id').value),
                ingredient_product_id: parseInt(document.getElementById('recipe-ingredient-select').value),
                qty_needed: parseFloat(document.getElementById('recipe-qty-needed').value),
                unit: document.getElementById('recipe-unit-name').value
            };

            const res = await fetch('api.php?action=save_recipe_item', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeRecipeModal();
                loadBOMRecipes();
            }
        }

        async function deleteRecipeItem(id) {
            if (!confirm('Hapus bahan baku ini dari formula resep?')) return;
            const res = await fetch('api.php?action=delete_recipe_item', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ recipe_id: id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) loadBOMRecipes();
        }

        // --- SUBTAB BOM: SWITCH SUBTAB & VARIANT BOM RECIPES ---
        function switchBOMSubTab(sub) {
            const btnBase = document.getElementById('bom-subtab-btn-base');
            const btnVar = document.getElementById('bom-subtab-btn-variant');
            const viewBase = document.getElementById('bom-view-base');
            const viewVar = document.getElementById('bom-view-variant');

            if (sub === 'base') {
                btnBase.className = 'px-3.5 py-1.5 bg-indigo-600 text-white rounded-xl text-xs font-bold transition-colors';
                btnVar.className = 'px-3.5 py-1.5 bg-slate-200 text-slate-700 rounded-xl text-xs font-bold hover:bg-slate-300 transition-colors';
                viewBase.classList.remove('hidden');
                viewVar.classList.add('hidden');
                loadBOMRecipes();
            } else {
                btnVar.className = 'px-3.5 py-1.5 bg-indigo-600 text-white rounded-xl text-xs font-bold transition-colors';
                btnBase.className = 'px-3.5 py-1.5 bg-slate-200 text-slate-700 rounded-xl text-xs font-bold hover:bg-slate-300 transition-colors';
                viewVar.classList.remove('hidden');
                viewBase.classList.add('hidden');
                loadVariantBOMRecipes();
            }
        }

        async function loadVariantBOMRecipes() {
            try {
                const res = await fetch('api.php?action=get_variant_recipes');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                state.variantRecipesData = data;
                const container = document.getElementById('variant-bom-cards-grid');
                if (!container) return;

                if (!data.variants || data.variants.length === 0) {
                    container.innerHTML = `<div class="col-span-2 text-center py-12 text-slate-400 text-sm">Belum ada varian produk yang terdaftar.</div>`;
                    return;
                }

                container.innerHTML = data.variants.map(v => {
                    const hasIngs = (v.ingredients && v.ingredients.length > 0);
                    const addPrice = Number(v.additional_price || 0);
                    const isFree = addPrice === 0;
                    const primaryVarId = v.primary_variant_id || v.id;
                    const productsList = v.products && v.products.length > 0 ? v.products : [{
                        variant_id: v.id,
                        product_id: v.product_id,
                        product_name: v.product_name || 'Produk Induk',
                        product_sku: v.product_sku || 'PRD',
                        sku_variant: v.sku_variant
                    }];

                    const priceBadge = isFree
                        ? `<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-600 border border-slate-300">Harga Normal (+Rp 0 Bebas Biaya)</span>`
                        : `<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300">+${formatRupiah(addPrice)} (Ada Tambahan Harga)</span>`;

                    return `
                        <div class="bg-white rounded-3xl border border-slate-200/90 shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col">
                            <!-- Card Header (Variant Identity & Action Toolbar) -->
                            <div class="p-4 border-b border-slate-100 bg-white space-y-3">
                                <div class="flex items-start justify-between gap-3">
                                    <div class="flex items-start space-x-3 min-w-0">
                                        <div class="w-10 h-10 rounded-2xl bg-gradient-to-br from-indigo-500 to-purple-600 text-white flex items-center justify-center shrink-0 text-base shadow-sm mt-0.5">
                                            ✨
                                        </div>
                                        <div class="min-w-0">
                                            <div class="flex flex-wrap items-center gap-1.5">
                                                <h4 class="font-black text-slate-900 text-sm leading-snug">
                                                    ${v.variant_name}
                                                </h4>
                                                <span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-black ${hasIngs ? 'bg-purple-100 text-purple-800 border border-purple-200' : 'bg-slate-100 text-slate-600 border border-slate-200'}">
                                                    ${hasIngs ? '⚡ Potong BOM Tambahan' : '🛡️ Tanpa Potong Bahan'}
                                                </span>
                                            </div>
                                            <p class="text-[11px] text-slate-400 font-mono mt-0.5">
                                                Kode / SKU Varian: <span class="text-indigo-600 font-bold bg-indigo-50 px-2 py-0.5 rounded-md border border-indigo-100">${v.sku_variant}</span>
                                            </p>
                                        </div>
                                    </div>

                                    <!-- Quick Delete Variant Action -->
                                    <button onclick="deleteProductVariantGroup('${v.variant_name.replace(/'/g, "\\'")}', ${JSON.stringify(v.variant_ids || [v.id])})" class="p-2 bg-rose-50 hover:bg-rose-100 text-rose-600 rounded-xl border border-rose-200 transition-colors shrink-0 shadow-2xs" title="Hapus Varian '${v.variant_name}' dari Semua Produk">
                                        <i data-lucide="trash-2" class="w-4 h-4"></i>
                                    </button>
                                </div>

                                <!-- Action Buttons Toolbar -->
                                <div class="flex flex-wrap items-center gap-1.5 pt-1 border-t border-slate-100">
                                    <button onclick='openApplyVariantToProductsModal(${JSON.stringify(v)})' class="px-3 py-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-xl text-xs font-bold border border-indigo-200 flex items-center space-x-1.5 transition-colors shadow-2xs">
                                        <i data-lucide="copy-plus" class="w-3.5 h-3.5 text-indigo-600 shrink-0"></i>
                                        <span>+ Kelola / Tambah Produk Induk</span>
                                    </button>
                                    <button onclick='openEditVariantFromBOMModal(${JSON.stringify(v)})' class="px-2.5 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-700 rounded-xl text-xs font-bold border border-amber-200 flex items-center space-x-1 transition-colors shadow-2xs">
                                        <i data-lucide="edit-3" class="w-3.5 h-3.5 text-amber-600 shrink-0"></i>
                                        <span>Edit Harga</span>
                                    </button>
                                    <button onclick="openAddVariantRecipeModal(${primaryVarId}, '${v.variant_name.replace(/'/g, "\\'")}', 'Semua Produk Terkait')" class="px-2.5 py-1.5 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-xl text-xs font-bold border border-purple-200 flex items-center space-x-1 transition-colors shadow-2xs">
                                        <i data-lucide="plus" class="w-3.5 h-3.5 text-purple-600 shrink-0"></i>
                                        <span>+ Resep Bahan</span>
                                    </button>
                                </div>

                                <!-- Parent Product Section: Multi-Products Pills Container -->
                                <div class="bg-slate-50/90 rounded-2xl p-3 border border-slate-200/80 space-y-2">
                                    <div class="flex flex-wrap items-center justify-between gap-2 text-xs">
                                        <div class="flex items-center space-x-1.5 font-black text-slate-700 uppercase tracking-wider text-[10px]">
                                            <span class="text-indigo-600">📦</span>
                                            <span>Diterapkan Pada Produk Induk:</span>
                                            <span class="bg-indigo-100 text-indigo-800 px-2 py-0.5 rounded-full text-[10px] font-bold">${productsList.length} Produk</span>
                                        </div>
                                        <div>
                                            ${priceBadge}
                                        </div>
                                    </div>

                                    <!-- Daftar Pill Produk Induk Terkait -->
                                    <div class="flex flex-wrap items-center gap-1.5 pt-0.5">
                                        ${productsList.map(p => `
                                            <div class="inline-flex items-center space-x-1.5 bg-white px-2.5 py-1 rounded-xl border border-indigo-200 shadow-2xs text-xs">
                                                <span class="w-2 h-2 rounded-full bg-emerald-500 shrink-0"></span>
                                                <span class="font-bold text-slate-800">${p.product_name}</span>
                                                <span class="text-[10px] font-mono text-slate-400 bg-slate-50 px-1 py-0.5 rounded">(${p.product_sku})</span>
                                                ${productsList.length > 1 ? `
                                                    <button onclick="detachProductFromVariant(${p.variant_id}, '${p.product_name.replace(/'/g, "\\'")}', '${v.variant_name.replace(/'/g, "\\'")}')" class="text-slate-300 hover:text-rose-600 ml-1 p-0.5 transition-colors" title="Lepas varian '${v.variant_name}' dari produk ${p.product_name}">
                                                        <i data-lucide="x" class="w-3 h-3"></i>
                                                    </button>
                                                ` : ''}
                                            </div>
                                        `).join('')}

                                        <button onclick='openApplyVariantToProductsModal(${JSON.stringify(v)})' class="inline-flex items-center space-x-1 px-2.5 py-1 rounded-xl border border-dashed border-indigo-300 text-indigo-600 hover:bg-indigo-50 text-[11px] font-bold transition-colors">
                                            <i data-lucide="plus" class="w-3 h-3"></i>
                                            <span>+ Tambah Produk Lain</span>
                                        </button>
                                    </div>
                                </div>
                            </div>

                            <!-- Card Body (Variant Ingredients: Berlaku untuk semua produk di atas) -->
                            <div class="p-4 flex-1 space-y-2 text-xs">
                                <div class="flex items-center justify-between text-[11px] font-bold text-slate-500 pb-0.5">
                                    <span>🧪 Formula Bahan Tambahan (Potong Stok saat Checkout):</span>
                                    <span class="text-slate-400 font-normal">Berlaku untuk semua produk induk</span>
                                </div>
                                ${hasIngs ? `
                                    <div class="space-y-1.5">
                                        ${v.ingredients.map(ing => `
                                            <div class="flex items-center justify-between p-2.5 bg-slate-50 rounded-xl border border-slate-100">
                                                <div class="min-w-0 pr-2">
                                                    <span class="font-bold text-slate-700 block truncate">${ing.ingredient_name}</span>
                                                    <span class="text-[10px] text-slate-400 block">${ing.qty_needed} ${ing.unit} @ ${formatRupiah(ing.ingredient_cogs)}/${ing.unit} ${ing.notes ? `• ${ing.notes}` : ''}</span>
                                                </div>
                                                <div class="flex items-center space-x-2 shrink-0">
                                                    <span class="font-mono text-slate-700 font-bold">${formatRupiah(ing.subtotal_ingredient_cost)}</span>
                                                    <button onclick="deleteVariantRecipeItem(${ing.id})" class="text-rose-500 hover:text-rose-700 p-1" title="Hapus bahan">
                                                        <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                                    </button>
                                                </div>
                                            </div>
                                        `).join('')}
                                    </div>
                                ` : `
                                    <div class="p-3 bg-slate-50/70 rounded-xl border border-dashed border-slate-200 text-center">
                                        <p class="text-slate-500 text-xs font-semibold">Tidak ada bahan baku tambahan.</p>
                                        <p class="text-[10px] text-slate-400 mt-0.5">Saat varian ini dipilih (contoh: galon tanpa tutup / refill), stok bahan tutup TIDAK akan dipotong.</p>
                                    </div>
                                `}
                            </div>

                            <!-- Card Footer (Total Variant Additional BOM Cost) -->
                            <div class="p-3.5 bg-gradient-to-r from-purple-50/90 to-indigo-50/90 border-t border-purple-100 flex justify-between items-center text-xs">
                                <span class="font-bold text-purple-900">Total HPP Tambahan Varian:</span>
                                <span class="font-black text-purple-900 text-sm font-mono">${formatRupiah(v.calculated_variant_cogs || 0)}</span>
                            </div>
                        </div>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function onVariantIngredientChange() {
            const ingId = parseInt(document.getElementById('vr-ingredient-select').value);
            const rawList = state.variantRecipesData ? (state.variantRecipesData.raw_materials || []) : [];
            const raw = rawList.find(r => r.id === ingId);
            const unit = raw ? raw.unit : 'pcs';
            renderUnitSelectOptions('vr-unit-name', unit);
        }

        function openAddVariantRecipeModal(vId, vName, pName) {
            document.getElementById('vr-variant-id').value = vId;
            document.getElementById('vr-modal-title-desc').innerText = `Varian: ${vName} (${pName})`;

            const rawList = state.variantRecipesData ? (state.variantRecipesData.raw_materials || []) : [];
            document.getElementById('vr-ingredient-select').innerHTML = rawList.map(rm => 
                `<option value="${rm.id}">${rm.name} (${rm.sku} - Satuan: ${rm.unit})</option>`
            ).join('');

            document.getElementById('vr-qty-needed').value = '1';
            onVariantIngredientChange();
            document.getElementById('vr-notes').value = '1 pcs per penjualan varian ini';
            document.getElementById('variant-recipe-add-modal').classList.remove('hidden');
        }

        function closeVariantRecipeModal() {
            document.getElementById('variant-recipe-add-modal').classList.add('hidden');
        }

        async function saveVariantRecipeItemForm(e) {
            e.preventDefault();
            const payload = {
                variant_id: parseInt(document.getElementById('vr-variant-id').value),
                ingredient_product_id: parseInt(document.getElementById('vr-ingredient-select').value),
                qty_needed: parseFloat(document.getElementById('vr-qty-needed').value),
                unit: document.getElementById('vr-unit-name').value.trim(),
                notes: document.getElementById('vr-notes').value.trim()
            };

            const res = await fetch('api.php?action=save_variant_recipe', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeVariantRecipeModal();
                loadVariantBOMRecipes();
                initApp(); // reload bootstrap data
            }
        }

        async function deleteVariantRecipeItem(id) {
            if (!confirm('Hapus bahan baku ini dari formula varian?')) return;
            const res = await fetch('api.php?action=delete_variant_recipe', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ variant_recipe_id: id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadVariantBOMRecipes();
                initApp();
            }
        }

        // ==========================================
        // 7. STOK CRUD & STOCK MOVEMENT
        // ==========================================
        function switchStockSubTab(sub) {
            const btnBal = document.getElementById('subtab-btn-balance');
            const btnMov = document.getElementById('subtab-btn-movements');
            const viewBal = document.getElementById('stock-view-balance');
            const viewMov = document.getElementById('stock-view-movements');

            if (sub === 'balance') {
                btnBal.className = 'px-3.5 py-1.5 bg-indigo-600 text-white rounded-xl text-xs font-bold';
                btnMov.className = 'px-3.5 py-1.5 bg-slate-200 text-slate-700 rounded-xl text-xs font-bold hover:bg-slate-300';
                viewBal.classList.remove('hidden');
                viewMov.classList.add('hidden');
                loadStockInventory();
            } else {
                btnMov.className = 'px-3.5 py-1.5 bg-indigo-600 text-white rounded-xl text-xs font-bold';
                btnBal.className = 'px-3.5 py-1.5 bg-slate-200 text-slate-700 rounded-xl text-xs font-bold hover:bg-slate-300';
                viewMov.classList.remove('hidden');
                viewBal.classList.add('hidden');
                loadStockMovements();
            }
        }

        function initStockBranchSelector() {
            const select = document.getElementById('stock-branch-select');
            if (!select) return;
            const curVal = select.value || 'ALL';
            let html = '<option value="ALL">🌐 Semua Cabang (Konsolidasi Global)</option>';
            if (Array.isArray(state.branches)) {
                state.branches.forEach(b => {
                    html += `<option value="${b.id}">📍 ${b.name} (${b.code || ''})</option>`;
                });
            }
            select.innerHTML = html;
            select.value = curVal;
        }

        function onStockBranchChange() {
            loadStockInventory();
            const viewMov = document.getElementById('stock-view-movements');
            if (viewMov && !viewMov.classList.contains('hidden')) {
                loadStockMovements();
            }
        }

        async function loadStockInventory() {
            initStockBranchSelector();
            const branchSelect = document.getElementById('stock-branch-select');
            const bId = branchSelect ? branchSelect.value : 'ALL';
            const isGlobal = (bId === 'ALL' || bId === '0' || bId === '');

            // Update Kolom Header
            const headerCol = document.getElementById('stock-col-header-balance');
            if (headerCol) {
                if (isGlobal) {
                    headerCol.innerHTML = `Stok Fisik Gabungan <span class="block text-[10px] text-indigo-600 font-semibold">(Semua Cabang)</span>`;
                } else {
                    const br = (state.branches || []).find(b => b.id == bId);
                    const brName = br ? br.name : `Cabang #${bId}`;
                    headerCol.innerHTML = `Stok Fisik Cabang <span class="block text-[10px] text-emerald-600 font-semibold">(${brName})</span>`;
                }
            }

            const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${bId}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('stock-balance-table-body').innerHTML = data.stocks.map(s => {
                const stockVal = parseFloat(s.stock);
                const reorderVal = parseFloat(s.reorder_point);
                const isWarning = stockVal <= reorderVal;

                // Breakdown cabang jika tampilan global
                let breakdownHtml = '';
                if (isGlobal && Array.isArray(s.branch_breakdown) && s.branch_breakdown.length > 0) {
                    breakdownHtml = `
                        <div class="flex flex-wrap gap-1 mt-1 justify-end">
                            ${s.branch_breakdown.map(bb => `
                                <span class="inline-flex items-center px-1.5 py-0.5 rounded text-[9px] bg-slate-100 text-slate-600 border border-slate-200 font-mono" title="${bb.branch_name}">
                                    <span class="font-semibold text-slate-800 mr-1">${bb.branch_name.replace('Cabang ', '')}:</span> ${bb.stock}
                                </span>
                            `).join('')}
                        </div>
                    `;
                }

                return `
                    <tr class="hover:bg-slate-50 transition-colors">
                        <td class="py-2.5 px-3 font-mono font-bold text-indigo-700">${s.sku}</td>
                        <td class="py-2.5 px-3 font-semibold text-slate-800">${s.image_emoji || ''} ${s.name}</td>
                        <td class="py-2.5 px-3"><span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold ${s.product_type === 'FINISHED_GOODS' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}">${s.product_type}</span></td>
                        <td class="py-2.5 px-3 text-slate-500 font-medium">${s.unit}</td>
                        <td class="py-2.5 px-3 text-right">
                            <span class="font-black text-sm font-mono ${isWarning ? 'text-rose-600' : 'text-slate-800'}">${s.stock}</span>
                            ${breakdownHtml}
                        </td>
                        <td class="py-2.5 px-3 text-right text-slate-500 font-mono">${s.reorder_point}</td>
                        <td class="py-2.5 px-3 text-right text-slate-700 font-mono">${formatRupiah(s.local_cogs)}</td>
                        <td class="py-2.5 px-3">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${isWarning ? 'bg-rose-100 text-rose-800 animate-pulse' : 'bg-emerald-100 text-emerald-800'}">
                                ${isWarning ? '⚠️ Menipis' : 'Aman'}
                            </span>
                        </td>
                        <td class="py-2.5 px-3 text-center">
                            <button onclick="openStockAdjustModal(${s.product_id}, ${isGlobal ? 'null' : bId})" class="px-2.5 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border border-indigo-200 rounded-lg text-[11px] font-bold shadow-sm transition-colors inline-flex items-center space-x-1" title="Atur / Setel Stok Awal Cabang">
                                <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
                                <span>Atur Stok</span>
                            </button>
                        </td>
                    </tr>
                `;
            }).join('');
            lucide.createIcons();
        }

        async function loadStockMovements() {
            const branchSelect = document.getElementById('stock-branch-select');
            const bId = branchSelect ? branchSelect.value : 'ALL';

            const res = await fetch(`api.php?action=get_stock_movements&branch_id=${bId}`);
            const data = await res.json();
            if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

            document.getElementById('stock-movements-table-body').innerHTML = data.movements.map(m => {
                let badgeClass = 'bg-slate-100 text-slate-700 font-bold';
                if (m.movement_type === 'BOM_DEDUCTION') badgeClass = 'bg-purple-100 text-purple-800 font-black';
                else if (m.movement_type === 'STOCK_OUT_SALE') badgeClass = 'bg-rose-100 text-rose-800 font-bold';
                else if (m.movement_type === 'PURCHASE') badgeClass = 'bg-emerald-100 text-emerald-800 font-bold';
                else if (m.movement_type === 'INITIAL_STOCK') badgeClass = 'bg-indigo-100 text-indigo-800 font-black';
                else if (m.movement_type === 'ADJUSTMENT_DAMAGE') badgeClass = 'bg-rose-100 text-rose-800 font-bold';
                else if (m.movement_type === 'ADJUSTMENT_OPNAME') badgeClass = 'bg-amber-100 text-amber-800 font-bold';

                const qtyVal = parseFloat(m.qty_change);
                return `
                    <tr class="hover:bg-slate-50 transition-colors">
                        <td class="py-2.5 px-3 text-slate-500 whitespace-nowrap text-[11px] font-mono">${m.created_at}</td>
                        <td class="py-2.5 px-3 font-semibold text-indigo-900 text-[11px] whitespace-nowrap">
                            <span class="px-2 py-0.5 bg-slate-100 rounded-md border border-slate-200">${m.branch_name || '-'}</span>
                        </td>
                        <td class="py-2.5 px-3 font-semibold text-slate-800">${m.product_name} (${m.unit})</td>
                        <td class="py-2.5 px-3"><span class="px-2 py-0.5 rounded-full text-[10px] ${badgeClass}">${m.movement_type}</span></td>
                        <td class="py-2.5 px-3 text-right font-black font-mono ${qtyVal < 0 ? 'text-rose-600' : 'text-emerald-600'}">${qtyVal > 0 ? '+' : ''}${m.qty_change}</td>
                        <td class="py-2.5 px-3 text-right text-slate-400 font-mono">${m.stock_before}</td>
                        <td class="py-2.5 px-3 text-right text-slate-800 font-bold font-mono">${m.stock_after}</td>
                        <td class="py-2.5 px-3 font-mono text-[10px] text-indigo-700 font-bold">${m.reference_no || '-'}</td>
                        <td class="py-2.5 px-3 text-slate-600 text-[11px]">${m.notes || '-'}</td>
                        <td class="py-2.5 px-3 text-slate-500">${m.user_name || 'Admin'}</td>
                    </tr>
                `;
            }).join('') || `<tr><td colspan="10" class="py-8 text-center text-slate-400">Belum ada riwayat pergerakan stok untuk cabang terpilih.</td></tr>`;
            lucide.createIcons();
        }

        // Variabel penampung stok saat ini untuk kalkulasi modal
        let currentModalBranchStocks = [];

        async function openStockAdjustModal(targetProductId = null, targetBranchId = null) {
            // 1. Populasi Dropdown Cabang
            const branchSelect = document.getElementById('adj-branch-select');
            if (branchSelect) {
                branchSelect.innerHTML = (state.branches || []).map(b => 
                    `<option value="${b.id}">📍 ${b.name} (${b.code || ''})</option>`
                ).join('');

                // Tentukan cabang default
                if (targetBranchId) {
                    branchSelect.value = targetBranchId;
                } else {
                    const pageBranch = document.getElementById('stock-branch-select')?.value;
                    if (pageBranch && pageBranch !== 'ALL') {
                        branchSelect.value = pageBranch;
                    } else if (state.currentBranch) {
                        branchSelect.value = state.currentBranch.id;
                    }
                }
            }

            // 2. Muat produk dan set stok awal
            await loadStockAdjustProducts(targetProductId);

            // 3. Setel default mode ke INITIAL_STOCK bila stok awal diedit
            document.getElementById('adj-type').value = 'INITIAL_STOCK';
            onStockAdjustTypeChange();

            document.getElementById('stock-adjust-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        async function loadStockAdjustProducts(selectedProductId = null) {
            const bId = parseInt(document.getElementById('adj-branch-select')?.value || (state.currentBranch ? state.currentBranch.id : 1));
            const prodSelect = document.getElementById('adj-product-select');
            if (prodSelect && prodSelect.options.length === 0) {
                prodSelect.innerHTML = '<option value="">⏳ Memuat daftar barang...</option>';
            }

            try {
                const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${bId}`);
                const data = await res.json();
                if (data.success && Array.isArray(data.stocks) && data.stocks.length > 0) {
                    currentModalBranchStocks = data.stocks;
                    prodSelect.innerHTML = currentModalBranchStocks.map(s => {
                        const icon = s.product_type === 'FINISHED_GOODS' ? '📦' : '🧪';
                        const typeLabel = s.product_type === 'FINISHED_GOODS' ? 'Barang Jadi' : 'Bahan Baku';
                        return `<option value="${s.product_id}" data-stock="${s.stock}" data-unit="${s.unit}">${icon} ${s.name} (${s.sku}) [${typeLabel}] - Stok Cabang Ini: ${s.stock} ${s.unit}</option>`;
                    }).join('');
                } else if (state.products && state.products.length > 0) {
                    // Fallback to bootstrap products if stock query is empty
                    prodSelect.innerHTML = state.products.map(p => {
                        const icon = p.product_type === 'FINISHED_GOODS' ? '📦' : '🧪';
                        const typeLabel = p.product_type === 'FINISHED_GOODS' ? 'Barang Jadi' : 'Bahan Baku';
                        return `<option value="${p.id}" data-stock="0" data-unit="${p.unit || 'pcs'}">${icon} ${p.name} (${p.sku}) [${typeLabel}] - Stok Cabang Ini: 0 ${p.unit || 'pcs'}</option>`;
                    }).join('');
                } else {
                    prodSelect.innerHTML = '<option value="">⚠️ Tidak ada data barang ditemukan</option>';
                }
            } catch (err) {
                console.error("Gagal memuat barang stok modal:", err);
                if (state.products && state.products.length > 0) {
                    prodSelect.innerHTML = state.products.map(p => {
                        const icon = p.product_type === 'FINISHED_GOODS' ? '📦' : '🧪';
                        const typeLabel = p.product_type === 'FINISHED_GOODS' ? 'Barang Jadi' : 'Bahan Baku';
                        return `<option value="${p.id}" data-stock="0" data-unit="${p.unit || 'pcs'}">${icon} ${p.name} (${p.sku}) [${typeLabel}] - Stok Cabang Ini: 0 ${p.unit || 'pcs'}</option>`;
                    }).join('');
                } else {
                    prodSelect.innerHTML = '<option value="">⚠️ Gagal memuat barang</option>';
                }
            }

            if (selectedProductId) {
                prodSelect.value = selectedProductId;
            }
            onStockAdjustProductChange();
        }

        async function onStockAdjustBranchChange() {
            const curPId = parseInt(document.getElementById('adj-product-select')?.value || 0);
            await loadStockAdjustProducts(curPId);
        }

        function onStockAdjustProductChange() {
            const prodSelect = document.getElementById('adj-product-select');
            const selectedOpt = prodSelect ? prodSelect.options[prodSelect.selectedIndex] : null;
            const curStock = selectedOpt ? parseFloat(selectedOpt.getAttribute('data-stock') || 0) : 0;
            const curUnit = selectedOpt ? (selectedOpt.getAttribute('data-unit') || 'pcs') : 'pcs';

            const badge = document.getElementById('adj-current-stock-badge');
            if (badge) badge.innerText = `${curStock} ${curUnit}`;

            updateStockAdjustPreview();
        }

        function onStockAdjustTypeChange() {
            const adjType = document.getElementById('adj-type').value;
            const labelEl = document.getElementById('adj-qty-label');
            const inputEl = document.getElementById('adj-qty');
            const notesEl = document.getElementById('adj-notes');

            if (adjType === 'INITIAL_STOCK') {
                labelEl.innerText = 'Nilai Stok Baru (Stok Awal Cabang):';
                inputEl.placeholder = 'Contoh: 100 (Stok akan disetel persis ke nilai ini)';
                if (!notesEl.value || notesEl.value.includes('Penerimaan') || notesEl.value.includes('Opname')) {
                    notesEl.value = 'Setel stok awal cabang';
                }
            } else if (adjType === 'PURCHASE') {
                labelEl.innerText = 'Jumlah Tambahan Stok Masuk (+):';
                inputEl.placeholder = 'Contoh: 50 (Menambah stok)';
                notesEl.value = 'Barang masuk pembelian / restock';
            } else if (adjType === 'ADJUSTMENT_DAMAGE') {
                labelEl.innerText = 'Jumlah Stok Berkurang / Rusak (-):';
                inputEl.placeholder = 'Contoh: 5 (Mengurangi stok)';
                notesEl.value = 'Barang rusak / bocor / kadaluwarsa';
            } else {
                labelEl.innerText = 'Selisih Kuantitas Opname (+ / -):';
                inputEl.placeholder = 'Contoh: 10 atau -3';
                notesEl.value = 'Koreksi penyesuaian stock opname fisik';
            }
            updateStockAdjustPreview();
        }

        function updateStockAdjustPreview() {
            const prodSelect = document.getElementById('adj-product-select');
            const selectedOpt = prodSelect ? prodSelect.options[prodSelect.selectedIndex] : null;
            const curStock = selectedOpt ? parseFloat(selectedOpt.getAttribute('data-stock') || 0) : 0;
            const curUnit = selectedOpt ? (selectedOpt.getAttribute('data-unit') || '') : '';

            const adjType = document.getElementById('adj-type').value;
            const inputVal = parseFloat(document.getElementById('adj-qty').value) || 0;
            const previewEl = document.getElementById('adj-preview-calc');
            if (!previewEl) return;

            let newStock = curStock;
            let diff = 0;

            if (adjType === 'INITIAL_STOCK') {
                newStock = inputVal;
                diff = newStock - curStock;
            } else if (adjType === 'ADJUSTMENT_DAMAGE') {
                diff = -Math.abs(inputVal);
                newStock = curStock + diff;
            } else {
                diff = inputVal;
                newStock = curStock + diff;
            }

            const diffText = diff >= 0 ? `+${diff}` : `${diff}`;
            const warnText = newStock < 0 ? '<span class="text-rose-600 font-bold ml-2">⚠️ Stok minus tidak diizinkan!</span>' : '';
            previewEl.innerHTML = `Perhitungan: Stok saat ini <b>${curStock} ${curUnit}</b> → Stok baru <b>${newStock} ${curUnit}</b> (Perubahan: <b>${diffText}</b>)${warnText}`;
        }

        function closeStockAdjustModal() {
            document.getElementById('stock-adjust-modal').classList.add('hidden');
        }

        async function saveStockAdjustForm(e) {
            e.preventDefault();
            const branchId = parseInt(document.getElementById('adj-branch-select').value);
            const pId = parseInt(document.getElementById('adj-product-select').value);
            const adjType = document.getElementById('adj-type').value;
            const inputVal = parseFloat(document.getElementById('adj-qty').value);
            const notes = document.getElementById('adj-notes').value.trim();

            if (isNaN(inputVal)) {
                alert('Silakan masukkan angka kuantitas yang valid.');
                return;
            }

            let payload = {
                branch_id: branchId,
                product_id: pId,
                adjustment_type: adjType,
                notes: notes,
                user_id: state.currentUser ? state.currentUser.id : 1
            };

            if (adjType === 'INITIAL_STOCK') {
                payload.exact_stock = inputVal;
            } else if (adjType === 'ADJUSTMENT_DAMAGE') {
                payload.qty_change = -Math.abs(inputVal);
            } else {
                payload.qty_change = inputVal;
            }

            const res = await fetch('api.php?action=adjust_stock', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeStockAdjustModal();
                loadStockInventory();
                loadStockMovements();
            }
        }

