            if (elRecSales) elRecSales.innerText = formatRupiah(pnl.receivable_sales || 0);

            document.getElementById('pnl-discount').innerText = `(${formatRupiah(pnl.discount)})`;
            document.getElementById('pnl-cogs').innerText = `(${formatRupiah(pnl.cogs)})`;
            document.getElementById('pnl-cogs-detail').innerText = formatRupiah(pnl.cogs);
            document.getElementById('pnl-gross-profit').innerText = `${formatRupiah(pnl.gross_profit)} (${pnl.gross_margin_percent}%)`;
            document.getElementById('pnl-total-expenses').innerText = `(${formatRupiah(pnl.total_operating_expenses)})`;

            document.getElementById('pnl-expenses-list').innerHTML = pnl.operating_expenses_list.map(exp => `
                <div class="flex justify-between items-center py-1 border-b border-dashed border-slate-100">
                    <span>${exp.category} ${exp.source === 'REIMBURSEMENT_ESS' ? '<span class="text-[9px] px-2 py-0.5 bg-amber-100 text-amber-800 rounded-full font-bold ml-1">ESS Klaim</span>' : ''}</span>
                    <span class="font-bold text-slate-700 font-mono">${formatRupiah(exp.total_amount)}</span>
                </div>
            `).join('') || `<p class="text-slate-400">Belum ada beban operasional tercatat</p>`;

            document.getElementById('pnl-operating-income').innerText = formatRupiah(pnl.operating_income);
            document.getElementById('pnl-tax').innerText = `(${formatRupiah(pnl.estimated_tax)})`;
            document.getElementById('pnl-net-profit').innerText = formatRupiah(pnl.net_profit);
            document.getElementById('pnl-net-margin').innerText = `${pnl.net_margin_percent}%`;

            // Populasi Kotak Analisis Piutang Usaha & Realisasi Kas
            const elArRatio = document.getElementById('pnl-ar-ratio-badge');
            if (elArRatio) elArRatio.innerText = `Rasio Piutang: ${ar.receivable_ratio_percent || 0}%`;

            const elArBilled = document.getElementById('pnl-ar-billed');
            if (elArBilled) elArBilled.innerText = formatRupiah(ar.period_receivables_billed || 0);

            const elArCollected = document.getElementById('pnl-ar-collected');
            if (elArCollected) elArCollected.innerText = `+ ${formatRupiah(ar.period_receivables_collected || 0)}`;

            const elArPeriodOut = document.getElementById('pnl-ar-period-outstanding');
            if (elArPeriodOut) elArPeriodOut.innerText = formatRupiah(ar.period_receivables_outstanding || 0);

            const elArCumOut = document.getElementById('pnl-ar-cum-outstanding');
            if (elArCumOut) elArCumOut.innerText = formatRupiah(ar.cumulative_outstanding_receivables || 0);

            const elArCashSales = document.getElementById('pnl-ar-cash-realized-sales');
            if (elArCashSales) elArCashSales.innerText = formatRupiah(ar.cash_realized_sales || 0);

            const elArCashProfit = document.getElementById('pnl-ar-cash-realized-profit');
            if (elArCashProfit) elArCashProfit.innerText = formatRupiah(ar.cash_realized_net_profit || 0);

            lucide.createIcons();
        }

        // ==========================================
        // 9. MODUL BUKU CATATAN BEBAN OPERASIONAL CABANG & MASTER KATEGORI BEBAN
        // ==========================================
        function setExpenseSubtab(subtab) {
            state.expenseSubtab = subtab;
            const btnLedger = document.getElementById('subtab-btn-exp-ledger');
            const btnCat = document.getElementById('subtab-btn-exp-category');
            const viewLedger = document.getElementById('subtab-exp-ledger');
            const viewCat = document.getElementById('subtab-exp-category');
            const btnAddExp = document.getElementById('exp-btn-add-expense');
            const btnAddCat = document.getElementById('exp-btn-add-category');

            if (subtab === 'ledger') {
                if (btnLedger) {
                    btnLedger.className = "px-4 py-2 rounded-xl text-xs font-bold bg-rose-600 text-white transition-colors flex items-center space-x-1.5 shadow-2xs";
                }
                if (btnCat) {
                    btnCat.className = "px-4 py-2 rounded-xl text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors flex items-center space-x-1.5";
                }
                if (viewLedger) viewLedger.classList.remove('hidden');
                if (viewCat) viewCat.classList.add('hidden');
                if (btnAddExp) btnAddExp.classList.remove('hidden');
                if (btnAddCat) btnAddCat.classList.add('hidden');
                loadBranchExpensesTable();
            } else {
                if (btnLedger) {
                    btnLedger.className = "px-4 py-2 rounded-xl text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors flex items-center space-x-1.5";
                }
                if (btnCat) {
                    btnCat.className = "px-4 py-2 rounded-xl text-xs font-bold bg-indigo-600 text-white transition-colors flex items-center space-x-1.5 shadow-2xs";
                }
                if (viewLedger) viewLedger.classList.add('hidden');
                if (viewCat) viewCat.classList.remove('hidden');
                if (btnAddExp) btnAddExp.classList.add('hidden');
                if (btnAddCat) btnAddCat.classList.remove('hidden');
                loadExpenseCategoriesTable(true);
            }
            lucide.createIcons();
        }

        async function loadBranchExpensesModule() {
            // Set default date jika belum terisi
            const startDateEl = document.getElementById('exp-ledger-start-date');
            const endDateEl = document.getElementById('exp-ledger-end-date');
            if (startDateEl && !startDateEl.value) {
                const now = new Date();
                startDateEl.value = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
            }
            if (endDateEl && !endDateEl.value) {
                endDateEl.value = new Date().toISOString().split('T')[0];
            }

            // Populasi cabang di dropdown filter ledger
            const branchSelect = document.getElementById('exp-ledger-branch-select');
            if (branchSelect) {
                const curBId = state.currentBranch ? state.currentBranch.id : '';
                branchSelect.innerHTML = `<option value="">Semua Cabang Outlet</option>` + (state.branches || []).map(b => `
                    <option value="${b.id}" ${b.id === curBId ? 'selected' : ''}>${b.name}</option>
                `).join('');
            }

            // Muat kategori beban terlebih dahulu
            await loadExpenseCategoriesTable(false);

            // Muat konten sub-tab aktif
            if (state.expenseSubtab === 'category') {
                renderExpenseCategoriesTable();
            } else {
                await loadBranchExpensesTable();
            }
        }

        function populateExpenseCategoryFilterDropdown() {
            const filterSelect = document.getElementById('exp-ledger-cat-filter');
            if (!filterSelect) return;
            const curVal = filterSelect.value || 'ALL';
            let html = '<option value="ALL">Semua Kategori Beban</option>';
            (state.expenseCategories || []).forEach(cat => {
                html += `<option value="${cat.name}">${cat.name}</option>`;
            });
            filterSelect.innerHTML = html;
            filterSelect.value = curVal;
        }

        async function loadBranchExpensesTable() {
            try {
                const branchSelect = document.getElementById('exp-ledger-branch-select');
                const bId = branchSelect ? branchSelect.value : (state.currentBranch ? state.currentBranch.id : '');
                const sDate = document.getElementById('exp-ledger-start-date')?.value || '';
                const eDate = document.getElementById('exp-ledger-end-date')?.value || '';
                const catFilter = document.getElementById('exp-ledger-cat-filter')?.value || 'ALL';

                let url = `api.php?action=get_branch_expenses&category=${encodeURIComponent(catFilter)}`;
                if (bId) url += `&branch_id=${bId}`;
                if (sDate) url += `&start_date=${sDate}`;
                if (eDate) url += `&end_date=${eDate}`;

                const res = await fetch(url);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const expenses = data.expenses || [];
                const tbody = document.getElementById('branch-expenses-table-body');
                const totalBadge = document.getElementById('exp-ledger-total-badge');
                const kpiTotal = document.getElementById('exp-kpi-total-amount');
                const kpiCount = document.getElementById('exp-kpi-total-count');
                const kpiBranch = document.getElementById('exp-kpi-branch-name');

                const totalFormatted = formatRupiah(data.total_amount || 0);
                if (totalBadge) totalBadge.innerText = totalFormatted;
                if (kpiTotal) kpiTotal.innerText = totalFormatted;
                if (kpiCount) kpiCount.innerText = expenses.length;

                if (kpiBranch) {
                    if (bId) {
                        const br = (state.branches || []).find(b => b.id == bId);
                        kpiBranch.innerText = br ? br.name : `Cabang ID #${bId}`;
                    } else {
                        kpiBranch.innerText = 'Semua Cabang';
                    }
                }

                if (!tbody) return;

                if (expenses.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="7" class="text-center py-10 text-slate-400">Belum ada catatan beban operasional pada kriteria filter ini</td></tr>`;
                    return;
                }

                tbody.innerHTML = expenses.map(exp => {
                    const isManual = (exp.source === 'MANUAL');
                    let srcBadge = '<span class="px-2 py-0.5 bg-slate-100 text-slate-700 rounded-full font-bold text-[10px]">Manual Input</span>';
                    if (exp.source === 'VEHICLE_FUEL') srcBadge = '<span class="px-2 py-0.5 bg-amber-100 text-amber-800 rounded-full font-bold text-[10px]">Armada BBM</span>';
                    else if (exp.source === 'VEHICLE_SERVICE') srcBadge = '<span class="px-2 py-0.5 bg-rose-100 text-rose-800 rounded-full font-bold text-[10px]">Servis Armada</span>';
                    else if (exp.source === 'REIMBURSEMENT_ESS') srcBadge = '<span class="px-2 py-0.5 bg-purple-100 text-purple-800 rounded-full font-bold text-[10px]">ESS Klaim</span>';

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-4 font-mono text-slate-600">${exp.expense_date}</td>
                            <td class="py-3 px-4 font-bold text-slate-800">${exp.category}</td>
                            <td class="py-3 px-4 text-slate-600 font-medium">${exp.branch_name || 'Cabang'}</td>
                            <td class="py-3 px-4 text-slate-600 text-[11px] max-w-xs truncate">${exp.notes || '-'}</td>
                            <td class="py-3 px-4 text-center">${srcBadge}</td>
                            <td class="py-3 px-4 text-right font-mono font-black text-rose-700">${formatRupiah(exp.amount)}</td>
                            <td class="py-3 px-4 text-center">
                                ${isManual ? `
                                    <div class="inline-flex items-center space-x-1.5">
                                        <button onclick="editBranchExpense(${JSON.stringify(exp).replace(/"/g, '&quot;')})" title="Edit Beban" class="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-lg transition-colors">
                                            <i data-lucide="edit-3" class="w-4 h-4"></i>
                                        </button>
                                        <button onclick="deleteBranchExpense(${exp.id}, '${exp.category.replace(/'/g, "\\'")}', ${exp.amount})" title="Hapus Beban" class="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors">
                                            <i data-lucide="trash-2" class="w-4 h-4"></i>
                                        </button>
                                    </div>
                                ` : `
                                    <span class="text-[10px] text-slate-400 italic">Sistem Auto</span>
                                `}
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error('Gagal memuat daftar beban operasional:', err);
            }
        }

        // ==========================================
        // 9B. CRUD MASTER KATEGORI BEBAN OPERASIONAL
        // ==========================================
        async function loadExpenseCategoriesTable(render = true) {
            try {
                const res = await fetch('api.php?action=get_expense_categories');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                state.expenseCategories = data.expense_categories || [];

                const kpiCatCount = document.getElementById('exp-kpi-categories-count');
                if (kpiCatCount) kpiCatCount.innerText = state.expenseCategories.length;

                populateExpenseCategoryFilterDropdown();

                if (render) {
                    renderExpenseCategoriesTable();
                }
            } catch (err) {
                console.error('Gagal memuat kategori beban:', err);
            }
        }

        function renderExpenseCategoriesTable() {
            const tbody = document.getElementById('expense-categories-table-body');
            if (!tbody) return;

            const groupFilter = document.getElementById('exp-cat-group-filter')?.value || 'ALL';
            const statusFilter = document.getElementById('exp-cat-status-filter')?.value || 'ALL';
            const searchKeyword = (document.getElementById('exp-cat-search-input')?.value || '').toLowerCase().trim();

            let filtered = (state.expenseCategories || []).filter(cat => {
                if (groupFilter !== 'ALL' && cat.group_type !== groupFilter) return false;
                if (statusFilter !== 'ALL' && cat.is_active != statusFilter) return false;
                if (searchKeyword) {
                    const matchName = (cat.name || '').toLowerCase().includes(searchKeyword);
                    const matchCode = (cat.code || '').toLowerCase().includes(searchKeyword);
                    const matchDesc = (cat.description || '').toLowerCase().includes(searchKeyword);
                    if (!matchName && !matchCode && !matchDesc) return false;
                }
                return true;
            });

            if (filtered.length === 0) {
                tbody.innerHTML = `<tr><td colspan="8" class="text-center py-10 text-slate-400">Tidak ada kategori beban yang sesuai filter</td></tr>`;
                return;
            }

            const groupBadgeMap = {
                'OPERASIONAL': '<span class="px-2 py-0.5 bg-rose-50 text-rose-700 border border-rose-200 rounded-full font-bold text-[10px]">Operasional Toko</span>',
                'UMUM_ADMIN': '<span class="px-2 py-0.5 bg-indigo-50 text-indigo-700 border border-indigo-200 rounded-full font-bold text-[10px]">Umum & Admin</span>',
                'PENJUALAN': '<span class="px-2 py-0.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full font-bold text-[10px]">Penjualan & Promo</span>',
                'LAINNYA': '<span class="px-2 py-0.5 bg-slate-100 text-slate-700 border border-slate-200 rounded-full font-bold text-[10px]">Lain-lain</span>'
            };

            tbody.innerHTML = filtered.map((cat, idx) => {
                const isActive = (cat.is_active == 1);
                const usageCount = parseInt(cat.expense_usage_count || 0);
                const totalUsed = parseFloat(cat.total_amount_used || 0);

                return `
                    <tr class="hover:bg-slate-50 transition-colors ${!isActive ? 'opacity-60 bg-slate-50/50' : ''}">
                        <td class="py-3 px-4 text-center font-bold text-slate-400">${idx + 1}</td>
                        <td class="py-3 px-4 font-mono font-bold text-indigo-700">${cat.code}</td>
                        <td class="py-3 px-4 font-black text-slate-800">${cat.name}</td>
                        <td class="py-3 px-4">${groupBadgeMap[cat.group_type] || cat.group_type}</td>
                        <td class="py-3 px-4 text-slate-500 text-[11px] max-w-xs truncate">${cat.description || '-'}</td>
                        <td class="py-3 px-4 text-center">
                            <button onclick="toggleExpenseCategoryStatus(${cat.id}, ${cat.is_active})" title="Klik untuk ubah status" class="px-2.5 py-1 rounded-full text-[10px] font-black cursor-pointer transition-colors ${isActive ? 'bg-emerald-100 text-emerald-800 hover:bg-emerald-200' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}">
                                ${isActive ? '✓ Aktif' : '✕ Nonaktif'}
                            </button>
                        </td>
                        <td class="py-3 px-4 text-right">
                            <span class="inline-flex items-center space-x-1 font-mono font-bold ${usageCount > 0 ? 'text-rose-700' : 'text-slate-400'}">
                                <span>${usageCount} Trx</span>
                                <span class="text-[10px]">(${formatRupiah(totalUsed)})</span>
                            </span>
                        </td>
                        <td class="py-3 px-4 text-center">
                            <div class="inline-flex items-center space-x-1.5">
                                <button onclick="editExpenseCategory(${JSON.stringify(cat).replace(/"/g, '&quot;')})" title="Edit Kategori" class="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors">
                                    <i data-lucide="edit-3" class="w-4 h-4"></i>
                                </button>
                                <button onclick="deleteExpenseCategory(${cat.id}, '${cat.name.replace(/'/g, "\\'")}', ${usageCount})" title="${usageCount > 0 ? 'Kategori sedang digunakan transaksi' : 'Hapus Kategori'}" class="p-1.5 ${usageCount > 0 ? 'text-slate-300 cursor-not-allowed' : 'text-slate-400 hover:text-rose-600 hover:bg-rose-50 cursor-pointer'} rounded-lg transition-colors">
                                    <i data-lucide="trash-2" class="w-4 h-4"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function openExpenseCategoryModal(cat = null) {
            const modal = document.getElementById('expense-category-modal');
            const titleEl = document.getElementById('expense-category-modal-title');
            if (!modal) return;

            if (cat) {
                titleEl.innerText = 'Edit Kategori Beban';
                document.getElementById('exp-cat-id').value = cat.id;
                document.getElementById('exp-cat-code').value = cat.code;
                document.getElementById('exp-cat-name').value = cat.name;
                document.getElementById('exp-cat-group').value = cat.group_type || 'OPERASIONAL';
                document.getElementById('exp-cat-desc').value = cat.description || '';
                document.getElementById('exp-cat-is-active').checked = (cat.is_active == 1);
            } else {
                titleEl.innerText = 'Tambah Kategori Beban Baru';
                document.getElementById('exp-cat-id').value = '';
                document.getElementById('exp-cat-code').value = '';
                document.getElementById('exp-cat-name').value = '';
                document.getElementById('exp-cat-group').value = 'OPERASIONAL';
                document.getElementById('exp-cat-desc').value = '';
                document.getElementById('exp-cat-is-active').checked = true;
            }

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeExpenseCategoryModal() {
            const modal = document.getElementById('expense-category-modal');
            if (modal) modal.classList.add('hidden');
        }

        function autoGenerateExpenseCategoryCode() {
            const name = document.getElementById('exp-cat-name')?.value.trim() || '';
            let slug = name.replace(/[^A-Za-z0-9]/g, '').toUpperCase().substring(0, 6);
            if (!slug) slug = 'EXP' + Math.floor(100 + Math.random() * 900);
            else slug = 'EXP-' + slug;
            document.getElementById('exp-cat-code').value = slug;
        }

        async function saveExpenseCategoryForm(e) {
            e.preventDefault();
            const id = document.getElementById('exp-cat-id').value;
            const code = document.getElementById('exp-cat-code').value.trim();
            const name = document.getElementById('exp-cat-name').value.trim();
            const groupType = document.getElementById('exp-cat-group').value;
            const description = document.getElementById('exp-cat-desc').value.trim();
            const isActive = document.getElementById('exp-cat-is-active').checked ? 1 : 0;

            if (!name) {
                alert('Nama kategori beban wajib diisi!');
                return;
            }

            const payload = {
                id: id ? parseInt(id) : null,
                code: code,
                name: name,
                group_type: groupType,
                description: description,
                is_active: isActive
            };

            try {
                const res = await fetch('api.php?action=save_expense_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    closeExpenseCategoryModal();
                    await loadExpenseCategoriesTable(true);
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        function editExpenseCategory(cat) {
            openExpenseCategoryModal(cat);
        }

        async function toggleExpenseCategoryStatus(id, currentStatus) {
            try {
                const res = await fetch('api.php?action=toggle_expense_category_status', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id, is_active: (currentStatus == 1 ? 0 : 1) })
                });
                const data = await res.json();
                if (data.success) {
                    await loadExpenseCategoriesTable(true);
                } else {
                    alert(data.message || data.error);
                }
            } catch (err) {
                console.error(err);
            }
        }

        async function deleteExpenseCategory(id, name, usageCount) {
            if (usageCount > 0) {
                alert(`Kategori '${name}' tidak dapat dihapus karena masih digunakan oleh ${usageCount} transaksi beban operasional.\nSilakan nonaktifkan status kategori sebagai gantinya.`);
                return;
            }

            if (!confirm(`Hapus kategori beban '${name}'?\nOperasi ini tidak dapat dibatalkan.`)) {
                return;
            }

            try {
                const res = await fetch('api.php?action=delete_expense_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadExpenseCategoriesTable(true);
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        // ==========================================
        // 9C. MODAL INPUT & EDIT BEBAN OPERASIONAL
        // ==========================================
        function openBranchExpenseModal(expense = null) {
            const modal = document.getElementById('branch-expense-modal');
            const titleEl = document.getElementById('branch-expense-modal-title');
            const branchSelect = document.getElementById('be-branch-id');
            const catSelect = document.getElementById('be-category');
            const customInput = document.getElementById('be-category-custom');

            // Populasi cabang
            const curBranchId = state.currentBranch ? state.currentBranch.id : 1;
            branchSelect.innerHTML = (state.branches || []).map(b => `
                <option value="${b.id}" ${b.id === curBranchId ? 'selected' : ''}>${b.name}</option>
            `).join('');

            // Populasi opsi kategori dari state.expenseCategories yang aktif
            const activeCats = (state.expenseCategories || []).filter(c => c.is_active == 1);
            let catOptionsHtml = activeCats.map(c => `
                <option value="${c.name}">${c.name}</option>
            `).join('');
            catOptionsHtml += `<option value="CUSTOM">Lainnya (Tulis Kategori Kustom...)</option>`;
            catSelect.innerHTML = catOptionsHtml;

            if (expense) {
                titleEl.innerText = 'Edit Beban Operasional Cabang';
                document.getElementById('be-id').value = expense.id;
                branchSelect.value = expense.branch_id;
                document.getElementById('be-amount').value = expense.amount;
                document.getElementById('be-expense-date').value = expense.expense_date;
                document.getElementById('be-notes').value = expense.notes || '';

                const standardOptions = Array.from(catSelect.options).map(o => o.value);
                if (standardOptions.includes(expense.category)) {
                    catSelect.value = expense.category;
                    customInput.classList.add('hidden');
                    customInput.value = '';
                } else {
                    catSelect.value = 'CUSTOM';
                    customInput.classList.remove('hidden');
                    customInput.value = expense.category;
                }
            } else {
                titleEl.innerText = 'Catat Beban Operasional Cabang';
                document.getElementById('be-id').value = '';
                document.getElementById('be-amount').value = '';
                document.getElementById('be-expense-date').value = new Date().toISOString().split('T')[0];
                document.getElementById('be-notes').value = '';
                if (activeCats.length > 0) {
                    catSelect.value = activeCats[0].name;
                }
                customInput.classList.add('hidden');
                customInput.value = '';
            }

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeBranchExpenseModal() {
            document.getElementById('branch-expense-modal').classList.add('hidden');
        }

        function onBeCategoryChange() {
            const catSelect = document.getElementById('be-category');
            const customInput = document.getElementById('be-category-custom');
            if (catSelect.value === 'CUSTOM') {
                customInput.classList.remove('hidden');
                customInput.focus();
            } else {
                customInput.classList.add('hidden');
                customInput.value = '';
            }
        }

        function editBranchExpense(exp) {
            openBranchExpenseModal(exp);
        }

        async function saveBranchExpenseForm(e) {
            e.preventDefault();
            const id = document.getElementById('be-id').value;
            const branchId = parseInt(document.getElementById('be-branch-id').value) || (state.currentBranch ? state.currentBranch.id : 1);
            const catSelect = document.getElementById('be-category').value;
            const customCat = document.getElementById('be-category-custom').value.trim();
            const category = (catSelect === 'CUSTOM') ? customCat : catSelect;
            const amount = parseFloat(document.getElementById('be-amount').value) || 0;
            const expenseDate = document.getElementById('be-expense-date').value;
            const notes = document.getElementById('be-notes').value.trim();

            if (!category) {
                alert('Tulis nama kategori beban operasional!');
                return;
            }
            if (amount <= 0) {
                alert('Nominal beban harus lebih besar dari 0!');
                return;
            }

            const payload = {
                id: id ? parseInt(id) : null,
                branch_id: branchId,
                category: category,
                amount: amount,
                expense_date: expenseDate,
                notes: notes
            };

            try {
                const res = await fetch('api.php?action=save_branch_expense', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    closeBranchExpenseModal();
                    loadBranchExpensesTable();
                    if (state.currentTab === 'pnl') loadProfitLoss();
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function deleteBranchExpense(id, category, amount) {
            if (!confirm(`Hapus catatan beban '${category}' sebesar ${formatRupiah(amount)}?\nPenghapusan ini akan mengembalikan Laba Bersih cabang.`)) {
                return;
            }

            try {
                const res = await fetch('api.php?action=delete_branch_expense', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    loadBranchExpensesTable();
                    if (state.currentTab === 'pnl') loadProfitLoss();
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        function getEffectiveProductPrice(product, customer = null, category = null) {
            const cust = customer || state.selectedCustomer;
            const cat = category || state.selectedCustomerCategory || (cust ? cust.category : 'REGULER');
            const baseBranchPrice = Number(product.selling_price || 0);

            if (cat === 'MITRA') {
                // Check if specific mitra has contracted custom price
                if (cust && state.mitraPrices && state.mitraPrices.length > 0) {
                    const custom = state.mitraPrices.find(mp => mp.customer_id == cust.id && mp.product_id == product.id);
                    if (custom && Number(custom.custom_price) > 0) {
                        return { 
                            price: Number(custom.custom_price), 
                            tag: '🤝 Kontrak Khusus', 
                            isContract: true 
                        };
                    }
                }
                if (Number(product.mitra_price) > 0) {
                    return { price: Number(product.mitra_price), tag: '🤝 Tier Mitra', isContract: false };
                }
                return { price: Math.round(baseBranchPrice * 0.72), tag: '🤝 Tier Mitra', isContract: false };
            }

            if (cat === 'RESELLER') {
                if (Number(product.reseller_price) > 0) {
                    return { price: Number(product.reseller_price), tag: '📦 Reseller (-20%)', isContract: false };
                }
                return { price: Math.round(baseBranchPrice * 0.8), tag: '📦 Reseller (-20%)', isContract: false };
            }

            if (cat === 'MEMBER') {
                if (Number(product.member_price) > 0) {
                    return { price: Number(product.member_price), tag: '⭐ Member VIP (-10%)', isContract: false };
                }
                return { price: Math.round(baseBranchPrice * 0.9), tag: '⭐ Member VIP (-10%)', isContract: false };
            }

            // REGULER
            return { price: baseBranchPrice, tag: 'Ritel Standar', isContract: false };
        }

        // Render Dinamis Tombol Pilihan Tier Pelanggan di Halaman Kasir POS
        function renderPosTierButtons() {
            const container = document.getElementById('pos-tier-buttons');
            if (!container) return;

            // Ambil hanya kategori pelanggan yang aktif (is_active == 1)
            const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
            const activeCodes = activeCats.map(c => c.code);

            // Jika kategori yang sedang aktif saat ini dinonaktifkan, otomatis fallback ke kategori aktif pertama (atau REGULER)
            if (activeCodes.length > 0 && !activeCodes.includes(state.selectedCustomerCategory)) {
                state.selectedCustomerCategory = activeCodes.includes('REGULER') ? 'REGULER' : activeCodes[0];
                if (state.selectedCustomer && !activeCodes.includes(state.selectedCustomer.category)) {
                    state.selectedCustomer = (state.customers || []).find(c => (c.category || 'REGULER') === state.selectedCustomerCategory) || null;
                }
            }

            const currentCat = state.selectedCustomerCategory || 'REGULER';

            if (activeCats.length === 0) {
                container.innerHTML = `<span class="text-[11px] text-slate-400 italic px-2">Tidak ada kategori aktif</span>`;
                return;
            }

            container.innerHTML = activeCats.map(c => {
                const isSelected = (c.code === currentCat);
                const btnClass = isSelected 
                    ? 'px-2.5 py-1 rounded-lg text-[11px] font-bold bg-indigo-600 text-white shadow-xs transition-all'
                    : 'px-2.5 py-1 rounded-lg text-[11px] font-bold text-slate-600 hover:bg-slate-100 transition-all';
                
                // Label tombol tier
                let label = c.name;
                if (c.code === 'REGULER') label = 'Ritel';
                else if (c.code === 'MEMBER') label = 'Member';
                else if (c.code === 'RESELLER') label = 'Reseller';
                else if (c.code === 'MITRA') label = 'Mitra B2B';

                const emoji = c.icon_emoji ? c.icon_emoji + ' ' : '';
                return `
                    <button type="button" onclick="setPosCustomerCategory('${c.code}')" id="btn-tier-${c.code}" class="${btnClass}">
                        ${emoji}${label}
                    </button>
                `;
            }).join('');
        }

        function renderPosCustomerSelect() {
            const select = document.getElementById('pos-customer-select');
            if (!select) return;

            // Ambil daftar kategori aktif
            const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
            const activeCodes = activeCats.map(c => c.code);

            // Pastikan kategori tier aktif ada dalam daftar kategori aktif
            if (activeCodes.length > 0 && !activeCodes.includes(state.selectedCustomerCategory)) {
                state.selectedCustomerCategory = activeCodes.includes('REGULER') ? 'REGULER' : activeCodes[0];
            }

            const activeCat = state.selectedCustomerCategory || (state.selectedCustomer ? state.selectedCustomer.category : 'REGULER');

            if (!state.customers || state.customers.length === 0) {
                select.innerHTML = '<option value="1">Pelanggan Umum (Walk-in)</option>';
                return;
            }

            // Filter pelanggan yang ditampilkan: harus berstatus aktif dan berkategori aktif
            let filteredCusts = state.customers.filter(c => {
                const cCat = c.category || 'REGULER';
                return cCat === activeCat && (activeCodes.length === 0 || activeCodes.includes(cCat)) && c.is_active == 1;
            });

            // Jika belum ada pelanggan di tier ini, berikan placeholder
            if (filteredCusts.length === 0) {
                select.innerHTML = `<option value="">(Belum ada data pelanggan tier ${activeCat})</option>`;
                updatePosCustomerUI();
                return;
            }

            // Pastikan state.selectedCustomer ada dalam daftar tier aktif
            if (!state.selectedCustomer || (state.selectedCustomer.category || 'REGULER') !== activeCat || state.selectedCustomer.is_active != 1) {
                state.selectedCustomer = filteredCusts[0];
            }

            select.innerHTML = filteredCusts.map(c => {
                const isSelected = state.selectedCustomer && state.selectedCustomer.id === c.id;
                const catLabel = c.category === 'MITRA' ? '🤝 MITRA' : (c.category === 'MEMBER' ? '⭐ MEMBER' : (c.category === 'RESELLER' ? '📦 RESELLER' : 'RITEL'));
                return `<option value="${c.id}" ${isSelected ? 'selected' : ''}>${c.name} [${catLabel}]</option>`;
            }).join('');

            // Set value select ke customer yang terpilih
            if (state.selectedCustomer) {
                select.value = state.selectedCustomer.id;
            }

            updatePosCustomerUI();
        }

        function updatePosCustomerUI() {
            const cust = state.selectedCustomer;
            const cat = state.selectedCustomerCategory || (cust ? cust.category : 'REGULER');
            const badge = document.getElementById('pos-customer-category-badge');
            const desc = document.getElementById('pos-customer-tier-desc');

            if (badge) {
                badge.innerText = cat;
                if (cat === 'MITRA') {
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-emerald-100 text-emerald-800 border border-emerald-300';
                    if (desc) desc.innerText = `• Mitra Rekanan: ${cust ? cust.name : 'B2B'} (Harga Kontrak)`;
                } else if (cat === 'MEMBER') {
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-purple-100 text-purple-800 border border-purple-300';
                    if (desc) desc.innerText = '• Diskon Member Terdaftar (-10%)';
                } else if (cat === 'RESELLER') {
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-amber-100 text-amber-800 border border-amber-300';
                    if (desc) desc.innerText = '• Harga Grosir Reseller (-20%)';
                } else {
                    badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-slate-200 text-slate-700';
                    if (desc) desc.innerText = '• Harga Ritel Standar Cabang';
                }
            }

            // Sinkronisasi status tombol tier dinamis
            renderPosTierButtons();
        }

        function onPosCustomerChange() {
            const select = document.getElementById('pos-customer-select');
            const cId = parseInt(select.value);
            const found = state.customers.find(c => c.id === cId);
            if (found) {
                state.selectedCustomer = found;
                state.selectedCustomerCategory = found.category || 'REGULER';
            }
            updatePosCustomerUI();
            recalculateCartPrices();
            renderProducts();
            if (document.getElementById('check-delivery-mode')?.checked) {
                calculateDeliveryFeeForPOS();
            }
        }

        function setPosCustomerCategory(cat) {
            // Validasi apakah kategori ini aktif
            const activeCats = (state.customerCategories || []).filter(c => c.is_active == 1);
            const isCatActive = activeCats.some(c => c.code === cat);
            if (!isCatActive && activeCats.length > 0) {
                alert(`Kategori '${cat}' saat ini sedang dinonaktifkan dan tidak dapat digunakan di menu penjualan.`);
                return;
            }

            state.selectedCustomerCategory = cat;
            // Pilih pelanggan pertama yang sesuai dengan kategori tier ini
            const matchingCust = state.customers.find(c => (c.category || 'REGULER') === cat && c.is_active == 1);
            if (matchingCust) {
                state.selectedCustomer = matchingCust;
            } else {
                state.selectedCustomer = null;
            }
            // Re-render isi dropdown pelanggan agar HANYA memunculkan pelanggan dari tier yang dipilih
            renderPosTierButtons();
            renderPosCustomerSelect();
            recalculateCartPrices();
            renderProducts();
            if (document.getElementById('check-delivery-mode')?.checked) {
                calculateDeliveryFeeForPOS();
            }
        }

        function recalculateCartPrices() {
            if (!state.cart || state.cart.length === 0) return;
            const activeCust = state.selectedCustomer;
            const activeCat = state.selectedCustomerCategory || (activeCust ? activeCust.category : 'REGULER');

            if (activeCat === 'MITRA') {
                // Keluarkan produk dari keranjang jika tidak memiliki status kontrak khusus mitra ini
                const beforeLen = state.cart.length;
                state.cart = state.cart.filter(item => {
                    const contract = (state.mitraPrices || []).find(mp => mp.customer_id == (activeCust ? activeCust.id : 0) && mp.product_id == item.product_id);
                    return contract && Number(contract.custom_price) > 0;
                });
                if (state.cart.length < beforeLen) {
                    alert('Beberapa produk telah dikeluarkan dari keranjang belanja karena belum memiliki kesepakatan harga kontrak khusus untuk Mitra ini.');
                }
            }

            state.cart = state.cart.map(item => {
                const prod = state.products.find(p => p.id === item.product_id);
                if (!prod) return item;
                const priceInfo = getEffectiveProductPrice(prod);
                return {
                    ...item,
                    price: priceInfo.price,
                    price_tag: priceInfo.tag
                };
            });
            renderCart();
        }

        // Subtab Navigation inside Tab 9
        function setCustomerSubtab(subtab) {
            state.customerActiveSubtab = subtab;
            const subtabs = [
                { key: 'list', elId: 'subview-cust-list', btnId: 'subtab-btn-cust-list' },
                { key: 'mitra-pricing', elId: 'subview-cust-mitra', btnId: 'subtab-btn-cust-mitra' },
                { key: 'branch-pricing', elId: 'subview-cust-branch', btnId: 'subtab-btn-cust-branch' },
                { key: 'category', elId: 'subview-cust-category', btnId: 'subtab-btn-cust-category' },
                { key: 'maps', elId: 'subview-cust-maps', btnId: 'subtab-btn-cust-maps' }
            ];

            subtabs.forEach(item => {
                const el = document.getElementById(item.elId);
                const btn = document.getElementById(item.btnId);
                if (item.key === subtab) {
                    if (el) el.classList.remove('hidden');
                    if (btn) {
                        btn.className = 'px-4 py-2 rounded-xl text-xs font-bold bg-indigo-600 text-white transition-colors flex items-center space-x-1.5 shadow-sm';
                    }
                } else {
                    if (el) el.classList.add('hidden');
                    if (btn) {
                        btn.className = 'px-4 py-2 rounded-xl text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors flex items-center space-x-1.5';
                    }
                }
            });

            // Dynamic Action Button on Header Navbar per subtab
            const btnAddCust = document.getElementById('cust-btn-add-customer');
            const btnAddMitraPrice = document.getElementById('cust-btn-add-mitra-price');
            const btnAddBranchPrice = document.getElementById('cust-btn-add-branch-price');
            const btnAddCustCat = document.getElementById('cust-btn-add-cust-cat');
            const btnFitMap = document.getElementById('cust-btn-fit-map');

            if (btnAddCust) btnAddCust.classList.add('hidden');
            if (btnAddMitraPrice) btnAddMitraPrice.classList.add('hidden');
            if (btnAddBranchPrice) btnAddBranchPrice.classList.add('hidden');
            if (btnAddCustCat) btnAddCustCat.classList.add('hidden');
            if (btnFitMap) btnFitMap.classList.add('hidden');

            if (subtab === 'list' && btnAddCust) {
                btnAddCust.classList.remove('hidden');
            } else if (subtab === 'mitra-pricing' && btnAddMitraPrice) {
                btnAddMitraPrice.classList.remove('hidden');
            } else if (subtab === 'branch-pricing' && btnAddBranchPrice) {
                btnAddBranchPrice.classList.remove('hidden');
            } else if (subtab === 'category' && btnAddCustCat) {
                btnAddCustCat.classList.remove('hidden');
            } else if (subtab === 'maps') {
                if (btnAddCust) btnAddCust.classList.remove('hidden');
                if (btnFitMap) btnFitMap.classList.remove('hidden');
                setTimeout(() => {
                    initCustomerMap();
                }, 150);
            }

            if (subtab === 'list') loadCustomers();
            if (subtab === 'mitra-pricing') loadMitraPricing();
            if (subtab === 'branch-pricing') loadBranchPricing();
            if (subtab === 'category') loadCustomerCategories();
            lucide.createIcons();
        }

        // SUBTAB 1: CUSTOMERS CRUD
        async function loadCustomers() {
            try {
                const cat = state.custCategoryFilter || 'ALL';
                const kw = encodeURIComponent(state.custSearchKeyword || '');
                const res = await fetch(`api.php?action=get_customers&category=${cat}&keyword=${kw}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const custs = data.customers || [];
                state.customers = custs;

                // Update KPI Cards
                document.getElementById('cust-kpi-total').innerText = custs.length;
                document.getElementById('cust-kpi-member').innerText = custs.filter(c => c.category === 'MEMBER').length;
                document.getElementById('cust-kpi-reseller').innerText = custs.filter(c => c.category === 'RESELLER').length;
                document.getElementById('cust-kpi-mitra').innerText = custs.filter(c => c.category === 'MITRA').length;

                const tbody = document.getElementById('customers-table-body');
                if (custs.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="8" class="text-center py-8 text-slate-400">Tidak ada data pelanggan ditemukan</td></tr>`;
                    return;
                }

                tbody.innerHTML = custs.map(c => {
                    const catBadge = c.category === 'MITRA' ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">🤝 Mitra B2B</span>' :
                                    (c.category === 'MEMBER' ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-purple-100 text-purple-800">⭐ Member VIP</span>' :
                                    (c.category === 'RESELLER' ? '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800">📦 Reseller</span>' :
                                    '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-700">Ritel Reguler</span>'));

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-4 font-mono font-bold text-slate-600">${c.code}</td>
                            <td class="py-3 px-4 font-bold text-slate-900">${c.name}</td>
                            <td class="py-3 px-4">${catBadge}</td>
                            <td class="py-3 px-4 text-slate-600">${c.phone || '-'} <br><span class="text-[10px] text-slate-400">${c.email || ''}</span></td>
                            <td class="py-3 px-4 text-slate-600">${c.branch_name || 'Semua Cabang'}</td>
                            <td class="py-3 px-4 font-bold text-indigo-700">${c.discount_percent > 0 ? c.discount_percent + '%' : '-'}</td>
                            <td class="py-3 px-4 text-slate-500 max-w-[180px] truncate">${c.notes || '-'}</td>
                            <td class="py-3 px-4 text-center">
                                <div class="flex items-center justify-center space-x-1.5">
                                    ${c.category === 'MITRA' ? `
                                        <button onclick="switchDirectToMitraContract(${c.id})" title="Kelola Harga Kontrak Mitra Ini" class="px-2 py-1 text-[11px] font-bold text-emerald-700 bg-emerald-50 hover:bg-emerald-600 hover:text-white rounded-lg border border-emerald-200 transition-colors flex items-center space-x-1 shadow-2xs">
                                            <i data-lucide="file-signature" class="w-3.5 h-3.5"></i>
                                            <span>Set Kontrak</span>
                                        </button>
                                    ` : ''}
                                    <button onclick="focusCustomerOnMap(${c.id})" title="Lihat Titik di Peta Maps" class="p-1.5 text-indigo-600 hover:text-indigo-800 hover:bg-indigo-50 rounded-lg">
                                        <i data-lucide="map-pin" class="w-4 h-4"></i>
                                    </button>
                                    <button onclick="editCustomer(${c.id})" title="Edit Pelanggan" class="p-1.5 text-slate-500 hover:text-indigo-600 hover:bg-slate-100 rounded-lg">
                                        <i data-lucide="edit-3" class="w-4 h-4"></i>
                                    </button>
                                    ${c.id !== 1 ? `
                                        <button onclick="deleteCustomer(${c.id})" title="Hapus Pelanggan" class="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg">
                                            <i data-lucide="trash-2" class="w-4 h-4"></i>
                                        </button>
                                    ` : ''}
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('');

                if (state.customerActiveSubtab === 'maps' && state.customerMap) {
                    populateCustomerMapSelections();
                    renderCustomerMapMarkers();
                }

                renderPosCustomerSelect();
                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function setCustCategoryFilter(cat) {
            state.custCategoryFilter = cat;
            document.querySelectorAll('.cust-cat-pill').forEach(btn => {
                if ((cat === 'ALL' && btn.innerText === 'Semua') || btn.innerText.toLowerCase().includes(cat.toLowerCase())) {
                    btn.className = 'cust-cat-pill px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
                } else {
                    btn.className = 'cust-cat-pill px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-100 text-slate-700 hover:bg-slate-200';
                }
            });
            loadCustomers();
        }

        function filterCustomerList() {
            state.custSearchKeyword = document.getElementById('cust-search-keyword').value;
            loadCustomers();
        }

        function updateCustPickerBadge(lat, lon) {
            const badge = document.getElementById('cust-picker-coords-text');
            const gmapsLink = document.getElementById('cust-modal-gmaps-link');
            const nLat = parseFloat(lat);
            const nLon = parseFloat(lon);
            if (badge) {
                if (!isNaN(nLat) && !isNaN(nLon)) {
                    badge.innerText = `${nLat.toFixed(6)}, ${nLon.toFixed(6)}`;
                } else {
                    badge.innerText = '-';
                }
            }
            if (gmapsLink && !isNaN(nLat) && !isNaN(nLon)) {
                gmapsLink.href = `https://www.google.com/maps?q=${nLat.toFixed(6)},${nLon.toFixed(6)}`;
            }
        }

        function toggleCustSearchClearBtn() {
            const input = document.getElementById('cust-modal-search-input');
            const clearBtn = document.getElementById('cust-modal-search-clear-btn');
            if (input && clearBtn) {
                if (input.value.trim().length > 0) {
                    clearBtn.classList.remove('hidden');
                } else {
                    clearBtn.classList.add('hidden');
                }
            }
        }

        function clearCustAddressSearch() {
            const input = document.getElementById('cust-modal-search-input');
            if (input) input.value = '';
            toggleCustSearchClearBtn();
            const statusEl = document.getElementById('cust-modal-search-status');
            if (statusEl) {
                statusEl.innerHTML = '';
                statusEl.classList.add('hidden');
            }
        }

        function copyCustAddressToSearch() {
            const address = document.getElementById('cust-address')?.value?.trim() || '';
            const name = document.getElementById('cust-name')?.value?.trim() || '';
            const query = address || name;
            if (!query) {
                alert('Silakan ketik Nama Pelanggan atau Alamat Lengkap terlebih dahulu pada formulir di sebelah kiri.');
                return;
            }
            const input = document.getElementById('cust-modal-search-input');
            if (input) {
                input.value = query;
                toggleCustSearchClearBtn();
                searchCustAddressOnMap();
            }
        }

        function applyCustFoundCoords(lat, lon, label) {
            const latVal = Number(lat).toFixed(6);
            const lonVal = Number(lon).toFixed(6);
            document.getElementById('cust-latitude').value = latVal;
            document.getElementById('cust-longitude').value = lonVal;
            updateCustPickerFromInputs();
            if (state.customerPickerMap) {
                state.customerPickerMap.setView([lat, lon], 16);
            }
            const statusEl = document.getElementById('cust-modal-search-status');
            if (statusEl) {
                statusEl.innerHTML = `<div class="p-2 bg-emerald-50 border border-emerald-200/80 rounded-lg text-emerald-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="check-circle-2" class="w-3.5 h-3.5 text-emerald-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span class="font-bold">Lokasi Ditemukan (${latVal}, ${lonVal}):</span><p class="text-[10px] text-slate-600 truncate">${escapeHtml(label)}</p></div><a href="https://www.google.com/maps?q=${latVal},${lonVal}" target="_blank" rel="noopener noreferrer" class="text-indigo-600 hover:text-indigo-800 font-bold underline shrink-0 text-[10px]">Google Maps</a></div>`;
                statusEl.classList.remove('hidden');
                if (window.lucide) lucide.createIcons();
            }
        }

        async function searchCustAddressOnMap() {
            const input = document.getElementById('cust-modal-search-input');
            let query = input?.value?.trim() || '';
            if (!query) {
                query = document.getElementById('cust-address')?.value?.trim() || '';
                if (query && input) {
                    input.value = query;
                    toggleCustSearchClearBtn();
                }
            }
            if (!query) {
                alert('Silakan masukkan alamat pelanggan, nama tempat, atau link / koordinat Google Maps.');
                if (input) input.focus();
                return;
            }

            const searchBtn = document.getElementById('cust-modal-search-btn');
            const statusEl = document.getElementById('cust-modal-search-status');
            const originalBtnHtml = searchBtn ? searchBtn.innerHTML : '';

            if (searchBtn) {
                searchBtn.disabled = true;
                searchBtn.innerHTML = '<span class="inline-block animate-spin mr-1">⏳</span><span>Mencari...</span>';
            }
            if (statusEl) {
                statusEl.innerHTML = '<span class="text-slate-500 italic flex items-center space-x-1"><span class="animate-spin inline-block">⏳</span><span>Menghubungkan & mencari lokasi alamat di peta...</span></span>';
                statusEl.classList.remove('hidden');
            }

            const finishSearch = () => {
                if (searchBtn) {
                    searchBtn.disabled = false;
                    searchBtn.innerHTML = originalBtnHtml;
                    if (window.lucide) lucide.createIcons();
                }
            };

            // 1. Cek apakah input berupa koordinat langsung atau URL Google Maps
            const coordRegex = /([-+]?\d{1,2}\.\d+)[,\s]+([-+]?\d{1,3}\.\d+)/;
            const match = query.match(coordRegex);
            if (match) {
                const lat = parseFloat(match[1]);
                const lon = parseFloat(match[2]);
                if (!isNaN(lat) && !isNaN(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180) {
                    applyCustFoundCoords(lat, lon, `Koordinat Google Maps Terdeteksi: ${lat.toFixed(6)}, ${lon.toFixed(6)}`);
                    finishSearch();
                    return;
                }
            }

            // 2. Geocoding via OpenStreetMap Nominatim API
            try {
                const encodedQuery = encodeURIComponent(query);
                const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodedQuery}&addressdetails=1&limit=1`;
                const resp = await fetch(url, { headers: { 'Accept-Language': 'id,en' } });
                const data = await resp.json();

                if (Array.isArray(data) && data.length > 0) {
                    const lat = parseFloat(data[0].lat);
                    const lon = parseFloat(data[0].lon);
                    applyCustFoundCoords(lat, lon, data[0].display_name);
                } else {
                    let fallbackFound = false;
                    const commaParts = query.split(',').map(s => s.trim()).filter(Boolean);
                    if (commaParts.length > 1) {
                        const broaderQuery = commaParts.slice(1).join(', ');
                        const resp2 = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(broaderQuery)}&addressdetails=1&limit=1`, { headers: { 'Accept-Language': 'id,en' } });
                        const data2 = await resp2.json();
                        if (Array.isArray(data2) && data2.length > 0) {
                            fallbackFound = true;
                            const lat = parseFloat(data2[0].lat);
                            const lon = parseFloat(data2[0].lon);
                            applyCustFoundCoords(lat, lon, `${data2[0].display_name} (Wilayah Terdekat)`);
                        }
                    }

                    if (!fallbackFound) {
                        const gmapsSearchUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
                        if (statusEl) {
                            statusEl.innerHTML = `<div class="p-2 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="alert-triangle" class="w-3.5 h-3.5 text-amber-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span>Alamat tidak ditemukan otomatis.</span> <a href="${gmapsSearchUrl}" target="_blank" rel="noopener noreferrer" class="font-bold underline text-indigo-700 hover:text-indigo-900 inline-flex items-center space-x-1 ml-1"><span>Cari di Google Maps</span><i data-lucide="external-link" class="w-3 h-3 inline"></i></a><p class="text-[10px] text-slate-500 mt-0.5">Anda bisa salin link atau koordinat dari Google Maps dan tempel di sini.</p></div></div>`;
                            if (window.lucide) lucide.createIcons();
                        }
                    }
                }
            } catch (err) {
                const gmapsSearchUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
                if (statusEl) {
                    statusEl.innerHTML = `<div class="p-2 bg-rose-50 border border-rose-200 rounded-lg text-rose-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="wifi-off" class="w-3.5 h-3.5 text-rose-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span>Koneksi pencarian alamat gagal.</span> <a href="${gmapsSearchUrl}" target="_blank" rel="noopener noreferrer" class="font-bold underline text-indigo-700 hover:text-indigo-900 inline-flex items-center space-x-1 ml-1"><span>Buka Langsung di Google Maps</span><i data-lucide="external-link" class="w-3 h-3 inline"></i></a></div></div>`;
                    if (window.lucide) lucide.createIcons();
                }
            } finally {
                finishSearch();
            }
        }

        function onCustBranchChangeInModal() {
            const bId = document.getElementById('cust-branch')?.value;
            const b = (state.branches || []).find(x => x.id == bId);
            if (b && (!document.getElementById('cust-latitude')?.value || !document.getElementById('cust-id')?.value)) {
                const bLat = parseFloat(b.latitude);
                const bLon = parseFloat(b.longitude);
                if (!isNaN(bLat) && !isNaN(bLon)) {
                    document.getElementById('cust-latitude').value = bLat.toFixed(6);
                    document.getElementById('cust-longitude').value = bLon.toFixed(6);
                    updateCustPickerBadge(bLat, bLon);
                    if (state.customerPickerMap) {
                        state.customerPickerMap.setView([bLat, bLon], 14);
                        if (state.customerPickerMarker) state.customerPickerMarker.setLatLng([bLat, bLon]);
                    }
                }
            }
        }

        function resetCustPickerToBranch() {
            const bId = document.getElementById('cust-branch')?.value;
            const b = (state.branches || []).find(x => x.id == bId) || state.currentBranch || (state.branches || [])[0];
            if (b) {
                const bLat = parseFloat(b.latitude) || -6.195000;
                const bLon = parseFloat(b.longitude) || 106.823000;
                document.getElementById('cust-latitude').value = bLat.toFixed(6);
                document.getElementById('cust-longitude').value = bLon.toFixed(6);
                updateCustPickerBadge(bLat, bLon);
                if (state.customerPickerMap) {
                    state.customerPickerMap.setView([bLat, bLon], 14);
                    if (state.customerPickerMarker) state.customerPickerMarker.setLatLng([bLat, bLon]);
                }
            }
        }

        function openCustomerModal(cust = null) {
            const modal = document.getElementById('customer-modal');
            const title = document.getElementById('cust-modal-title');
            const branchSelect = document.getElementById('cust-branch');

            // Populate branch options
            const branchList = state.branches || [];
            branchSelect.innerHTML = '<option value="">Semua Cabang (Global)</option>' + 
                branchList.map(b => `<option value="${b.id}">${b.name}</option>`).join('');

            // Populate category options dynamically from active categories
            const catSelect = document.getElementById('cust-category');
            if (catSelect) {
                const cats = state.customerCategories || [];
                const availableCats = cats.filter(c => c.is_active == 1 || (cust && cust.category === c.code));
                if (availableCats.length > 0) {
                    catSelect.innerHTML = availableCats.map(c => `
                        <option value="${c.code}">${c.icon_emoji ? c.icon_emoji + ' ' : ''}${c.name} (${c.code})</option>
                    `).join('');
                } else {
                    catSelect.innerHTML = `
                        <option value="REGULER">👤 Pelanggan Reguler (REGULER)</option>
                        <option value="MEMBER">⭐ Member Loyalitas (MEMBER)</option>
                        <option value="RESELLER">🛍️ Reseller / Agen (RESELLER)</option>
                        <option value="MITRA">🏢 Mitra Bisnis B2B (MITRA)</option>
                    `;
                }
            }

            if (cust) {
                title.innerText = 'Edit Data Pelanggan / Mitra';
                const submitBtn = document.getElementById('cust-modal-submit-btn');
                if (submitBtn) submitBtn.innerHTML = '<i data-lucide="save" class="w-4 h-4"></i><span>Perbarui Data</span>';
                document.getElementById('cust-id').value = cust.id;
                document.getElementById('cust-category').value = cust.category || 'REGULER';
                document.getElementById('cust-code').value = cust.code;
                document.getElementById('cust-name').value = cust.name;
                document.getElementById('cust-phone').value = cust.phone || '';
                document.getElementById('cust-email').value = cust.email || '';
                document.getElementById('cust-discount').value = cust.discount_percent || 0;
                document.getElementById('cust-branch').value = cust.branch_id || '';
                document.getElementById('cust-address').value = cust.address || '';
                document.getElementById('cust-latitude').value = cust.latitude || '';
                document.getElementById('cust-longitude').value = cust.longitude || '';
                document.getElementById('cust-notes').value = cust.notes || '';
                
                const searchInput = document.getElementById('cust-modal-search-input');
                if (searchInput) searchInput.value = cust.address || cust.name || '';
                toggleCustSearchClearBtn();
                const statusEl = document.getElementById('cust-modal-search-status');
                if (statusEl) {
                    statusEl.innerHTML = '';
                    statusEl.classList.add('hidden');
                }

                updateCustPickerBadge(cust.latitude, cust.longitude);
            } else {
                title.innerText = 'Tambah Pelanggan / Mitra Baru';
                const submitBtn = document.getElementById('cust-modal-submit-btn');
                if (submitBtn) submitBtn.innerHTML = '<i data-lucide="check" class="w-4 h-4"></i><span>Simpan Data</span>';
                document.getElementById('cust-id').value = '';
                document.getElementById('cust-category').value = 'REGULER';
                document.getElementById('cust-code').value = '';
                document.getElementById('cust-name').value = '';
                document.getElementById('cust-phone').value = '';
                document.getElementById('cust-email').value = '';
                document.getElementById('cust-discount').value = '0';
                document.getElementById('cust-branch').value = state.currentBranch ? state.currentBranch.id : '';
                document.getElementById('cust-address').value = '';
                const defLat = state.currentBranch?.latitude || -6.195000;
                const defLon = state.currentBranch?.longitude || 106.823000;
                document.getElementById('cust-latitude').value = Number(defLat).toFixed(6);
                document.getElementById('cust-longitude').value = Number(defLon).toFixed(6);
                document.getElementById('cust-notes').value = '';
                clearCustAddressSearch();
                updateCustPickerBadge(defLat, defLon);
            }
            modal.classList.remove('hidden');
            setTimeout(() => {
                initCustomerPickerMap();
            }, 100);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 300);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 500);
            lucide.createIcons();
        }

        function closeCustomerModal() {
            document.getElementById('customer-modal').classList.add('hidden');
        }

        function autoDetectCustLocation() {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(
                    pos => {
                        const lat = pos.coords.latitude.toFixed(6);
                        const lon = pos.coords.longitude.toFixed(6);
                        document.getElementById('cust-latitude').value = lat;
                        document.getElementById('cust-longitude').value = lon;
                        updateCustPickerBadge(lat, lon);
                        updateCustPickerFromInputs();
                        alert(`Titik GPS berhasil dideteksi:\nLat: ${lat}, Lon: ${lon}`);
                    },
                    err => {
                        // Fallback koordinat sekitar Jakarta/Cabang
                        const defLat = state.currentBranch?.latitude || -6.195000;
                        const defLon = state.currentBranch?.longitude || 106.823000;
                        const sLat = (defLat + (Math.random() - 0.5) * 0.02).toFixed(6);
                        const sLon = (defLon + (Math.random() - 0.5) * 0.02).toFixed(6);
                        document.getElementById('cust-latitude').value = sLat;
                        document.getElementById('cust-longitude').value = sLon;
                        updateCustPickerBadge(sLat, sLon);
                        updateCustPickerFromInputs();
                        alert('Izin GPS tidak diberikan atau offline. Koordinat simulasi sekitar outlet telah diisi.');
                    }
                );
            } else {
                alert('Browser Anda tidak mendukung geolokasi GPS.');
            }
        }

        // --- CUSTOMER MINI-MAP PICKER ---
        function updateCustPickerFromInputs() {
            const lat = parseFloat(document.getElementById('cust-latitude')?.value);
            const lon = parseFloat(document.getElementById('cust-longitude')?.value);
            updateCustPickerBadge(lat, lon);
            if (!isNaN(lat) && !isNaN(lon) && state.customerPickerMap && state.customerPickerMarker) {
                state.customerPickerMarker.setLatLng([lat, lon]);
                state.customerPickerMap.setView([lat, lon], state.customerPickerMap.getZoom() || 14);
            }
        }

        function initCustomerPickerMap() {
            const container = document.getElementById('cust-modal-map-picker');
            if (!container) return;

            let lat = parseFloat(document.getElementById('cust-latitude')?.value);
            let lon = parseFloat(document.getElementById('cust-longitude')?.value);

            if (isNaN(lat) || isNaN(lon) || (lat === 0 && lon === 0)) {
                const bId = document.getElementById('cust-branch')?.value;
                const b = (state.branches || []).find(x => x.id == bId) || state.currentBranch;
                lat = parseFloat(b?.latitude) || -6.195000;
                lon = parseFloat(b?.longitude) || 106.823000;
                document.getElementById('cust-latitude').value = lat.toFixed(6);
                document.getElementById('cust-longitude').value = lon.toFixed(6);
            }

            updateCustPickerBadge(lat, lon);

            if (!state.customerPickerMap) {
                state.customerPickerMap = L.map('cust-modal-map-picker', {
                    zoomControl: true,
                    attributionControl: false
                }).setView([lat, lon], 14);

                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19
                }).addTo(state.customerPickerMap);

                state.customerPickerMarker = L.marker([lat, lon], { draggable: true }).addTo(state.customerPickerMap);

                state.customerPickerMarker.on('dragend', function(e) {
                    const pos = e.target.getLatLng();
                    document.getElementById('cust-latitude').value = pos.lat.toFixed(6);
                    document.getElementById('cust-longitude').value = pos.lng.toFixed(6);
                    updateCustPickerBadge(pos.lat, pos.lng);
                });

                state.customerPickerMap.on('click', function(e) {
                    state.customerPickerMarker.setLatLng(e.latlng);
                    document.getElementById('cust-latitude').value = e.latlng.lat.toFixed(6);
                    document.getElementById('cust-longitude').value = e.latlng.lng.toFixed(6);
                    updateCustPickerBadge(e.latlng.lat, e.latlng.lng);
                });
            } else {
                state.customerPickerMarker.setLatLng([lat, lon]);
                state.customerPickerMap.setView([lat, lon], 14);
            }

            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 50);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 250);
            setTimeout(() => {
                if (state.customerPickerMap) state.customerPickerMap.invalidateSize();
            }, 500);
        }

        // --- SUBTAB 5: PETA GEOSPASIAL PELANGGAN & MITRA ---
        function getHaversineDistanceKm(lat1, lon1, lat2, lon2) {
            if (!lat1 || !lon1 || !lat2 || !lon2) return 0;
            const R = 6371; // Earth's radius in km
            const dLat = (lat2 - lat1) * Math.PI / 180;
            const dLon = (lon2 - lon1) * Math.PI / 180;
            const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
                      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                      Math.sin(dLon/2) * Math.sin(dLon/2);
            const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
            return parseFloat((R * c).toFixed(2));
        }

        async function initCustomerMap() {
            const mapContainer = document.getElementById('customer-geospatial-map');
            if (!mapContainer) return;

            if (!state.branches || state.branches.length === 0) {
                await loadBranches();
            }
            if (!state.customers || state.customers.length === 0) {
                await loadCustomers();
            }

            const branchLat = parseFloat(state.currentBranch?.latitude) || -6.195000;
            const branchLon = parseFloat(state.currentBranch?.longitude) || 106.823000;

            if (!state.customerMap) {
                state.customerMap = L.map('customer-geospatial-map').setView([branchLat, branchLon], 12);
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19,
                    attribution: '&copy; OpenStreetMap contributors'
                }).addTo(state.customerMap);
            } else {
                state.customerMap.invalidateSize();
            }

            setTimeout(() => {
                if (state.customerMap) state.customerMap.invalidateSize();
            }, 50);
            setTimeout(() => {
                if (state.customerMap) state.customerMap.invalidateSize();
            }, 250);

            populateCustomerMapSelections();
            renderCustomerMapMarkers();
        }

        function populateCustomerMapSelections() {
            const bFilter = document.getElementById('cust-map-branch-filter');
            const cSelect = document.getElementById('cust-map-customer-select');
            if (!bFilter || !cSelect) return;

            const curBVal = bFilter.value || 'ALL';
            bFilter.innerHTML = '<option value="ALL">Semua Cabang Pendaftaran</option>' + 
                state.branches.map(b => `<option value="${b.id}" ${curBVal == b.id ? 'selected' : ''}>🏢 ${b.name}</option>`).join('');

            const bFilterVal = bFilter.value || 'ALL';
            const catFilterVal = document.getElementById('cust-map-category-filter')?.value || 'ALL';

            const filteredCusts = state.customers.filter(c => {
                const matchBranch = (bFilterVal === 'ALL' || c.branch_id == bFilterVal);
                const matchCat = (catFilterVal === 'ALL' || c.category === catFilterVal);
                return matchBranch && matchCat;
            });

            if (filteredCusts.length === 0) {
                cSelect.innerHTML = '<option value="">Tidak ada pelanggan ditemukan</option>';
            } else {
                cSelect.innerHTML = filteredCusts.map(c => `
                    <option value="${c.id}">📍 ${c.name} [${c.category || 'REGULER'}]</option>
                `).join('');
            }
        }

        function filterCustomerMapMarkers() {
            populateCustomerMapSelections();
            renderCustomerMapMarkers();
        }

        function renderCustomerMapMarkers() {
            if (!state.customerMap) return;

            // Clear old markers
            if (state.customerMapMarkers) {
                state.customerMapMarkers.forEach(m => state.customerMap.removeLayer(m));
            }
            state.customerMapMarkers = [];

            if (state.customerMapPolyline) {
                state.customerMap.removeLayer(state.customerMapPolyline);
                state.customerMapPolyline = null;
            }

            const bFilterVal = document.getElementById('cust-map-branch-filter')?.value || 'ALL';
            const catFilterVal = document.getElementById('cust-map-category-filter')?.value || 'ALL';

            // 1. Add branch markers (Outlet toko acuan)
            state.branches.forEach(b => {
                if (b.latitude && b.longitude && (bFilterVal === 'ALL' || b.id == bFilterVal)) {
                    const marker = L.marker([b.latitude, b.longitude]).addTo(state.customerMap);
                    marker.bindPopup(`
                        <div class="text-xs">
                            <strong class="text-indigo-900 block text-sm">🏢 ${b.name}</strong>
                            <p class="text-slate-600">${b.address}</p>
                            <span class="inline-block mt-1 px-2 py-0.5 bg-indigo-100 text-indigo-800 rounded font-bold text-[10px]">Outlet Cabang</span>
                        </div>
                    `);
                    state.customerMapMarkers.push(marker);
                }
            });

            // 2. Add customer markers
            const filteredCusts = state.customers.filter(c => {
                const matchBranch = (bFilterVal === 'ALL' || c.branch_id == bFilterVal);
                const matchCat = (catFilterVal === 'ALL' || c.category === catFilterVal);
                return matchBranch && matchCat;
            });

            const categoryColors = {
                'MITRA': '#059669',    // emerald
                'MEMBER': '#9333ea',   // purple
                'RESELLER': '#d97706', // amber
                'REGULER': '#4f46e5'   // indigo
            };

            filteredCusts.forEach(c => {
                if (c.latitude && c.longitude) {
                    const fillColor = categoryColors[c.category] || '#4f46e5';
                    const marker = L.circleMarker([c.latitude, c.longitude], {
                        radius: 8,
                        fillColor: fillColor,
                        color: '#ffffff',
                        weight: 2,
                        opacity: 1,
                        fillOpacity: 0.9
                    }).addTo(state.customerMap);

                    marker.bindPopup(`
                        <div class="text-xs">
                            <strong class="text-slate-900 block font-bold">${c.category === 'MITRA' ? '🤝 Mitra:' : (c.category === 'MEMBER' ? '⭐ Member:' : (c.category === 'RESELLER' ? '📦 Reseller:' : '👤 Pelanggan:'))} ${c.name}</strong>
                            <p class="text-slate-500">${c.address || '-'}</p>
                            <div class="mt-1 flex items-center space-x-1">
                                <span class="px-1.5 py-0.5 bg-slate-100 text-slate-700 rounded text-[10px] font-mono">
                                    ${Number(c.latitude).toFixed(4)}, ${Number(c.longitude).toFixed(4)}
                                </span>
                                <span class="px-1.5 py-0.5 rounded text-[10px] font-bold" style="background:${fillColor}20; color:${fillColor};">
                                    ${c.category || 'REGULER'}
                                </span>
                            </div>
                        </div>
                    `);

                    marker.on('click', () => {
                        selectCustomerOnMap(c);
                    });

                    state.customerMapMarkers.push(marker);
                }
            });

            // Default select
            const cSelect = document.getElementById('cust-map-customer-select');
            const selectedCustId = cSelect ? parseInt(cSelect.value) : null;
            const targetCust = filteredCusts.find(c => c.id === selectedCustId) || filteredCusts[0];
            if (targetCust) {
                selectCustomerOnMap(targetCust, false);
            }
        }

        function onCustomerMapSelectChange() {
            const cId = parseInt(document.getElementById('cust-map-customer-select')?.value || 0);
            const cust = state.customers.find(c => c.id === cId);
            if (cust) {
                selectCustomerOnMap(cust, true);
            }
        }

        function selectCustomerOnMap(cust, zoomTo = true) {
            if (!cust) return;
            state.customerSelectedOnMap = cust;

            const cSelect = document.getElementById('cust-map-customer-select');
            if (cSelect && cSelect.value != cust.id) {
                cSelect.value = cust.id;
            }

            const avatarEl = document.getElementById('cust-map-avatar');
            const nameEl = document.getElementById('cust-map-info-name');
            const catBadgeEl = document.getElementById('cust-map-info-cat-badge');
            const codeEl = document.getElementById('cust-map-info-code');
            const phoneEl = document.getElementById('cust-map-info-phone');
            const waBtn = document.getElementById('cust-map-wa-btn');
            const waContainer = document.getElementById('cust-map-wa-container');
            const addrEl = document.getElementById('cust-map-info-address');
            const branchEl = document.getElementById('cust-map-info-branch');
            const coordsEl = document.getElementById('cust-map-info-coords');
            const distEl = document.getElementById('cust-map-info-distance');
            const etaEl = document.getElementById('cust-map-info-eta');
            const notesBox = document.getElementById('cust-map-notes-box');
            const notesEl = document.getElementById('cust-map-info-notes');
            const gmapsLink = document.getElementById('cust-map-gmaps-link');

            const avatars = {
                'MITRA': '🤝',
                'MEMBER': '⭐',
                'RESELLER': '📦',
                'REGULER': '👤'
            };

            if (avatarEl) avatarEl.innerText = avatars[cust.category] || '👤';
            if (nameEl) nameEl.innerText = cust.name;
            if (codeEl) codeEl.innerText = `Kode: ${cust.code || '-'}`;
            if (catBadgeEl) {
                catBadgeEl.innerText = cust.category || 'REGULER';
                if (cust.category === 'MITRA') catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800';
                else if (cust.category === 'MEMBER') catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-purple-100 text-purple-800';
                else if (cust.category === 'RESELLER') catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800';
                else catBadgeEl.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-700';
            }

            if (phoneEl) phoneEl.innerText = cust.phone || '-';
            if (waBtn && waContainer) {
                if (cust.phone && cust.phone.length > 5) {
                    let cleanPhone = cust.phone.replace(/[^0-9]/g, '');
                    if (cleanPhone.startsWith('0')) cleanPhone = '62' + cleanPhone.substring(1);
                    waBtn.href = `https://wa.me/${cleanPhone}?text=Halo%20${encodeURIComponent(cust.name)},%20kami%20dari%20${encodeURIComponent(state.currentBranch?.name || 'Kasir')}.`;
                    waContainer.classList.remove('hidden');
                } else {
                    waContainer.classList.add('hidden');
                }
            }

            if (addrEl) addrEl.innerText = cust.address || 'Alamat fisik belum diisi';
            if (branchEl) branchEl.innerText = cust.branch_name || (state.currentBranch ? state.currentBranch.name : 'Semua Cabang');

            const cLat = parseFloat(cust.latitude);
            const cLon = parseFloat(cust.longitude);
            const hasCoords = !isNaN(cLat) && !isNaN(cLon) && (cLat !== 0 || cLon !== 0);

            if (coordsEl) {
                coordsEl.innerText = hasCoords ? `${cLat.toFixed(6)}, ${cLon.toFixed(6)}` : 'Koordinat belum diset';
            }

            const branch = state.branches.find(b => b.id == cust.branch_id) || state.currentBranch || state.branches[0];
            if (hasCoords && branch && branch.latitude && branch.longitude) {
                const bLat = parseFloat(branch.latitude);
                const bLon = parseFloat(branch.longitude);
                const distKm = getHaversineDistanceKm(bLat, bLon, cLat, cLon);
                if (distEl) distEl.innerText = `${distKm} km`;
                if (etaEl) {
                    const minTime = Math.max(5, Math.round(distKm * 3));
                    etaEl.innerText = `~${minTime} - ${minTime + 5} Menit (Motor)`;
                }

                if (state.customerMap) {
                    if (state.customerMapPolyline) {
                        state.customerMap.removeLayer(state.customerMapPolyline);
                    }
                    state.customerMapPolyline = L.polyline([[bLat, bLon], [cLat, cLon]], {
                        color: '#4f46e5',
                        weight: 3,
                        dashArray: '6, 6',
                        opacity: 0.8
                    }).addTo(state.customerMap);
                }
            } else {
                if (distEl) distEl.innerText = '- km';
                if (etaEl) etaEl.innerText = '-';
                if (state.customerMapPolyline && state.customerMap) {
                    state.customerMap.removeLayer(state.customerMapPolyline);
                    state.customerMapPolyline = null;
                }
            }

            if (notesBox && notesEl) {
                if (cust.notes && cust.notes.trim()) {
                    notesEl.innerText = cust.notes;
                    notesBox.classList.remove('hidden');
                } else {
                    notesBox.classList.add('hidden');
                }
            }

            if (gmapsLink) {
                if (hasCoords) {
                    gmapsLink.href = `https://www.google.com/maps?q=${cLat},${cLon}`;
                    gmapsLink.classList.remove('opacity-50', 'pointer-events-none');
                } else {
                    gmapsLink.href = '#';
                    gmapsLink.classList.add('opacity-50', 'pointer-events-none');
                }
            }

            if (zoomTo && hasCoords && state.customerMap) {
                state.customerMap.setView([cLat, cLon], 15, { animate: true });
            }
        }

        function fitCustomerMapBounds() {
            if (!state.customerMap) return;
            const group = L.featureGroup(state.customerMapMarkers || []);
            if (group.getLayers().length > 0) {
                state.customerMap.fitBounds(group.getBounds(), { padding: [50, 50] });
            }
        }

        function focusCustomerOnMap(custId) {
            setCustomerSubtab('maps');
            setTimeout(() => {
                const cSelect = document.getElementById('cust-map-customer-select');
                if (cSelect) {
                    cSelect.value = custId;
                    onCustomerMapSelectChange();
                }
            }, 200);
        }

        function openCustomerModalFromMap() {
            if (state.customerSelectedOnMap) {
                openCustomerModal(state.customerSelectedOnMap);
            } else {
                openCustomerModal();
            }
        }

        function onModalCustCategoryChange() {
            const cat = document.getElementById('cust-category').value;
            const codeInput = document.getElementById('cust-code');
            if (!codeInput.value || codeInput.value.startsWith('CUST-') || codeInput.value.startsWith('MBR-') || codeInput.value.startsWith('MTR-')) {
                const prefix = (cat === 'MITRA') ? 'MTR-' : ((cat === 'MEMBER') ? 'MBR-' : ((cat === 'RESELLER') ? 'RSL-' : 'CUST-'));
                const rand = Math.floor(100 + Math.random() * 900);
                codeInput.value = prefix + String(Date.now()).slice(-4) + rand;
            }
        }

        function editCustomer(id) {
            const cust = state.customers.find(c => c.id === id);
            if (cust) openCustomerModal(cust);
        }

        async function saveCustomerForm(e) {
            e.preventDefault();
            const id = document.getElementById('cust-id').value;
            const latVal = document.getElementById('cust-latitude').value;
            const lonVal = document.getElementById('cust-longitude').value;
            const payload = {
                id: id ? parseInt(id) : null,
                category: document.getElementById('cust-category').value,
                code: document.getElementById('cust-code').value,
                name: document.getElementById('cust-name').value,
                phone: document.getElementById('cust-phone').value,
                email: document.getElementById('cust-email').value,
                discount_percent: parseFloat(document.getElementById('cust-discount').value) || 0,
                branch_id: document.getElementById('cust-branch').value ? parseInt(document.getElementById('cust-branch').value) : null,
                address: document.getElementById('cust-address').value,
                latitude: latVal ? parseFloat(latVal) : null,
                longitude: lonVal ? parseFloat(lonVal) : null,
                notes: document.getElementById('cust-notes').value
            };

            const res = await fetch('api.php?action=save_customer', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeCustomerModal();
                loadCustomers();
                initApp();
            }
        }

        async function deleteCustomer(id) {
            if (!confirm('Apakah Anda yakin ingin menonaktifkan pelanggan ini?')) return;
            const res = await fetch('api.php?action=delete_customer', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadCustomers();
                initApp();
            }
        }

        // SUBTAB 2: HARGA KONTRAK MITRA (Setiap mitra harga berbeda)
        async function switchDirectToMitraContract(partnerId) {
            setCustomerSubtab('mitra-pricing');
            const select = document.getElementById('mitra-pricing-partner-select');
            if (select) {
                select.value = partnerId;
            }
            await loadMitraPricing(partnerId);
        }

        async function loadMitraPricing(targetPartnerId = null) {
            try {
                if (!state.customers || state.customers.length === 0) {
                    const cres = await fetch('api.php?action=get_customers&category=ALL');
                    const cdata = await cres.json();
                    if (cdata.success) state.customers = cdata.customers || [];
                }

                if (!state.products || state.products.length === 0) {
                    const pres = await fetch('api.php?action=bootstrap');
                    const pdata = await pres.json();
                    if (pdata.success) state.products = pdata.products || [];
                }

                // Populate Mitra Partner Dropdown
                const partnerSelect = document.getElementById('mitra-pricing-partner-select');
                const mitraPartners = (state.customers || []).filter(c => c.category === 'MITRA');

                if (mitraPartners.length === 0) {
                    partnerSelect.innerHTML = '<option value="">Tidak ada Mitra B2B terdaftar</option>';
                    document.getElementById('mitra-pricing-table-body').innerHTML = `
                        <tr><td colspan="7" class="text-center py-8 text-slate-400">Belum ada mitra rekanan B2B. Daftarkan mitra baru di tab Data Pelanggan.</td></tr>
                    `;
                    return;
                }

                const currentPartnerId = targetPartnerId ? parseInt(targetPartnerId) : (partnerSelect.value ? parseInt(partnerSelect.value) : mitraPartners[0].id);
                partnerSelect.innerHTML = mitraPartners.map(m => `
                    <option value="${m.id}" ${m.id === currentPartnerId ? 'selected' : ''}>${m.name} (${m.code})</option>
                `).join('');
                partnerSelect.value = currentPartnerId;

                const selectedPartner = mitraPartners.find(m => m.id === currentPartnerId) || mitraPartners[0];

                // Fetch custom contract prices for this mitra
                const res = await fetch(`api.php?action=get_mitra_prices&customer_id=${selectedPartner.id}`);
                const data = await res.json();
                const contractPrices = (data.success && data.prices) ? data.prices : [];

                // Render table: all finished goods products
                const tbody = document.getElementById('mitra-pricing-table-body');
                const products = state.products || [];

                tbody.innerHTML = products.map(p => {
                    const custom = contractPrices.find(cp => cp.product_id === p.id);
                    const defaultRetail = Number(p.selling_price);
                    const defaultMitra = Number(p.mitra_price > 0 ? p.mitra_price : Math.round(defaultRetail * 0.72));
                    const isContractSet = custom && Number(custom.custom_price) > 0;
                    const contractPrice = isContractSet ? Number(custom.custom_price) : defaultMitra;

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-4 font-bold text-slate-900">${p.image_emoji || '📦'} ${p.name}</td>
                            <td class="py-3 px-4 font-mono text-slate-500">${p.sku}</td>
                            <td class="py-3 px-4 text-right text-slate-600 font-semibold">${formatRupiah(defaultRetail)}</td>
                            <td class="py-3 px-4 text-right text-indigo-700 font-semibold">${formatRupiah(defaultMitra)}</td>
                            <td class="py-3 px-4 text-right font-black ${isContractSet ? 'text-emerald-700 text-sm' : 'text-slate-400'}">
                                ${formatRupiah(contractPrice)}
                            </td>
                            <td class="py-3 px-4 text-center">
                                ${isContractSet ? 
                                    '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800 border border-emerald-300">✅ Kontrak Aktif</span>' :
                                    '<span class="px-2 py-0.5 rounded-full text-[10px] font-medium bg-slate-100 text-slate-500">Tier Default</span>'
                                }
                            </td>
                            <td class="py-3 px-4 text-center">
                                <div class="flex items-center justify-center space-x-1">
                                    <button onclick="openMitraPriceModal(${p.id}, ${contractPrice})" class="px-2.5 py-1 bg-indigo-50 hover:bg-indigo-600 hover:text-white text-indigo-700 font-bold text-[11px] rounded-lg border border-indigo-200 transition-colors">
                                        ${isContractSet ? 'Edit Kontrak' : '+ Set Kontrak'}
                                    </button>
                                    ${isContractSet ? `
                                        <button onclick="deleteMitraPrice(${custom.id})" title="Hapus Kontrak Khusus" class="p-1 text-slate-400 hover:text-rose-600 rounded-lg">
                                            <i data-lucide="rotate-ccw" class="w-3.5 h-3.5"></i>
                                        </button>
                                    ` : ''}
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function onMitraPartnerSelectChange() {
            loadMitraPricing();
        }

        function openMitraPriceModal(productId = null, currentPrice = null) {
            const partnerSelect = document.getElementById('mitra-pricing-partner-select');
            const mitraPartners = (state.customers || []).filter(c => c.category === 'MITRA');
            
            if (mitraPartners.length === 0) {
                alert('Belum ada mitra rekanan B2B yang terdaftar. Silakan tambahkan pelanggan dengan kategori MITRA terlebih dahulu.');
                return;
            }

            const activePartnerId = partnerSelect && partnerSelect.value ? parseInt(partnerSelect.value) : mitraPartners[0].id;

            // Populate Mitra Partner select in modal
            const modalPartnerSelect = document.getElementById('mp-customer-id-select');
            if (modalPartnerSelect) {
                modalPartnerSelect.innerHTML = mitraPartners.map(m => `
                    <option value="${m.id}" ${m.id === activePartnerId ? 'selected' : ''}>${m.name} (${m.code})</option>
                `).join('');
                modalPartnerSelect.value = activePartnerId;
            }

            document.getElementById('mp-customer-id').value = activePartnerId;
            const selectedPartner = mitraPartners.find(m => m.id === activePartnerId) || mitraPartners[0];
            document.getElementById('mp-modal-partner-desc').innerText = `Mitra: ${selectedPartner.name} (${selectedPartner.code})`;

            const prodSelect = document.getElementById('mp-product-select');
            prodSelect.innerHTML = state.products.map(p => `
                <option value="${p.id}" ${productId && p.id === productId ? 'selected' : ''}>${p.image_emoji || '📦'} ${p.name} (${p.sku})</option>
            `).join('');

            if (productId) {
                prodSelect.value = productId;
            }

            onMpProductSelectChange();
            if (currentPrice) {
                document.getElementById('mp-custom-price').value = currentPrice;
            }

            document.getElementById('mitra-price-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function onMpPartnerSelectChange() {
            const modalPartnerSelect = document.getElementById('mp-customer-id-select');
            const pId = parseInt(modalPartnerSelect.value);
            document.getElementById('mp-customer-id').value = pId;
            const mitraPartners = (state.customers || []).filter(c => c.category === 'MITRA');
            const partner = mitraPartners.find(m => m.id === pId);
            if (partner) {
                document.getElementById('mp-modal-partner-desc').innerText = `Mitra: ${partner.name} (${partner.code})`;
            }
        }

        function closeMitraPriceModal() {
            document.getElementById('mitra-price-modal').classList.add('hidden');
        }

        function onMpProductSelectChange() {
            const pId = parseInt(document.getElementById('mp-product-select').value);
            const p = state.products.find(pr => pr.id === pId);
            if (!p) return;

            const defaultRetail = Number(p.selling_price);
            const defaultMitra = Number(p.mitra_price > 0 ? p.mitra_price : Math.round(defaultRetail * 0.72));

            document.getElementById('mp-info-retail').innerText = formatRupiah(defaultRetail);
            document.getElementById('mp-info-mitra-default').innerText = formatRupiah(defaultMitra);
            if (!document.getElementById('mp-custom-price').value || document.getElementById('mp-custom-price').value == 0) {
                document.getElementById('mp-custom-price').value = defaultMitra;
            }
        }

        async function saveMitraPriceForm(e) {
            e.preventDefault();
            const customerId = parseInt(document.getElementById('mp-customer-id').value) || parseInt(document.getElementById('mp-customer-id-select').value);
            const productId = parseInt(document.getElementById('mp-product-select').value);
            const customPrice = parseFloat(document.getElementById('mp-custom-price').value);

            if (!customerId || !productId || customPrice <= 0) {
                alert('Pilih mitra, produk, dan isi harga kontrak khusus yang valid!');
                return;
            }

            const payload = {
                customer_id: customerId,
                product_id: productId,
                custom_price: customPrice,
                notes: document.getElementById('mp-notes').value
            };

            const res = await fetch('api.php?action=save_mitra_price', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeMitraPriceModal();
                // Ensure page partner select matches
                const partnerSelect = document.getElementById('mitra-pricing-partner-select');
                if (partnerSelect) partnerSelect.value = customerId;
                loadMitraPricing();
                initApp();
            }
        }

        async function deleteMitraPrice(id) {
            if (!confirm('Kembalikan harga jual produk ini ke harga tier mitra default?')) return;
            const res = await fetch('api.php?action=delete_mitra_price', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadMitraPricing();
                initApp();
            }
        }

        // SUBTAB 3: HARGA JUAL ANTAR CABANG (Setiap branch harga berbeda)
        async function loadBranchPricing() {
            try {
                if (!state.branches || state.branches.length === 0) {
                    const bres = await fetch('api.php?action=bootstrap');
                    const bdata = await bres.json();
                    if (bdata.success) {
                        state.branches = bdata.branches || [];
                        state.products = bdata.products || [];
                    }
                }

                const branchSelect = document.getElementById('branch-pricing-branch-select');
                const currentBranchId = branchSelect.value ? parseInt(branchSelect.value) : (state.currentBranch ? state.currentBranch.id : 1);

                branchSelect.innerHTML = (state.branches || []).map(b => `
                    <option value="${b.id}" ${b.id === currentBranchId ? 'selected' : ''}>${b.name}</option>
                `).join('');

                const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${currentBranchId}&product_type=FINISHED_GOODS`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const stocks = data.stocks || [];
                const tbody = document.getElementById('branch-pricing-table-body');

                if (stocks.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="9" class="text-center py-8 text-slate-400">Tidak ada produk ditemukan</td></tr>`;
                    return;
                }

                tbody.innerHTML = stocks.map(st => {
                    const cogs = Number(st.local_cogs);
                    const price = Number(st.local_price);
                    const margin = price > 0 ? Math.round(((price - cogs) / price) * 100) : 0;
                    const isActive = Number(st.is_active ?? 1) === 1;

                    // Hitung status pengiriman cabang (0 = Standar, 1 = Wajib Ongkir, 2 = Termasuk Biaya Kirim)
                    let currentDelivMode = 0;
                    if (Number(st.is_delivery_included) === 1 || Number(st.is_delivery_required) === 2) {
                        currentDelivMode = 2;
                    } else if (Number(st.is_delivery_required) === 1) {
                        currentDelivMode = 1;
                    }
                    const nextDelivMode = (currentDelivMode === 0) ? 1 : ((currentDelivMode === 1) ? 2 : 0);

                    let delivBadgeClass = 'bg-slate-100 text-slate-500 border-slate-300 hover:bg-slate-200';
                    let delivBadgeText = '⚪ Standar Toko';
                    if (currentDelivMode === 2) {
                        delivBadgeClass = 'bg-emerald-100 text-emerald-900 border-emerald-300 hover:bg-emerald-200';
                        delivBadgeText = '🎁 Termasuk Kirim';
                    } else if (currentDelivMode === 1) {
                        delivBadgeClass = 'bg-amber-100 text-amber-900 border-amber-300 hover:bg-amber-200';
                        delivBadgeText = '🚚 Wajib Ongkir';
                    }

                    return `
                        <tr class="hover:bg-slate-50 transition-colors ${!isActive ? 'bg-slate-50/70 opacity-75' : ''}">
                            <td class="py-3 px-4 font-bold text-slate-900">
                                <div class="flex items-center space-x-2">
                                    <span class="text-base">${st.image_emoji || '📦'}</span>
                                    <div>
                                        <div class="${!isActive ? 'line-through text-slate-500' : ''}">${st.name}</div>
                                        ${!isActive ? '<span class="text-[10px] font-bold text-rose-600 bg-rose-50 px-1.5 py-0.5 rounded border border-rose-200">Nonaktif di Cabang</span>' : ''}
                                    </div>
                                </div>
                            </td>
                            <td class="py-3 px-4 font-mono text-slate-500">${st.sku}</td>
                            <td class="py-3 px-4 text-slate-600">${st.category}</td>
                            <td class="py-3 px-4 text-center">
                                <div class="inline-flex items-center space-x-2">
                                    <button onclick="toggleBranchProductStatus(${currentBranchId}, ${st.product_id}, ${isActive ? 0 : 1})" 
                                            title="${isActive ? 'Klik untuk nonaktifkan menu di cabang ini' : 'Klik untuk aktifkan menu di cabang ini'}"
                                            class="inline-flex items-center space-x-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold border transition-colors cursor-pointer ${isActive ? 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100' : 'bg-slate-100 text-slate-500 border-slate-300 hover:bg-slate-200'}">
                                        <span class="w-2 h-2 rounded-full ${isActive ? 'bg-emerald-500' : 'bg-slate-400'}"></span>
                                        <span>${isActive ? 'Dijual (Aktif)' : 'Nonaktif'}</span>
                                    </button>
                                </div>
                            </td>
                            <td class="py-3 px-4 text-center">
                                <div class="inline-flex items-center space-x-2">
                                    <button onclick="toggleBranchProductDelivery(${currentBranchId}, ${st.product_id}, ${nextDelivMode})" 
                                            title="Mode Pengiriman Cabang: ${delivBadgeText}. Klik untuk ganti rotasi (Standar -> Wajib Ongkir -> Termasuk Kirim)."
                                            class="inline-flex items-center space-x-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold border transition-colors cursor-pointer ${delivBadgeClass}">
                                        <span>${delivBadgeText}</span>
                                    </button>
                                </div>
                            </td>
                            <td class="py-3 px-4 text-right text-rose-700 font-semibold">${formatRupiah(cogs)}</td>
                            <td class="py-3 px-4 text-right font-black text-indigo-950 text-sm">${formatRupiah(price)}</td>
                            <td class="py-3 px-4 text-right font-bold ${margin >= 40 ? 'text-emerald-700' : 'text-amber-700'}">${margin}%</td>
                            <td class="py-3 px-4 text-center">
                                <button onclick="openBranchPriceModal(${st.product_id}, '${st.name.replace(/'/g, "\\'")}', ${cogs}, ${price}, ${isActive ? 1 : 0}, ${currentDelivMode})" class="px-2.5 py-1 bg-indigo-50 hover:bg-indigo-600 hover:text-white text-indigo-700 font-bold text-[11px] rounded-lg border border-indigo-200 transition-colors">
                                    Edit Menu & Harga
                                </button>
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function onBranchPricingSelectChange() {
            loadBranchPricing();
        }

        async function toggleBranchProductStatus(branchId, productId, newStatus) {
            try {
                const res = await fetch('api.php?action=toggle_branch_product_status', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: branchId, product_id: productId, is_active: newStatus })
                });
                const data = await res.json();
                if (data.success) {
                    loadBranchPricing();
                    // Jika cabang yang diubah adalah cabang aktif saat ini di POS kasir, muat ulang produk POS
                    if (state.currentBranch && state.currentBranch.id === branchId) {
                        initApp();
                    }
                } else {
                    alert(data.message || 'Gagal mengubah status menu cabang.');
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        async function toggleBranchProductDelivery(branchId, productId, newStatus) {
            try {
                const res = await fetch('api.php?action=toggle_branch_product_delivery', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: branchId, product_id: productId, is_delivery_required: newStatus })
                });
                const data = await res.json();
                if (data.success) {
                    loadBranchPricing();
                    // Jika cabang yang diubah adalah cabang aktif saat ini di POS kasir, muat ulang produk POS
                    if (state.currentBranch && state.currentBranch.id === branchId) {
                        initApp();
                    }
                } else {
                    alert(data.message || 'Gagal mengubah pengaturan ongkir cabang.');
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan jaringan.');
            }
        }

        function onBpDeliveryModeChange() {
            const selectEl = document.getElementById('bp-delivery-mode');
            const badge = document.getElementById('bp-delivery-badge');
            if (!badge || !selectEl) return;
            const mode = selectEl.value;
            if (mode === '2') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800';
                badge.innerText = '🎁 Free Ongkir';
            } else if (mode === '1') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-amber-100 text-amber-800';
                badge.innerText = '🚚 Wajib Ongkir';
            } else if (mode === '0') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-100 text-slate-700';
                badge.innerText = '⚪ Standar';
            } else {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-black bg-slate-100 text-slate-500';
                badge.innerText = 'Default Master';
            }
        }

        async function openBranchPriceModal(productId = null, productName = null, cogs = null, currentPrice = null, isActive = 1, isDeliveryMode = null) {
            const branchSelect = document.getElementById('branch-pricing-branch-select');
            const branchId = branchSelect && branchSelect.value ? parseInt(branchSelect.value) : (state.currentBranch ? state.currentBranch.id : 1);

            // Populate branch dropdown in modal
            const modalBranchSelect = document.getElementById('bp-branch-id-select');
            if (modalBranchSelect) {
                modalBranchSelect.innerHTML = (state.branches || []).map(b => `
                    <option value="${b.id}" ${b.id === branchId ? 'selected' : ''}>${b.name}</option>
                `).join('');
                modalBranchSelect.value = branchId;
            }

            document.getElementById('bp-branch-id').value = branchId;
            const branchObj = (state.branches || []).find(b => b.id === branchId);
            const branchName = branchObj ? branchObj.name : 'Cabang';
            document.getElementById('bp-modal-branch-desc').innerText = `Cabang: ${branchName}`;

            // Checkbox status menu
            const activeCheckbox = document.getElementById('bp-is-active');
            if (activeCheckbox) activeCheckbox.checked = (isActive === 1);

            // Select delivery mode
            const delivSelect = document.getElementById('bp-delivery-mode');

            // Populate products dropdown in modal
            const prodSelect = document.getElementById('bp-product-select');
            const finishedGoods = (state.products || []).filter(p => p.product_type === 'FINISHED_GOODS' || !p.product_type);
            prodSelect.innerHTML = finishedGoods.map(p => `
                <option value="${p.id}" ${productId && p.id === productId ? 'selected' : ''}>${p.image_emoji || '📦'} ${p.name} (${p.sku})</option>
            `).join('');

            if (productId) {
                prodSelect.value = productId;
                document.getElementById('bp-product-id').value = productId;
                document.getElementById('bp-cogs').value = cogs || 0;
                document.getElementById('bp-local-price').value = currentPrice || 0;
                document.getElementById('bp-info-cogs-display').innerText = formatRupiah(cogs || 0);

                const pObj = finishedGoods.find(p => p.id === productId);
                document.getElementById('bp-info-central-retail').innerText = formatRupiah(pObj ? pObj.selling_price : currentPrice || 0);
                if (delivSelect) {
                    delivSelect.value = (isDeliveryMode !== null) ? isDeliveryMode.toString() : '';
                    onBpDeliveryModeChange();
                }
            } else {
                onBpProductSelectChange();
            }

            document.getElementById('branch-price-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function onBpBranchSelectChange() {
            const modalBranchSelect = document.getElementById('bp-branch-id-select');
            const branchId = parseInt(modalBranchSelect.value);
            document.getElementById('bp-branch-id').value = branchId;
            const branchObj = (state.branches || []).find(b => b.id === branchId);
            if (branchObj) {
                document.getElementById('bp-modal-branch-desc').innerText = `Cabang: ${branchObj.name}`;
            }
            onBpProductSelectChange();
        }

        async function onBpProductSelectChange() {
            const prodSelect = document.getElementById('bp-product-select');
            const productId = parseInt(prodSelect.value);
            const branchId = parseInt(document.getElementById('bp-branch-id').value) || 1;

            document.getElementById('bp-product-id').value = productId;

            const pObj = (state.products || []).find(p => p.id === productId);
            const defaultSelling = pObj ? Number(pObj.selling_price) : 0;
            const defaultCogs = pObj ? Number(pObj.cogs) : 0;

            document.getElementById('bp-info-central-retail').innerText = formatRupiah(defaultSelling);
            document.getElementById('bp-cogs').value = defaultCogs;
            document.getElementById('bp-info-cogs-display').innerText = formatRupiah(defaultCogs);

            const activeCheckbox = document.getElementById('bp-is-active');
            const delivSelect = document.getElementById('bp-delivery-mode');

            // Fetch current branch price if already exists
            try {
                const res = await fetch(`api.php?action=get_inventory_stocks&branch_id=${branchId}&product_type=FINISHED_GOODS`);
                const data = await res.json();
                if (data.success && data.stocks) {
                    const st = data.stocks.find(s => s.product_id === productId);
                    if (st) {
                        document.getElementById('bp-cogs').value = Number(st.local_cogs);
                        document.getElementById('bp-info-cogs-display').innerText = formatRupiah(Number(st.local_cogs));
                        document.getElementById('bp-local-price').value = Number(st.local_price);
                        if (activeCheckbox) activeCheckbox.checked = Number(st.is_active ?? 1) === 1;
                        if (delivSelect) {
                            if (Number(st.is_delivery_included) === 1 || Number(st.is_delivery_required) === 2) {
                                delivSelect.value = '2';
                            } else if (Number(st.is_delivery_required) === 1) {
                                delivSelect.value = '1';
                            } else if (st.is_delivery_required !== null && st.is_delivery_required !== undefined) {
                                delivSelect.value = '0';
                            } else {
                                delivSelect.value = '';
                            }
                            onBpDeliveryModeChange();
                        }
                        return;
                    }
                }
            } catch (err) {
                console.error(err);
            }

            document.getElementById('bp-local-price').value = defaultSelling;
            if (activeCheckbox) activeCheckbox.checked = true;
            if (delivSelect) {
                delivSelect.value = '';
                onBpDeliveryModeChange();
            }
        }

        function closeBranchPriceModal() {
            document.getElementById('branch-price-modal').classList.add('hidden');
        }

        async function saveBranchPriceForm(e) {
            e.preventDefault();
            const branchId = parseInt(document.getElementById('bp-branch-id').value) || parseInt(document.getElementById('bp-branch-id-select').value);
            const productId = parseInt(document.getElementById('bp-product-id').value) || parseInt(document.getElementById('bp-product-select').value);
            const localPrice = parseFloat(document.getElementById('bp-local-price').value);
            const activeCheckbox = document.getElementById('bp-is-active');
            const isActive = activeCheckbox && activeCheckbox.checked ? 1 : 0;
            const delivSelect = document.getElementById('bp-delivery-mode');
            const delivVal = delivSelect ? delivSelect.value : '';

            let isDeliveryRequired = (delivVal === '') ? null : parseInt(delivVal);
            let isDeliveryIncluded = (delivVal === '2') ? 1 : (delivVal === '' ? null : 0);

            if (!branchId || !productId || localPrice <= 0) {
                alert('Pilih cabang, produk, dan isi harga jual cabang yang valid!');
                return;
            }

            const payload = {
                branch_id: branchId,
                product_id: productId,
                local_price: localPrice,
                is_active: isActive,
                is_delivery_required: isDeliveryRequired,
                is_delivery_included: isDeliveryIncluded
            };

            const res = await fetch('api.php?action=update_branch_product_price', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                closeBranchPriceModal();
                const branchSelect = document.getElementById('branch-pricing-branch-select');
                if (branchSelect) branchSelect.value = branchId;
                loadBranchPricing();
                initApp();
            }
        }

        // ========================================================
        // SUBTAB 4: MASTER KATEGORI PELANGGAN & STATUS AKTIF/NONAKTIF
        // ========================================================
        state.custCatStatusFilter = 'ALL';

        async function loadCustomerCategories() {
            try {
                const res = await fetch('api.php?action=get_customer_categories');
                const data = await res.json();
                if (data.success) {
                    state.customerCategories = data.customer_categories || [];
                    renderCustomerCategoriesTable();
                }
            } catch (err) {
                console.error('Gagal memuat kategori pelanggan:', err);
            }
        }

        function setCustCatStatusFilter(status) {
            state.custCatStatusFilter = status;
            document.querySelectorAll('.cust-cat-status-filter').forEach(btn => {
                btn.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-100 text-slate-700 hover:bg-slate-200';
            });
            if (status === 'ALL') {
                const el = document.getElementById('filter-cust-cat-all');
                if (el) el.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
            } else if (status === 'ACTIVE') {
                const el = document.getElementById('filter-cust-cat-active');
                if (el) el.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
            } else if (status === 'INACTIVE') {
                const el = document.getElementById('filter-cust-cat-inactive');
                if (el) el.className = 'cust-cat-status-filter px-3 py-1.5 rounded-xl text-xs font-bold bg-indigo-600 text-white';
            }
            renderCustomerCategoriesTable();
        }

        function renderCustomerCategoriesTable() {
            const tbody = document.getElementById('customer-categories-table-body');
            if (!tbody) return;

            let cats = state.customerCategories || [];
            const kw = (document.getElementById('cust-cat-search-keyword')?.value || '').toLowerCase().trim();

            if (state.custCatStatusFilter === 'ACTIVE') {
                cats = cats.filter(c => c.is_active == 1);
            } else if (state.custCatStatusFilter === 'INACTIVE') {
                cats = cats.filter(c => c.is_active == 0);
            }

            if (kw) {
                cats = cats.filter(c => 
                    (c.name && c.name.toLowerCase().includes(kw)) ||
                    (c.code && c.code.toLowerCase().includes(kw)) ||
                    (c.default_tier && c.default_tier.toLowerCase().includes(kw)) ||
                    (c.description && c.description.toLowerCase().includes(kw))
                );
            }

            if (cats.length === 0) {
                tbody.innerHTML = `<tr><td colspan="7" class="text-center py-8 text-slate-400">Tidak ada kategori pelanggan yang cocok</td></tr>`;
                return;
            }

            tbody.innerHTML = cats.map(cat => {
                const isActive = (cat.is_active == 1);
                
                // Tier badge styling
                let tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-slate-100 text-slate-700">👤 Ritel Reguler</span>';
                if (cat.default_tier === 'MEMBER') {
                    tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-purple-100 text-purple-800">⭐ Member VIP</span>';
                } else if (cat.default_tier === 'RESELLER') {
                    tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-amber-100 text-amber-800">🛍️ Reseller / Grosir</span>';
                } else if (cat.default_tier === 'MITRA') {
                    tierBadge = '<span class="px-2.5 py-1 rounded-xl text-[11px] font-bold bg-emerald-100 text-emerald-800">🏢 Kontrak Mitra B2B</span>';
                }

                // Active toggle switch
                const toggleSwitch = `
                    <div class="flex items-center justify-center space-x-2">
                        <span class="text-[10px] font-bold ${isActive ? 'text-emerald-700' : 'text-slate-400'}">${isActive ? 'Aktif' : 'Nonaktif'}</span>
                        <label class="relative inline-flex items-center cursor-pointer">
                            <input type="checkbox" ${isActive ? 'checked' : ''} onchange="toggleCustomerCategoryStatus(${cat.id}, this.checked ? 1 : 0)" class="sr-only peer">
                            <div class="w-9 h-5 bg-slate-300 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-emerald-600"></div>
                        </label>
                    </div>
                `;

                const activeCustCount = cat.active_customer_count !== undefined ? Number(cat.active_customer_count) : 0;
                const totalCustCount = cat.total_customer_count !== undefined ? Number(cat.total_customer_count) : activeCustCount;

                // Escaped JSON for edit button
                const catJson = JSON.stringify(cat).replace(/"/g, '&quot;');

                return `
                    <tr class="hover:bg-slate-50 transition-colors ${!isActive ? 'opacity-60 bg-slate-50/50' : ''}">
                        <td class="py-3.5 px-4 font-bold text-slate-900">
                            <div class="flex items-center space-x-2.5">
                                <span class="p-2 bg-slate-100 rounded-xl text-base">${cat.icon_emoji || '👥'}</span>
                                <div>
                                    <p class="font-bold text-slate-900 text-xs">${cat.name}</p>
                                    <p class="text-[10px] text-slate-400 font-normal">ID: #${cat.id}</p>
                                </div>
                            </div>
                        </td>
                        <td class="py-3.5 px-4">
                            <span class="px-2.5 py-1 bg-slate-100 font-mono font-bold text-slate-800 rounded-lg text-xs border border-slate-200">${cat.code}</span>
                        </td>
                        <td class="py-3.5 px-4">${tierBadge}</td>
                        <td class="py-3.5 px-4 text-slate-600 max-w-xs truncate" title="${cat.description || '-'}">${cat.description || '-'}</td>
                        <td class="py-3.5 px-4 text-center">
                            <span class="px-2.5 py-1 bg-indigo-50 text-indigo-700 font-bold rounded-full text-xs">
                                ${activeCustCount} org
                            </span>
                        </td>
                        <td class="py-3.5 px-4 text-center">${toggleSwitch}</td>
                        <td class="py-3.5 px-4 text-center">
                            <div class="flex items-center justify-center space-x-1.5">
                                <button onclick="openCustomerCategoryModal(${catJson})" class="p-1.5 bg-slate-100 hover:bg-indigo-50 hover:text-indigo-600 text-slate-600 rounded-lg transition-colors" title="Edit Kategori">
                                    <i data-lucide="edit-3" class="w-4 h-4"></i>
                                </button>
                                <button onclick="deleteCustomerCategory(${cat.id}, '${cat.name.replace(/'/g, "\\'")}', ${activeCustCount})" class="p-1.5 bg-slate-100 hover:bg-rose-50 hover:text-rose-600 text-slate-600 rounded-lg transition-colors" title="Hapus Kategori">
                                    <i data-lucide="trash-2" class="w-4 h-4"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function openCustomerCategoryModal(cat = null) {
            const modal = document.getElementById('customer-category-modal');
            const title = document.getElementById('cust-cat-modal-title');
            const badge = document.getElementById('cust-cat-modal-badge');
            const isEdit = !!cat;

            if (isEdit) {
                title.innerText = 'Edit Kategori Pelanggan';
                badge.innerText = cat.icon_emoji || '👥';
                document.getElementById('cust-cat-id').value = cat.id;
                document.getElementById('cust-cat-emoji').value = cat.icon_emoji || '👥';
                document.getElementById('cust-cat-code').value = cat.code;
                document.getElementById('cust-cat-name').value = cat.name;
                document.getElementById('cust-cat-tier').value = cat.default_tier || 'REGULER';
                document.getElementById('cust-cat-desc').value = cat.description || '';
                document.getElementById('cust-cat-is-active').checked = (cat.is_active == 1);
            } else {
                title.innerText = 'Tambah Kategori Pelanggan Baru';
                badge.innerText = '👥';
                document.getElementById('cust-cat-id').value = '';
                document.getElementById('cust-cat-emoji').value = '👥';
                document.getElementById('cust-cat-code').value = '';
                document.getElementById('cust-cat-name').value = '';
                document.getElementById('cust-cat-tier').value = 'REGULER';
                document.getElementById('cust-cat-desc').value = '';
                document.getElementById('cust-cat-is-active').checked = true;
            }

            onCustomerCatStatusToggleChange();
            modal.classList.remove('hidden');
        }

        function closeCustomerCategoryModal() {
            document.getElementById('customer-category-modal').classList.add('hidden');
        }

        function onCustomerCatStatusToggleChange() {
            const chk = document.getElementById('cust-cat-is-active');
            const lbl = document.getElementById('cust-cat-status-label');
            if (chk.checked) {
                lbl.innerText = 'Aktif (Dapat digunakan transaksi & pendaftaran)';
                lbl.className = 'text-[11px] text-emerald-600 font-semibold';
            } else {
                lbl.innerText = 'Nonaktif (Disembunyikan dari pendaftaran & kasir)';
                lbl.className = 'text-[11px] text-rose-600 font-semibold';
            }
        }

        async function saveCustomerCategoryForm(e) {
            e.preventDefault();
            const id = document.getElementById('cust-cat-id').value;
            const code = document.getElementById('cust-cat-code').value.trim().toUpperCase();
            const name = document.getElementById('cust-cat-name').value.trim();
            const defaultTier = document.getElementById('cust-cat-tier').value;
            const description = document.getElementById('cust-cat-desc').value.trim();
            const iconEmoji = document.getElementById('cust-cat-emoji').value.trim() || '👥';
            const isActive = document.getElementById('cust-cat-is-active').checked ? 1 : 0;

            if (!name) {
                alert('Nama kategori pelanggan wajib diisi!');
                return;
            }

            const payload = {
                id: id ? parseInt(id) : null,
                code: code,
                name: name,
                default_tier: defaultTier,
                description: description,
                icon_emoji: iconEmoji,
                is_active: isActive
            };

            try {
                const res = await fetch('api.php?action=save_customer_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    closeCustomerCategoryModal();
                    await loadCustomerCategories();
                    await initApp();
                    renderPosTierButtons();
                    renderPosCustomerSelect();
                    recalculateCartPrices();
                    renderProducts();
                }
            } catch (err) {
                alert('Gagal menyimpan kategori: ' + err.message);
            }
        }

        async function toggleCustomerCategoryStatus(id, newStatus) {
            try {
                const res = await fetch('api.php?action=toggle_customer_category_status', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id, is_active: newStatus })
                });
                const data = await res.json();
                if (!data.success) {
                    alert(data.message || 'Gagal mengubah status kategori');
                }
                await loadCustomerCategories();
                await initApp();
                renderPosTierButtons();
                renderPosCustomerSelect();
                recalculateCartPrices();
                renderProducts();
            } catch (err) {
                console.error(err);
                alert('Gagal mengubah status: ' + err.message);
                loadCustomerCategories();
            }
        }

        async function deleteCustomerCategory(id, name, activeCount) {
            if (activeCount > 0) {
                if (confirm(`Kategori '${name}' sedang digunakan oleh ${activeCount} pelanggan aktif.\nKategori tidak dapat dihapus permanen.\n\nApakah Anda ingin menonaktifkan status kategori ini saja?`)) {
                    toggleCustomerCategoryStatus(id, 0);
                }
                return;
            }

            if (!confirm(`Apakah Anda yakin ingin menghapus kategori '${name}'?`)) return;

            try {
                const res = await fetch('api.php?action=delete_customer_category', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadCustomerCategories();
                    await initApp();
                    renderPosTierButtons();
                    renderPosCustomerSelect();
                    recalculateCartPrices();
                    renderProducts();
                }
            } catch (err) {
                alert('Gagal menghapus kategori: ' + err.message);
            }
        }

        // ========================================================
        // MODUL 10: KURIR, LOGISTIK, PETA GEOSPASIAL & ARMADA MOTOR
        // ========================================================
        function setLogisticsSubtab(subtab) {
            state.logisticsActiveSubtab = subtab;
            const subtabs = [
                { key: 'vehicles', viewId: 'subtab-logistics-vehicles', btnId: 'subtab-btn-vehicles' },
                { key: 'fuel', viewId: 'subtab-logistics-fuel', btnId: 'subtab-btn-fuel' },
                { key: 'service', viewId: 'subtab-logistics-service', btnId: 'subtab-btn-service' },
                { key: 'settings', viewId: 'subtab-logistics-settings', btnId: 'subtab-btn-settings' },
                { key: 'maps', viewId: 'subtab-logistics-maps', btnId: 'subtab-btn-maps' }
            ];

            subtabs.forEach(item => {
                const view = document.getElementById(item.viewId);
                const btn = document.getElementById(item.btnId);
                if (item.key === subtab) {
                    if (view) view.classList.remove('hidden');
                    if (btn) {
                        btn.className = 'px-3.5 py-2 rounded-xl text-xs font-bold transition-all bg-indigo-600 text-white shadow-sm flex items-center space-x-1.5';
                    }
                } else {
                    if (view) view.classList.add('hidden');
                    if (btn) {
                        btn.className = 'px-3.5 py-2 rounded-xl text-xs font-bold transition-all bg-white text-slate-600 hover:bg-slate-100 border border-slate-200 flex items-center space-x-1.5';
                    }
                }
            });

            if (subtab === 'vehicles') loadVehicles();
            if (subtab === 'fuel') loadFuelLogs();
            if (subtab === 'service') loadServiceLogs();
            if (subtab === 'settings') loadDeliverySettings();
            if (subtab === 'maps') {
                setTimeout(() => {
                    initLogisticsMap();
                }, 150);
            }
            lucide.createIcons();
        }

        // Alias for compatibility
        function switchLogisticsSubtab(subtab) {
            setLogisticsSubtab(subtab);
        }

        async function loadLogisticsData() {
            setLogisticsSubtab(state.logisticsActiveSubtab || 'vehicles');
        }

        // --- SUBTAB 1: ARMADA KENDARAAN KURIR ---
        async function loadVehicles() {
            try {
                const res = await fetch('api.php?action=get_courier_vehicles');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                state.vehicles = data.vehicles || [];

                // Update KPIs
                const totalVehicles = state.vehicles.length;
                const activeBikes = state.vehicles.filter(v => v.vehicle_type === 'MOTOR' && v.status === 'ACTIVE').length;
                const activeCars = state.vehicles.filter(v => v.vehicle_type === 'MOBIL' && v.status === 'ACTIVE').length;

                const kpiTotal = document.getElementById('logistics-kpi-vehicles');
                const kpiActive = document.getElementById('logistics-kpi-active');
                if (kpiTotal) kpiTotal.innerText = totalVehicles;
                if (kpiActive) kpiActive.innerText = `${activeBikes} Motor / ${activeCars} Mobil`;

                // Populate Branch Filter for Vehicles if empty or changed
                const branchFilter = document.getElementById('vehicle-branch-filter');
                if (branchFilter && state.branches && state.branches.length > 0) {
                    const curBranchVal = branchFilter.value || 'ALL';
                    branchFilter.innerHTML = '<option value="ALL">Semua Cabang</option>' + 
                        state.branches.map(b => `<option value="${b.id}" ${curBranchVal == b.id ? 'selected' : ''}>${b.name}</option>`).join('');
                }

                renderVehiclesTable();
                renderPosCourierSelect();
                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function renderVehiclesTable() {
            const tbody = document.getElementById('vehicles-table-body');
            if (!tbody) return;

            const searchInput = document.getElementById('vehicle-search');
            const searchVal = searchInput ? searchInput.value.trim().toLowerCase() : '';

            const branchFilter = document.getElementById('vehicle-branch-filter');
            const branchVal = branchFilter ? branchFilter.value : 'ALL';

            let filtered = state.vehicles || [];
            if (branchVal !== 'ALL') {
                filtered = filtered.filter(v => v.branch_id == branchVal);
            }
            if (searchVal) {
                filtered = filtered.filter(v => 
                    (v.plate_number && v.plate_number.toLowerCase().includes(searchVal)) ||
                    (v.vehicle_name && v.vehicle_name.toLowerCase().includes(searchVal)) ||
                    (v.driver_name && v.driver_name.toLowerCase().includes(searchVal))
                );
            }

            if (filtered.length === 0) {
                tbody.innerHTML = `<tr><td colspan="8" class="text-center py-8 text-slate-400">Tidak ada armada kurir terdaftar${searchVal ? ' yang cocok dengan pencarian' : ''}. Klik "+ Tambah Kendaraan Kurir" untuk mendaftarkan motor/mobil.</td></tr>`;
                return;
            }

            tbody.innerHTML = filtered.map(v => {
                const branchName = state.branches.find(b => b.id === v.branch_id)?.name || 'Semua Cabang';
                const ratioText = (v.fuel_ratio_unit === 'METER_PER_LITER') ? `${v.fuel_ratio} m/L` : `${v.fuel_ratio} km/L`;
                
                let statusBadge = '';
                if (v.status === 'ACTIVE') {
                    statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800 border border-emerald-300">✅ Aktif Operasional</span>';
                } else if (v.status === 'MAINTENANCE') {
                    statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800 border border-amber-300">🔧 Sedang Servis</span>';
                } else {
                    statusBadge = '<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 text-slate-600">Nonaktif</span>';
                }

                return `
                    <tr class="hover:bg-slate-50 transition-colors">
                        <td class="py-3 px-4">
                            <span class="font-mono font-black text-indigo-950 px-2 py-1 bg-indigo-50 border border-indigo-200 rounded-lg text-xs tracking-wider">${v.plate_number}</span>
                        </td>
                        <td class="py-3 px-4 font-bold text-slate-800">
                            <span>${v.vehicle_type === 'MOTOR' ? '🛵' : '🚚'} ${v.vehicle_name}</span>
                        </td>
                        <td class="py-3 px-4 text-slate-600 font-medium">${v.driver_name || '-'}</td>
                        <td class="py-3 px-4 text-slate-600">${branchName}</td>
                        <td class="py-3 px-4 font-mono font-bold text-slate-800 text-right">${Number(v.current_odometer).toLocaleString('id-ID')} km</td>
                        <td class="py-3 px-4 text-center">
                            <span class="font-mono font-bold text-amber-700 bg-amber-50 px-2 py-0.5 rounded-md border border-amber-200 text-[11px]">${ratioText}</span>
                            <span class="text-[10px] text-slate-400 block">${v.fuel_type || 'Pertalite'}</span>
                        </td>
                        <td class="py-3 px-4 text-center">${statusBadge}</td>
                        <td class="py-3 px-4 text-center">
                            <div class="flex items-center justify-center space-x-1">
                                <button onclick="editVehicle(${v.id})" class="px-2 py-1 bg-indigo-50 hover:bg-indigo-600 hover:text-white text-indigo-700 font-bold text-[11px] rounded-lg border border-indigo-200 transition-colors">
                                    Edit
                                </button>
                                <button onclick="deleteVehicle(${v.id})" title="Hapus Kendaraan" class="p-1 text-slate-400 hover:text-rose-600 rounded-lg">
                                    <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                </button>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            lucide.createIcons();
        }

        function populateVehicleDriverOptions(selectedBranchId, selectedDriverUserId = null, currentDriverName = '') {
            const driverSelect = document.getElementById('vehicle-driver-select');
            const hiddenDriverInput = document.getElementById('vehicle-driver');
            if (!driverSelect) return;

            const branchId = selectedBranchId ? parseInt(selectedBranchId) : null;
            // Ambil data karyawan sesuai lokasi cabang yang dimiliki oleh karyawan
            const branchEmployees = (state.users || []).filter(u => (!branchId || !u.branch_id || u.branch_id === branchId) && u.is_active != 0);

            let optionsHtml = '';
            if (branchEmployees.length === 0) {
                optionsHtml = '<option value="">(Belum ada karyawan di cabang ini)</option>';
            } else {
                optionsHtml = '<option value="">-- Pilih Karyawan Cabang sebagai Driver --</option>' +
                    branchEmployees.map(u => {
                        const isSel = (selectedDriverUserId && u.id === selectedDriverUserId) || (!selectedDriverUserId && currentDriverName && u.name === currentDriverName);
                        return `<option value="${u.id}" data-name="${u.name}" ${isSel ? 'selected' : ''}>${u.name} (${u.role}) - ${u.phone || '-'}</option>`;
                    }).join('');
            }

            // Opsi jika driver nama kustom yang belum terhubung dengan akun user
            if (currentDriverName && !branchEmployees.some(u => u.name === currentDriverName)) {
                optionsHtml = `<option value="" data-name="${currentDriverName}" selected>${currentDriverName} (Driver Eksternal / Mitra)</option>` + optionsHtml;
            }

            driverSelect.innerHTML = optionsHtml;
            onVehicleDriverSelectChange();
        }

        function onVehicleBranchChange() {
            const branchSelect = document.getElementById('vehicle-branch');
            const selectedBranchId = branchSelect ? branchSelect.value : null;
            populateVehicleDriverOptions(selectedBranchId);
        }

        function onVehicleDriverSelectChange() {
            const driverSelect = document.getElementById('vehicle-driver-select');
            const hiddenDriverInput = document.getElementById('vehicle-driver');
            if (!driverSelect || !hiddenDriverInput) return;

            const selectedOption = driverSelect.options[driverSelect.selectedIndex];
            if (selectedOption && selectedOption.value) {
                hiddenDriverInput.value = selectedOption.getAttribute('data-name') || selectedOption.text.split(' (')[0];
            } else if (selectedOption && selectedOption.getAttribute('data-name')) {
                hiddenDriverInput.value = selectedOption.getAttribute('data-name');
            } else {
                hiddenDriverInput.value = '';
            }
        }

        function openVehicleModal(veh = null) {
            const modal = document.getElementById('vehicle-modal');
            const title = document.getElementById('vehicle-modal-title');
            const branchSelect = document.getElementById('vehicle-branch');

            branchSelect.innerHTML = '<option value="">Semua Cabang (Global)</option>' + 
                state.branches.map(b => `<option value="${b.id}">${b.name}</option>`).join('');

            if (veh) {
                title.innerText = 'Edit Data Armada Kendaraan Kurir';
                document.getElementById('vehicle-id').value = veh.id;
                document.getElementById('vehicle-branch').value = veh.branch_id || '';
                document.getElementById('vehicle-plate').value = veh.plate_number;
                document.getElementById('vehicle-name').value = veh.vehicle_name;
                document.getElementById('vehicle-type').value = veh.vehicle_type || 'MOTOR';
                document.getElementById('vehicle-driver').value = veh.driver_name || '';
                document.getElementById('vehicle-odometer').value = veh.current_odometer || 0;
                document.getElementById('vehicle-fuel-ratio').value = veh.fuel_ratio || 35;
                document.getElementById('vehicle-fuel-ratio-unit').value = veh.fuel_ratio_unit || 'KM_PER_LITER';
                document.getElementById('vehicle-fuel-type').value = veh.fuel_type || 'Pertalite';
                document.getElementById('vehicle-status').value = veh.status || 'ACTIVE';
                document.getElementById('vehicle-notes').value = veh.notes || '';
                populateVehicleDriverOptions(veh.branch_id, veh.driver_user_id, veh.driver_name);
            } else {
                title.innerText = 'Tambah Armada Kendaraan Baru';
                document.getElementById('vehicle-id').value = '';
                const defaultBranchId = state.currentBranch ? state.currentBranch.id : '';
                document.getElementById('vehicle-branch').value = defaultBranchId;
                document.getElementById('vehicle-plate').value = '';
                document.getElementById('vehicle-name').value = '';
                document.getElementById('vehicle-type').value = 'MOTOR';
                document.getElementById('vehicle-driver').value = '';
                document.getElementById('vehicle-odometer').value = '0';
                document.getElementById('vehicle-fuel-ratio').value = '35';
                document.getElementById('vehicle-fuel-ratio-unit').value = 'KM_PER_LITER';
                document.getElementById('vehicle-fuel-type').value = 'Pertalite';
                document.getElementById('vehicle-status').value = 'ACTIVE';
                document.getElementById('vehicle-notes').value = '';
                populateVehicleDriverOptions(defaultBranchId, null, '');
            }
            modal.classList.remove('hidden');
        }

