        // --- SUBTAB 2: CATATAN BENSIN BBM & ODOMETER MOTOR ---
        async function loadFuelLogs() {
            try {
                const res = await fetch('api.php?action=get_fuel_logs');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                state.fuelLogs = data.fuel_logs || data.logs || [];

                // Filter options
                const filterSelect = document.getElementById('fuel-vehicle-filter');
                if (filterSelect) {
                    const currentFilter = filterSelect.value || 'ALL';
                    filterSelect.innerHTML = '<option value="ALL">Semua Kendaraan</option>' + 
                        (state.vehicles || []).map(v => `<option value="${v.id}" ${currentFilter == v.id ? 'selected' : ''}>${v.plate_number} - ${v.vehicle_name}</option>`).join('');
                }

                const filtered = (filterSelect && filterSelect.value !== 'ALL') ? 
                    state.fuelLogs.filter(fl => fl.vehicle_id == filterSelect.value) : state.fuelLogs;

                // Update KPI Biaya BBM
                const totalFuelCost = filtered.reduce((acc, l) => acc + Number(l.total_cost || 0), 0);
                const totalLiters = filtered.reduce((acc, l) => acc + Number(l.liters_bought || 0), 0);
                const kpiFuelCost = document.getElementById('logistics-kpi-fuel-cost') || document.getElementById('logistics-kpi-fuel');
                if (kpiFuelCost) kpiFuelCost.innerText = formatRupiah(totalFuelCost);

                const tbody = document.getElementById('fuel-logs-table-body') || document.getElementById('fuel-table-body');
                if (!tbody) return;

                if (filtered.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="11" class="text-center py-8 text-slate-400">Belum ada riwayat pembelian bensin BBM. Klik "+ Catat Pembelian Bensin" untuk input transaksi kurir.</td></tr>`;
                    return;
                }

                tbody.innerHTML = filtered.map(l => {
                    const ratioText = (l.fuel_ratio_unit === 'METER_PER_LITER') ? `${l.configured_ratio} m/L` : `${l.configured_ratio} km/L`;
                    const efficiency = Number(l.efficiency_percent || 100);
                    let badgeClass = 'bg-emerald-100 text-emerald-800';
                    if (efficiency < 85) badgeClass = 'bg-rose-100 text-rose-800 font-bold';
                    else if (efficiency < 95) badgeClass = 'bg-amber-100 text-amber-800';

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-4 font-mono text-slate-600">${l.log_date}</td>
                            <td class="py-3 px-4 font-bold text-slate-900">
                                <span class="font-mono bg-slate-100 px-1.5 py-0.5 rounded text-[11px]">${l.plate_number}</span>
                                <span class="block text-[11px] text-slate-500 font-normal">${l.vehicle_name}</span>
                            </td>
                            <td class="py-3 px-4 text-slate-700 font-medium">${l.driver_name || '-'}</td>
                            <td class="py-3 px-4 font-mono text-center text-slate-600">
                                <span class="text-[10px] text-slate-400">${Number(l.last_odometer).toLocaleString()} &rarr;</span>
                                <span class="font-bold text-slate-800">${Number(l.current_odometer).toLocaleString()} km</span>
                            </td>
                            <td class="py-3 px-4 font-mono font-black text-indigo-900 text-right text-xs">+${Number(l.distance_traveled).toFixed(1)} km</td>
                            <td class="py-3 px-4 font-mono font-bold text-slate-800 text-right">${Number(l.liters_bought).toFixed(2)} L</td>
                            <td class="py-3 px-4 font-mono font-black text-rose-600 text-right text-xs">${formatRupiah(l.total_cost)}</td>
                            <td class="py-3 px-4 text-center font-mono text-[11px] text-slate-700 font-bold">${ratioText}</td>
                            <td class="py-3 px-4 text-center">
                                <span class="px-2 py-0.5 rounded-full text-[10px] ${badgeClass}">${efficiency}%</span>
                            </td>
                            <td class="py-3 px-4 text-center">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-900 border border-amber-200">
                                    ⛽ Beban BBM Cabang
                                </span>
                            </td>
                            <td class="py-3 px-4 text-center">
                                <button onclick="deleteFuelLog(${l.id})" title="Hapus Log BBM" class="p-1 text-slate-400 hover:text-rose-600 rounded-lg">
                                    <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                </button>
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                console.error(err);
            }
        }

        function openFuelLogModal() {
            const select = document.getElementById('fl-vehicle-select');
            select.innerHTML = state.vehicles.map(v => 
                `<option value="${v.id}">${v.plate_number} - ${v.vehicle_name} (Odo: ${v.current_odometer} km)</option>`
            ).join('');

            document.getElementById('fl-date').value = new Date().toISOString().split('T')[0];
            onFuelLogVehicleChange();
            document.getElementById('fuel-log-modal').classList.remove('hidden');
        }

        function closeFuelLogModal() {
            document.getElementById('fuel-log-modal').classList.add('hidden');
        }

        function onFuelLogVehicleChange() {
            const vId = parseInt(document.getElementById('fl-vehicle-select').value);
            const veh = state.vehicles.find(v => v.id === vId);
            if (veh) {
                document.getElementById('fl-last-odometer').value = veh.current_odometer || 0;
                document.getElementById('fl-current-odometer').value = veh.current_odometer || 0;
            }
            calculateFuelLogPreview();
        }

        function calculateFuelLogPreview() {
            const vId = parseInt(document.getElementById('fl-vehicle-select').value);
            const veh = state.vehicles.find(v => v.id === vId);
            const lastOdo = parseFloat(document.getElementById('fl-last-odometer').value) || 0;
            const curOdo = parseFloat(document.getElementById('fl-current-odometer').value) || lastOdo;
            const liters = parseFloat(document.getElementById('fl-liters').value) || 0;
            const costPerLiter = parseFloat(document.getElementById('fl-cost-per-liter').value) || 10000;

            const distance = Math.max(0, curOdo - lastOdo);
            const totalCost = Math.round(liters * costPerLiter);

            document.getElementById('fl-distance-display').innerText = `${distance.toFixed(1)} km`;
            document.getElementById('fl-total-cost-display').innerText = formatRupiah(totalCost);

            // Calculate expected fuel based on configured ratio
            if (veh && liters > 0 && distance > 0) {
                const ratio = Number(veh.fuel_ratio || 35);
                const unit = veh.fuel_ratio_unit || 'KM_PER_LITER';
                let effectiveRatioKm = (unit === 'METER_PER_LITER') ? (ratio / 1000.0) : ratio;
                if (effectiveRatioKm <= 0) effectiveRatioKm = 35.0;

                const expectedLiters = distance / effectiveRatioKm;
                const efficiency = Math.round((expectedLiters / liters) * 100);

                document.getElementById('fl-expected-liters').innerText = `${expectedLiters.toFixed(2)} L (Standar: ${effectiveRatioKm} km/L)`;
                const badge = document.getElementById('fl-efficiency-badge');
                if (badge) {
                    badge.innerText = `${efficiency}% ${efficiency >= 95 ? '(Irit / Normal)' : '(Boros / Perlu Servis)'}`;
                    badge.className = efficiency >= 95 ? 
                        'px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800' :
                        'px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-800';
                }
            }
        }

