        // --- SUBTAB 4: PENGATURAN BIAYA KIRIM DINAMIS ---
        async function loadDeliverySettings() {
            try {
                const branchSelect = document.getElementById('setting-branch-select');
                if (!branchSelect) return;

                const currentBranchId = branchSelect.value ? parseInt(branchSelect.value) : (state.currentBranch ? state.currentBranch.id : 1);
                branchSelect.innerHTML = state.branches.map(b => `
                    <option value="${b.id}" ${b.id === currentBranchId ? 'selected' : ''}>${b.name}</option>
                `).join('');

                const res = await fetch(`api.php?action=get_delivery_settings&branch_id=${currentBranchId}`);
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const s = data.setting;
                document.getElementById('ds-base-fee').value = s.base_fee;
                document.getElementById('ds-base-km').value = s.base_distance_km;
                document.getElementById('ds-per-km-rate').value = s.per_km_rate;
                document.getElementById('ds-free-threshold').value = s.free_delivery_threshold;
                document.getElementById('ds-max-km').value = s.max_distance_km;

                const kpiBaseFee = document.getElementById('logistics-kpi-base-fee');
                if (kpiBaseFee) kpiBaseFee.innerText = formatRupiah(s.base_fee);

                testDeliveryFeeCalculator();
            } catch (err) {
                console.error(err);
            }
        }

        function onSettingBranchChange() {
            loadDeliverySettings();
        }

        function updateDeliverySimulator() {
            const baseFee = parseFloat(document.getElementById('ds-base-fee').value) || 10000;
            const baseKm = parseFloat(document.getElementById('ds-base-km').value) || 3.0;
            const perKm = parseFloat(document.getElementById('ds-per-km-rate').value) || 2500;
            const freeThreshold = parseFloat(document.getElementById('ds-free-threshold').value) || 150000;

            const distRange = document.getElementById('sim-distance-range');
            const distVal = distRange ? parseFloat(distRange.value) : 5.0;
            const subtotalInput = document.getElementById('sim-subtotal-val');
            const subtotal = subtotalInput ? parseFloat(subtotalInput.value) : 75000;

            const distDisplay = document.getElementById('sim-distance-val');
            if (distDisplay) distDisplay.innerText = `${distVal.toFixed(1)} km`;

            let fee = baseFee;
            let formulaDesc = '';

            if (freeThreshold > 0 && subtotal >= freeThreshold) {
                fee = 0;
                formulaDesc = `🎉 Promo Gratis Ongkir aktif (Belanja ${formatRupiah(subtotal)} ≥ Minimal ${formatRupiah(freeThreshold)})`;
            } else if (distVal <= baseKm) {
                fee = baseFee;
                formulaDesc = `Tarif Dasar: ${formatRupiah(baseFee)} untuk ${baseKm} km pertama`;
            } else {
                const extraKm = Math.ceil(distVal - baseKm);
                const extraFee = extraKm * perKm;
                fee = baseFee + extraFee;
                formulaDesc = `Dasar ${formatRupiah(baseFee)} + (${extraKm} km × ${formatRupiah(perKm)}) = ${formatRupiah(fee)}`;
            }

            const feeResult = document.getElementById('sim-fee-result');
            if (feeResult) feeResult.innerText = formatRupiah(fee);

            const formulaEl = document.getElementById('sim-formula-desc');
            if (formulaEl) formulaEl.innerText = formulaDesc;
        }

        function testDeliveryFeeCalculator() {
            updateDeliverySimulator();
        }

        async function saveDeliverySettingsForm(e) {
            e.preventDefault();
            const branchId = parseInt(document.getElementById('setting-branch-select').value);
            const payload = {
                branch_id: branchId,
                base_fee: parseFloat(document.getElementById('ds-base-fee').value),
                base_distance_km: parseFloat(document.getElementById('ds-base-km').value),
                per_km_rate: parseFloat(document.getElementById('ds-per-km-rate').value),
                free_delivery_threshold: parseFloat(document.getElementById('ds-free-threshold').value),
                max_distance_km: parseFloat(document.getElementById('ds-max-km').value)
            };

            const res = await fetch('api.php?action=save_delivery_settings', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            alert(data.message || data.error);
            if (data.success) {
                loadDeliverySettings();
                initApp();
            }
        }

        // --- SUBTAB 5: PETA GEOSPASIAL OUTLET & PELANGGAN LEAFLET ---
        function initLogisticsMap() {
            const mapContainer = document.getElementById('logistics-map');
            if (!mapContainer) return;

            const branchLat = state.currentBranch?.latitude || -6.195000;
            const branchLon = state.currentBranch?.longitude || 106.823000;

            if (!state.logisticsMap) {
                state.logisticsMap = L.map('logistics-map').setView([branchLat, branchLon], 13);
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19,
                    attribution: '&copy; OpenStreetMap contributors'
                }).addTo(state.logisticsMap);
            } else {
                state.logisticsMap.invalidateSize();
            }

            populateMapSelections();
            renderMapMarkers();
        }

        function populateMapSelections() {
            const bSelect = document.getElementById('map-branch-select');
            const cSelect = document.getElementById('map-customer-select');
            if (!bSelect || !cSelect) return;

            const curBId = state.currentBranch ? state.currentBranch.id : 1;
            bSelect.innerHTML = state.branches.map(b => `
                <option value="${b.id}" ${b.id === curBId ? 'selected' : ''}>🏢 ${b.name}</option>
            `).join('');

            const custWithCoords = state.customers.filter(c => c.latitude && c.longitude);
            if (custWithCoords.length === 0) {
                cSelect.innerHTML = state.customers.map(c => `
                    <option value="${c.id}">📍 ${c.name} (${c.category || 'REGULER'})</option>
                `).join('');
            } else {
                cSelect.innerHTML = custWithCoords.map(c => `
                    <option value="${c.id}">📍 ${c.name} [${c.category || 'REGULER'}]</option>
                `).join('');
            }
        }

        function renderMapMarkers() {
            if (!state.logisticsMap) return;

            // Clear old markers
            if (state.mapMarkers) {
                state.mapMarkers.forEach(m => state.logisticsMap.removeLayer(m));
            }
            state.mapMarkers = [];

            // Add branch markers (Icon Toko / Merah)
            state.branches.forEach(b => {
                if (b.latitude && b.longitude) {
                    const marker = L.marker([b.latitude, b.longitude]).addTo(state.logisticsMap);
                    marker.bindPopup(`
                        <div class="text-xs">
                            <strong class="text-indigo-900 block text-sm">🏢 ${b.name}</strong>
                            <p class="text-slate-600">${b.address}</p>
                            <span class="inline-block mt-1 px-2 py-0.5 bg-indigo-100 text-indigo-800 rounded font-bold">Outlet Cabang Acuan</span>
                        </div>
                    `);
                    state.mapMarkers.push(marker);
                }
            });

            // Add customer markers (Icon Pelanggan / Biru)
            state.customers.forEach(c => {
                if (c.latitude && c.longitude) {
                    const marker = L.circleMarker([c.latitude, c.longitude], {
                        radius: 8,
                        fillColor: c.category === 'MITRA' ? '#059669' : '#4f46e5',
                        color: '#ffffff',
                        weight: 2,
                        opacity: 1,
                        fillOpacity: 0.85
                    }).addTo(state.logisticsMap);

                    marker.bindPopup(`
                        <div class="text-xs">
                            <strong class="text-slate-900 block font-bold">${c.category === 'MITRA' ? '🤝 Mitra:' : '👤 Pelanggan:'} ${c.name}</strong>
                            <p class="text-slate-500">${c.address || '-'}</p>
                            <span class="inline-block mt-1 px-1.5 py-0.5 bg-slate-100 text-slate-700 rounded text-[10px] font-mono">
                                Lat: ${Number(c.latitude).toFixed(4)}, Lon: ${Number(c.longitude).toFixed(4)}
                            </span>
                        </div>
                    `);
                    state.mapMarkers.push(marker);
                }
            });

            drawDeliveryRouteOnMap();
        }

        function onMapSelectionChange() {
            drawDeliveryRouteOnMap();
        }

        async function drawDeliveryRouteOnMap() {
            if (!state.logisticsMap) return;

            const bId = parseInt(document.getElementById('map-branch-select')?.value || 1);
            const cId = parseInt(document.getElementById('map-customer-select')?.value || 1);

            const branch = state.branches.find(b => b.id === bId);
            const cust = state.customers.find(c => c.id === cId);

            if (!branch || !cust) return;

            // Remove existing polyline
            if (state.mapRoutePolyline) {
                state.logisticsMap.removeLayer(state.mapRoutePolyline);
                state.mapRoutePolyline = null;
            }

            const bLat = branch.latitude || -6.195000;
            const bLon = branch.longitude || 106.823000;
            const cLat = cust.latitude || (bLat + 0.02);
            const cLon = cust.longitude || (bLon + 0.015);

            // Draw straight geodesic route line
            const latlngs = [[bLat, bLon], [cLat, cLon]];
            state.mapRoutePolyline = L.polyline(latlngs, {
                color: '#4f46e5',
                weight: 4,
                dashArray: '8, 8',
                opacity: 0.85
            }).addTo(state.logisticsMap);

            state.logisticsMap.fitBounds(state.mapRoutePolyline.getBounds(), { padding: [50, 50] });

            // Calculate Dynamic Fee via API
            try {
                const res = await fetch(`api.php?action=calculate_delivery_fee&branch_id=${bId}&customer_id=${cId}&subtotal=100000`);
                const data = await res.json();
                if (data.success) {
                    const infoBranch = document.getElementById('map-info-branch-name');
                    const infoCust = document.getElementById('map-info-cust-name');
                    const infoBranchCoords = document.getElementById('map-info-branch-coords');
                    const infoCustCoords = document.getElementById('map-info-cust-coords');
                    const infoDist = document.getElementById('map-info-distance');
                    const infoEta = document.getElementById('map-info-eta');
                    const infoFee = document.getElementById('map-info-delivery-fee') || document.getElementById('map-info-fee');
                    const infoRule = document.getElementById('map-info-rule');

                    if (infoBranch) infoBranch.innerText = branch.name;
                    if (infoCust) infoCust.innerText = `${cust.name} (${cust.category || 'REGULER'})`;
                    if (infoBranchCoords) infoBranchCoords.innerText = `${Number(bLat).toFixed(4)}, ${Number(bLon).toFixed(4)}`;
                    if (infoCustCoords) infoCustCoords.innerText = `${Number(cLat).toFixed(4)}, ${Number(cLon).toFixed(4)}`;
                    if (infoDist) infoDist.innerText = `${data.distance_km} km`;
                    if (infoFee) infoFee.innerText = formatRupiah(data.delivery_fee);
                    if (infoRule) infoRule.innerText = data.free_delivery_reason || `Tarif Jarak ${data.distance_km} km`;
                    if (infoEta) {
                        const minTime = Math.max(5, Math.round(data.distance_km * 3));
                        infoEta.innerText = `~${minTime} - ${minTime + 5} Menit`;
                    }
                }
            } catch (err) {
                console.error(err);
            }
        }

        // ==========================================
        // 11. MANAJEMEN CABANG & OUTLET (CRUD BRANCHES)
        // ==========================================
        async function loadBranches() {
            try {
                const res = await fetch('api.php?action=get_branches');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const branches = data.branches;
                state.branches = branches;

                // KPI Counter
                const totalBranches = branches.length;
                const activeBranches = branches.filter(b => b.is_active != 0).length;
                const totalStaff = branches.reduce((sum, b) => sum + Number(b.total_staff || 0), 0);
                const totalVehicles = branches.reduce((sum, b) => sum + Number(b.total_vehicles || 0), 0);

                const elTotal = document.getElementById('branch-kpi-total');
                const elActive = document.getElementById('branch-kpi-active');
                const elStaff = document.getElementById('branch-kpi-staff');
                const elVehicles = document.getElementById('branch-kpi-vehicles');
                if (elTotal) elTotal.innerText = totalBranches;
                if (elActive) elActive.innerText = activeBranches;
                if (elStaff) elStaff.innerText = totalStaff;
                if (elVehicles) elVehicles.innerText = totalVehicles;

                const tbody = document.getElementById('branches-table-body');
                if (!tbody) return;

                if (branches.length === 0) {
                    tbody.innerHTML = `<tr><td colspan="9" class="text-center py-8 text-slate-400">Belum ada data cabang. Silakan tambah cabang baru.</td></tr>`;
                    return;
                }

                tbody.innerHTML = branches.map(b => {
                    const isActive = b.is_active != 0;
                    const isMain = b.id == 1;

                    return `
                        <tr class="hover:bg-slate-50/80 transition-colors">
                            <td class="py-3 px-4 font-mono font-black text-indigo-700">
                                <span class="bg-indigo-50 border border-indigo-200 px-2 py-0.5 rounded-md text-[11px]">${b.code}</span>
                            </td>
                            <td class="py-3 px-4 font-bold text-slate-800">
                                <div class="flex items-center space-x-1.5">
                                    <span>${b.name}</span>
                                    ${isMain ? '<span class="px-1.5 py-0.2 bg-purple-100 text-purple-700 rounded text-[9px] font-black uppercase">Pusat</span>' : ''}
                                </div>
                            </td>
                            <td class="py-3 px-4 text-slate-600 max-w-xs truncate" title="${b.address}">${b.address}</td>
                            <td class="py-3 px-4 font-mono text-[11px] text-slate-500">
                                <div class="flex items-center space-x-1.5">
                                    <button onclick="focusBranchOnMap(${b.id})" title="Lihat Titik di Peta Maps" class="px-2 py-0.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-bold rounded-lg text-[10px] transition-colors flex items-center space-x-1 border border-indigo-200">
                                        <i data-lucide="map-pin" class="w-3 h-3 text-indigo-600"></i>
                                        <span>${Number(b.latitude).toFixed(4)}, ${Number(b.longitude).toFixed(4)}</span>
                                    </button>
                                </div>
                            </td>
                            <td class="py-3 px-4 text-center font-bold text-slate-700">
                                <span class="bg-slate-100 border border-slate-200 px-2 py-0.5 rounded-full text-[10px]">${b.radius_meters || 100} m</span>
                            </td>
                            <td class="py-3 px-4 text-slate-600">${b.phone || '-'}</td>
                            <td class="py-3 px-4 text-center">
                                <div class="flex items-center justify-center space-x-2 text-[11px]">
                                    <span title="Jumlah Staf" class="bg-blue-50 text-blue-700 font-bold px-1.5 py-0.5 rounded">👥 ${b.total_staff || 0}</span>
                                    <span title="Katalog Produk" class="bg-emerald-50 text-emerald-700 font-bold px-1.5 py-0.5 rounded">📦 ${b.total_products || 0}</span>
                                </div>
                            </td>
                            <td class="py-3 px-4 text-center">
                                <span class="px-2.5 py-1 rounded-full text-[10px] font-bold ${isActive ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}">
                                    ${isActive ? '● Aktif' : '○ Nonaktif'}
                                </span>
                            </td>
                            <td class="py-3 px-4 text-center whitespace-nowrap">
                                <div class="flex items-center justify-center space-x-1">
                                    <button onclick="focusBranchOnMap(${b.id})" title="Buka di Peta Maps" class="p-1.5 text-indigo-600 hover:text-indigo-800 hover:bg-indigo-50 rounded-lg">
                                        <i data-lucide="map" class="w-4 h-4"></i>
                                    </button>
                                    <button onclick="editBranchById(${b.id})" class="px-2.5 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-bold rounded-lg text-[11px] transition-colors flex items-center space-x-1">
                                        <i data-lucide="edit-3" class="w-3 h-3"></i>
                                        <span>Edit</span>
                                    </button>
                                    ${!isMain ? `
                                        <button onclick="deleteBranch(${b.id}, '${b.name.replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-rose-50 hover:bg-rose-100 text-rose-700 font-bold rounded-lg text-[11px] transition-colors flex items-center space-x-1">
                                            <i data-lucide="trash-2" class="w-3 h-3"></i>
                                            <span>Hapus</span>
                                        </button>
                                    ` : `
                                        <span class="text-[10px] text-slate-400 font-bold italic px-2">Protected</span>
                                    `}
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('');

                renderBranchOptions();

                if (state.branchActiveSubtab === 'maps') {
                    initBranchMap();
                }

                lucide.createIcons();
            } catch (err) {
                console.error("loadBranches Error:", err);
            }
        }

        function editBranchById(id) {
            const b = (state.branches || []).find(x => x.id == id);
            if (b) editBranch(b);
        }

        function updateBranchPickerBadge(lat, lon, radius) {
            const badgeCoords = document.getElementById('branch-picker-coords-text');
            const badgeRadius = document.getElementById('branch-picker-radius-badge');
            const gmapsLink = document.getElementById('branch-modal-gmaps-link');
            const nLat = parseFloat(lat);
            const nLon = parseFloat(lon);
            if (badgeCoords) {
                if (!isNaN(nLat) && !isNaN(nLon)) {
                    badgeCoords.innerText = `${nLat.toFixed(6)}, ${nLon.toFixed(6)}`;
                } else {
                    badgeCoords.innerText = '-';
                }
            }
            if (badgeRadius) {
                badgeRadius.innerText = `${radius || 100}m`;
            }
            if (gmapsLink && !isNaN(nLat) && !isNaN(nLon)) {
                gmapsLink.href = `https://www.google.com/maps?q=${nLat.toFixed(6)},${nLon.toFixed(6)}`;
            }
        }

        function toggleBranchSearchClearBtn() {
            const input = document.getElementById('branch-modal-search-input');
            const clearBtn = document.getElementById('branch-modal-search-clear-btn');
            if (input && clearBtn) {
                if (input.value.trim().length > 0) {
                    clearBtn.classList.remove('hidden');
                } else {
                    clearBtn.classList.add('hidden');
                }
            }
        }

        function clearBranchAddressSearch() {
            const input = document.getElementById('branch-modal-search-input');
            if (input) input.value = '';
            toggleBranchSearchClearBtn();
            const statusEl = document.getElementById('branch-modal-search-status');
            if (statusEl) {
                statusEl.innerHTML = '';
                statusEl.classList.add('hidden');
            }
        }

        function copyBranchAddressToSearch() {
            const address = document.getElementById('branch-modal-address')?.value?.trim() || '';
            const name = document.getElementById('branch-modal-name')?.value?.trim() || '';
            const query = address || name;
            if (!query) {
                alert('Silakan ketik Nama Outlet atau Alamat Fisik Toko terlebih dahulu pada formulir di sebelah kiri.');
                return;
            }
            const input = document.getElementById('branch-modal-search-input');
            if (input) {
                input.value = query;
                toggleBranchSearchClearBtn();
                searchBranchAddressOnMap();
            }
        }

        function applyBranchFoundCoords(lat, lon, label) {
            const latVal = Number(lat).toFixed(6);
            const lonVal = Number(lon).toFixed(6);
            document.getElementById('branch-modal-lat').value = latVal;
            document.getElementById('branch-modal-lng').value = lonVal;
            updateBranchPickerFromInputs();
            if (state.branchPickerMap) {
                state.branchPickerMap.setView([lat, lon], 16);
            }
            const statusEl = document.getElementById('branch-modal-search-status');
            if (statusEl) {
                statusEl.innerHTML = `<div class="p-2 bg-emerald-50 border border-emerald-200/80 rounded-lg text-emerald-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="check-circle-2" class="w-3.5 h-3.5 text-emerald-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span class="font-bold">Lokasi Ditemukan (${latVal}, ${lonVal}):</span><p class="text-[10px] text-slate-600 truncate">${escapeHtml(label)}</p></div><a href="https://www.google.com/maps?q=${latVal},${lonVal}" target="_blank" rel="noopener noreferrer" class="text-indigo-600 hover:text-indigo-800 font-bold underline shrink-0 text-[10px]">Google Maps</a></div>`;
                statusEl.classList.remove('hidden');
                if (window.lucide) lucide.createIcons();
            }
        }

        async function searchBranchAddressOnMap() {
            const input = document.getElementById('branch-modal-search-input');
            let query = input?.value?.trim() || '';
            if (!query) {
                query = document.getElementById('branch-modal-address')?.value?.trim() || '';
                if (query && input) {
                    input.value = query;
                    toggleBranchSearchClearBtn();
                }
            }
            if (!query) {
                alert('Silakan masukkan alamat toko, nama tempat, atau link / koordinat Google Maps.');
                if (input) input.focus();
                return;
            }

            const searchBtn = document.getElementById('branch-modal-search-btn');
            const statusEl = document.getElementById('branch-modal-search-status');
            const originalBtnHtml = searchBtn ? searchBtn.innerHTML : '';

            if (searchBtn) {
                searchBtn.disabled = true;
                searchBtn.innerHTML = '<span class="inline-block animate-spin mr-1">⏳</span><span>Mencari...</span>';
            }
            if (statusEl) {
                statusEl.innerHTML = '<span class="text-slate-500 italic flex items-center space-x-1"><span class="animate-spin inline-block">⏳</span><span>Menghubungkan & mencari lokasi alamat di peta...</span></span>';
                statusEl.classList.remove('hidden');
            }

            const finishSearch = () => {
                if (searchBtn) {
                    searchBtn.disabled = false;
                    searchBtn.innerHTML = originalBtnHtml;
                    if (window.lucide) lucide.createIcons();
                }
            };

            // 1. Cek apakah input berupa koordinat langsung atau URL Google Maps
            const coordRegex = /([-+]?\d{1,2}\.\d+)[,\s]+([-+]?\d{1,3}\.\d+)/;
            const match = query.match(coordRegex);
            if (match) {
                const lat = parseFloat(match[1]);
                const lon = parseFloat(match[2]);
                if (!isNaN(lat) && !isNaN(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180) {
                    applyBranchFoundCoords(lat, lon, `Koordinat Google Maps Terdeteksi: ${lat.toFixed(6)}, ${lon.toFixed(6)}`);
                    finishSearch();
                    return;
                }
            }

            // 2. Geocoding via OpenStreetMap Nominatim API
            try {
                const encodedQuery = encodeURIComponent(query);
                const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodedQuery}&addressdetails=1&limit=1`;
                const resp = await fetch(url, { headers: { 'Accept-Language': 'id,en' } });
                const data = await resp.json();

                if (Array.isArray(data) && data.length > 0) {
                    const lat = parseFloat(data[0].lat);
                    const lon = parseFloat(data[0].lon);
                    applyBranchFoundCoords(lat, lon, data[0].display_name);
                } else {
                    let fallbackFound = false;
                    const commaParts = query.split(',').map(s => s.trim()).filter(Boolean);
                    if (commaParts.length > 1) {
                        const broaderQuery = commaParts.slice(1).join(', ');
                        const resp2 = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(broaderQuery)}&addressdetails=1&limit=1`, { headers: { 'Accept-Language': 'id,en' } });
                        const data2 = await resp2.json();
                        if (Array.isArray(data2) && data2.length > 0) {
                            fallbackFound = true;
                            const lat = parseFloat(data2[0].lat);
                            const lon = parseFloat(data2[0].lon);
                            applyBranchFoundCoords(lat, lon, `${data2[0].display_name} (Wilayah Terdekat)`);
                        }
                    }

                    if (!fallbackFound) {
                        const gmapsSearchUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
                        if (statusEl) {
                            statusEl.innerHTML = `<div class="p-2 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="alert-triangle" class="w-3.5 h-3.5 text-amber-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span>Alamat tidak ditemukan otomatis.</span> <a href="${gmapsSearchUrl}" target="_blank" rel="noopener noreferrer" class="font-bold underline text-indigo-700 hover:text-indigo-900 inline-flex items-center space-x-1 ml-1"><span>Cari di Google Maps</span><i data-lucide="external-link" class="w-3 h-3 inline"></i></a><p class="text-[10px] text-slate-500 mt-0.5">Anda bisa salin link atau koordinat dari Google Maps dan tempel di sini.</p></div></div>`;
                            if (window.lucide) lucide.createIcons();
                        }
                    }
                }
            } catch (err) {
                const gmapsSearchUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
                if (statusEl) {
                    statusEl.innerHTML = `<div class="p-2 bg-rose-50 border border-rose-200 rounded-lg text-rose-800 text-[11px] flex items-start space-x-1.5"><i data-lucide="wifi-off" class="w-3.5 h-3.5 text-rose-600 shrink-0 mt-0.5"></i><div class="min-w-0 flex-1"><span>Koneksi pencarian alamat gagal.</span> <a href="${gmapsSearchUrl}" target="_blank" rel="noopener noreferrer" class="font-bold underline text-indigo-700 hover:text-indigo-900 inline-flex items-center space-x-1 ml-1"><span>Buka Langsung di Google Maps</span><i data-lucide="external-link" class="w-3 h-3 inline"></i></a></div></div>`;
                    if (window.lucide) lucide.createIcons();
                }
            } finally {
                finishSearch();
            }
        }

        function openBranchModal() {
            document.getElementById('branch-modal-id').value = '';
            document.getElementById('branch-modal-code').value = '';
            document.getElementById('branch-modal-code').readOnly = false;
            document.getElementById('branch-modal-name').value = '';
            document.getElementById('branch-modal-phone').value = '';
            document.getElementById('branch-modal-address').value = '';
            const defLat = state.currentBranch?.latitude || -6.195000;
            const defLon = state.currentBranch?.longitude || 106.823000;
            document.getElementById('branch-modal-lat').value = Number(defLat).toFixed(6);
            document.getElementById('branch-modal-lng').value = Number(defLon).toFixed(6);
            document.getElementById('branch-modal-radius').value = '100';
            document.getElementById('branch-modal-active').value = '1';
            clearBranchAddressSearch();
            updateBranchPickerBadge(defLat, defLon, 100);
            document.getElementById('branch-modal-title').innerHTML = '<i data-lucide="store" class="w-5 h-5 text-indigo-600"></i><span>Tambah Cabang / Outlet Baru</span>';
            document.getElementById('branch-modal-submit-btn').innerText = 'Simpan Cabang';
            document.getElementById('branch-modal').classList.remove('hidden');
            setTimeout(() => {
                initBranchPickerMap();
            }, 100);
            setTimeout(() => {
                if (state.branchPickerMap) state.branchPickerMap.invalidateSize();
            }, 300);
            lucide.createIcons();
        }

        function editBranch(b) {
            document.getElementById('branch-modal-id').value = b.id;
            document.getElementById('branch-modal-code').value = b.code;
            document.getElementById('branch-modal-code').readOnly = (b.id == 1);
            document.getElementById('branch-modal-name').value = b.name;
            document.getElementById('branch-modal-phone').value = b.phone || '';
            document.getElementById('branch-modal-address').value = b.address || '';
            document.getElementById('branch-modal-lat').value = b.latitude;
            document.getElementById('branch-modal-lng').value = b.longitude;
            document.getElementById('branch-modal-radius').value = b.radius_meters || 100;
            document.getElementById('branch-modal-active').value = (b.is_active != 0) ? '1' : '0';
            
            const searchInput = document.getElementById('branch-modal-search-input');
            if (searchInput) searchInput.value = b.address || b.name || '';
            toggleBranchSearchClearBtn();
            const statusEl = document.getElementById('branch-modal-search-status');
            if (statusEl) {
                statusEl.innerHTML = '';
                statusEl.classList.add('hidden');
            }

            updateBranchPickerBadge(b.latitude, b.longitude, b.radius_meters || 100);
            document.getElementById('branch-modal-title').innerHTML = '<i data-lucide="edit-3" class="w-5 h-5 text-indigo-600"></i><span>Edit Cabang: ' + b.name + '</span>';
            document.getElementById('branch-modal-submit-btn').innerText = 'Perbarui Cabang';
            document.getElementById('branch-modal').classList.remove('hidden');
            setTimeout(() => {
                initBranchPickerMap();
            }, 100);
            setTimeout(() => {
                if (state.branchPickerMap) state.branchPickerMap.invalidateSize();
            }, 300);
            lucide.createIcons();
        }

        function closeBranchModal() {
            document.getElementById('branch-modal').classList.add('hidden');
        }

        // --- SUBTAB 2: PETA GEOSPASIAL JARINGAN CABANG (OUTLET MAPS) ---
        async function setBranchSubtab(subtab) {
            state.branchActiveSubtab = subtab;
            const isTable = (subtab === 'table');
            const tableEl = document.getElementById('subview-branch-table');
            const mapsEl = document.getElementById('subview-branch-maps');
            const btnTable = document.getElementById('subtab-btn-branch-table');
            const btnMaps = document.getElementById('subtab-btn-branch-maps');

            if (isTable) {
                if (tableEl) tableEl.classList.remove('hidden');
                if (mapsEl) mapsEl.classList.add('hidden');
                if (btnTable) btnTable.className = 'px-4 py-2 rounded-xl text-xs font-bold bg-indigo-600 text-white transition-colors flex items-center space-x-1.5 shadow-sm';
                if (btnMaps) btnMaps.className = 'px-4 py-2 rounded-xl text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors flex items-center space-x-1.5';
            } else {
                if (tableEl) tableEl.classList.add('hidden');
                if (mapsEl) mapsEl.classList.remove('hidden');
                if (btnTable) btnTable.className = 'px-4 py-2 rounded-xl text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors flex items-center space-x-1.5';
                if (btnMaps) btnMaps.className = 'px-4 py-2 rounded-xl text-xs font-bold bg-indigo-600 text-white transition-colors flex items-center space-x-1.5 shadow-sm';
                if (!state.branches || state.branches.length === 0) {
                    await loadBranches();
                }
                setTimeout(() => {
                    initBranchMap();
                }, 100);
                setTimeout(() => {
                    if (state.branchMap) state.branchMap.invalidateSize();
                }, 300);
            }
            lucide.createIcons();
        }

        async function initBranchMap() {
            const mapContainer = document.getElementById('branch-geospatial-map');
            if (!mapContainer) return;

            if (!state.branches || state.branches.length === 0) {
                await loadBranches();
            }

            const branchLat = parseFloat(state.currentBranch?.latitude) || -6.195000;
            const branchLon = parseFloat(state.currentBranch?.longitude) || 106.823000;

            if (!state.branchMap) {
                state.branchMap = L.map('branch-geospatial-map').setView([branchLat, branchLon], 12);
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19,
                    attribution: '&copy; OpenStreetMap contributors'
                }).addTo(state.branchMap);
            } else {
                state.branchMap.invalidateSize();
            }

            setTimeout(() => {
                if (state.branchMap) state.branchMap.invalidateSize();
            }, 100);
            setTimeout(() => {
                if (state.branchMap) state.branchMap.invalidateSize();
            }, 300);

            populateBranchMapSelections();
            renderBranchMapMarkers();
        }

        function populateBranchMapSelections() {
            const bSelect = document.getElementById('branch-map-select');
            if (!bSelect) return;

            const curBId = state.currentBranch ? state.currentBranch.id : (state.branches[0]?.id || 1);
            bSelect.innerHTML = state.branches.map(b => `
                <option value="${b.id}" ${b.id === curBId ? 'selected' : ''}>🏢 ${b.name} (${b.code})</option>
            `).join('');
        }

        function renderBranchMapMarkers() {
            if (!state.branchMap) return;

            // Clear old markers & circles
            if (state.branchMapMarkers) {
                state.branchMapMarkers.forEach(m => state.branchMap.removeLayer(m));
            }
            state.branchMapMarkers = [];

            if (state.branchMapCircles) {
                state.branchMapCircles.forEach(c => state.branchMap.removeLayer(c));
            }
            state.branchMapCircles = [];

            const statusFilter = document.getElementById('branch-map-status-filter')?.value || 'ALL';

            const filteredBranches = state.branches.filter(b => {
                if (statusFilter === 'ACTIVE') return b.is_active != 0;
                if (statusFilter === 'INACTIVE') return b.is_active == 0;
                return true;
            });

            filteredBranches.forEach(b => {
                if (b.latitude && b.longitude) {
                    const isMain = (b.id == 1);
                    const marker = L.marker([b.latitude, b.longitude]).addTo(state.branchMap);
                    marker.bindPopup(`
                        <div class="text-xs">
                            <strong class="text-slate-900 block font-bold text-sm">🏢 ${b.name}</strong>
                            <p class="text-slate-600">${b.address}</p>
                            <div class="mt-1 flex items-center space-x-1">
                                <span class="px-1.5 py-0.5 ${isMain ? 'bg-purple-100 text-purple-800' : 'bg-indigo-100 text-indigo-800'} rounded text-[10px] font-bold">
                                    ${isMain ? 'PUSAT' : 'OUTLET'}
                                </span>
                                <span class="px-1.5 py-0.5 bg-slate-100 text-slate-700 rounded text-[10px] font-mono">
                                    Radius: ${b.radius_meters || 100}m
                                </span>
                            </div>
                        </div>
                    `);

                    marker.on('click', () => {
                        selectBranchOnMap(b);
                    });

                    state.branchMapMarkers.push(marker);

                    // Add Geofence circle
                    const radiusCircle = L.circle([b.latitude, b.longitude], {
                        radius: b.radius_meters || 100,
                        color: isMain ? '#9333ea' : '#4f46e5',
                        fillColor: isMain ? '#c084fc' : '#818cf8',
                        fillOpacity: 0.2,
                        weight: 2
                    }).addTo(state.branchMap);

                    state.branchMapCircles.push(radiusCircle);
                }
            });

            // Default select
            const bSelect = document.getElementById('branch-map-select');
            const selectedBranchId = bSelect ? parseInt(bSelect.value) : null;
            const targetBranch = filteredBranches.find(b => b.id === selectedBranchId) || filteredBranches[0];
            if (targetBranch) {
                selectBranchOnMap(targetBranch, false);
            }
        }

        function onBranchMapSelectChange() {
            const bId = parseInt(document.getElementById('branch-map-select')?.value || 0);
            const branch = state.branches.find(b => b.id === bId);
            if (branch) {
                selectBranchOnMap(branch, true);
            }
        }

        function selectBranchOnMap(branch, zoomTo = true) {
            if (!branch) return;
            state.branchSelectedOnMap = branch;

            const bSelect = document.getElementById('branch-map-select');
            if (bSelect && bSelect.value != branch.id) {
                bSelect.value = branch.id;
            }

            const nameEl = document.getElementById('branch-map-info-name');
            const statusBadgeEl = document.getElementById('branch-map-info-status-badge');
            const codeEl = document.getElementById('branch-map-info-code');
            const phoneEl = document.getElementById('branch-map-info-phone');
            const addrEl = document.getElementById('branch-map-info-address');
            const coordsEl = document.getElementById('branch-map-info-coords');
            const radiusEl = document.getElementById('branch-map-info-radius');
            const staffEl = document.getElementById('branch-map-info-staff');
            const productsEl = document.getElementById('branch-map-info-products');
            const vehiclesEl = document.getElementById('branch-map-info-vehicles');
            const gmapsLink = document.getElementById('branch-map-gmaps-link');

            const isActive = branch.is_active != 0;
            const isMain = branch.id == 1;

            if (nameEl) nameEl.innerText = branch.name;
            if (codeEl) codeEl.innerText = `Kode: ${branch.code} ${isMain ? '[PUSAT]' : ''}`;
            if (statusBadgeEl) {
                statusBadgeEl.innerText = isActive ? '● Aktif' : '○ Nonaktif';
                statusBadgeEl.className = `px-2 py-0.5 rounded-full text-[10px] font-bold ${isActive ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}`;
            }

            if (phoneEl) phoneEl.innerText = branch.phone || '-';
            if (addrEl) addrEl.innerText = branch.address;

            const bLat = parseFloat(branch.latitude);
            const bLon = parseFloat(branch.longitude);
            const hasCoords = !isNaN(bLat) && !isNaN(bLon);

            if (coordsEl) coordsEl.innerText = hasCoords ? `${bLat.toFixed(6)}, ${bLon.toFixed(6)}` : '-';
            if (radiusEl) radiusEl.innerText = `${branch.radius_meters || 100} Meter`;

            if (staffEl) staffEl.innerText = branch.total_staff || 0;
            if (productsEl) productsEl.innerText = branch.total_products || 0;
            if (vehiclesEl) vehiclesEl.innerText = branch.total_vehicles || 0;

            if (gmapsLink) {
                if (hasCoords) {
                    gmapsLink.href = `https://www.google.com/maps?q=${bLat},${bLon}`;
                    gmapsLink.classList.remove('opacity-50', 'pointer-events-none');
                } else {
                    gmapsLink.href = '#';
                    gmapsLink.classList.add('opacity-50', 'pointer-events-none');
                }
            }

            if (zoomTo && hasCoords && state.branchMap) {
                state.branchMap.setView([bLat, bLon], 15, { animate: true });
            }
        }

        function fitBranchMapBounds() {
            if (!state.branchMap) return;
            const group = L.featureGroup(state.branchMapMarkers || []);
            if (group.getLayers().length > 0) {
                state.branchMap.fitBounds(group.getBounds(), { padding: [50, 50] });
            }
        }

        function focusBranchOnMap(branchId) {
            setBranchSubtab('maps');
            setTimeout(() => {
                const bSelect = document.getElementById('branch-map-select');
                if (bSelect) {
                    bSelect.value = branchId;
                    onBranchMapSelectChange();
                }
            }, 200);
        }

        function openBranchModalFromMap() {
            if (state.branchSelectedOnMap) {
                editBranch(state.branchSelectedOnMap);
            } else {
                openBranchModal();
            }
        }

        // Modal Branch Mini-Map Picker
        function initBranchPickerMap() {
            const container = document.getElementById('branch-modal-map-picker');
            if (!container) return;

            let lat = parseFloat(document.getElementById('branch-modal-lat')?.value);
            let lon = parseFloat(document.getElementById('branch-modal-lng')?.value);
            let radius = parseInt(document.getElementById('branch-modal-radius')?.value) || 100;

            if (isNaN(lat) || isNaN(lon) || (lat === 0 && lon === 0)) {
                lat = parseFloat(state.currentBranch?.latitude) || -6.195000;
                lon = parseFloat(state.currentBranch?.longitude) || 106.823000;
                document.getElementById('branch-modal-lat').value = lat.toFixed(6);
                document.getElementById('branch-modal-lng').value = lon.toFixed(6);
            }

            updateBranchPickerBadge(lat, lon, radius);

            if (!state.branchPickerMap) {
                state.branchPickerMap = L.map('branch-modal-map-picker', {
                    zoomControl: true,
                    attributionControl: false
                }).setView([lat, lon], 14);

                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 19
                }).addTo(state.branchPickerMap);

                state.branchPickerMarker = L.marker([lat, lon], { draggable: true }).addTo(state.branchPickerMap);
                state.branchPickerCircle = L.circle([lat, lon], {
                    radius: radius,
                    color: '#4f46e5',
                    fillColor: '#818cf8',
                    fillOpacity: 0.25,
                    weight: 2
                }).addTo(state.branchPickerMap);

                state.branchPickerMarker.on('dragend', function(e) {
                    const pos = e.target.getLatLng();
                    document.getElementById('branch-modal-lat').value = pos.lat.toFixed(6);
                    document.getElementById('branch-modal-lng').value = pos.lng.toFixed(6);
                    if (state.branchPickerCircle) state.branchPickerCircle.setLatLng(pos);
                    updateBranchPickerBadge(pos.lat, pos.lng, parseInt(document.getElementById('branch-modal-radius')?.value) || 100);
                });

                state.branchPickerMap.on('click', function(e) {
                    state.branchPickerMarker.setLatLng(e.latlng);
                    if (state.branchPickerCircle) state.branchPickerCircle.setLatLng(e.latlng);
                    document.getElementById('branch-modal-lat').value = e.latlng.lat.toFixed(6);
                    document.getElementById('branch-modal-lng').value = e.latlng.lng.toFixed(6);
                    updateBranchPickerBadge(e.latlng.lat, e.latlng.lng, parseInt(document.getElementById('branch-modal-radius')?.value) || 100);
                });
            } else {
                state.branchPickerMarker.setLatLng([lat, lon]);
                if (state.branchPickerCircle) {
                    state.branchPickerCircle.setLatLng([lat, lon]);
                    state.branchPickerCircle.setRadius(radius);
                }
                state.branchPickerMap.setView([lat, lon], 14);
            }

            setTimeout(() => {
                if (state.branchPickerMap) state.branchPickerMap.invalidateSize();
            }, 50);
            setTimeout(() => {
                if (state.branchPickerMap) state.branchPickerMap.invalidateSize();
            }, 250);
            setTimeout(() => {
                if (state.branchPickerMap) state.branchPickerMap.invalidateSize();
            }, 500);
        }

        function updateBranchPickerFromInputs() {
            const lat = parseFloat(document.getElementById('branch-modal-lat')?.value);
            const lon = parseFloat(document.getElementById('branch-modal-lng')?.value);
            const radius = parseInt(document.getElementById('branch-modal-radius')?.value) || 100;
            updateBranchPickerBadge(lat, lon, radius);
            if (!isNaN(lat) && !isNaN(lon) && state.branchPickerMap && state.branchPickerMarker) {
                state.branchPickerMarker.setLatLng([lat, lon]);
                if (state.branchPickerCircle) {
                    state.branchPickerCircle.setLatLng([lat, lon]);
                    state.branchPickerCircle.setRadius(radius);
                }
                state.branchPickerMap.setView([lat, lon], state.branchPickerMap.getZoom() || 14);
            }
        }

        function autoDetectBranchLocation() {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(
                    pos => {
                        document.getElementById('branch-modal-lat').value = pos.coords.latitude.toFixed(6);
                        document.getElementById('branch-modal-lng').value = pos.coords.longitude.toFixed(6);
                        updateBranchPickerFromInputs();
                        alert(`Titik GPS Outlet berhasil dideteksi:\nLat: ${pos.coords.latitude.toFixed(6)}, Lon: ${pos.coords.longitude.toFixed(6)}`);
                    },
                    err => {
                        alert('Izin GPS tidak diberikan atau offline.');
                    }
                );
            } else {
                alert('Browser Anda tidak mendukung geolokasi GPS.');
            }
        }

        async function saveBranchForm(e) {
            e.preventDefault();
            const id = document.getElementById('branch-modal-id').value;
            const payload = {
                id: id ? parseInt(id) : null,
                code: document.getElementById('branch-modal-code').value,
                name: document.getElementById('branch-modal-name').value,
                phone: document.getElementById('branch-modal-phone').value,
                address: document.getElementById('branch-modal-address').value,
                latitude: parseFloat(document.getElementById('branch-modal-lat').value),
                longitude: parseFloat(document.getElementById('branch-modal-lng').value),
                radius_meters: parseInt(document.getElementById('branch-modal-radius').value) || 100,
                is_active: parseInt(document.getElementById('branch-modal-active').value)
            };

            const submitBtn = document.getElementById('branch-modal-submit-btn');
            submitBtn.disabled = true;
            submitBtn.innerText = 'Menyimpan...';

            try {
                const res = await fetch('api.php?action=save_branch', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                submitBtn.disabled = false;
                submitBtn.innerText = id ? 'Perbarui Cabang' : 'Simpan Cabang';

                alert(data.message || data.error);
                if (data.success) {
                    closeBranchModal();
                    await loadBranches();
                    await initApp();
                }
            } catch (err) {
                submitBtn.disabled = false;
                submitBtn.innerText = id ? 'Perbarui Cabang' : 'Simpan Cabang';
                alert('Terjadi kesalahan koneksi server.');
            }
        }

        async function deleteBranch(branchId, branchName) {
            if (!confirm(`Hapus atau nonaktifkan cabang '${branchName}'?`)) return;

            try {
                const res = await fetch('api.php?action=delete_branch', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: branchId })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadBranches();
                    await initApp();
                }
            } catch (err) {
                alert('Gagal menghubungi server.');
            }
        }

        // ==========================================
        // 12. MANAJEMEN METODE PEMBAYARAN (CRUD)
        // ==========================================
        async function loadPaymentMethods() {
            try {
                const res = await fetch('api.php?action=get_payment_methods');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const methods = data.payment_methods;
                state.paymentMethods = methods;

                // KPI Counter
                const totalMethods = methods.length;
                const activeMethods = methods.filter(m => m.is_active != 0).length;
                const cashMethods = methods.filter(m => m.is_cash == 1).length;
                const cashlessMethods = methods.filter(m => m.is_cash == 0).length;

                const elTotal = document.getElementById('pm-kpi-total');
                const elActive = document.getElementById('pm-kpi-active');
                const elCash = document.getElementById('pm-kpi-cash');
                const elCashless = document.getElementById('pm-kpi-cashless');

                if (elTotal) elTotal.innerText = totalMethods;
                if (elActive) elActive.innerText = activeMethods;
                if (elCash) elCash.innerText = cashMethods;
                if (elCashless) elCashless.innerText = cashlessMethods;

                const tbody = document.getElementById('payments-table-body');
                if (!tbody) return;

                tbody.innerHTML = methods.map(m => {
                    const statusBadge = m.is_active != 0 
                        ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">Aktif</span>'
                        : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-500">Nonaktif</span>';

                    const typeBadge = m.is_cash == 1
                        ? '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-blue-100 text-blue-800">Tunai (Cash)</span>'
                        : '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-purple-100 text-purple-800">Non-Tunai</span>';

                    const isCashDefault = (m.id == 1 || m.code === 'CASH');

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-4 text-center font-bold text-slate-500">${m.sort_order || 0}</td>
                            <td class="py-3 px-4 font-mono font-bold text-indigo-700">${m.code}</td>
                            <td class="py-3 px-4">
                                <div class="font-bold text-slate-800">${m.name}</div>
                                <div class="text-[11px] text-slate-400">${m.description || '-'}</div>
                            </td>
                            <td class="py-3 px-4">
                                <span class="px-2 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-700">${m.category}</span>
                            </td>
                            <td class="py-3 px-4 font-mono font-medium text-slate-700">${m.account_number || '-'}</td>
                            <td class="py-3 px-4 text-slate-600 font-medium">${m.account_holder || '-'}</td>
                            <td class="py-3 px-4 text-center">${typeBadge}</td>
                            <td class="py-3 px-4 text-center">
                                <span class="font-bold text-slate-700">${m.transaction_count || 0} tx</span>
                                <div class="text-[10px] text-emerald-600 font-bold">${formatRupiah(m.total_volume || 0)}</div>
                            </td>
                            <td class="py-3 px-4 text-center">${statusBadge}</td>
                            <td class="py-3 px-4 text-center">
                                <div class="flex items-center justify-center space-x-1.5">
                                    <button onclick='editPaymentMethod(${JSON.stringify(m).replace(/'/g, "&#39;")})' class="p-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-600 rounded-lg" title="Edit Metode">
                                        <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
                                    </button>
                                    ${isCashDefault ? `
                                        <button disabled class="p-1.5 bg-slate-100 text-slate-300 rounded-lg cursor-not-allowed" title="Tunai sistem tidak dapat dihapus">
                                            <i data-lucide="lock" class="w-3.5 h-3.5"></i>
                                        </button>
                                    ` : `
                                        <button onclick="deletePaymentMethod(${m.id}, '${m.name}')" class="p-1.5 bg-rose-50 hover:bg-rose-100 text-rose-600 rounded-lg" title="Hapus / Nonaktifkan">
                                            <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                        </button>
                                    `}
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('') || `<tr><td colspan="10" class="text-center py-6 text-slate-400">Belum ada metode pembayaran terdaftar.</td></tr>`;

                lucide.createIcons();
            } catch (err) {
                console.error("loadPaymentMethods Error:", err);
            }
        }

        function openPaymentMethodModal() {
            document.getElementById('pm-modal-id').value = '';
            document.getElementById('pm-modal-code').value = '';
            document.getElementById('pm-modal-code').readOnly = false;
            document.getElementById('pm-modal-name').value = '';
            document.getElementById('pm-modal-category').value = 'OTHER';
            document.getElementById('pm-modal-acc-number').value = '';
            document.getElementById('pm-modal-acc-holder').value = '';
            document.getElementById('pm-modal-is-cash').value = '0';
            document.getElementById('pm-modal-sort-order').value = (state.paymentMethods ? state.paymentMethods.length + 1 : 1);
            document.getElementById('pm-modal-desc').value = '';
            document.getElementById('pm-modal-active').value = '1';

            document.getElementById('payment-method-modal-title').innerHTML = '<i data-lucide="credit-card" class="w-5 h-5 text-indigo-600"></i><span>Tambah Metode Pembayaran Baru</span>';
            document.getElementById('pm-modal-submit-btn').innerText = 'Simpan Metode';
            document.getElementById('payment-method-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closePaymentMethodModal() {
            document.getElementById('payment-method-modal').classList.add('hidden');
        }

        function editPaymentMethod(m) {
            document.getElementById('pm-modal-id').value = m.id;
            document.getElementById('pm-modal-code').value = m.code;
            document.getElementById('pm-modal-code').readOnly = (m.id == 1 || m.code === 'CASH');
            document.getElementById('pm-modal-name').value = m.name;
            document.getElementById('pm-modal-category').value = m.category || 'OTHER';
            document.getElementById('pm-modal-acc-number').value = m.account_number || '';
            document.getElementById('pm-modal-acc-holder').value = m.account_holder || '';
            document.getElementById('pm-modal-is-cash').value = m.is_cash ? '1' : '0';
            document.getElementById('pm-modal-sort-order').value = m.sort_order || 0;
            document.getElementById('pm-modal-desc').value = m.description || '';
            document.getElementById('pm-modal-active').value = m.is_active ? '1' : '0';

            document.getElementById('payment-method-modal-title').innerHTML = `<i data-lucide="edit-3" class="w-5 h-5 text-amber-600"></i><span>Edit Metode Pembayaran: ${m.name}</span>`;
            document.getElementById('pm-modal-submit-btn').innerText = 'Perbarui Metode';
            document.getElementById('payment-method-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        async function savePaymentMethodForm(e) {
            e.preventDefault();
            const submitBtn = document.getElementById('pm-modal-submit-btn');
            submitBtn.disabled = true;
            submitBtn.innerText = 'Menyimpan...';

            const payload = {
                id: document.getElementById('pm-modal-id').value || null,
                code: document.getElementById('pm-modal-code').value.trim(),
                name: document.getElementById('pm-modal-name').value.trim(),
                category: document.getElementById('pm-modal-category').value,
                account_number: document.getElementById('pm-modal-acc-number').value.trim(),
                account_holder: document.getElementById('pm-modal-acc-holder').value.trim(),
                is_cash: parseInt(document.getElementById('pm-modal-is-cash').value) || 0,
                sort_order: parseInt(document.getElementById('pm-modal-sort-order').value) || 0,
                description: document.getElementById('pm-modal-desc').value.trim(),
                is_active: parseInt(document.getElementById('pm-modal-active').value)
            };

            try {
                const res = await fetch('api.php?action=save_payment_method', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                submitBtn.disabled = false;
                submitBtn.innerText = payload.id ? 'Perbarui Metode' : 'Simpan Metode';

                alert(data.message || data.error);
                if (data.success) {
                    closePaymentMethodModal();
                    await loadPaymentMethods();
                    await initApp();
                }
            } catch (err) {
                submitBtn.disabled = false;
                submitBtn.innerText = payload.id ? 'Perbarui Metode' : 'Simpan Metode';
                alert('Terjadi kesalahan koneksi server.');
            }
        }

        async function deletePaymentMethod(pmId, pmName) {
            if (!confirm(`Hapus atau nonaktifkan metode pembayaran '${pmName}'?`)) return;

            try {
                const res = await fetch('api.php?action=delete_payment_method', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: pmId })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadPaymentMethods();
                    await initApp();
                }
            } catch (err) {
                alert('Gagal menghubungi server.');
            }
        }

        // ==========================================
        // 12.2 MANAJEMEN PECAHAN UANG KASIR (CRUD CASH DENOMINATIONS)
        // ==========================================
        async function loadCashDenominations() {
            try {
                const res = await fetch('api.php?action=get_cash_denominations');
                const data = await res.json();
                if (!data.success) {
                    console.error('Bootstrap failed:', data.error || 'Unknown error');
                    return;
                }

                const denoms = data.cash_denominations || [];
                state.cashDenominations = denoms;

                // Update KPI Cards
                const total = denoms.length;
                const active = denoms.filter(d => d.is_active != 0).length;
                const exact = denoms.filter(d => d.action_type === 'EXACT').length;
                const nominal = denoms.filter(d => d.action_type !== 'EXACT').length;

                const elTotal = document.getElementById('cd-kpi-total');
                const elActive = document.getElementById('cd-kpi-active');
                const elExact = document.getElementById('cd-kpi-exact');
                const elNominal = document.getElementById('cd-kpi-nominal');

                if (elTotal) elTotal.innerText = total;
                if (elActive) elActive.innerText = active;
                if (elExact) elExact.innerText = exact;
                if (elNominal) elNominal.innerText = nominal;

                // Render POS Buttons in terminal kasir
                renderPosCashDenominations();

                const tbody = document.getElementById('cash-denominations-table-body');
                if (!tbody) return;

                tbody.innerHTML = denoms.map(d => {
                    const statusBadge = d.is_active != 0
                        ? '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">Aktif</span>'
                        : '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-500">Nonaktif</span>';

                    let typeBadge = '';
                    if (d.action_type === 'EXACT') {
                        typeBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-blue-100 text-blue-800">Uang Pas (EXACT)</span>';
                    } else if (d.action_type === 'ADD') {
                        typeBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800">Tambah Nilai (ADD)</span>';
                    } else {
                        typeBadge = '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-indigo-100 text-indigo-800">Ganti Nilai (SET)</span>';
                    }

                    const displayAmount = d.action_type === 'EXACT' ? 'Mengikuti Tagihan' : formatRupiah(d.amount);

                    return `
                        <tr class="hover:bg-slate-50 transition-colors">
                            <td class="py-3 px-4 text-center font-bold text-slate-500">${d.sort_order || 0}</td>
                            <td class="py-3 px-4 font-bold text-slate-800">${d.label}</td>
                            <td class="py-3 px-4">${typeBadge}</td>
                            <td class="py-3 px-4 font-mono font-bold text-slate-700">${displayAmount}</td>
                            <td class="py-3 px-4 text-center">
                                <button type="button" class="py-1 px-2.5 text-xs font-bold rounded-lg border text-center bg-white border-slate-200 text-slate-700 shadow-xs cursor-default">
                                    ${d.label}
                                </button>
                            </td>
                            <td class="py-3 px-4 text-center">${statusBadge}</td>
                            <td class="py-3 px-4 text-center">
                                <div class="flex items-center justify-center space-x-1.5">
                                    <button onclick='editCashDenomination(${JSON.stringify(d).replace(/'/g, "&#39;")})' class="p-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-600 rounded-lg" title="Edit Tombol">
                                        <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
                                    </button>
                                    <button onclick="deleteCashDenomination(${d.id}, '${d.label}')" class="p-1.5 bg-rose-50 hover:bg-rose-100 text-rose-600 rounded-lg" title="Hapus Tombol">
                                        <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                                    </button>
                                </div>
                            </td>
                        </tr>
                    `;
                }).join('') || `<tr><td colspan="7" class="text-center py-6 text-slate-400">Belum ada pecahan uang terdaftar.</td></tr>`;

                lucide.createIcons();
            } catch (err) {
                console.error("loadCashDenominations Error:", err);
            }
        }

        function onCdActionTypeChange() {
            const type = document.getElementById('cd-modal-action-type').value;
            const amountInput = document.getElementById('cd-modal-amount');
            if (type === 'EXACT') {
                amountInput.value = 0;
                amountInput.disabled = true;
            } else {
                amountInput.disabled = false;
                if (!amountInput.value || parseFloat(amountInput.value) === 0) {
                    amountInput.value = 50000;
                }
            }
        }

        function openCashDenominationModal() {
            document.getElementById('cd-modal-id').value = '';
            document.getElementById('cd-modal-label').value = '';
            document.getElementById('cd-modal-action-type').value = 'SET';
            const amountInput = document.getElementById('cd-modal-amount');
            amountInput.disabled = false;
            amountInput.value = '';
            document.getElementById('cd-modal-sort-order').value = (state.cashDenominations ? state.cashDenominations.length + 1 : 1);
            document.getElementById('cd-modal-is-active').value = '1';

            document.getElementById('cash-denomination-modal-title').innerHTML = '<i data-lucide="banknote" class="w-5 h-5 text-emerald-600"></i><span>Tambah Tombol Pecahan Uang</span>';
            document.getElementById('cd-modal-submit-btn').innerText = 'Simpan Tombol';
            document.getElementById('cash-denomination-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeCashDenominationModal() {
            document.getElementById('cash-denomination-modal').classList.add('hidden');
        }

        function editCashDenomination(d) {
            document.getElementById('cd-modal-id').value = d.id;
            document.getElementById('cd-modal-label').value = d.label;
            document.getElementById('cd-modal-action-type').value = d.action_type || 'SET';
            const amountInput = document.getElementById('cd-modal-amount');
            amountInput.value = Math.round(d.amount);
            if (d.action_type === 'EXACT') {
                amountInput.disabled = true;
            } else {
                amountInput.disabled = false;
            }
            document.getElementById('cd-modal-sort-order').value = d.sort_order || 0;
            document.getElementById('cd-modal-is-active').value = d.is_active ? '1' : '0';

            document.getElementById('cash-denomination-modal-title').innerHTML = `<i data-lucide="edit-3" class="w-5 h-5 text-amber-600"></i><span>Edit Tombol Pecahan: ${d.label}</span>`;
            document.getElementById('cd-modal-submit-btn').innerText = 'Perbarui Tombol';
            document.getElementById('cash-denomination-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        async function saveCashDenominationForm(e) {
            e.preventDefault();
            const submitBtn = document.getElementById('cd-modal-submit-btn');
            submitBtn.disabled = true;
            submitBtn.innerText = 'Menyimpan...';

            const payload = {
                id: document.getElementById('cd-modal-id').value || null,
                label: document.getElementById('cd-modal-label').value.trim(),
                action_type: document.getElementById('cd-modal-action-type').value,
                amount: parseFloat(document.getElementById('cd-modal-amount').value) || 0,
                sort_order: parseInt(document.getElementById('cd-modal-sort-order').value) || 0,
                is_active: parseInt(document.getElementById('cd-modal-is-active').value)
            };

            try {
                const res = await fetch('api.php?action=save_cash_denomination', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await res.json();
                submitBtn.disabled = false;
                submitBtn.innerText = payload.id ? 'Perbarui Tombol' : 'Simpan Tombol';

                alert(data.message || data.error);
                if (data.success) {
                    closeCashDenominationModal();
                    await loadCashDenominations();
                }
            } catch (err) {
                submitBtn.disabled = false;
                submitBtn.innerText = payload.id ? 'Perbarui Tombol' : 'Simpan Tombol';
                alert('Terjadi kesalahan koneksi server.');
            }
        }

        async function deleteCashDenomination(cdId, cdLabel) {
            if (!confirm(`Hapus tombol pecahan uang '${cdLabel}'?`)) return;

            try {
                const res = await fetch('api.php?action=delete_cash_denomination', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: cdId })
                });
                const data = await res.json();
                alert(data.message || data.error);
                if (data.success) {
                    await loadCashDenominations();
                }
            } catch (err) {
                alert('Gagal menghubungi server.');
            }
        }

        // ==========================================
        // 15. MODUL PEMBATALAN TRANSAKSI PENJUALAN (VOID SALES)
        // ==========================================
        let voidSalesStatusFilter = 'ALL';
        let voidSearchDebounceTimer = null;

        function setVoidStatusFilter(status) {
            voidSalesStatusFilter = status;
            ['all', 'completed', 'cancelled'].forEach(s => {
                const btn = document.getElementById(`void-filter-btn-${s}`);
                if (btn) {
                    if (s === status.toLowerCase()) {
                        btn.className = 'px-3 py-1.5 rounded-lg bg-white text-slate-800 shadow-xs font-bold transition-colors';
                    } else {
                        btn.className = 'px-3 py-1.5 rounded-lg text-slate-600 hover:text-slate-800 font-bold transition-colors';
                    }
                }
            });
            loadSaleCancellations();
        }

        function onVoidSearchKeyUp(e) {
            clearTimeout(voidSearchDebounceTimer);
            voidSearchDebounceTimer = setTimeout(() => {
                loadSaleCancellations();
            }, 300);
        }

        async function loadSaleCancellations() {
            const tableBody = document.getElementById('cancellations-table-body');
            if (!tableBody) return;

            // Render authority banner
            const authContainer = document.getElementById('void-auth-status-container');
            const isSuperAdmin = (state.loggedInUser && ['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role));

            if (authContainer) {
                if (isSuperAdmin) {
                    authContainer.innerHTML = `
                        <div class="flex items-center space-x-2 bg-rose-950/60 border border-rose-500/50 px-3 py-1.5 rounded-2xl">
                            <span class="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse"></span>
                            <span class="text-xs font-bold text-rose-100">Super Admin: ${state.loggedInUser.name}</span>
                        </div>
                        <button type="button" onclick="openPurgeSalesModal()" class="px-3 py-1.5 bg-rose-600 hover:bg-rose-500 text-white rounded-xl text-xs font-black shadow transition-colors flex items-center space-x-1.5" title="Hapus seluruh riwayat penjualan dari database">
                            <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
                            <span>Hapus Seluruh Data Penjualan</span>
                        </button>
                    `;
                } else {
                    const currentRole = state.loggedInUser ? state.loggedInUser.role : 'KASIR';
                    authContainer.innerHTML = `
                        <div class="flex items-center space-x-2">
                            <span class="text-xs text-rose-300 font-semibold hidden md:inline">Peran Saat Ini: ${currentRole}</span>
                            <button type="button" onclick="loginAsSuperadminVoid()" class="px-3 py-1.5 bg-rose-600 hover:bg-rose-500 text-white rounded-xl text-xs font-black shadow transition-colors flex items-center space-x-1">
                                <span>👑 Beralih ke Super Admin</span>
                            </button>
                        </div>
                    `;
                }
            }

            const branchId = state.currentBranch ? state.currentBranch.id : '';
            const keyword = document.getElementById('void-search-keyword') ? document.getElementById('void-search-keyword').value.trim() : '';
            const startDate = document.getElementById('void-start-date') ? document.getElementById('void-start-date').value : '';
            const endDate = document.getElementById('void-end-date') ? document.getElementById('void-end-date').value : '';

            tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-8 text-slate-400">Memuat data transaksi...</td></tr>`;

            try {
                let url = `api.php?action=get_cancellable_sales&status_filter=${voidSalesStatusFilter}`;
                if (branchId) url += `&branch_id=${branchId}`;
                if (keyword) url += `&keyword=${encodeURIComponent(keyword)}`;
                if (startDate && endDate) url += `&start_date=${startDate}&end_date=${endDate}`;

                const res = await fetch(url);
                const data = await res.json();

                if (!data.success) {
                    tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-8 text-rose-500 font-bold">${data.message || 'Gagal memuat transaksi'}</td></tr>`;
                    return;
                }

                // Update KPI Cards
                if (data.kpi) {
                    document.getElementById('void-kpi-active-count').innerText = (data.kpi.active_count || 0).toLocaleString('id-ID');
                    document.getElementById('void-kpi-active-amount').innerText = formatRupiah(data.kpi.active_amount || 0);
                    document.getElementById('void-kpi-cancelled-count').innerText = (data.kpi.cancelled_count || 0).toLocaleString('id-ID');
                    document.getElementById('void-kpi-cancelled-amount').innerText = formatRupiah(data.kpi.cancelled_amount || 0);
                    document.getElementById('void-kpi-restocked-qty').innerText = (data.kpi.total_restocked_qty || 0).toLocaleString('id-ID') + ' unit';
                    document.getElementById('void-kpi-void-receivables').innerText = formatRupiah(data.kpi.total_void_receivables || 0);
                }

                const sales = data.sales || [];
                const tableInfo = document.getElementById('void-table-info');
                if (tableInfo) tableInfo.innerText = `Menampilkan ${sales.length} transaksi`;

                if (sales.length === 0) {
                    tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-10 text-slate-400">Tidak ada transaksi penjualan ditemukan untuk filter ini.</td></tr>`;
                    return;
                }

                tableBody.innerHTML = sales.map(s => {
                    const isCancelled = (s.status === 'CANCELLED');
                    const badgeClass = isCancelled 
                        ? 'bg-rose-100 text-rose-800 border border-rose-300' 
                        : 'bg-emerald-100 text-emerald-800 border border-emerald-300';
                    const statusLabel = isCancelled ? 'DIBATALKAN (VOID)' : 'COMPLETED';

                    let voidDetailsHtml = '<span class="text-slate-300">-</span>';
                    if (isCancelled) {
                        voidDetailsHtml = `
                            <div class="text-[11px] leading-tight">
                                <span class="font-bold text-rose-700 block">Dibatalkan oleh: ${s.cancelled_by_name || 'Super Admin'}</span>
                                <span class="text-slate-500 block text-[10px]">${s.cancelled_at || '-'}</span>
                                <span class="text-slate-700 italic block mt-0.5 bg-rose-50 p-1 rounded border border-rose-100">"${s.cancellation_reason || '-'}"</span>
                            </div>
                        `;
                    }

                    const actionBtn = isCancelled
                        ? `<button type="button" onclick="showSaleDetail('${s.invoice_number}')" class="px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-bold transition-colors">Detail</button>`
                        : `
                            <div class="flex items-center space-x-1.5 justify-center">
                                <button type="button" onclick="showSaleDetail('${s.invoice_number}')" class="px-2 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-bold transition-colors">
                                    Detail
                                </button>
                                <button type="button" onclick="openVoidSaleModal(${s.id}, '${s.invoice_number}', ${s.grand_total}, '${(s.customer_name || 'Pelanggan Umum').replace(/'/g, "\\'")}', '${(s.branch_name || '').replace(/'/g, "\\'")}', '${s.payment_method}', '${(s.cashier_name || '').replace(/'/g, "\\'")}')" class="px-2.5 py-1 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-xs font-black shadow-xs transition-colors flex items-center space-x-1">
                                    <i data-lucide="ban" class="w-3 h-3"></i>
                                    <span>Batalkan</span>
                                </button>
                            </div>
                        `;

                    return `
                        <tr class="hover:bg-slate-50/80 transition-colors ${isCancelled ? 'bg-rose-50/30' : ''}">
                            <td class="py-3 px-4 font-mono font-bold ${isCancelled ? 'text-rose-600 line-through' : 'text-indigo-600'}">
                                ${s.invoice_number}
                            </td>
                            <td class="py-3 px-4 text-slate-500 text-[11px] whitespace-nowrap">
                                ${s.created_at || '-'}
                            </td>
                            <td class="py-3 px-4 font-medium text-slate-800">
                                ${s.branch_name || '-'}
                            </td>
                            <td class="py-3 px-4 text-slate-700">
                                ${s.cashier_name || '-'}
                            </td>
                            <td class="py-3 px-4">
                                <span class="font-bold text-slate-800">${s.customer_name || 'Pelanggan Umum'}</span>
                                <span class="block text-[10px] text-slate-400 font-semibold">${s.customer_category || 'REGULER'}</span>
                            </td>
                            <td class="py-3 px-4 text-right font-bold font-mono text-slate-900">
                                ${formatRupiah(s.grand_total)}
                            </td>
                            <td class="py-3 px-4 text-center">
                                <span class="px-2 py-0.5 rounded-md text-[10px] font-bold ${s.payment_method === 'PIUTANG' ? 'bg-amber-100 text-amber-800' : 'bg-slate-100 text-slate-700'}">
                                    ${s.payment_method}
                                </span>
                            </td>
                            <td class="py-3 px-4 text-center">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold ${badgeClass}">
                                    ${statusLabel}
                                </span>
                            </td>
                            <td class="py-3 px-4 max-w-xs">
                                ${voidDetailsHtml}
                            </td>
                            <td class="py-3 px-4 text-center whitespace-nowrap">
                                ${actionBtn}
                            </td>
                        </tr>
                    `;
                }).join('');

                lucide.createIcons();
            } catch (err) {
                tableBody.innerHTML = `<tr><td colspan="10" class="text-center py-8 text-rose-500">Gagal mengambil data dari server.</td></tr>`;
            }
        }

        function openVoidSaleModal(saleId, invoiceNumber, grandTotal, customerName, branchName, paymentMethod, cashierName) {
            document.getElementById('void-modal-sale-id').value = saleId;
            document.getElementById('void-modal-invoice-no').innerText = invoiceNumber;
            document.getElementById('void-modal-branch').innerText = branchName || '-';
            document.getElementById('void-modal-cashier').innerText = cashierName || '-';
            document.getElementById('void-modal-customer').innerText = customerName || 'Pelanggan Umum';
            document.getElementById('void-modal-payment').innerText = paymentMethod || 'CASH';
            document.getElementById('void-modal-grand-total').innerText = formatRupiah(grandTotal);

            // Reset form inputs
            document.getElementById('void-modal-reason-quick').value = '';
            document.getElementById('void-modal-reason-text').value = '';
            
            // Auto fill PIN if logged in as superadmin
            if (state.loggedInUser && ['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role)) {
                document.getElementById('void-modal-admin-pin').value = state.loggedInUser.pin || '999999';
                document.getElementById('void-modal-admin-password').value = 'admin123';
            } else {
                document.getElementById('void-modal-admin-pin').value = '';
                document.getElementById('void-modal-admin-password').value = '';
            }

            document.getElementById('void-sale-modal').classList.remove('hidden');
            lucide.createIcons();
        }

        function closeVoidSaleModal() {
            document.getElementById('void-sale-modal').classList.add('hidden');
        }

        function onVoidReasonQuickChange() {
            const quickVal = document.getElementById('void-modal-reason-quick').value;
            const textEl = document.getElementById('void-modal-reason-text');
            if (quickVal && quickVal !== 'Lainnya') {
                textEl.value = quickVal;
            }
        }

        async function submitVoidSaleForm(e) {
            e.preventDefault();
            const submitBtn = document.getElementById('void-modal-submit-btn');
            const saleId = document.getElementById('void-modal-sale-id').value;
            const invoiceNo = document.getElementById('void-modal-invoice-no').innerText;
            const reason = document.getElementById('void-modal-reason-text').value.trim();
            const adminPin = document.getElementById('void-modal-admin-pin').value.trim();
            const adminPassword = document.getElementById('void-modal-admin-password').value.trim();

            if (!reason) {
                alert('Alasan pembatalan transaksi wajib diisi!');
                return;
            }

            if (!adminPin && !adminPassword && (!state.loggedInUser || !['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role))) {
                alert('Masukkan PIN atau Kata Sandi Super Admin (Budi Santoso - PIN 999999 / Password admin123) untuk mengotorisasi pembatalan!');
                return;
            }

            if (!confirm(`PERINGATAN: Apakah Anda yakin ingin MEMBATALKAN transaksi '${invoiceNo}'?\n\nSemua persediaan produk & bahan baku BOM akan dikembalikan ke cabang, dan catatan piutang (jika ada) akan dibatalkan permanen.`)) {
                return;
            }

            submitBtn.disabled = true;
            submitBtn.innerHTML = `<span>Memproses Void...</span>`;

            try {
                const res = await fetch('api.php?action=cancel_sale', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        sale_id: saleId,
                        invoice_number: invoiceNo,
                        reason: reason,
                        admin_pin: adminPin || '999999',
                        admin_password: adminPassword || 'admin123',
                        admin_user_id: state.loggedInUser ? state.loggedInUser.id : 1
                    })
                });

                const data = await res.json();
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="ban" class="w-4 h-4"></i><span>Batalkan Transaksi (Void)</span>`;

                if (data.success) {
                    alert('BERHASIL! ' + data.message);
                    closeVoidSaleModal();
                    await loadSaleCancellations();
                    // Refresh other tabs cache if loaded
                    if (state.currentTab === 'stocks') loadStockInventory();
                    if (state.currentTab === 'reports') loadSalesReports();
                    if (state.currentTab === 'pnl') loadProfitLoss();
                } else {
                    alert('GAGAL: ' + (data.message || data.error));
                }
            } catch (err) {
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="ban" class="w-4 h-4"></i><span>Batalkan Transaksi (Void)</span>`;
                alert('Terjadi kesalahan jaringan saat membatalkan transaksi.');
            }
        }

        async function loginAsSuperadminVoid() {
            if (!confirm('Beralih ke akun Super Admin sekarang? Anda wajib memasukkan kata sandi Super Admin untuk otorisasi.')) return;
            showLoginScreen('Silakan masukkan kata sandi Super Admin untuk melanjutkan otorisasi.');
            selectQuickAccount('ADM001', 'Super Admin');
        }

        // --- Fitur Hapus Seluruh Riwayat Penjualan (Super Admin Only) ---
        // ==============================================================
        // MASTER RESET & PEMBERSIHAN DATA CABANG (GRANULAR DATA PURGE)
        // ==============================================================
        function openMasterResetModal(preselectOpts = {}) {
            // Populate branch dropdown
            const branchSelect = document.getElementById('master-reset-branch-select');
            if (branchSelect) {
                let html = '<option value="ALL">🌐 SEMUA CABANG (Global Reset - Seluruh Database)</option>';
                if (state.branches && state.branches.length > 0) {
                    state.branches.forEach(b => {
                        const isCurrent = (state.currentBranch && state.currentBranch.id == b.id) ? 'selected' : '';
                        html += `<option value="${b.id}" ${isCurrent}>📍 Cabang: ${b.name} (${b.code || ''})</option>`;
                    });
                }
                branchSelect.innerHTML = html;
            }

            // Set checkboxes based on preselectOpts
            const optStocks = document.getElementById('reset-opt-stocks');
            const optSales = document.getElementById('reset-opt-sales');
            const optBom = document.getElementById('reset-opt-bom');
            const optShifts = document.getElementById('reset-opt-shifts');

            if (Object.keys(preselectOpts).length === 0) {
                if (optStocks) optStocks.checked = false;
                if (optSales) optSales.checked = true;
                if (optBom) optBom.checked = false;
                if (optShifts) optShifts.checked = false;
            } else {
                if (optStocks) optStocks.checked = !!preselectOpts.stocks;
                if (optSales) optSales.checked = !!preselectOpts.sales;
                if (optBom) optBom.checked = !!preselectOpts.bom;
                if (optShifts) optShifts.checked = !!preselectOpts.shifts;
            }

            // Auto-fill credentials if Superadmin
            if (state.loggedInUser && ['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role)) {
                document.getElementById('master-reset-admin-pin').value = state.loggedInUser.pin || '999999';
                document.getElementById('master-reset-admin-password').value = 'admin123';
            } else {
                document.getElementById('master-reset-admin-pin').value = '';
                document.getElementById('master-reset-admin-password').value = '';
            }

            // Reset confirmation text
            const confirmInput = document.getElementById('master-reset-confirm-text');
            if (confirmInput) confirmInput.value = '';

            updateResetScopeInfo();

            const modal = document.getElementById('master-reset-modal');
            if (modal) modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeMasterResetModal() {
            const modal = document.getElementById('master-reset-modal');
            if (modal) modal.classList.add('hidden');
        }

        // Backward compatibility alias
        function openPurgeSalesModal() {
            openMasterResetModal({ sales: true });
        }
        function closePurgeSalesModal() {
            closeMasterResetModal();
        }

        function toggleSelectAllResetOptions(checked) {
            const optStocks = document.getElementById('reset-opt-stocks');
            const optSales = document.getElementById('reset-opt-sales');
            const optBom = document.getElementById('reset-opt-bom');
            const optShifts = document.getElementById('reset-opt-shifts');

            if (optStocks) optStocks.checked = checked;
            if (optSales) optSales.checked = checked;
            if (optBom) optBom.checked = checked;
            if (optShifts) optShifts.checked = checked;
        }

        function updateResetScopeInfo() {
            const select = document.getElementById('master-reset-branch-select');
            const badge = document.getElementById('reset-scope-badge');
            const desc = document.getElementById('reset-scope-desc');
            if (!select || !badge || !desc) return;

            const val = select.value;
            if (val === 'ALL') {
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-100 text-rose-800';
                badge.innerText = 'Global (Semua Cabang)';
                desc.innerHTML = 'Operasi akan mengeksekusi reset pada <b>seluruh cabang toko</b> di seluruh database secara simultan.';
            } else {
                const text = select.options[select.selectedIndex] ? select.options[select.selectedIndex].text : `Cabang #${val}`;
                badge.className = 'px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-100 text-indigo-800';
                badge.innerText = 'Spesifik: ' + text.replace('📍 Cabang: ', '');
                desc.innerHTML = `Operasi reset <b>HANYA</b> akan berdampak pada <b>${text}</b>. Cabang lainnya tetap utuh dan aman.`;
            }
        }

        async function submitMasterResetForm(e) {
            e.preventDefault();
            const submitBtn = document.getElementById('master-reset-submit-btn');
            const branchId = document.getElementById('master-reset-branch-select').value;
            
            const purgeStocks = document.getElementById('reset-opt-stocks').checked;
            const purgeSales = document.getElementById('reset-opt-sales').checked;
            const purgeBom = document.getElementById('reset-opt-bom').checked;
            const purgeShifts = document.getElementById('reset-opt-shifts').checked;

            if (!purgeStocks && !purgeSales && !purgeBom && !purgeShifts) {
                alert('Pilih minimal salah satu opsi data yang ingin direset!');
                return;
            }

            const adminPin = document.getElementById('master-reset-admin-pin').value.trim();
            const adminPassword = document.getElementById('master-reset-admin-password').value.trim();
            const confirmText = document.getElementById('master-reset-confirm-text').value.trim().toUpperCase();

            if (!['RESET DATA', 'RESET', 'HAPUS', 'HAPUS DATA', 'HAPUS PENJUALAN'].includes(confirmText)) {
                alert('Teks konfirmasi salah! Anda wajib mengetik "RESET DATA".');
                return;
            }

            if (!adminPin && !adminPassword && (!state.loggedInUser || !['SUPER_ADMIN', 'SUPERADMIN'].includes(state.loggedInUser.role))) {
                alert('Masukkan PIN atau Kata Sandi Super Admin untuk otorisasi reset data!');
                return;
            }

            const branchLabel = branchId === 'ALL' ? 'SEMUA CABANG (GLOBAL WIPE)' : (document.getElementById('master-reset-branch-select').selectedOptions[0]?.text || `Cabang #${branchId}`);
            
            const selectedItems = [];
            if (purgeStocks) selectedItems.push('1. Stok Seluruh Produk (Set ke 0)');
            if (purgeSales) selectedItems.push('2. Riwayat Transaksi Penjualan & Piutang');
            if (purgeBom) selectedItems.push('3. Log Pemakaian Bahan Baku (BOM)');
            if (purgeShifts) selectedItems.push('4. Riwayat Laporan Shift & Meteran Air');

            const finalConfirm = confirm(`⚠️ PERINGATAN TINGKAT TINGGI!\n\nAnda akan MENGHAPUS / MERESET:\n• ${selectedItems.join('\n• ')}\n\nLingkup Target: ${branchLabel}\n\nOperasi ini bersifat PERMANEN dan TIDAK DAPAT DIBATALKAN!\n\nApakah Anda benar-benar yakin ingin mengeksekusi reset?`);
            if (!finalConfirm) return;

            submitBtn.disabled = true;
            submitBtn.innerHTML = `<span>Mengeksekusi Reset...</span>`;

            try {
                const res = await fetch('api.php?action=master_reset_data', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        branch_id: branchId,
                        purge_stocks: purgeStocks,
                        purge_sales: purgeSales,
                        purge_bom: purgeBom,
                        purge_shifts: purgeShifts,
                        confirm_text: confirmText,
                        admin_pin: adminPin || '999999',
                        admin_password: adminPassword || 'admin123',
                        admin_user_id: state.loggedInUser ? state.loggedInUser.id : 1
                    })
                });

                const data = await res.json();
                if (data.success) {
                    alert(`✅ ${data.message}`);
                    closeMasterResetModal();

                    // Refresh relevant tables and views
                    if (typeof loadSalesReports === 'function') loadSalesReports();
                    if (typeof loadBomUsageReport === 'function') loadBomUsageReport();
                    if (typeof loadShiftReports === 'function') loadShiftReports();
                    if (typeof loadInventoryStocks === 'function') loadInventoryStocks();
                    if (typeof loadStockMovements === 'function') loadStockMovements();
                    if (typeof loadReceivablesReport === 'function') loadReceivablesReport();
                    if (typeof loadSaleCancellations === 'function') loadSaleCancellations();
                    if (typeof bootstrapApp === 'function') bootstrapApp();
                } else {
                    alert(`❌ GAGAL: ${data.message || 'Terjadi kesalahan sistem'}`);
                }
            } catch (err) {
                console.error(err);
                alert('Terjadi kesalahan koneksi saat mereset data.');
            } finally {
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i data-lucide="trash-2" class="w-4 h-4"></i><span>Eksekusi Reset Sekarang</span>`;
                lucide.createIcons();
            }
        }

        // Backward compatibility
        async function submitPurgeSalesForm(e) {
            submitMasterResetForm(e);
        }

        // ==========================================
        // 15. CONTROLLER PENGATURAN SISTEM, ROLE & CETAK
        // ==========================================
        let settingsSubtabActive = 'general';

        function setSettingsSubtab(subtab) {
            settingsSubtabActive = subtab;
            const subtabs = ['general', 'roles', 'printer', 'receipt', 'payslip', 'notifications'];
            subtabs.forEach(st => {
                const el = document.getElementById(`settings-subtab-${st}`);
                const btn = document.getElementById(`settings-tab-btn-${st}`);
                if (st === subtab) {
                    if (el) el.classList.remove('hidden');
                    if (btn) {
                        btn.className = 'px-4 py-2 rounded-xl text-xs font-bold transition-all bg-indigo-600 text-white shadow-sm flex items-center space-x-1.5';
                    }
                } else {
                    if (el) el.classList.add('hidden');
                    if (btn) {
                        btn.className = 'px-4 py-2 rounded-xl text-xs font-bold transition-all bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center space-x-1.5';
                    }
                }
            });

            if (subtab === 'receipt') updateReceiptLivePreview();
            if (subtab === 'roles') renderRolePermissionsMatrix();
            lucide.createIcons();
        }

        function applyAppSettingsToUI() {
            const s = state.appSettings || {};

            // 1. Ubah Logo
            const logoEmoji = s.app_logo_emoji || '🛍️';
            const logoEl = document.getElementById('sidebar-app-logo');
            if (logoEl) logoEl.innerText = logoEmoji;

            // 2. Ubah Nama Aplikasi & Slogan
            const appName = s.app_name || 'ESBAS RETAIL';
            const appSubtitle = s.app_subtitle || 'POS, BOM & ESS';
            const nameEl = document.getElementById('sidebar-app-name');
            const subEl = document.getElementById('sidebar-app-subtitle');
            if (nameEl) nameEl.innerText = appName;
            if (subEl) subEl.innerText = appSubtitle;

            // Dokumen Title
            document.title = `${appName} - ${appSubtitle}`;
        }

        function applyRolePermissionsToSidebar() {
            const curUser = state.currentUser || state.loggedInUser;
            if (!curUser) return;
            const role = (curUser.role || 'CASHIER').toUpperCase().trim();
            const isSuperAdmin = (role === 'SUPERADMIN' || role === 'SUPER_ADMIN' || role === 'SUPER ADMIN');

            // Ambil izin menu role
            const userPerms = state.userPermissions || {};
            const allMenus = ['pos', 'reports', 'ess', 'employees', 'products', 'bom', 'stocks', 'pnl', 'expenses', 'customers', 'logistics', 'branches', 'payments', 'sale-cancellations', 'settings'];

            allMenus.forEach(mKey => {
                const btn = document.getElementById(`tab-btn-${mKey}`);
                if (!btn) return;

                // Superadmin SELALU memiliki akses penuh ke seluruh menu (1 s/d 15)
                let canAccess = true;
                if (!isSuperAdmin) {
                    if (userPerms[mKey] !== undefined) {
                        canAccess = (userPerms[mKey] == 1);
                    } else if (role === 'MANAGER' || role === 'BRANCH_MANAGER') {
                        canAccess = (mKey !== 'sale-cancellations');
                    } else {
                        canAccess = false;
                    }
                }

                if (canAccess) {
                    btn.classList.remove('hidden');
                    btn.style.display = 'flex';
                } else {
                    btn.classList.add('hidden');
                    btn.style.display = 'none';
                }
            });
        }

        state.settingsSelectedBranchId = 0;

        async function loadAppSettingsModule() {
            try {
                populateSettingsBranchSelect();
                const branchId = state.settingsSelectedBranchId || 0;
                await loadBranchSettings(branchId);

                const resRoles = await fetch('api.php?action=get_role_permissions');
                const dataRoles = await resRoles.json();
                if (dataRoles.success) {
                    state.userRoles = dataRoles.roles || state.userRoles || [];
                    state.rolePermissions = dataRoles.permissions || [];
                    state.groupedRolePermissions = dataRoles.grouped || {};
                    renderRolePermissionsMatrix();
                }
            } catch (err) {
                console.error(err);
            }
        }

        function populateSettingsBranchSelect() {
            const selectEl = document.getElementById('settings-branch-select');
            if (!selectEl) return;
            const curVal = selectEl.value || '0';
            let html = '<option value="0">🌐 [Standar Global] Semua Cabang / Kantor Pusat</option>';
            if (Array.isArray(state.branches)) {
                state.branches.forEach(b => {
                    html += `<option value="${b.id}">🏢 [Cabang ${b.id}] ${escapeHtml(b.name)}</option>`;
                });
            }
            selectEl.innerHTML = html;
            selectEl.value = curVal;
        }

        async function onSettingsBranchChange() {
            const bId = parseInt(document.getElementById('settings-branch-select')?.value || '0');
            state.settingsSelectedBranchId = bId;
            await loadBranchSettings(bId);
        }

        async function loadBranchSettings(branchId) {
            try {
                const res = await fetch('api.php?action=get_app_settings&branch_id=' + branchId);
                const data = await res.json();
                if (data.success) {
                    populateAppSettingsForm(data.settings || {}, data.has_override);

                    // Update Badge Status & Tombol Reset
                    const badge = document.getElementById('settings-branch-badge');
                    const btnReset = document.getElementById('btn-reset-branch-settings');
                    if (badge) {
                        if (branchId === 0) {
                            badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-indigo-100 text-indigo-700 border border-indigo-200';
                            badge.innerText = '🌐 Standar Global (Pusat)';
                        } else if (data.has_override) {
                            badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-emerald-100 text-emerald-800 border border-emerald-300';
                            badge.innerText = '🏢 Pengaturan Khusus Cabang Aktif';
                        } else {
                            badge.className = 'px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-slate-100 text-slate-700 border border-slate-300';
                            badge.innerText = '🏢 Mewarisi Standar Pusat';
                        }
                    }

                    if (btnReset) {
                        if (branchId > 0 && data.has_override) {
                            btnReset.classList.remove('hidden');
                        } else {
                            btnReset.classList.add('hidden');
                        }
                    }
                }
            } catch (err) {
                console.error('Gagal memuat setting cabang:', err);
            }
        }

        async function resetCurrentBranchSettings() {
            const branchId = parseInt(document.getElementById('settings-branch-select')?.value || '0');
            if (branchId <= 0) return;

            if (!confirm('Apakah Anda yakin ingin menghapus seluruh kustomisasi pengaturan cabang ini dan mengembalikannya ke pengaturan standar kantor pusat?')) {
                return;
            }

            try {
                const res = await fetch('api.php?action=reset_branch_settings', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ branch_id: branchId })
                });
                const data = await res.json();
                alert(data.message || 'Pengaturan cabang berhasil di-reset!');
                if (data.success) {
                    if (branchId === parseInt(state.currentBranch?.id)) {
                        state.appSettings = data.settings || {};
                        applyAppSettingsToUI();
                    }
                    await loadBranchSettings(branchId);
                }
            } catch (err) {
                alert('Gagal me-reset pengaturan cabang.');
            }
        }

